/* Past-year questions for Rank mode · JEE Mains · Electrostatics, grouped by topic and sub-topic.
   Sources: JEE Main, JEE Advanced, IIT-JEE and AIEEE papers. Wording as in the paper; solutions written for this site.
   MCQ: o + c (index or array of indices). Numerical: n. Multi-part: a. s = worked solution. y = exam and year. fig = diagram (PhysicaFig spec). */
window.PhysicaRankPyqEs=[
{"y":"JEE Main 2025 · 2 Apr · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"A point charge +q is placed at the origin. A second point charge +9q is placed at (d, 0, 0) in Cartesian coordinate system. The point in between them where the electric field vanishes is","o":["(d/4, 0, 0)","(4d/3, 0, 0)","(3d/4, 0, 0)","(d/3, 0, 0)"],"c":0,"s":"Let the point be at x. Both charges are positive, so the fields cancel between them.\nq/x² = 9q/(d − x)²\nTake the square root: (d − x) = 3x, so x = d/4.\nThe point is (d/4, 0, 0)."},
{"y":"JEE Main 2025 · 8 Apr · Shift 2","tp":"ecn","st":"Charge sharing and earthing","q":"Two metal spheres of radius R and 3R have same surface charge density σ. If they are brought in contact and then separated, surface charge density on smaller and bigger sphere becomes σ₁ and σ₂, respectively. The ratio {σ₁;σ₂} is","o":["{1;9}","{1;3}","3","9"],"c":2,"s":"Initial charges: q₁ = σ·4πR², q₂ = σ·4π(3R)² = 9q₁. Total = 10q₁.\nAfter contact the potentials are equal, so charge is shared in the ratio of radii, 1 : 3.\nSmall sphere: 2.5q₁, big sphere: 7.5q₁.\nσ₁ = 2.5q₁/(4πR²), σ₂ = 7.5q₁/(4π·9R²).\nσ₁/σ₂ = (2.5 × 9)/7.5 = 3."},
{"y":"JEE Main 2025 · 24 Jan · Shift 2","tp":"ecl","st":"Force between point charges","q":"A small uncharged conducting sphere is placed in contact with an identical sphere but having 4 × 10⁻⁸ C charge and then removed to a distance such that the force of repulsion between them is 9 × 10⁻³ N. The distance between them is (Take {1;4πε₀} as 9 × 10⁹ in SI units)","o":["3 cm","1 cm","4 cm","2 cm"],"c":3,"s":"On contact the charge is shared equally: each sphere has 2 × 10⁻⁸ C.\nF = kq²/r², so r² = kq²/F.\nr² = 9×10⁹ × (2×10⁻⁸)² / (9×10⁻³) = 3.6×10⁻⁶/(9×10⁻³) = 4×10⁻⁴ m².\nr = 2×10⁻² m = 2 cm."},
{"y":"JEE Main 2024 · 5 Apr · Shift 1","tp":"ecl","st":"Force between point charges","q":"In hydrogen like system, the ratio of coulombian force and gravitational force between an electron and a proton is in the order of","o":["10¹⁹","10²⁹","10³⁹","10³⁶"],"c":2,"s":"Coulomb force: ke²/r². Gravitational force: Gm_e m_p/r². The r² cancels.\nRatio = ke²/(G m_e m_p) = 9×10⁹ × (1.6×10⁻¹⁹)² / (6.67×10⁻¹¹ × 9.1×10⁻³¹ × 1.67×10⁻²⁷).\n= 2.3×10⁻²⁸ / 1.0×10⁻⁶⁷ ≈ 2×10³⁹.\nSo the order is 10³⁹."},
{"y":"JEE Main 2024 · 5 Apr · Shift 2","tp":"ecn","st":"Charge sharing and earthing","q":"The vehicles carrying inflammable fluids usually have metallic chains touching the ground,","o":["to alert other vehicles","it is a custom","to protect tyres from catching dirt from ground","to conduct excess charge due to air friction to ground and prevent sparking"],"c":3,"s":"Friction with air charges the vehicle body.\nA metal chain touching the ground gives this extra charge a path to earth.\nThis stops charge from building up, so no spark can set fire to the fluid.\nAnswer: to conduct excess charge due to air friction to ground and prevent sparking."},
{"y":"JEE Main 2024 · 6 Apr · Shift 1","tp":"egs","st":"Gauss's law and symmetric bodies","q":"σ is the uniform surface charge density of a thin spherical shell of radius R. The electric field at any point on the surface of the spherical shell is","o":["σ/ε₀","σ/4ε₀","σ/ε₀R","σ/2ε₀"],"c":0,"s":"Apply Gauss's law to a sphere just outside the shell: E·4πR² = σ·4πR²/ε₀, so E = σ/ε₀.\nInside the shell the field is zero.\nThe book takes the field on the surface as the value just outside, σ/ε₀.\nAnswer: σ/ε₀."},
{"y":"JEE Main 2024 · 6 Apr · Shift 2","tp":"ecl","st":"Force between point charges","q":"Two identical conducting spheres P and S with charge Q on each, repel each other with a force 16 N. A third identical uncharged conducting sphere R is successively brought in contact with the two spheres. The new force of repulsion between P and S is","o":["4 N","1 N","12 N","6 N"],"c":3,"s":"Original force: kQ²/r² = 16 N.\nR touches P: each has Q/2. R (Q/2) then touches S (Q): each has 3Q/4.\nNow P has Q/2 and S has 3Q/4.\nNew force = k(Q/2)(3Q/4)/r² = (3/8) × 16 = 6 N."},
{"y":"JEE Main 2024 · 8 Apr · Shift 1","tp":"ecn","st":"Charge sharing and earthing","q":"Two charged conducting spheres of radii a and b are connected to each other by a conducting wire. The ratio of charges of the two spheres respectively is","o":["√(ab)","{b;a}","{a;b}","ab"],"c":2,"s":"Connected spheres reach the same potential: kq_a/a = kq_b/b.\nSo q_a/q_b = a/b.\nThe charge is shared in the ratio of the radii."},
{"y":"JEE Main 2024 · 31 Jan · Shift 2","tp":"ecl","st":"Force between point charges","q":"Force between two point charges q₁ and q₂ placed in vacuum at 'r' cm apart is F. Force between them when placed in a medium having dielectric constant k = 5 at 'r/5' cm apart will be","o":["25F","F/5","5F","F/25"],"c":2,"s":"In vacuum: F = kq₁q₂/r².\nIn the medium: F' = kq₁q₂/(K·(r/5)²) = 25kq₁q₂/(5r²) = 5 × kq₁q₂/r².\nSo F' = 5F."},
{"y":"JEE Advanced 2024","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two beads, each with charge q and mass m, are on a horizontal, frictionless, non-conducting, circular hoop of radius R. One of the beads is glued to the hoop at some point, while the other one performs small oscillations about its equilibrium position along the hoop. The square of the angular frequency of the small oscillations is given by\n[ε₀ is the permittivity of free space.]","o":["q²/(4πε₀R³m)","q²/(32πε₀R³m)","q²/(8πε₀R³m)","q²/(16πε₀R³m)"],"c":1,"s":"Equilibrium: the free bead is diametrically opposite the fixed one.\nLet it move through a small angle φ. The chord between the beads is 2R cos(φ/2) ≈ 2R(1 − φ²/8).\nU = kq²/chord ≈ (kq²/2R)(1 + φ²/8). Kinetic energy = ½mR²φ̇².\nThis is SHM with ½Cφ², C = kq²/(8R), and moment of inertia mR².\nω² = C/(mR²) = kq²/(8mR³) = q²/(32πε₀R³m)."},
{"y":"JEE Main 2023 · 13 Apr · Shift 2","tp":"ecl","st":"Force between point charges","q":"A 10 μC charge is divided into two parts and placed at 1 cm distance so that the repulsive force between them is maximum. The charges of the two parts are","o":["9 μC, 1 μC","7 μC, 3 μC","8 μC, 2 μC","5 μC, 5 μC"],"c":3,"s":"Let the parts be q and (10 − q) μC. Force ∝ q(10 − q).\nThe product is maximum when q = 10 − q, that is q = 5 μC.\nBoth parts are 5 μC."},
{"y":"JEE Main 2023 · 24 Jan · Shift 1","tp":"ecl","st":"Force between point charges","q":"If two charges q₁ and q₂ are separated with distance 'd' and placed in a medium of dielectric constant k. What will be the equivalent distance between charges in air for the same electrostatic force?","o":["k√d","1.5d√k","2d√k","d√k"],"c":3,"s":"In the medium: F = q₁q₂/(4πε₀ k d²).\nIn air at distance d': F = q₁q₂/(4πε₀ d'²).\nEqual forces give d'² = k d², so d' = d√k."},
{"y":"JEE Main 2023 · 29 Jan · Shift 2","tp":"evp","st":"Potential energy and work","q":"A point charge 2 × 10⁻² C is moved from P to S in a uniform electric field of 30 N C⁻¹ directed along positive x-axis. If co-ordinates of P and S are (1, 2, 0) m and (0, 0, 0), respectively, the work done by electric field will be","o":["1200 mJ","600 mJ","−600 mJ","−1200 mJ"],"c":2,"s":"Force on the charge: F = qE = 2×10⁻² × 30 = 0.6 N along +x.\nDisplacement along x: from x = 1 to x = 0, that is −1 m.\nW = F·Δx = 0.6 × (−1) = −0.6 J = −600 mJ.\nThe y displacement does no work because it is perpendicular to the field."},
{"y":"JEE Main 2023 · 30 Jan · Shift 1","tp":"ecn","st":"Charge sharing and earthing","q":"Two isolated metallic solid spheres of radii R and 2R are charged such that both have same charge density σ. The spheres are then connected by a thin conducting wire. If the new charge density of the bigger sphere is σ'. The ratio {σ';σ} is","o":["{5;3}","{9;4}","{5;6}","{4;3}"],"c":2,"s":"Charges: q₁ = σ·4πR², q₂ = σ·4π(2R)² = 4q₁. Total = 5q₁.\nAfter connection the charge divides in the ratio of the radii, 1 : 2.\nBigger sphere: q₂' = (2/3) × 5q₁ = 10q₁/3.\nσ' = (10q₁/3)/(4π·4R²) = (10/3)(σ·4πR²)/(16πR²) = (10/12)σ = 5σ/6."},
{"y":"JEE Main 2022 · 27 Jul · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two identical positive charge Q each are fixed at a distance of '2a' apart from each other. Another point charge q₀ with mass 'm' is placed at midpoint between two fixed charges. For a small displacement along the line joining the fixed charges, the charge q₀ executes SHM. The time period of oscillation of charge q₀ will be","o":["√{4π³ε₀ma³;q₀Q}","√{q₀Q;4π³ε₀ma³}","√{2π³ε₀ma³;q₀Q}","√{8π³ε₀ma³;q₀Q}"],"c":0,"s":"Displace q₀ by x towards one charge. Net force towards the middle:\nF = kQq₀[1/(a − x)² − 1/(a + x)²] ≈ kQq₀ · 4x/a³ (for x << a).\nSo mω² = 4kQq₀/a³, ω² = Qq₀/(πε₀ m a³).\nT = 2π/ω = 2π√(πε₀ma³/(Qq₀)) = √(4π³ε₀ma³/(q₀Q))."},
{"y":"JEE Main 2022 · 27 Jul · Shift 2","tp":"ecl","st":"Force between point charges","q":"A charge of 4 μC is to be divided into two. The distance between the two divided charges is constant. The magnitude of the divided charges so that the force between them is maximum, will be","o":["1 μC and 3 μC","2 μC and 2 μC","0 and 4 μC","1.5 μC and 2.5 μC"],"c":1,"s":"Parts q and (4 − q) μC. Force ∝ q(4 − q).\nThe product is greatest when q = 4 − q, so q = 2 μC.\nBoth charges are 2 μC."},
{"y":"JEE Main 2022 · 29 Jul · Shift 2","tp":"ecl","st":"Force between point charges","q":"Two identical metallic spheres A and B when placed at certain distance in air repel each other with a force of F. Another identical uncharged sphere C is first placed in contact with A and then in contact with B and finally placed at the midpoint between spheres A and B. The force experienced by sphere C will be","o":["3F/2","3F/4","F","2F"],"c":1,"s":"Let A and B have charge q and be r apart: F = kq²/r².\nC touches A: A and C have q/2. C touches B: C and B have 3q/4.\nNow A = q/2, B = 3q/4, C = 3q/4, with C at distance r/2 from each.\nForce on C from A: k(3q/4)(q/2)/(r/2)² = (3/2)F, towards B (repulsion).\nForce on C from B: k(3q/4)(3q/4)/(r/2)² = (9/4)F, towards A.\nNet = 9F/4 − 3F/2 = 3F/4."},
{"y":"JEE Main 2022 · 24 Jun · Shift 2","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two identical charged particles each having a mass 10 g and charge 2.0 × 10⁻⁷ C are placed on a horizontal table with a separation of L between them such that they stay in limited equilibrium. If the coefficient of friction between each particle and the table is 0.25, find the value of L. [Use g = 10 m s⁻²]","o":["12 cm","10 cm","8 cm","5 cm"],"c":0,"s":"Limiting equilibrium: electric repulsion = maximum friction.\nkq²/L² = μmg = 0.25 × 0.01 × 10 = 0.025 N.\nL² = 9×10⁹ × 4×10⁻¹⁴/0.025 = 3.6×10⁻⁴/0.025 = 0.0144 m².\nL = 0.12 m = 12 cm."},
{"y":"JEE Main 2022 · 27 Jun · Shift 2","tp":"ecl","st":"Equilibrium and motion of charges","q":"Three identical charged balls each of charge 2C are suspended from a common point P by silk threads of 2 m each (as shown in figure). They form an equilateral triangle of side 1 m. The ratio of net force on a charged ball to the force between any two charged balls will be","fig":{"w":340,"h":190,"alt":"Three charged balls B1, B2, B3 hang by 2 m threads from a point P and form an equilateral triangle of side 1 m","d":[["l",140,22,200,22,"B"],["t",170,14,"P","m"],["l",170,22,110,150],["l",170,22,230,150],["l",170,22,170,116,"d"],["c",110,150,6,"F"],["c",230,150,6,"F"],["c",170,122,6,"F"],["l",116,150,224,150],["l",114,146,166,126],["l",226,146,174,126],["t",98,156,"B₁","e"],["t",240,156,"B₂"],["t",180,118,"B₃"],["t",128,78,"2 m","e"],["t",212,78,"2 m"],["t",170,172,"1 m","m"]]},"o":["1 : 1","1 : 4","√3 : 2","√3 : 1"],"c":3,"s":"Let the force between any two balls be F.\nOn one ball, two forces of size F act, along the two sides of the equilateral triangle. The angle between them is 60°.\nResultant = 2F cos30° = √3 F.\nRatio = √3F : F = √3 : 1."},
{"y":"JEE Main 2021 · 31 Aug · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two particles A and B having charges 20 μC and −5 μC respectively are held fixed with a separation of 5 cm. At what position a third charged particle should be placed so that it does not experience a net electric force?","fig":{"w":340,"h":110,"alt":"Charge 20 microcoulomb at A and charge minus 5 microcoulomb at B, 5 cm apart","d":[["c",70,55,6,"F"],["c",250,55,6,"F"],["t",70,35,"20 μC","m"],["t",250,35,"−5 μC","m"],["t",70,100,"A","m"],["t",250,100,"B","m"],["l",76,80,244,80,"b"],["t",160,74,"5 cm","m"]]},"o":["At 5 cm from −5 μC on the right side.","At 5 cm from 20 μC on the left side of system.","At 1.25 cm from a −5 μC between two charges.","At midpoint between two charges."],"c":0,"s":"The third charge must be outside the pair, next to the smaller charge (−5 μC), so that the forces can cancel.\nLet it be x cm beyond B, on the side away from A.\nk·20/(5 + x)² = k·5/x², so (5 + x)/x = 2.\nx = 5 cm.\nIt is at 5 cm from −5 μC, on the right side."},
{"y":"JEE Main 2021 · 20 Jul · Shift 1","tp":"ecl","st":"Force between point charges","q":"A certain charge Q is divided into two parts q and (Q − q). How should the charge Q and q be divided so that q and (Q − q) placed at a certain distance experience maximum electrostatic repulsion?","o":["Q = 2q","Q = {q;2}","Q = 4q","Q = 3q"],"c":0,"s":"Force ∝ q(Q − q). Its maximum is where d/dq[q(Q − q)] = Q − 2q = 0.\nSo q = Q/2, that is Q = 2q."},
{"y":"JEE Main 2021 · 27 Jul · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two identical tennis balls each having mass m and charge q are suspended from a fixed point by threads of length l. What is the equilibrium separation when each thread makes a small angle θ with the vertical?","o":["x = ({q²l²;2πε₀m²g²})^(1/3)","x = ({q²l;2πε₀mg})^(1/2)","x = ({q²l²;2πε₀m²g})^(1/3)","x = ({q²l;2πε₀mg})^(1/3)"],"c":3,"s":"For one ball: T cosθ = mg and T sinθ = kq²/x², so kq²/x² = mg tanθ.\nFor small θ, tanθ ≈ sinθ = (x/2)/l = x/(2l).\nkq²/x² = mg x/(2l), so x³ = 2lkq²/(mg) = q²l/(2πε₀mg).\nx = (q²l/(2πε₀mg))^(1/3)."},
{"y":"JEE Main 2021 · 24 Feb · Shift 2","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two electrons each are fixed at a distance '2d'. A third charge proton placed at the midpoint is displaced slightly by a distance x (x << d) perpendicular to the line joining the two fixed charges. Proton will execute simple harmonic motion having angular frequency (m = mass of charged particle) (q = magnitude of the charge of each particle)","o":["({πε₀md³;2q²})^(1/2)","({2q²;πε₀md³})^(1/2)","({q²;2πε₀md³})^(1/2)","({2πε₀md³;q²})^(1/2)"],"c":2,"s":"Each electron attracts the proton with force kq²/(d² + x²).\nThe components along the line cancel. The components towards the midpoint add up:\nF = 2 × kq²/(d² + x²) × x/√(d² + x²) ≈ 2kq²x/d³.\nSo mω² = 2kq²/d³, ω² = q²/(2πε₀md³).\nω = (q²/(2πε₀md³))^(1/2)."},
{"y":"JEE Main 2019 · 9 Jan · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"Three charges +Q, q, +Q are placed respectively, at distance, 0, d/2 and d from the origin, on the x-axis. If the net force experienced by +Q, placed at x = 0, is zero, then value of q is","o":["+Q/4","−Q/2","+Q/2","−Q/4"],"c":3,"s":"Force on the +Q at x = 0 from the other +Q (distance d) is repulsive, along −x: kQ²/d².\nThe force from q (distance d/2) must be attractive: kQq/(d/2)² = 4kQq/d² in magnitude.\nSo q is negative and 4|q| = Q.\nq = −Q/4."},
{"y":"JEE Main 2019 · 9 Jan · Shift 2","tp":"egs","st":"Non-uniform charge distributions","q":"Charge is distributed within a sphere of radius R with a volume charge density ρ(r) = {A;r²} e^(−2r/a), where A and a are constants. If Q is the total charge of this charge distribution, the radius R is","o":["a log( {1;1 − Q/(2πaA)} )","a log(1 − Q/(2πaA))","{a;2} log(1 − Q/(2πaA))","{a;2} log( {1;1 − Q/(2πaA)} )"],"c":3,"s":"Q = ∫₀ᴿ ρ·4πr² dr = 4πA ∫₀ᴿ e^(−2r/a) dr = 4πA·(a/2)(1 − e^(−2R/a)).\nSo Q = 2πaA(1 − e^(−2R/a)).\ne^(−2R/a) = 1 − Q/(2πaA).\nTake logs: R = −(a/2) log(1 − Q/(2πaA)) = (a/2) log(1/(1 − Q/(2πaA)))."},
{"y":"JEE Main 2019 · 12 Jan · Shift 1","tp":"evp","st":"Potential energy and work","q":"There is a uniform spherically symmetric surface charge density at a distance R₀ from the origin. The charge distribution is initially at rest and starts expanding because of mutual repulsion. The figure that represents best the speed V(R(t)) of the distribution as a function of its instantaneous radius R(t) is","fig":{"w":340,"h":240,"alt":"Four graphs of V against R starting at R0: (a) rises then falls, (b) S-shaped rise, (c) accelerating rise, (d) rise that flattens to a constant V0","d":[["t",20,20,"(a)"],["l",45,95,45,28,"a"],["l",45,95,160,95,"a"],["t",51,30,"V","s"],["t",163,98,"R","s"],["t",45,109,"R₀","ms"],["t",180,20,"(b)"],["l",205,95,205,28,"a"],["l",205,95,320,95,"a"],["t",211,30,"V","s"],["t",323,98,"R","s"],["t",205,109,"R₀","ms"],["t",20,135,"(c)"],["l",45,210,45,143,"a"],["l",45,210,160,210,"a"],["t",51,145,"V","s"],["t",163,213,"R","s"],["t",45,224,"R₀","ms"],["t",180,135,"(d)"],["l",205,210,205,143,"a"],["l",205,210,320,210,"a"],["t",211,145,"V","s"],["t",323,213,"R","s"],["t",205,224,"R₀","ms"],["p","M45,95 C70,35 95,35 115,65 S140,90 158,93"],["p","M205,95 C225,92 240,38 275,36 S300,35 318,35"],["p","M45,210 C85,205 125,185 150,140"],["p","M205,210 C207,160 240,148 305,142"],["l",205,141,305,141,"d"],["t",310,139,"V₀","s"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":3,"s":"Energy of the charged shell of radius R is Q²/(8πε₀R). It is released at rest at R₀.\nEnergy conservation: ½Mv² = (Q²/8πε₀)(1/R₀ − 1/R).\nSo v ∝ √(1 − R₀/R).\nv is zero at R = R₀, rises quickly, then flattens out and approaches a constant V₀ as R becomes very large (1/R → 0). That is graph (d)."},
{"y":"JEE Main 2018 · Online","tp":"ecl","st":"Force between point charges","q":"Two identical conducting spheres A and B, carry equal charge. They are separated by a distance much larger than their diameters, and the force between them is F. A third identical conducting sphere, C, is uncharged. Sphere C is first touched to A, then to B, and then removed. As a result, the force between A and B would be equal to","o":["{3F;8}","{F;2}","{3F;4}","F"],"c":0,"s":"Let each of A and B have charge q: F = kq²/r².\nC touches A: A = q/2. C (q/2) touches B: B = 3q/4.\nNew force = k(q/2)(3q/4)/r² = (3/8)F."},
{"y":"JEE Main 2015 · Online","tp":"ecn","st":"Induced charge and shielding","q":"Shown in the figure are two point charges +Q and −Q inside the cavity of a spherical shell. The charges are kept near the surface of the cavity on opposite sides of the centre of the shell. If σ₁ is the surface charge on the inner surface and Q₁ net charge on it and σ₂ the surface charge on the outer surface and Q₂ net charge on it then","fig":{"w":340,"h":200,"alt":"A thick spherical shell with a cavity; +Q near the upper right and -Q near the lower left of the cavity wall","d":[["c",170,100,90],["c",170,100,58],["c",205,66,3,"F"],["t",212,62,"+Q"],["c",135,134,3,"F"],["t",100,140,"−Q"]]},"o":["σ₁ ≠ 0, Q₁ ≠ 0 ; σ₂ ≠ 0, Q₂ ≠ 0","σ₁ ≠ 0, Q₁ ≠ 0 ; σ₂ = 0, Q₂ = 0","σ₁ ≠ 0, Q₁ = 0 ; σ₂ = 0, Q₂ = 0","σ₁ = 0, Q₁ = 0 ; σ₂ = 0, Q₂ = 0"],"c":2,"s":"The two point charges have zero total charge, so the inner surface carries a total induced charge Q₁ = 0 (shell neutral, Q₂ = 0 as well).\nThe charges sit near the surface of the cavity, so the induced charge on the inner surface is non-uniform and non-zero: σ₁ ≠ 0.\nThe outer surface has no net charge and the field outside is zero, so the outer surface has no charge at all: σ₂ = 0.\nSo σ₁ ≠ 0, Q₁ = 0; σ₂ = 0, Q₂ = 0."},
{"y":"JEE Main 2013","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two charges, each equal to q, are kept at x = −a and x = a on the x-axis. A particle of mass m and charge q₀ = {q;2} is placed at the origin. If charge q₀ is given a small displacement (y << a) along the y-axis, the net force acting on the particle is proportional to","o":["−1/y","y","−y","1/y"],"c":1,"s":"At height y, each fixed charge is at distance √(a² + y²) from q₀.\nThe x-components cancel. The y-components add, and since all charges are positive they push q₀ away from the axis:\nF_y = 2·k q q₀ y/(a² + y²)^(3/2) ≈ 2kqq₀ y/a³ for y << a.\nSo the force is proportional to y."},
{"y":"AIEEE 2011","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two identical charged spheres suspended from a common point by two massless strings of length l are initially a distance d (d << l) apart because of their mutual repulsion. The charge begins to leak from both the spheres at a constant rate. As a result the charges approach each other with a velocity v. Then as a function of distance x between them","o":["v ∝ x^(−1/2)","v ∝ x^(−1)","v ∝ x^(1/2)","v ∝ x"],"c":0,"s":"For small angles, equilibrium gives kq²/x² = mg·x/(2l), so x³ ∝ q² and q ∝ x^(3/2).\nCharge leaks at a constant rate: dq/dt = constant.\ndq/dt ∝ x^(1/2) dx/dt = constant, so v = dx/dt ∝ x^(−1/2)."},
{"y":"AIEEE 2010","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two identical charged spheres are suspended by strings of equal lengths. The strings make an angle of 30° with each other. When suspended in a liquid of density 0.8 g cm⁻³, the angle remains the same. If density of the material of the sphere is 1.6 g cm⁻³, the dielectric constant of the liquid is","o":["1","4","3","2"],"c":3,"s":"In air: tanθ = F/(mg). In the liquid: tanθ = (F/K)/(mg − upthrust).\nUpthrust/weight = 0.8/1.6 = 1/2, so the effective weight is mg/2.\nSame angle: F/(mg) = (F/K)/(mg/2), so 1 = 2/K.\nK = 2."},
{"y":"AIEEE 2009","tp":"ecl","st":"Equilibrium and motion of charges","q":"A charge Q is placed at each of the opposite corners of a square. A charge q is placed at each of the other two corners. If the net electrical force on Q is zero, then {Q;q} equals","o":["−2√2","−1","1","−{1;√2}"],"c":0,"s":"Let the side be a. On one Q: the other Q (diagonal, distance a√2) pushes along the diagonal with kQ²/(2a²).\nEach q (distance a) gives kQq/a²; the two are at right angles, so the resultant is √2 kQq/a² along the diagonal.\nFor zero net force, the q's must attract: Q²/2 = −√2 Qq.\nQ/q = −2√2."},
{"y":"IIT-JEE 2009","tp":"ecn","st":"Induced charge and shielding","q":"Three concentric metallic spherical shells of radii R, 2R, 3R, are given charges Q₁, Q₂, Q₃, respectively. It is found that the surface charge densities on the outer surfaces of the shells are equal. Then, the ratio of the charges given to the shells, Q₁ : Q₂ : Q₃, is","o":["1 : 2 : 3","1 : 3 : 5","1 : 4 : 9","1 : 8 : 18"],"c":1,"s":"Equal surface density on outer surfaces means outer-surface charges are in the ratio of areas, 1 : 4 : 9.\nOuter charge of shell 1 = Q₁. Of shell 2 = Q₁ + Q₂. Of shell 3 = Q₁ + Q₂ + Q₃.\nSo Q₁ = k, Q₁ + Q₂ = 4k, Q₁ + Q₂ + Q₃ = 9k.\nQ₂ = 3k, Q₃ = 5k.\nQ₁ : Q₂ : Q₃ = 1 : 3 : 5."},
{"y":"AIEEE 2007","tp":"ecl","st":"Charge, quantisation and conservation","q":"If g_E and g_M are the accelerations due to gravity on the surfaces of the earth and the moon respectively and if Millikan's oil drop experiment could be performed on the two surfaces, one will find the ratio {electronic charge on the moon;electronic charge on the earth} to be","o":["g_M/g_E","1","0","g_E/g_M"],"c":1,"s":"The charge on an electron is a fundamental constant of nature.\nIt does not depend on gravity or on the place where it is measured.\nSo the ratio is 1."},
{"y":"AIEEE 2004","tp":"ecl","st":"Equilibrium and motion of charges","q":"Four charges equal to −Q are placed at the four corners of a square and a charge q is at its centre. If the system is in equilibrium the value of q is","o":["−{Q;4}(1 + 2√2)","{Q;4}(1 + 2√2)","−{Q;2}(1 + 2√2)","{Q;2}(1 + 2√2)"],"c":1,"s":"Consider one corner charge −Q, square side a. Forces away from the square's centre:\nTwo neighbours: 2 × (kQ²/a²) cos45° = √2 kQ²/a².\nOpposite corner: kQ²/(2a²).\nThe centre charge is at a/√2, so it must attract with kQq/(a²/2) = 2kQq/a² (q positive).\n2Qq = (√2 + 1/2)Q², so q = (Q/4)(1 + 2√2)."},
{"y":"AIEEE 2003","tp":"ecl","st":"Force between point charges","q":"Three charges −q₁, +q₂ and −q₃ are placed as shown in the figure. The x-component of the force on −q₁ is proportional to","fig":{"w":340,"h":200,"alt":"Charge minus q1 at the origin, plus q2 at distance b along the x-axis, minus q3 at distance a up and to the left, making angle theta with the y-axis","d":[["l",140,160,140,20,"a"],["l",140,160,325,160,"a"],["t",147,24,"y"],["t",326,164,"x"],["l",140,160,80,56],["c",140,160,4,"F"],["c",80,56,4,"F"],["c",280,160,4,"F"],["t",96,178,"−q₁"],["t",50,52,"−q₃"],["t",272,150,"+q₂"],["t",100,112,"a","e"],["t",146,128,"θ"],["l",140,176,280,176,"b"],["t",210,192,"b","m"]]},"o":["{q₂;b²} − {q₃;a²} cosθ","{q₂;b²} + {q₃;a²} sinθ","{q₂;b²} + {q₃;a²} cosθ","{q₂;b²} − {q₃;a²} sinθ"],"c":1,"s":"Take −q₁ at the origin, +q₂ at distance b on the x-axis, and −q₃ at distance a along a line at angle θ to the y-axis.\n+q₂ attracts −q₁ along +x: kq₁q₂/b².\n−q₃ repels −q₁, pushing it away from −q₃, which has x-component +kq₁q₃ sinθ/a².\nBoth act along +x, so Fₓ ∝ q₂/b² + (q₃/a²) sinθ."},
{"y":"AIEEE 2002","tp":"ecl","st":"Equilibrium and motion of charges","q":"If a charge q is placed at the centre of the line joining two equal charges Q such that the system is in equilibrium then the value of q is","o":["Q/2","−Q/2","Q/4","−Q/4"],"c":3,"s":"Let each Q be a distance r from the centre. The Q's are 2r apart.\nFor one Q: repulsion from the other Q is kQ²/(2r)² = kQ²/(4r²).\nThe force from q must cancel it: kQq/r² = −kQ²/(4r²).\nq = −Q/4."},
{"y":"JEE Advanced 2020","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two identical non-conducting solid spheres of same mass and charge are suspended in air from a common point by two non-conducting, massless strings of same length. At equilibrium, the angle between the strings is α. The spheres are now immersed in a dielectric liquid of density 800 kg m⁻³ and dielectric constant 21. If the angle between the strings remains the same after the immersion, then","o":["electric force between the spheres remains unchanged","electric force between the spheres reduces","mass density of the spheres is 840 kg m⁻³","the tension in the strings holding the spheres remains same"],"c":[1,2],"s":"In the liquid the electric force becomes F/21, so it reduces: (b) is true and (a) is false.\nSame angle means F/W is unchanged, where W is the effective weight (W = mg in air, W' = mg(1 − 800/ρ) in the liquid).\nSo (F/21)/W' = F/(mg), giving 1/21 = 1 − 800/ρ.\n800/ρ = 20/21, so ρ = 840 kg m⁻³: (c) is true.\nBoth F and the weight fall, so the tension T = √(F² + W²) falls: (d) is false.\nCorrect: (b) and (c)."},
{"y":"JEE Advanced 2020","tp":"efl","st":"Field lines and motion in a field","q":"A uniform electric field, E⃗ = −400√3 ĵ N C⁻¹ is applied in a region. A charged particle of mass m carrying positive charge q is projected in this region with an initial speed of 2√10 × 10⁶ m s⁻¹. This particle is aimed to hit a target T, which is 5 m away from its entry point into the field as shown schematically in the figure. Take {q;m} = 10¹⁰ C kg⁻¹. Then","fig":{"w":340,"h":190,"alt":"Downward uniform field in a region; a particle enters at the left edge with speed u at angle theta to the horizontal dashed line and the target T is 5 m away on that line","d":[["l",90,18,90,172],["l",290,18,290,172],["l",115,24,115,170,"a"],["l",150,24,150,170,"a"],["l",185,24,185,170,"a"],["l",220,24,220,170,"a"],["l",255,24,255,170,"a"],["l",30,120,335,120,"d"],["l",90,120,112,78,"a"],["t",118,76,"u"],["p","M110,120 A20,20 0 0 0 100,103"],["t",114,114,"θ","s"],["c",262,120,3,"F"],["t",262,110,"T","m"],["l",90,140,262,140,"b"],["t",176,156,"5 m","m"],["t",300,60,"E⃗"]]},"o":["the particle will hit T if projected at an angle 45° from the horizontal","the particle will hit T if projected either at an angle 30° or 60° from the horizontal","time taken by the particle to hit T could be √{5;6} μs and √{5;2} μs","time taken by the particle to hit T is √{5;3} μs"],"c":[1,2],"s":"Acceleration a = qE/m = 10¹⁰ × 400√3 = 4√3 × 10¹² m/s², downward. The particle moves like a projectile.\nRange R = u² sin2θ/a = (4×10¹³) sin2θ/(4√3×10¹²) = (10/√3) sin2θ.\nR = 5 gives sin2θ = √3/2, so θ = 30° or 60°: (a) false, (b) true.\nTime t = 2u sinθ/a = (√10/√3) sinθ μs. For 30°: √(5/6) μs. For 60°: √(5/2) μs. So (c) true, (d) false.\nCorrect: (b) and (c)."},
{"y":"IIT-JEE 2009","tp":"ecl","st":"Equilibrium and motion of charges","q":"Under the influence of the Coulomb field of charge +Q, a charge −q is moving around it in an elliptical orbit. Find out the correct statement(s).","o":["The angular momentum of the charge −q is constant.","The linear momentum of the charge −q is constant.","The angular velocity of the charge −q is constant.","The linear speed of the charge −q is constant."],"c":0,"s":"The Coulomb force on −q always points along the line to +Q, so its torque about +Q is zero.\nHence the angular momentum of −q is constant: (a) is correct.\nThe direction of velocity changes, so the linear momentum is not constant.\nIn an ellipse the speed and the angular velocity change (faster near +Q).\nOnly (a) is correct."},
{"y":"IIT-JEE 1984","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two equal negative charge −q are fixed at points (0, −a) and (0, a) on y-axis. A positive charge Q is released from rest at the point (2a, 0) on the x-axis. The charge Q will","o":["execute simple harmonic motion about the origin","move to the origin remain at rest","move to infinity","execute oscillatory but not simple harmonic motion"],"c":3,"s":"At (x, 0) the y-components of the two forces cancel. The net force is along −x (attraction towards the origin):\nF = 2kqQ x/(x² + a²)^(3/2).\nThe charge is pulled to the origin, passes through it, and goes to the other side, so it oscillates.\nThe force is not proportional to x, because x = 2a is not small compared with a. So the motion is oscillatory but not simple harmonic."},
{"y":"JEE Main 2025 · 23 Jan · Shift 1","tp":"ecl","st":"Force between point charges","q":"A positive ion A and a negative ion B has charges 6.67 × 10⁻¹⁹ C and 9.6 × 10⁻¹⁰ C, and masses 19.2 × 10⁻²⁷ kg and 9 × 10⁻²⁷ kg respectively. At an instant, the ions are separated by a certain distance r. At that instant the ratio of the magnitudes of electrostatic force to gravitational force is P × 10⁻¹³, where the value of P is ______.\n(Take {1;4πε₀} = 9 × 10⁹ N m² C⁻¹ and universal gravitational constant as 6.67 × 10⁻¹¹ N m² kg⁻²)","n":5,"s":"The distance r cancels in the ratio.\nRatio = k q_A q_B/(G m_A m_B).\nThe 6.67 cancels between q_A and G. Numerically 9 × 9.6/(19.2 × 9) = 0.5, and the powers of ten combine to give 5 × 10⁴⁴.\nSo the coefficient is 5 and the official answer is P = 5. (With the powers of ten exactly as printed the ratio works out to 5 × 10⁴⁴; the printed 10⁻¹³ appears to be a misprint, but the coefficient matches the key.)"},
{"y":"JEE Main 2024 · 1 Feb · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two identical charged spheres are suspended by strings of equal lengths. The strings make an angle θ with each other. When suspended in water, the angle remains the same. If density of the material of the sphere is 1.5 g/cc, the dielectric constant of water will be ______. (Take density of water = 1 g/cc)","n":3,"s":"In air: tan(θ/2) = F/(mg). In water: tan(θ/2) = (F/K)/(mg − upthrust).\nUpthrust/weight = ρ_water/ρ_sphere = 1/1.5 = 2/3, so effective weight = mg/3.\nSame angle: F/mg = (F/K)/(mg/3), so 1 = 3/K.\nK = 3."},
{"y":"JEE Main 2024 · 27 Jan · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"A thin metallic wire having cross sectional area of 10⁻⁴ m² is used to make a ring of radius 30 cm. A positive charge of 2π C is uniformly distributed over the ring, while another positive charge of 30 pC is kept at the centre of the ring. The tension in the ring is ______ N; provided that the ring does not get deformed (neglect the influence of gravity).\n(given, {1;4πε₀} = 9 × 10⁹ SI units)","n":3,"s":"Take a small arc of the ring subtending angle dθ. Its charge is dq = (2π/2π)dθ = dθ coulomb.\nCentre charge q = 30 pC repels it: dF = k q dq/R² (outwards).\nTension balance for the small arc: 2T sin(dθ/2) ≈ T dθ = dF.\nT = k q /R² = 9×10⁹ × 30×10⁻¹² / (0.3)² = 0.27/0.09 = 3 N.\n(As in the official answer, only the force from the central charge is used.)"},
{"y":"JEE Main 2024 · 30 Jan · Shift 2","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two identical charged spheres are suspended by strings of equal lengths. The strings make an angle if 37° with each other. When suspended in a liquid of density 0.7 g cm⁻³, the angle remains same. If density of material of the sphere is 1.4 g cm⁻³, the dielectric constant of the liquid is ______. (tan37° = {3;4})","n":2,"s":"Upthrust/weight = 0.7/1.4 = 1/2, so the effective weight in the liquid is mg/2.\nIn air: tan(θ/2) = F/(mg). In liquid: tan(θ/2) = (F/K)/(mg/2).\nSame angle gives 1 = 2/K.\nK = 2. (The angle 37° is not needed.)"},
{"y":"JEE Main 2023 · 11 Apr · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"As shown in the figure, a configuration of two equal point charges (q₀ = +2 μC) is placed on an inclined plane. Mass of each point charge is 20 g. Assume that there is no friction between charge and plane. For the system of two point charges to be in equilibrium (at rest) the height h = x × 10⁻³ m. The value of x is ______.\n(Take {1;4πε₀} = 9 × 10⁹ N m² C⁻², g = 10 m s⁻²)","fig":{"w":340,"h":180,"alt":"Right-angled triangle with a 30 degree angle at the lower right; a charge q0 on the slope at height h and another q0 at the foot of the slope","d":[["l",60,20,285,150,"B"],["l",60,20,60,150,"d"],["l",60,150,300,150,"d"],["c",110,49,5,"F"],["c",285,150,5,"F"],["t",118,42,"q₀"],["t",292,140,"q₀"],["l",110,52,110,148,"bd"],["t",118,106,"h"],["t",222,144,"30°","s"]]},"n":300,"s":"The lower charge is at the foot of the incline (height 0); the upper charge is at height h along the slope, distance r from it.\nFor the upper charge, along the slope: kq₀²/r² = mg sin30°.\nr² = 9×10⁹ × 4×10⁻¹² / (0.02 × 10 × 0.5) = 0.036/0.1 = 0.36, so r = 0.6 m.\nh = r sin30° = 0.3 m = 300 × 10⁻³ m.\nx = 300."},
{"y":"JEE Main 2023 · 13 Apr · Shift 2","tp":"ecl","st":"Force between point charges","q":"Three point charges q, −2q and 2q are placed on x-axis at a distance x = 0, x = {3;4}R and x = R respectively from origin as shown. If q = 2 × 10⁻⁶ C and R = 2 cm, the magnitude of net force experienced by the charge −2q is ______ N.","fig":{"w":340,"h":120,"alt":"Charges q at x = 0, minus 2q at 3R/4 and 2q at R along the x-axis","d":[["l",20,50,325,50,"a"],["c",40,50,4,"F"],["c",205,50,4,"F"],["c",260,50,4,"F"],["t",40,38,"q","m"],["t",205,38,"−2q","m"],["t",260,38,"2q","m"],["t",328,54,"x","s"],["t",40,66,"x = 0","ms"],["l",205,50,205,100,"d"],["l",260,50,260,100,"d"],["l",40,80,205,80,"b"],["t",122,76,"3R/4","ms"],["l",40,100,260,100,"b"],["t",150,114,"R","m"]]},"n":5440,"s":"On −2q: q is at distance 3R/4 and attracts it towards the left: F₁ = k(2q)(q)/(3R/4)² = 32kq²/(9R²).\n2q is at distance R/4 and attracts it towards the right: F₂ = k(2q)(2q)/(R/4)² = 64kq²/R².\nNet = (64 − 32/9)kq²/R² = (544/9)kq²/R².\nkq²/R² = 9×10⁹ × 4×10⁻¹²/(4×10⁻⁴) = 90 N.\nNet = (544/9) × 90 = 5440 N."},
{"y":"JEE Main 2023 · 1 Feb · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Two equal positive point charges are separated by a distance 2a. The distance of a point from the centre of the line joining two charges on the equatorial line (perpendicular bisector) at which force experienced by a test charge q₀ become maximum is {a;√x}. The value of x is ______.","n":2,"s":"At distance r on the bisector: E = 2kq r/(a² + r²)^(3/2).\nFor maximum E set dE/dr = 0: (a² + r²) − 3r² = 0, so r = a/√2.\nComparing with a/√x gives x = 2."},
{"y":"JEE Main 2023 · 1 Feb · Shift 2","tp":"egs","st":"Gauss's law and symmetric bodies","q":"A cubical volume is bounded by the surfaces x = 0, x = a, y = 0, y = a, z = 0, z = a. The electric field in the region is given by E⃗ = E₀x î. Where E₀ = 4 × 10⁴ NC⁻¹m⁻¹. If a = 2 cm, the charge contained in the cubical volume is Q × 10⁻¹⁴ C. The value of Q is ______.\n(Take ε₀ = 9 × 10⁻¹² C²/Nm²)","n":288,"s":"The field has only an x-component, so only the faces at x = 0 and x = a carry flux.\nAt x = 0, E = 0: no flux. At x = a, E = E₀a over area a²: flux = E₀a³.\nGauss's law: q = ε₀E₀a³ = 9×10⁻¹² × 4×10⁴ × (0.02)³ = 9×10⁻¹² × 4×10⁴ × 8×10⁻⁶.\nq = 2.88×10⁻¹² C = 288 × 10⁻¹⁴ C.\nQ = 288."},
{"y":"JEE Main 2023 · 29 Jan · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"A point charge q₁ = 4q₀ is placed at origin. Another point charge q₂ = −q₀ is placed at x = 12 cm. Charge of proton is q₀. The proton is placed on x axis so that the electrostatic force on the proton is zero. In this situation, the position of the proton from the origin is ______ cm.","n":24,"s":"The net force on the proton can vanish only outside the two charges, on the side of the smaller charge (q₂), at distance d beyond x = 12 cm.\nk·4q₀/(12 + d)² = k·q₀/d², so (12 + d) = 2d.\nd = 12 cm, so the position is 12 + 12 = 24 cm from the origin."},
{"y":"JEE Main 2022 · 26 Jul · Shift 2","tp":"ecl","st":"Force between point charges","q":"Three point charges of magnitude 5 μC, 0.16 μC and 0.3 μC are located at the vertices A, B, C of a right angled triangle whose sides are AB = 3 cm, BC = 3√2 cm and CA = 3 cm and point A is the right angle corner. Charge at point A experiences ______ N of electrostatic force due to the other two charges.","n":17,"s":"The charge 5 μC at A is acted on by forces along AB and AC, which are perpendicular.\nF_B = 9×10⁹ × 5×10⁻⁶ × 0.16×10⁻⁶/(0.03)² = 8 N.\nF_C = 9×10⁹ × 5×10⁻⁶ × 0.3×10⁻⁶/(0.03)² = 15 N.\nNet = √(8² + 15²) = 17 N."},
{"y":"JEE Main 2021 · 25 Jul · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"A particle of mass 1 mg and charge q is lying at the mid-point of two stationary particles kept at a distance 2 m when each is carrying same charge q. If the free charged particle is displaced from its equilibrium position through distance 'x' (x << 1 m). The particle executes SHM. Its angular frequency of oscillation will be ______ × 10⁵ rad/s if q² = 10 C².","n":6000,"s":"Displace by x: net restoring force = kq²[1/(1 − x)² − 1/(1 + x)²] ≈ 4kq²x (distances 1 m from the middle).\nmω² = 4kq², so ω² = 4 × 9×10⁹ × 10/10⁻⁶ = 3.6×10¹⁷.\nω = 6×10⁸ rad/s = 6000 × 10⁵ rad/s.\nAnswer: 6000."},
{"y":"JEE Main 2021 · 18 Mar · Shift 2","tp":"ecl","st":"Force between point charges","q":"An infinite number of point charges, each carrying 1 μC charge, are placed along the y-axis at y = 1 m, 2 m, 4 m, 8 m ......... The total force on a 1 C point charge, placed at the origin, is x × 10³ N. The value of x, to the nearest integer, is ______.\n[Take {1;4πε₀} = 9 × 10⁹ N m²/C²]","n":12,"s":"All forces on the 1 C charge point the same way, along the y-axis, so they add.\nF = k(1)(10⁻⁶)[1/1² + 1/2² + 1/4² + 1/8² + ...] = 9×10³ × (1 + 1/4 + 1/16 + ...).\nThe series is geometric with ratio 1/4: sum = 1/(1 − 1/4) = 4/3.\nF = 9×10³ × 4/3 = 12 × 10³ N, so x = 12."},
{"y":"JEE Main 2021 · 25 Feb · Shift 2","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two small spheres each of mass 10 mg are suspended from a point by threads 0.5 m long. They are equally charged and repel each other to a distance of 0.20 m. The charge on each of the sphere is {a;21} × 10⁻⁸ C. The value of 'a' will be ______. [Given g = 10 m s⁻²]","n":20,"s":"Each sphere is 0.1 m from the vertical, so sinθ = 0.1/0.5 and tanθ = 0.1/√(0.25 − 0.01) = 1/√24.\nBalance: kq²/(0.2)² = mg tanθ = 10×10⁻⁶ × 10 /√24 = 2.04×10⁻⁵ N.\nq² = 2.04×10⁻⁵ × 0.04/(9×10⁹) = 9.07×10⁻¹⁷, so q = 9.52×10⁻⁹ C = (20/21) × 10⁻⁸ C.\nSo a = 20."},
{"y":"JEE Main 2021 · 25 Feb · Shift 2","tp":"ecn","st":"Charge sharing and earthing","q":"Two identical conducting spheres with negligible volume have 2.1 nC and −0.1 nC charges, respectively. They are brought into contact and then separated by a distance of 0.5 m. The electrostatic force acting between the spheres is ______ × 10⁻⁹ N.\n[Given: 4πε₀ = {1;9×10⁹} SI unit]","n":36,"s":"On contact the total charge 2.1 − 0.1 = 2.0 nC is shared equally by the two identical spheres.\nEach sphere now carries 1.0 nC = 10⁻⁹ C.\nF = kq²/r² = 9×10⁹ × (10⁻⁹)² / (0.5)² = 9×10⁻⁹ / 0.25 = 36×10⁻⁹ N.\nThe force is 36 × 10⁻⁹ N, so the answer is 36."},
{"y":"IIT-JEE 2011","tp":"ecl","st":"Equilibrium and motion of charges","q":"Four point charges, each of +q, are rigidly fixed at the four corners of a square planar soap film of side a. The surface tension of the soap film is γ. The system of charges and planar film are in equilibrium, and a = k[{q²;γ}]^(1/N), where k is a constant. Then N is ______.","n":3,"s":"Use dimensions. Surface tension γ is force per unit length, so the film pulls with a force of order γa.\nThe electric force on a corner charge is of order q²/(4πε₀a²).\nIn equilibrium q²/(ε₀a²) ~ γa, so a³ ~ q²/(ε₀γ).\nThus a = k (q²/γ)^(1/3), where the constant k also contains ε₀.\nSo N = 3."},
{"y":"JEE Advanced 2014","tp":"ecl","st":"Statements, matching and subjective","q":"Four charges Q₁, Q₂, Q₃ and Q₄ of same magnitude are fixed along the x-axis at x = −2a, −a, +a and +2a respectively. A positive charge q is placed on the positive y-axis at a distance b > 0. Four options of the signs of these charges are given in List I. The direction of the forces on the charge q is given in List II. Match List I with List II and select the correct answer using the code given below the lists.\nList I\nP. Q₁, Q₂, Q₃, Q₄ all positive\nQ. Q₁, Q₂ positive; Q₃, Q₄ negative\nR. Q₁, Q₄ positive; Q₂, Q₃ negative\nS. Q₁, Q₃ positive; Q₂, Q₄ negative\nList II\n1. +x\n2. −x\n3. +y\n4. −y","fig":{"w":340,"h":190,"alt":"Charges Q1, Q2, Q3, Q4 on the x-axis at -2a, -a, +a and +2a, and the positive charge q on the y-axis at height b above the origin","d":[["l",20,150,325,150,"a"],["t",328,154,"x","s"],["l",190,150,190,50,"d"],["c",90,150,5,"F"],["c",140,150,5,"F"],["c",240,150,5,"F"],["c",290,150,5,"F"],["t",90,172,"Q₁","ms"],["t",140,172,"Q₂","ms"],["t",240,172,"Q₃","ms"],["t",290,172,"Q₄","ms"],["t",90,138,"−2a","ms"],["t",140,138,"−a","ms"],["t",240,138,"+a","ms"],["t",290,138,"+2a","ms"],["c",190,50,6,"F"],["t",200,46,"q (0, b)"],["l",190,50,190,20,"a"],["t",196,22,"y","s"],["t",180,104,"b","es"]]},"o":["P-3, Q-1, R-4, S-2","P-4, Q-2, R-3, S-1","P-3, Q-1, R-2, S-4","P-4, Q-2, R-1, S-3"],"c":0,"s":"Like charges repel, unlike charges attract. Take b not much larger than a, so the nearer charges Q₂, Q₃ matter more than Q₁, Q₄.\nP: all repel q; the x-parts cancel by symmetry, so the force is along +y. P → 3.\nQ: Q₁, Q₂ (positive, on the left) push q to the right; Q₃, Q₄ (negative, on the right) pull q to the right. Force is +x. Q → 1.\nR: the set-up is symmetric about the y-axis, so the force is along y. The near negative charges Q₂, Q₃ pull q down and win over the far positive ones. R → 4 (−y).\nS: Q₂ (negative, at −a) pulls q to the left and Q₃ (positive, at +a) pushes q to the left; these near charges win. S → 2 (−x).\nCode P-3, Q-1, R-4, S-2 is option (a)."},
{"y":"IIT-JEE 2011","tp":"efl","st":"Field lines and motion in a field","q":"Comprehension: A dense collection of equal number of electrons and positive ions is called neutral plasma. Certain solids containing fixed positive ions surrounded by free electrons can be treated as neutral plasma. Let N be the number density of free electrons, each of mass m. When the electrons are subjected to an electric field, they are displaced relatively away from the heavy positive ions. If the electric field becomes zero, the electrons begin to oscillate about the positive ions with a natural angular frequency ωₚ, which is called the plasma frequency. To sustain the oscillations, a time varying electric field needs to be applied that has an angular frequency ω, where a part of the energy is absorbed and a part of the energy is reflected. As ω approaches ωₚ, all the free electrons are set to resonance together and all the energy is reflected. This is the explanation of high reflectivity of metals.\nTaking the electronic charge as e and the permittivity as ε₀, use dimensional analysis to determine the correct expression for ωₚ.","o":["√{Ne;mε₀}","√{mε₀;Ne}","√{Ne²;mε₀}","√{mε₀;Ne²}"],"c":2,"s":"ωₚ has the dimension of frequency, so ωₚ² has dimension T⁻².\nCoulomb's law gives e²/ε₀ = force × length², which is kg m³ s⁻².\nDivide by m (kg): e²/(mε₀) has dimension m³ s⁻².\nMultiply by N (m⁻³): Ne²/(mε₀) has dimension s⁻². This matches ωₚ².\nThe other three expressions do not reduce to s⁻². So ωₚ = √(Ne²/(mε₀)), option (c)."},
{"y":"IIT-JEE 2011","tp":"efl","st":"Field lines and motion in a field","q":"(Same plasma passage as the previous question: all the energy is reflected when the wave frequency equals the plasma frequency ωₚ.)\nEstimate the wavelength at which plasma reflection will occur for a metal having the density of electrons N ≈ 4 × 10²⁷ m⁻³. Take ε₀ ≈ 10⁻¹¹ and m ≈ 10⁻³⁰, where these quantities are in proper SI units.","o":["800 nm","600 nm","300 nm","200 nm"],"c":1,"s":"Reflection occurs when ω = ωₚ = √(Ne²/(mε₀)), with e = 1.6×10⁻¹⁹ C.\nNe² = 4×10²⁷ × 2.56×10⁻³⁸ = 1.02×10⁻¹⁰ and mε₀ = 10⁻⁴¹.\nωₚ = √(1.02×10³¹) ≈ 3.2×10¹⁵ rad/s.\nλ = 2πc/ωₚ = 2π × 3×10⁸ / 3.2×10¹⁵ ≈ 5.9×10⁻⁷ m.\nThis is about 600 nm, option (b)."},
{"y":"IIT-JEE 2001","tp":"ecl","st":"Equilibrium and motion of charges","q":"A small ball of mass 2 × 10⁻³ kg having a charge of 1 μC is suspended by a string of length 0.8 m. Another identical ball having the same charge is kept at the point of suspension. Determine the minimum horizontal velocity (in m/s) which should be imparted to the lower ball so that it can make complete revolution. (Take g = 10 m/s²)","n":5.86,"s":"The fixed charge at the point of suspension repels the ball with a constant radial force F = kq²/L² = 9×10⁹ × (10⁻⁶)² / 0.8² = 1.41×10⁻² N, directed outward along the string. It does no work on the circular path.\nWeight mg = 2×10⁻³ × 10 = 2×10⁻² N.\nMinimum speed at the top (tension zero): mv²/L = mg − F, so v_top² = L(g − F/m) = 0.8 × (10 − 7.03) = 2.375 m²/s².\nEnergy from bottom to top: v² = v_top² + 4gL = 2.375 + 32 = 34.375.\nv = √34.375 ≈ 5.86 m/s."},
{"y":"IIT-JEE 1996","tp":"ecn","st":"Charge sharing and earthing","q":"Two isolated metallic solid spheres of radii R and 2R are charged such that both of these have same charge density σ. The spheres are located far away from each other and connected by a thin conducting wire. Find the new charge density on the bigger sphere.","a":"5σ/6","s":"Initial charges: q₁ = σ × 4πR² and q₂ = σ × 4π(2R)² = 4q₁. Total charge = 5q₁ = 20πR²σ.\nThe wire makes the potentials equal: kq₁'/R = kq₂'/(2R), so q₂' = 2q₁'.\nHence the bigger sphere gets 2/3 of the total: q₂' = (2/3)(20πR²σ) = 40πR²σ/3.\nNew density σ' = q₂'/(4π(2R)²) = (40πR²σ/3)/(16πR²) = 5σ/6."},
{"y":"IIT-JEE 1988","tp":"ecl","st":"Equilibrium and motion of charges","q":"Three particles, each of mass 1 g and carrying a charge q, are suspended from a common point by insulated massless strings, each 100 cm long. If the particles are in equilibrium and are located at the corners of an equilateral triangle of side length 3 cm, calculate the charge q on each particle. (Take g = 10 m/s².)","a":"3.16×10⁻⁹ C","s":"The three particles hang symmetrically. Each is at distance r = 3/√3 = √3 cm = 1.73×10⁻² m from the vertical axis.\nFor each string, tanθ = r/√(L² − r²) ≈ 1.73×10⁻² (L = 1 m).\nOne particle is pushed outward by the other two: each exerts F = kq²/s² (s = 3 cm), and the outward resultant is 2F cos30° = √3 F.\nHorizontal balance: √3 kq²/s² = mg tanθ.\nq² = mg tanθ × s² / (√3 k) = (10⁻³ × 10 × 1.73×10⁻² × 9×10⁻⁴) / (1.73 × 9×10⁹) = 10⁻¹⁷.\nq = 3.16×10⁻⁹ C."},
{"y":"IIT-JEE 1978","tp":"ecl","st":"Statements, matching and subjective","q":"A rigid insulated wire frame in the form of a right angled triangle ABC, is set in a vertical plane as shown in the figure. Two beads of equal masses m each and carrying charges q₁ and q₂ are connected by a cord of length l and can slide without friction on the wires. Considering the case when the beads are stationary, determine\n(a) (i) the angle α\n(ii) the tension in the cord\n(iii) the normal reaction on the beads.\n(b) If the cord is now cut, what are the values of the charges for which the beads continue to remain stationary?","fig":{"w":340,"h":230,"alt":"Right angled triangle ABC with BC horizontal, angle B 30 degrees, angle C 60 degrees and the right angle at A. Bead P with charge q1 on AB and bead Q with charge q2 on AC are joined by a cord of length l. Angle alpha is at P between PA and the cord.","d":[["l",40,200,300,200],["l",40,200,235,87],["l",235,87,300,200],["l",183,117,287,177],["c",183,117,6,"F"],["c",287,177,6,"F"],["t",240,80,"A"],["t",24,212,"B"],["t",304,212,"C"],["t",172,112,"P, q₁","e"],["t",296,181,"Q, q₂"],["t",70,196,"30°"],["t",262,196,"60°"],["t",194,112,"α"],["t",238,144,"l"]]},"a":"(a) (i) α = 60°  (ii) T = q₁q₂/(4πε₀l²) + mg  (iii) R₁ = √3 mg, R₂ = mg  (b) Unlike charges","s":"Let N be the net pull along the line PQ on each bead (tension minus Coulomb repulsion). It is the same for both beads. Let α = angle APQ; the angle at A is 90°, so angle AQP = 90° − α.\nBead P (wire AB at 30° to the horizontal): along the wire, N cosα = mg sin30°.\nBead Q (wire AC at 60° to the horizontal): along the wire, N sinα = mg sin60°.\nDividing: tanα = sin60°/sin30° = √3, so α = 60°. Then N = mg (sin30°/cos60° = 1).\nTension: T − q₁q₂/(4πε₀l²) = mg, so T = q₁q₂/(4πε₀l²) + mg.\nNormal reactions (perpendicular to the wires): R₁ = mg cos30° + N sin60° = √3 mg. R₂ = mg cos60° + N sin30° = mg.\n(b) Without the cord the pull N = mg must come from the Coulomb force alone, so it must be attraction: the charges are unlike, with q₁q₂/(4πε₀l²) = mg in magnitude."},
{"y":"IIT-JEE 1983","tp":"ecl","st":"Statements, matching and subjective","q":"Two identical metallic spheres of exactly equal masses are taken. One is given a positive charge Q coulomb and the other an equal negative charge. Their masses after charging are different.","o":["True","False"],"c":0,"s":"Charging a metal sphere changes the number of electrons on it.\nA positive charge Q means electrons were removed, so that sphere loses mass (Q/e) × mₑ.\nThe negatively charged sphere gains the same number of electrons, so its mass increases by the same amount.\nSo the masses become different. The statement is True."},
{"y":"IIT-JEE 1992","tp":"ecl","st":"Statements, matching and subjective","q":"Five point charges, each of value +q coulomb, are placed on five vertices of a regular hexagon of side L metre. The magnitude of the force on the point charge of value −q coulomb placed at the centre of the hexagon is ______ newton.","a":"(1/4πε₀)(q²/L²) N","s":"The centre of a regular hexagon is at distance L from each vertex.\nIf all six vertices held +q, the forces on the centre charge would cancel in opposite pairs, giving zero.\nSo the force from the five charges is equal and opposite to the force the missing sixth charge would give.\nThat force has magnitude (1/4πε₀) q²/L².\nSo the force is (1/4πε₀)(q²/L²) newton, pointing away from the empty vertex."},
{"y":"IIT-JEE 1986","tp":"ecl","st":"Statements, matching and subjective","q":"Two small balls having equal positive charge Q (coulomb) on each are suspended by two insulating strings of equal length L (metre) from a hook fixed to a stand. The whole set-up is taken in a satellite into space where there is no gravity (state of weightlessness). The angle between the two strings is ______ and the tension in each string is ______ newton.","a":"180°, (1/4πε₀)(Q²/4L²) N","s":"With no weight, each ball is acted on only by the string tension and the Coulomb repulsion.\nFor equilibrium these must be along the same line, so the strings are in one straight line with the balls on opposite sides of the hook: the angle is 180°.\nThe distance between the balls is 2L.\nT = (1/4πε₀) Q²/(2L)² = (1/4πε₀)(Q²/4L²) newton."},
{"y":"JEE Main 2025 · 2 Apr · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"A small bob of mass 100 mg and charge +10 μC is connected to an insulating string of length 1 m. It is brought near an infinitely long non-conducting sheet of charge density 'σ' as shown in the figure. If the string subtends an angle of 45° with the sheet at equilibrium, the charge density of the sheet will be\n(Given, ε₀ = 8.85×10⁻¹² F/m and acceleration due to gravity, g = 10 m/s²)","fig":{"w":340,"h":245,"alt":"A vertical charged sheet with plus signs. A string of length 1 m is attached at the top of the sheet and holds a +10 microcoulomb bob at 45 degrees to the sheet, away from the sheet.","d":[["l",60,20,60,225,"B"],["t",46,44,"+","m"],["t",46,74,"+","m"],["t",46,104,"+","m"],["t",46,134,"+","m"],["t",46,164,"+","m"],["t",46,194,"+","m"],["t",46,224,"+","m"],["t",60,240,"+σ","m"],["t",70,14,"A"],["l",60,40,159,139],["c",159,139,8,"F"],["t",174,143,"+10 μC"],["t",75,86,"45°"],["t",122,80,"l = 1 m"]]},"o":["0.885 nC/m²","17.7 nC/m²","885 nC/m²","1.77 nC/m²"],"c":3,"s":"The bob is in equilibrium under its weight mg (down), the string tension, and the electric force qE (horizontal, away from the sheet).\nThe string is at 45° to the vertical sheet, so tan45° = qE/mg, which gives qE = mg.\nE = mg/q = (10⁻⁴ kg × 10)/(10×10⁻⁶ C) = 100 N/C.\nFor a non-conducting sheet E = σ/(2ε₀), so σ = 2ε₀E = 2 × 8.85×10⁻¹² × 100 = 1.77×10⁻⁹ C/m².\nσ = 1.77 nC/m², option (d)."},
{"y":"JEE Main 2025 · 2 Apr · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Consider two infinitely large plane parallel conducting plates as shown in the figure. The plates are uniformly charged with a surface charge density +σ and −2σ. The force experienced by a point charge +q placed at the mid point of the plates will be","fig":{"w":340,"h":170,"alt":"Two large parallel plates a distance d apart: the left plate carries +sigma, the right plate carries -2 sigma. A charge +q sits at the midpoint, d/2 from each plate.","d":[["l",90,20,90,140,"B"],["l",250,20,250,140,"B"],["t",90,158,"+σ","m"],["t",250,158,"−2σ","m"],["c",170,80,5,"F"],["t",170,68,"+q","ms"],["l",90,105,170,105,"b"],["t",130,100,"d/2","ms"],["l",170,105,250,105,"b"],["t",210,100,"d/2","ms"]]},"o":["{σq;4ε₀}","{σq;2ε₀}","{3σq;4ε₀}","{3σq;2ε₀}"],"c":3,"s":"For large parallel conducting plates the field between them is E = (σ₁ − σ₂)/(2ε₀), where σ₁ and σ₂ are the total charge per unit area on the two plates.\nHere σ₁ = +σ and σ₂ = −2σ, so E = (σ + 2σ)/(2ε₀) = 3σ/(2ε₀).\nThe field is uniform between the plates and points from the +σ plate to the −2σ plate.\nForce on +q: F = qE = 3σq/(2ε₀), directed towards the −2σ plate. Option (d)."},
{"y":"JEE Main 2025 · 2 Apr · Shift 2","tp":"efl","st":"Field of point charges and distributions","q":"Consider a circular loop that is uniformly charged and has a radius a√2. Find the position along the positive z-axis of the cartesian coordinate system where the electric field is maximum if the ring was assumed to be placed in xy plane at the origin.","o":["0","a","{a;√2}","{a;2}"],"c":1,"s":"On the axis of a ring of radius R, E = kQz/(z² + R²)^(3/2).\nFor the maximum, dE/dz = 0: (z² + R²) − 3z² = 0, so z = R/√2.\nHere R = a√2, so z = a√2/√2 = a.\nThe field is maximum at z = a, option (b)."},
{"y":"JEE Main 2025 · 4 Apr · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Two infinite identical charged sheets and a charged spherical body of charge density 'ρ' are arranged as shown in the figure. Then the correct relation between the electric fields at A, B, C and D points is","fig":{"w":340,"h":175,"alt":"Two parallel positively charged sheets, each with plus sigma. A positively charged sphere of radius R with density rho lies between them, nearer the right sheet. Points C and D lie 2 cm outside the left and right sheets. Point B is between the left sheet and the sphere and point A is on the left surface of the sphere.","d":[["l",110,25,110,150,"B"],["l",230,25,230,150,"B"],["t",100,44,"+","m"],["t",240,44,"+","m"],["t",100,64,"+","m"],["t",240,64,"+","m"],["t",100,84,"+","m"],["t",240,84,"+","m"],["t",100,104,"+","m"],["t",240,104,"+","m"],["t",100,124,"+","m"],["t",240,124,"+","m"],["t",100,144,"+","m"],["t",240,144,"+","m"],["t",110,16,"+σ","m"],["t",230,16,"+σ","m"],["c",185,88,30],["t",185,92,"+ρ","m"],["t",198,76,"R","s"],["c",155,88,3,"F"],["t",155,80,"A","ms"],["c",132,88,3,"F"],["t",132,80,"B","ms"],["c",70,88,3,"F"],["t",70,80,"C","ms"],["c",270,88,3,"F"],["t",270,80,"D","ms"],["l",70,128,110,128,"b"],["t",90,160,"2 cm","ms"],["l",230,128,270,128,"b"],["t",250,160,"2 cm","ms"]]},"o":["E⃗_A = E⃗_B ; E⃗_C = E⃗_D","|E⃗_A| = |E⃗_B| ; E⃗_C > E⃗_D","E⃗_A > E⃗_B ; E⃗_C = E⃗_D","E⃗_C ≠ E⃗_D ; E⃗_A > E⃗_B"],"c":3,"s":"Each sheet gives a field σ/(2ε₀) pointing away from it.\nBetween the two sheets (A and B) the sheet fields are equal and opposite and cancel. Only the sphere acts there. Its field falls with distance, and A is closer to the sphere than B, so E_A > E_B.\nOutside the sheets (C and D) the two sheet fields add to the same value σ/ε₀ on both sides.\nThe sphere is not centred between the sheets: it lies nearer D, so its field is larger at D than at C. Hence E_C ≠ E_D.\nThe correct relation is E_C ≠ E_D and E_A > E_B, option (d)."},
{"y":"JEE Main 2025 · 4 Apr · Shift 1","tp":"efl","st":"Electric dipole","q":"Two small spherical balls of mass 10 g each with charges −2 μC and 2 μC are attached to two ends of very light rigid rod of length 20 cm. The arrangement is now placed near an infinite non-conducting charge sheet with uniform charge density of 100 μC/m² such that length of rod makes an angle of 30° with electric field generated by charge sheet. Net torque acting on the rod is\n(Take ε₀ : 8.85 × 10⁻¹² C²/N m²)","o":["112 N m","11.2 N m","1.12 N m","2.24 N m"],"c":2,"s":"Field of a non-conducting sheet: E = σ/(2ε₀) = 100×10⁻⁶/(2 × 8.85×10⁻¹²) = 5.65×10⁶ N/C (uniform).\nDipole moment p = q × length = 2×10⁻⁶ × 0.2 = 4×10⁻⁷ C m.\nTorque τ = pE sinθ = 4×10⁻⁷ × 5.65×10⁶ × sin30° = 1.13 N m.\nThis is ≈ 1.12 N m, option (c)."},
{"y":"JEE Main 2025 · 4 Apr · Shift 2","tp":"efl","st":"Field of point charges and distributions","q":"A metallic ring is uniformly charged as shown in the figure. AC and BD are two mutually perpendicular diameters. Electric field due to arc AB at 'O' is 'E' in magnitude. What would be the magnitude of electric field at 'O' due to arc ABC?","fig":{"w":340,"h":175,"alt":"A uniformly charged ring with centre O. A is at the top, B at the right, C at the bottom and D at the left; AC and BD are perpendicular diameters and the arc AB is marked in bold.","d":[["c",170,88,60],["l",170,28,170,148],["l",110,88,230,88],["p","M170 28 A60 60 0 0 1 230 88","B"],["t",170,20,"A","ms"],["t",170,166,"C","ms"],["t",238,92,"B"],["t",102,92,"D","e"],["t",176,102,"O","s"]]},"o":["2E","√2 E","Zero","E/2"],"c":1,"s":"The ring is divided by the diameters into four equal quarter arcs.\nArc ABC is two quarter arcs: AB and BC. Each gives a field of magnitude E at O.\nThe field of a symmetric arc points along its bisector. The bisectors of AB and BC are 90° apart, so the two fields are perpendicular.\nResultant = √(E² + E²) = √2 E, option (b)."},
{"y":"JEE Main 2025 · 8 Apr · Shift 2","tp":"ecn","st":"Induced charge and shielding","q":"Electric charge is transferred to an irregular metallic disk as shown in the figure. If σ₁, σ₂, σ₃ and σ₄ are charge densities at given points then, choose the correct answer from the options given below:\nA. σ₁ > σ₃ ; σ₂ = σ₄\nB. σ₁ > σ₂ ; σ₃ > σ₄\nC. σ₁ > σ₃ > σ₂ = σ₄\nD. σ₁ < σ₃ < σ₂ = σ₄\nE. σ₁ = σ₃ = σ₂ = σ₄","fig":{"w":340,"h":200,"alt":"An irregular metallic disk shaped like a lemon with a sharp tip at the right (point 1), a rounded end at the left (point 3) and flatter top and bottom (points 2 and 4).","d":[["p","M50 100 C50 60 120 50 170 60 L300 100 L170 140 C110 150 50 140 50 100 Z","f"],["c",300,100,3,"F"],["t",308,104,"1"],["c",170,60,3,"F"],["t",170,50,"2","ms"],["c",50,100,3,"F"],["t",40,104,"3","e"],["c",170,140,3,"F"],["t",170,158,"4","ms"]]},"o":["B and C Only","D and E Only","A, B and C Only","A and D Only"],"c":2,"s":"On a charged conductor the surface charge density is larger where the surface is more sharply curved (smaller radius of curvature).\nPoint 1 is on the sharpest tip, so σ₁ is the largest. Point 3 is on a less sharply curved end, so σ₃ is smaller than σ₁ but larger than σ₂ and σ₄.\nPoints 2 and 4 are on equally flat parts, so σ₂ = σ₄ and these are the smallest.\nSo σ₁ > σ₃ > σ₂ = σ₄. This makes A, B and C true and D, E false.\nOption (c)."},
{"y":"JEE Main 2025 · 8 Apr · Shift 2","tp":"egs","st":"Electric flux","q":"An infinitely long wire has uniform linear charge density λ = 2 nC/m. The net flux through a Gaussian cube of side √3 cm, if the wire passes through any two corners of the cube that are maximally displaced from each other, would be x N m² C⁻¹, where x is:\n[Neglect any edge effects and use {1;4πε₀} = 9×10⁹ SI units]","o":["2.16π","6.48π","1.44π","0.72π"],"c":0,"s":"Two corners that are farthest apart are the ends of a body diagonal, so the wire inside the cube has length √3 × side = √3 × √3 cm = 3 cm = 0.03 m.\nEnclosed charge q = λ × 0.03 = 2×10⁻⁹ × 0.03 = 6×10⁻¹¹ C.\nFlux = q/ε₀ = q × 4π × 9×10⁹ = 6×10⁻¹¹ × 36π×10⁹ = 2.16π N m²/C.\nOption (a)."},
{"y":"JEE Main 2025 · 22 Jan · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"An electron is made to enter symmetrically between two parallel and equally but oppositely charged metal plates, each of 10 cm length. The electron emerges out of the electric field region with a horizontal component of velocity 10⁶ m/s. If the magnitude of the electric field between the plates is 9.1 V/cm, then the vertical component of velocity of electron is\n(mass of electron = 9.1 × 10⁻³¹ kg and charge of electron = 1.6 × 10⁻¹⁹ C)","o":["16 × 10⁶ m/s","0","16 × 10⁴ m/s","1 × 10⁶ m/s"],"c":0,"s":"The horizontal speed stays 10⁶ m/s, so the time in the plates is t = 0.10 m / 10⁶ m/s = 10⁻⁷ s.\nE = 9.1 V/cm = 910 V/m, so the vertical acceleration is a = eE/m = (1.6×10⁻¹⁹ × 910)/(9.1×10⁻³¹) = 1.6×10¹⁴ m/s².\nVertical velocity v = at = 1.6×10¹⁴ × 10⁻⁷ = 1.6×10⁷ m/s = 16 × 10⁶ m/s.\nOption (a)."},
{"y":"JEE Main 2025 · 22 Jan · Shift 1","tp":"egs","st":"Electric flux","q":"A line charge of length {a;2} is kept at the center of an edge BC of a cube ABCDEFGH having edge length 'a' as shown in the figure. If the density of line charge is λ C per unit length, then the total electric flux through all the faces of the cube will be ______. (Take, ε₀ as the free space permittivity)","fig":{"w":340,"h":200,"alt":"A cube of edge a. The middle half of the bottom front edge BC is drawn in bold: this is the line charge of length a/2.","d":[["r",60,70,100,100],["r",110,30,100,100],["l",60,70,110,30],["l",160,70,210,30],["l",60,170,110,130],["l",160,170,210,130],["l",85,170,135,170,"B"],["t",52,184,"B","e"],["t",168,184,"C"],["t",110,194,"a/2","ms"],["t",54,124,"a","e"]]},"o":["{λa;16ε₀}","{λa;2ε₀}","{λa;4ε₀}","{λa;8ε₀}"],"c":3,"s":"Charge on the line: Q = λ × a/2.\nThe line lies along an edge, and four identical cubes meet at an edge. By symmetry the flux of this charge is shared equally among the four cubes.\nFlux through this cube = (1/4) × Q/ε₀ = (1/4)(λa/2)/ε₀ = λa/(8ε₀).\nOption (d)."},
{"y":"JEE Main 2025 · 23 Jan · Shift 1","tp":"egs","st":"Electric flux","q":"The electric flux is φ = ασ + βλ, where λ and σ are linear and surface charge density, respectively. ({α;β}) represents","o":["charge","displacement","area","electric field"],"c":1,"s":"Flux has the dimension of (charge)/ε₀. Both terms ασ and βλ must have this dimension.\nσ = charge/area, so α must have the dimension (area)/ε₀.\nλ = charge/length, so β must have the dimension (length)/ε₀.\nα/β = area/length = length, which is a displacement.\nOption (b)."},
{"y":"JEE Main 2025 · 23 Jan · Shift 1","tp":"efl","st":"Electric dipole","q":"A point particle of charge Q is located at P along the axis of an electric dipole 1 at a distance r as shown in the figure. The point P is also on the equatorial plane of a second electric dipole 2 at a distance r. The dipoles are made of opposite charge q separated by a distance 2a. For the charge particle at P not to experience any net force, which of the following correctly describes the situation?","fig":{"w":340,"h":245,"alt":"Point P at the top left. Dipole 1 lies to the right of P on the same horizontal line, its centre at distance r from P, with +q on the left and -q on the right, separated by 2a. Dipole 2 lies directly below P at distance r with +q on the left and -q on the right, separated by 2a.","d":[["c",80,60,4,"F"],["t",80,48,"P","ms"],["c",200,60,5,"F"],["c",280,60,5,"F"],["t",200,50,"+q","ms"],["t",280,50,"−q","ms"],["t",240,30,"Dipole 1","ms"],["l",240,40,240,100,"d"],["l",84,92,236,92,"b"],["t",160,87,"r","ms"],["l",200,65,200,115,"d"],["l",280,65,280,115,"d"],["l",200,110,280,110,"b"],["t",240,128,"2a","ms"],["l",80,66,80,186,"b"],["t",88,130,"r","s"],["c",40,190,5,"F"],["c",120,190,5,"F"],["t",40,180,"+q","ms"],["t",120,180,"−q","ms"],["t",80,166,"Dipole 2","ms"],["l",40,195,40,218,"d"],["l",120,195,120,218,"d"],["l",40,213,120,213,"b"],["t",80,234,"2a","ms"]]},"o":["a/r ~ 3","a/r ~ 20","a/r ~ 0.5","a/r ~ 10"],"c":0,"s":"Let x = a/r. Charges ±q at ±a from the centre of each dipole.\nDipole 1 (P on its axis, distance r from the centre): E₁ = kq[1/(r−a)² − 1/(r+a)²] = 4kqar/(r²−a²)².\nDipole 2 (P on its equatorial plane): E₂ = 2kqa/(r²+a²)^(3/2), pointing opposite to E₁ for the orientations shown.\nNo net force on Q needs E₁ = E₂, which gives 2(1+x²)^(3/2) = (1−x²)².\nTry x = 3: left side = 2 × 10^(3/2) = 63.2 and right side = 64, nearly equal. The values 20, 10 and 0.5 do not satisfy it.\nSo a/r ≈ 3, option (a)."},
{"y":"JEE Main 2025 · 28 Jan · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"A particle of mass 'm' and charge 'q' is fastened to one end 'A' of a massless string having equilibrium length l, whose other end is fixed at point 'O'. The whole system is placed on a frictionless horizontal plane and is initially at rest. If uniform electric field is switched on along the direction as shown in the figure, then the speed of the particle when it crosses the x-axis is","fig":{"w":340,"h":200,"alt":"Top view: point O at the origin, a string of length l from O to the particle A at 60 degrees above the positive x-axis, and a uniform electric field E pointing along the positive x-axis.","d":[["l",80,170,310,170,"a"],["t",314,174,"x","s"],["l",80,170,80,15,"a"],["t",86,20,"y","s"],["l",80,170,140,66],["c",140,66,5,"F"],["t",148,62,"A"],["t",66,186,"O"],["t",118,114,"l"],["p","M110 170 A30 30 0 0 0 95 144"],["t",114,164,"60°","s"],["l",190,150,250,150,"a"],["t",172,154,"E"]]},"o":["√{2qEl;m}","√{qEl;m}","√{qEl;4m}","√{qEl;2m}"],"c":1,"s":"The force qE acts along +x. The string stays taut, so the particle moves on a circle of radius l about O. The tension does no work, and the plane is horizontal so gravity does no work.\nAt the start A is at 60° above the x-axis, so its x-coordinate is l cos60° = l/2. On the x-axis its x-coordinate is l.\nWork done by the field = qE × (l − l/2) = qEl/2.\n½mv² = qEl/2, so v = √(qEl/m).\nOption (b)."},
{"y":"JEE Main 2025 · 29 Jan · Shift 1","tp":"efl","st":"Electric dipole","q":"An electric dipole of mass m, charge q, and length l is placed in a uniform electric field E⃗ = E₀î. When the dipole is rotated slightly from its equilibrium position and released, the time period of its oscillations will be","o":["{1;2π}√{2ml;qE₀}","2π√{ml;qE₀}","2π√{ml;2qE₀}","{1;2π}√{ml;2qE₀}"],"c":2,"s":"For a small angle θ from equilibrium, the restoring torque is τ = pE₀ sinθ ≈ (ql)E₀θ.\nTake mass m at each end, at distance l/2 from the centre: I = 2 × m(l/2)² = ml²/2.\nIθ'' = −qlE₀θ gives ω² = qlE₀/I = 2qE₀/(ml).\nT = 2π/ω = 2π√(ml/(2qE₀)).\nOption (c)."},
{"y":"JEE Main 2025 · 29 Jan · Shift 2","tp":"egs","st":"Gauss's law and symmetric bodies","q":"A point charge causes an electric flux of −2 × 10⁴ N m² C⁻¹ to pass through a spherical Gaussian surface of 8.0 cm radius, centred on the charge. The value of the point charge is\n(Given ε₀ = 8.85 × 10⁻¹² C²N⁻¹m⁻²)","o":["17.7 × 10⁻⁸ C","−15.7 × 10⁻⁸ C","−17.7 × 10⁻⁸ C","15.7 × 10⁻⁸ C"],"c":2,"s":"Gauss's law: flux = q/ε₀, so q = ε₀ × flux.\nq = 8.85×10⁻¹² × (−2×10⁴) = −1.77×10⁻⁷ C = −17.7×10⁻⁸ C.\nThe radius of the sphere does not matter.\nOption (c)."},
{"y":"JEE Advanced 2025","tp":"egs","st":"Gauss's law and symmetric bodies","q":"Two co-axial conducting cylinders of same length l with radii √2 R and 2R are kept. The charge on the inner cylinder is Q and the outer cylinder is grounded. The annular region between the cylinders is filled with a material of dielectric constant k = 5. Consider an imaginary plane of the same length l at a distance R from the common axis of the cylinders. This plane is parallel to the axis of the cylinders. The cross-sectional view of this arrangement is shown in the figure.\nIgnoring edge effects, the flux of the electric field through the plane is (ε₀ is the permittivity of free space)","fig":{"w":340,"h":215,"alt":"Cross-section of two co-axial cylinders with radii root 2 R and 2 R, the space between them filled with dielectric k = 5. A vertical dashed line, the imaginary plane, lies at distance R from the axis.","d":[["c",120,105,80],["c",120,105,57],["l",160,15,160,195,"d"],["t",166,24,"plane","s"],["l",120,105,160,105,"a"],["t",140,100,"R","ms"],["c",120,105,2,"F"],["l",120,105,80,65],["t",76,62,"√2 R","es"],["l",120,105,64,162],["t",60,174,"2R","es"],["t",120,40,"k = 5","ms"],["t",92,92,"Q","ms"],["t",10,208,"outer cylinder earthed","s"]]},"o":["{Q;30ε₀}","{Q;15ε₀}","{Q;60ε₀}","{Q;120ε₀}"],"c":2,"s":"In the dielectric (√2R < r < 2R) the field is radial: E = Q/(2πε₀ k l r). Inside the inner cylinder and outside the earthed outer one the field is zero.\nOn the plane (distance R from the axis) take y along the plane from the foot of the perpendicular. Points with √2R < r < 2R are those with R < |y| < √3R, since r² = R² + y².\nThe component of E normal to the plane is E cosφ = E × R/r.\nFlux = 2 ∫ [Q/(2πε₀ k l r)](R/r) l dy from y = R to √3R = (Q/(πε₀k)) ∫ R dy/(R²+y²) = (Q/(πε₀k)) [tan⁻¹(y/R)] from 1 to √3.\n= (Q/(πε₀k))(π/3 − π/4) = Q/(12ε₀k). With k = 5 the flux is Q/(60ε₀).\nOption (c)."},
{"y":"JEE Main 2024 · 4 Apr · Shift 1","tp":"egs","st":"Gauss's law and symmetric bodies","q":"An infinitely long positively charged straight thread has a linear charge density λ C m⁻¹. An electron revolves along a circular path having axis along the length of the wire. The graph that correctly represents the variation of the kinetic energy of electron as a function of radius of circular path from the wire is","fig":{"w":340,"h":225,"alt":"Four small graphs of kinetic energy KE against radius r. (a) a straight line rising from the origin; (b) a horizontal line; (c) a curve falling steeply then flattening; (d) a curve rising slowly then steeply.","d":[["l",25,85,140,85,"a"],["l",25,85,25,20,"a"],["t",30,29,"KE","s"],["t",143,89,"r","s"],["l",25,85,125,30],["t",82,103,"(a)","m"],["l",190,85,305,85,"a"],["l",190,85,190,20,"a"],["t",195,29,"KE","s"],["t",308,89,"r","s"],["l",190,45,295,45],["t",247,103,"(b)","m"],["l",25,195,140,195,"a"],["l",25,195,25,130,"a"],["t",30,139,"KE","s"],["t",143,199,"r","s"],["p","M33 135 Q43 183 130 187"],["t",82,213,"(c)","m"],["l",190,195,305,195,"a"],["l",190,195,190,130,"a"],["t",195,139,"KE","s"],["t",308,199,"r","s"],["p","M190 195 Q275 187 290 135"],["t",247,213,"(d)","m"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"The field of the thread at distance r is E = λ/(2πε₀r), and it attracts the electron.\nThis force supplies the centripetal force: eλ/(2πε₀r) = mv²/r.\nSo mv² = eλ/(2πε₀) and KE = ½mv² = eλ/(4πε₀).\nThis does not depend on r, so KE against r is a horizontal straight line.\nGraph (b)."},
{"y":"JEE Main 2024 · 4 Apr · Shift 1","tp":"egs","st":"Electric flux","q":"A charge q is placed at the centre of one of the surface of a cube. The flux linked with the cube is","o":["{q;8ε₀}","{q;4ε₀}","{q;2ε₀}","zero"],"c":2,"s":"Put a second identical cube against the first so that q is now at the centre of the box formed by the two cubes.\nThe total flux through the closed surface of the two-cube box is q/ε₀. The face where q sits has no flux (the field lines lie along it), and by symmetry each cube gets half.\nFlux through the cube = q/(2ε₀).\nOption (c)."},
{"y":"JEE Main 2024 · 9 Apr · Shift 2","tp":"egs","st":"Electric flux","q":"Five charges +q, +5q, −2q, +3q and −4q are situated as shown in the figure. The electric flux due to this configuration through the surface S is","fig":{"w":340,"h":170,"alt":"A closed surface S enclosing the charges +5q, +q and -2q. The charge -4q is outside on the left and +3q is outside on the right.","d":[["p","M75 85 A95 55 0 1 1 265 85 A95 55 0 1 1 75 85 Z"],["c",130,65,3,"F"],["t",120,58,"+5q","ms"],["c",200,65,3,"F"],["t",205,58,"+q","s"],["c",190,110,3,"F"],["t",205,114,"−2q","s"],["t",150,105,"S"],["c",35,85,3,"F"],["t",35,74,"−4q","ms"],["c",305,85,3,"F"],["t",305,74,"+3q","ms"]]},"o":["{3q;ε₀}","{q;ε₀}","{5q;ε₀}","{4q;ε₀}"],"c":3,"s":"By Gauss's law the flux through S depends only on the charge enclosed by S.\nInside S: +5q, +q and −2q, so the enclosed charge is 5q + q − 2q = 4q.\nThe charges +3q and −4q lie outside S and give no net flux.\nFlux = 4q/ε₀. Option (d)."},
{"y":"JEE Main 2024 · 1 Feb · Shift 1","tp":"egs","st":"Electric flux","q":"C₁ and C₂ are two hollow concentric cubes enclosing charges 2Q and 3Q respectively as shown in the figure. The ratio of electric flux passing through C₁ and C₂ is","fig":{"w":340,"h":230,"alt":"Two concentric cubes. The inner cube C1 contains the charge 2Q. The charge 3Q sits in the space between the inner cube and the outer cube C2.","d":[["r",40,60,140,140],["r",75,25,140,140],["l",40,60,75,25],["l",180,60,215,25],["l",40,200,75,165],["l",180,200,215,165],["r",95,115,50,50],["r",109,101,50,50],["l",95,115,109,101],["l",145,115,159,101],["l",95,165,109,151],["l",145,165,159,151],["t",120,144,"2Q","ms"],["c",62,150,3,"F"],["t",68,154,"3Q"],["t",100,178,"C₁","s"],["t",190,196,"C₂","s"]]},"o":["3 : 2","5 : 2","2 : 5","2 : 3"],"c":2,"s":"The flux through a closed surface is (charge enclosed)/ε₀.\nC₁, the inner cube, encloses only 2Q: flux = 2Q/ε₀.\nC₂, the outer cube, encloses 2Q + 3Q = 5Q: flux = 5Q/ε₀.\nRatio = 2Q : 5Q = 2 : 5. Option (c)."},
{"y":"JEE Main 2024 · 29 Jan · Shift 1","tp":"egs","st":"Electric flux","q":"Two charges of 5Q and −2Q are situated at the points (3a, 0) and (−5a, 0) respectively. The electric flux through a sphere of radius '4a' having center at origin is","o":["{2Q;ε₀}","{7Q;ε₀}","{5Q;ε₀}","{3Q;ε₀}"],"c":2,"s":"The charge 5Q is at distance 3a from the origin. This is less than 4a, so it is inside the sphere.\nThe charge −2Q is at distance 5a from the origin. This is more than 4a, so it is outside.\nFlux = (enclosed charge)/ε₀ = 5Q/ε₀.\nOption (c)."},
{"y":"JEE Main 2024 · 29 Jan · Shift 2","tp":"egs","st":"Electric flux","q":"An electric field is given by (6î + 5ĵ + 3k̂) N/C. The electric flux through a surface of area 30î m² lying in YZ-plane (in SI unit) is","o":["150","60","180","90"],"c":2,"s":"The area vector of a surface in the YZ-plane is along x, here A = 30î m².\nFlux = E · A = (6î + 5ĵ + 3k̂) · (30î) = 6 × 30 = 180 N m²/C.\nOnly the x-component of the field passes through the surface. Option (c)."},
{"y":"JEE Main 2024 · 30 Jan · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"A particle of charge −q and mass m moves in a circle of radius r around an infinitely long line charge of linear density +λ. Then time period will be given as (Consider k as Coulomb's constant)","o":["T = 2πr√{m;2kλq}","T = {1;2π}√{2kλq;m}","T² = {4π²m;2kλq}r³","T = {1;2πr}√{m;2kλq}"],"c":0,"s":"Field of a line charge at distance r: E = 2kλ/r.\nThis attractive force provides the centripetal force: q × 2kλ/r = mv²/r, so v = √(2kλq/m).\nT = 2πr/v = 2πr√(m/(2kλq)).\nOption (a)."},
{"y":"JEE Main 2024 · 31 Jan · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Two charges q and 3q are separated by a distance 'r' in air. At a distance x from charge q, the resultant electric field is zero. The value of x is","o":["{(1+√3);r}","r(1+√3)","{r;3(1+√3)}","{r;(1+√3)}"],"c":3,"s":"Take the two charges as like charges; then the field is zero at a point between them, at x from q and (r − x) from 3q.\nkq/x² = k(3q)/(r − x)², so (r − x)/x = √3.\nr = x(1 + √3), so x = r/(1 + √3).\nOption (d)."},
{"y":"JEE Main 2023 · 6 Apr · Shift 2","tp":"efl","st":"Electric dipole","q":"A dipole comprises of two charged particles of identical magnitude q and opposite in nature. The mass 'm' of the positive charged particle is half of the mass of the negative charged particle. The two charges are separated by a distance 'l'. If the dipole is placed in a uniform electric field E⃗ in such a way that dipole axis makes a very small angle with the electric field E⃗. The angular frequency of the oscillations of the dipole when released is given by","o":["√{8qE;3ml}","√{8qE;ml}","√{4qE;3ml}","√{4qE;ml}"],"c":2,"s":"The positive particle has mass m and the negative one 2m, separated by l.\nThe centre of mass is 2l/3 from the positive particle and l/3 from the negative one.\nMoment of inertia about it: I = m(2l/3)² + 2m(l/3)² = 2ml²/3.\nFor a small angle θ the torque is qElθ, so ω² = qEl/I = 3qE/(2ml).\nOf the four given options, (c) √(4qE/(3ml)) is the closest, and it is the option marked in the book."},
{"y":"JEE Main 2023 · 8 Apr · Shift 1","tp":"egs","st":"Gauss's law and symmetric bodies","q":"Graphical variation of electric field due to a uniformly charged insulating solid sphere of radius R, with distance r from the centre O is represented by","fig":{"w":340,"h":225,"alt":"Four graphs of electric field E against distance r with the sphere radius R marked. (a) E rises as a curve to R then stays constant; (b) E rises as a curve to R then falls linearly; (c) E is constant up to R then falls as a curve; (d) E rises linearly to R then falls as a curve.","d":[["l",25,80,140,80,"a"],["l",25,80,25,15,"a"],["t",30,24,"E","s"],["t",143,84,"r","s"],["l",80,30,80,80,"d"],["t",80,91,"R","ms"],["p","M25 80 Q55 30 80 30"],["l",80,30,135,30],["t",82,106,"(a)","m"],["l",190,80,305,80,"a"],["l",190,80,190,15,"a"],["t",195,24,"E","s"],["t",308,84,"r","s"],["l",245,30,245,80,"d"],["t",245,91,"R","ms"],["p","M190 80 Q220 30 245 30"],["l",245,30,300,55],["t",247,106,"(b)","m"],["l",25,190,140,190,"a"],["l",25,190,25,125,"a"],["t",30,134,"E","s"],["t",143,194,"r","s"],["l",80,140,80,190,"d"],["t",80,201,"R","ms"],["l",25,140,80,140],["p","M80 140 Q90 176 135 182"],["t",82,216,"(c)","m"],["l",190,190,305,190,"a"],["l",190,190,190,125,"a"],["t",195,134,"E","s"],["t",308,194,"r","s"],["l",245,140,245,190,"d"],["t",245,201,"R","ms"],["l",190,190,245,140],["p","M245 140 Q255 176 300 182"],["t",247,216,"(d)","m"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":3,"s":"Inside a uniformly charged solid sphere E = ρr/(3ε₀), which rises linearly from zero at the centre.\nAt the surface E has its maximum value ρR/(3ε₀).\nOutside the sphere E = kQ/r², which falls as 1/r² and equals the same value at r = R.\nSo the graph is a straight line rising up to R, then a falling 1/r² curve.\nGraph (d)."},
{"y":"JEE Main 2023 · 13 Apr · Shift 2","tp":"efl","st":"Electric dipole","q":"Two charges each magnitude 0.01 C and separated by a distance of 0.4 mm constitute an electric dipole. If the dipole is placed in a uniform electric field 'E⃗' of 10 dyne/C magnitude, such that the dipole makes an angle of 30° with E⃗, the magnitude of torque acting on the dipole is","o":["1.0 × 10⁻⁸ Nm","1.5 × 10⁻⁹ Nm","4.0 × 10⁻¹⁰ Nm","2.0 × 10⁻¹⁰ Nm"],"c":3,"s":"Dipole moment p = q × d = 0.01 × 0.4×10⁻³ = 4×10⁻⁶ C m.\nE = 10 dyne/C = 10 × 10⁻⁵ N/C = 10⁻⁴ N/C.\nTorque τ = pE sinθ = 4×10⁻⁶ × 10⁻⁴ × sin30° = 2×10⁻¹⁰ N m.\nOption (d)."},
{"y":"JEE Main 2023 · 15 Apr · Shift 1","tp":"efl","st":"Electric dipole","q":"The electric field due to a short electric dipole at a large distance (r) from center of dipole on the equatorial plane varies with distance as","o":["{1;r²}","{1;r}","{1;r³}","r"],"c":2,"s":"At a large distance r on the equatorial plane of a short dipole, E = kp/r³.\nSo E is proportional to 1/r³. (On the axis it is 2kp/r³, also proportional to 1/r³.)\nOption (c)."},
{"y":"JEE Main 2023 · 1 Feb · Shift 1","tp":"egs","st":"Gauss's law and symmetric bodies","q":"Let σ be the uniform surface charge density of two infinite thin plane sheets shown in the figure (n̂ is the unit vector normal to the sheets, pointing from region I towards region III). Then the electric fields E_I, E_II and E_III in three different regions are","fig":{"w":340,"h":150,"alt":"Two parallel sheets, each with surface charge density plus sigma, a distance d apart. Region I is to the left of both, region II is between them and region III is to the right. The unit vector n points to the right.","d":[["l",120,25,120,120,"B"],["l",220,25,220,120,"B"],["t",120,18,"+σ","ms"],["t",220,18,"+σ","ms"],["t",60,75,"I","m"],["t",170,62,"II","m"],["t",280,75,"III","m"],["l",120,100,220,100,"b"],["t",170,96,"d","ms"],["l",20,138,70,138,"a"],["t",76,142,"n̂"]]},"o":["E⃗_I = 0, E⃗_II = {σ;ε₀}n̂, E⃗_III = 0","E⃗_I = {2σ;ε₀}n̂, E⃗_II = 0, E⃗_III = {2σ;ε₀}n̂","E⃗_I = −{σ;ε₀}n̂, E⃗_II = 0, E⃗_III = {σ;ε₀}n̂","E⃗_I = {σ;2ε₀}n̂, E⃗_II = 0, E⃗_III = {σ;2ε₀}n̂"],"c":2,"s":"Each positive sheet gives a field σ/(2ε₀) pointing away from itself.\nRegion I (left of both): both fields point to the left, so E = −σ/ε₀ n̂.\nRegion II (between): the two fields are equal and opposite, so E = 0.\nRegion III (right of both): both fields point to the right, so E = +σ/ε₀ n̂.\nOption (c)."},
{"y":"JEE Main 2023 · 25 Jan · Shift 2","tp":"efl","st":"Field of point charges and distributions","q":"A point charge of 10 μC is placed at the origin. At what location on the X-axis should a point charge of 40 μC be placed so that the net electric field is zero at x = 2 cm on the X-axis?","o":["x = −4 cm","x = 4 cm","x = 8 cm","x = 6 cm"],"c":3,"s":"At x = 2 cm the 10 μC charge gives a field along +x proportional to 10/2² = 2.5 (units of k, with μC and cm).\nThe 40 μC charge must give an equal field along −x, so it must lie on the +x side of the point, at distance d from it: 40/d² = 2.5.\nd² = 16, so d = 4 cm.\nIts position is x = 2 + 4 = 6 cm. Option (d)."},
{"y":"JEE Main 2023 · 29 Jan · Shift 1","tp":"egs","st":"Electric flux","q":"In a cuboid of dimension 2L × 2L × L, a charge q is placed at the center of the surface 'S' having area of 4L². The flux through the opposite surface to 'S' is given by","o":["{q;12ε₀}","{q;2ε₀}","{q;3ε₀}","{q;6ε₀}"],"c":3,"s":"The opposite face is a 2L × 2L square at distance L from the charge, which sits at the centre of face S.\nConsider a cube of side 2L with q at its centre: each face is also a 2L × 2L square at distance L from q. So the flux through our opposite face equals the flux through one face of that cube.\nBy symmetry each of the 6 faces of the cube gets 1/6 of q/ε₀.\nFlux = q/(6ε₀). Option (d)."},
{"y":"JEE Main 2023 · 30 Jan · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Electric field in a certain region is given by E⃗ = ({A;x²}î + {B;y³}ĵ). The SI unit of A and B are","o":["Nm²C⁻¹ ; Nm³C⁻¹","Nm³C ; Nm²C","Nm²C ; Nm³C","Nm³C⁻¹ ; Nm²C⁻¹"],"c":0,"s":"E is in N/C, so each term A/x² and B/y³ must be in N/C.\nA = E × x² has unit (N/C) × m² = N m² C⁻¹.\nB = E × y³ has unit (N/C) × m³ = N m³ C⁻¹.\nOption (a)."},
{"y":"JEE Main 2023 · 30 Jan · Shift 2","tp":"ecn","st":"Induced charge and shielding","q":"As shown in the figure, a point charge Q is placed at the centre of conducting spherical shell of inner radius a and outer radius b. The electric field due to charge Q in three different regions I, II and III is given by (I : r < a, II : a < r < b, III : r > b)","fig":{"w":340,"h":190,"alt":"A point charge Q at the centre of a conducting spherical shell with inner radius a and outer radius b. Region I is inside the cavity, region II is within the shell material and region III is outside.","d":[["c",150,95,40],["c",150,95,75],["c",150,95,4,"F"],["t",142,92,"Q","e"],["l",150,95,178,123,"a"],["t",176,136,"a","s"],["l",150,95,203,42,"a"],["t",206,40,"b","s"],["t",166,80,"I","s"],["t",150,42,"II","ms"],["t",250,98,"III","m"]]},"o":["E_I = 0, E_II = 0, E_III = 0","E_I ≠ 0, E_II = 0, E_III = 0","E_I = 0, E_II = 0, E_III ≠ 0","E_I ≠ 0, E_II = 0, E_III ≠ 0"],"c":3,"s":"Q at the centre induces −Q on the inner surface (r = a) and +Q on the outer surface (r = b).\nRegion I (r < a): only Q is enclosed, so E = kQ/r² ≠ 0.\nRegion II (inside the conducting material): E = 0.\nRegion III (r > b): the enclosed charge is Q (−Q + Q + Q), so E = kQ/r² ≠ 0.\nSo E_I ≠ 0, E_II = 0, E_III ≠ 0. Option (d)."},
{"y":"JEE Main 2022 · 28 Jul · Shift 2","tp":"efl","st":"Field lines and motion in a field","q":"A uniform electric field E = (8m/e) V/m is created between two parallel plates of length 1 m as shown in the figure (where m = mass of electron and e = charge of electron). An electron enters the field symmetrically between the plates with a speed of 2 m/s. The angle of the deviation (θ) of the path of the electron as it comes out of the field will be ______.","fig":{"w":340,"h":170,"alt":"Two parallel plates of length 1 m, the upper positive and the lower negative. The electric field E points down. An electron enters at the middle with speed 2 m/s, bends upward towards the positive plate and leaves at an angle theta to its original direction.","d":[["l",60,50,280,50,"B"],["l",60,120,280,120,"B"],["t",70,44,"+","m"],["t",95,44,"+","m"],["t",120,44,"+","m"],["t",145,44,"+","m"],["t",170,44,"+","m"],["t",195,44,"+","m"],["t",220,44,"+","m"],["t",245,44,"+","m"],["t",270,44,"+","m"],["t",70,138,"−","m"],["t",95,138,"−","m"],["t",120,138,"−","m"],["t",145,138,"−","m"],["t",170,138,"−","m"],["t",195,138,"−","m"],["t",220,138,"−","m"],["t",245,138,"−","m"],["t",270,138,"−","m"],["l",60,28,280,28,"b"],["t",170,22,"1 m","ms"],["l",10,85,58,85,"a"],["t",10,76,"2 m/s","s"],["p","M60 85 Q190 85 280 58"],["p","M280 58 L322 46","d"],["p","M280 58 L330 58","d"],["t",306,72,"θ"],["l",100,92,100,114,"a"],["t",106,108,"E"]]},"o":["tan⁻¹(4)","tan⁻¹(2)","tan⁻¹({1;3})","tan⁻¹(3)"],"c":1,"s":"Acceleration of the electron: a = eE/m = e × (8m/e)/m = 8 m/s².\nTime between the plates: t = length/speed = 1/2 = 0.5 s (horizontal speed stays 2 m/s).\nVertical speed on leaving: v_y = at = 8 × 0.5 = 4 m/s.\ntanθ = v_y/v_x = 4/2 = 2, so θ = tan⁻¹(2).\nOption (b)."},
{"y":"JEE Main 2022 · 29 Jul · Shift 1","tp":"egs","st":"Non-uniform charge distributions","q":"A spherically symmetric charge distribution is considered with charge density varying as\nρ(r) = ρ₀({3;4} − {r;R}) for r ≤ R, and zero for r > R,\nwhere r (r < R) is the distance from the centre O (as shown in the figure). The electric field at point P will be","fig":{"w":340,"h":200,"alt":"A sphere of radius R with centre O. The point P lies inside the sphere at distance r from O.","d":[["c",150,100,75],["c",150,100,3,"F"],["t",140,114,"O","s"],["l",150,100,205,54],["c",205,54,4,"F"],["t",212,52,"P"],["t",168,66,"r","s"],["l",150,100,97,153,"d"],["t",100,140,"R","es"]]},"o":["{ρ₀r;4ε₀}({3;4} − {r;R})","{ρ₀r;3ε₀}({3;4} − {r;R})","{ρ₀r;4ε₀}(1 − {r;R})","{ρ₀r;5ε₀}(1 − {r;R})"],"c":2,"s":"P is inside the sphere, so use a Gaussian sphere of radius r.\nCharge inside = ∫ 4πr'² ρ₀(3/4 − r'/R) dr' from 0 to r = 4πρ₀[r³/4 − r⁴/(4R)] = πρ₀r³(1 − r/R).\nGauss: E × 4πr² = Q_in/ε₀, so E = ρ₀ r (1 − r/R)/(4ε₀).\nOption (c)."},
{"y":"JEE Main 2022 · 24 Jun · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"A vertical electric field of magnitude 4.9 × 10⁵ N/C just prevents a water droplet of a mass 0.1 g from falling. The value of charge on the droplet will be","o":["1.6 × 10⁻⁹ C","2.0 × 10⁻⁹ C","3.2 × 10⁻⁹ C","0.5 × 10⁻⁹ C"],"c":1,"s":"The droplet is at rest, so the electric force balances its weight: qE = mg.\nq = mg/E = (0.1×10⁻³ kg × 9.8 m/s²)/(4.9×10⁵ N/C) = 2.0×10⁻⁹ C.\nOption (b)."},
{"y":"JEE Main 2022 · 24 Jun · Shift 2","tp":"egs","st":"Gauss's law and symmetric bodies","q":"A long cylindrical volume contains a uniformly distributed charge of density ρ. The radius of cylindrical volume is R. A charge particle (q) revolves around the cylinder in a circular path. The kinetic energy of the particle is","o":["{ρqR²;4ε₀}","{ρqR²;2ε₀}","{qρ;4ε₀R²}","{4ε₀R²;qρ}"],"c":0,"s":"Outside the cylinder (distance r > R), Gauss's law gives E × 2πrl = ρπR²l/ε₀, so E = ρR²/(2ε₀r).\nThe electric force supplies the centripetal force: qρR²/(2ε₀r) = mv²/r.\nSo mv² = qρR²/(2ε₀) and KE = ½mv² = ρqR²/(4ε₀), independent of r.\nOption (a)."},
{"y":"JEE Main 2022 · 25 Jun · Shift 1","tp":"egs","st":"Gauss's law and symmetric bodies","q":"In the figure, a very large plane sheet of positive charge is shown. P₁ and P₂ are two points at distance l and 2l from the charge distribution. If σ is the surface charge density, then the magnitude of electric fields E₁ and E₂ at P₁ and P₂ respectively are","fig":{"w":340,"h":170,"alt":"A large vertical sheet of positive charge. Point P1 is at distance l to its right and point P2 at distance 2l; the fields E1 and E2 point away from the sheet.","d":[["l",60,15,60,155,"B"],["t",48,34,"+","m"],["t",48,59,"+","m"],["t",48,84,"+","m"],["t",48,109,"+","m"],["t",48,134,"+","m"],["c",160,85,4,"F"],["c",260,85,4,"F"],["t",160,100,"P₁","ms"],["t",260,100,"P₂","ms"],["l",166,85,205,85,"a"],["t",186,78,"E₁","ms"],["l",266,85,305,85,"a"],["t",286,78,"E₂","ms"],["l",60,122,160,122,"b"],["t",110,117,"l","ms"],["l",60,148,260,148,"b"],["t",160,143,"2l","ms"]]},"o":["E₁ = {σ;ε₀}, E₂ = {σ;2ε₀}","E₁ = {2σ;ε₀}, E₂ = {σ;ε₀}","E₁ = E₂ = {σ;2ε₀}","E₁ = E₂ = {σ;ε₀}"],"c":2,"s":"A very large uniformly charged plane sheet gives a uniform field E = σ/(2ε₀) on each side.\nThe field does not depend on the distance from the sheet.\nSo E₁ = E₂ = σ/(2ε₀). Option (c)."},
{"y":"JEE Main 2022 · 27 Jun · Shift 2","tp":"egs","st":"Electric flux","q":"If a charge q is placed at the centre of a closed hemispherical non-conducting surface, the total flux passing through the flat surface would be","fig":{"w":340,"h":180,"alt":"A closed hemispherical surface standing on its flat circular base, with the charge q at the centre of the base.","d":[["p","M60 140 A90 90 0 0 1 240 140"],["p","M60 140 A90 22 0 0 0 240 140"],["p","M60 140 A90 22 0 0 1 240 140","d"],["c",150,138,4,"F"],["t",158,132,"q"]]},"o":["{q;ε₀}","{q;2ε₀}","{q;4ε₀}","{q;2πε₀}"],"c":1,"s":"The hemisphere together with its flat base forms a closed surface enclosing q, so the total flux is q/ε₀.\nTreat q as lying at the centre, just inside the base: the flat base then takes up half of all directions (solid angle 2π) and the curved surface the other half.\nBy symmetry the two parts get equal flux, so the flux through the flat surface is q/(2ε₀). Option (b)."},
{"y":"JEE Main 2022 · 28 Jun · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"The three charges {q;2}, q and {q;2} are placed at the corners A, B and C of a square of side 'a' as shown in the figure. The magnitude of electric field (E) at the corner D of the square is","fig":{"w":340,"h":175,"alt":"A square ABCD of side a. A (top left) holds charge q/2, B (bottom left) holds q, C (bottom right) holds q/2, and D is the empty top right corner.","d":[["r",110,30,110,110],["c",110,30,4,"F"],["c",110,140,4,"F"],["c",220,140,4,"F"],["c",220,30,4],["t",102,26,"A  q/2","e"],["t",102,156,"B  q","e"],["t",228,156,"C  q/2"],["t",228,26,"D"]]},"o":["{q;4πε₀a²}({1;√2}+{1;2})","{q;4πε₀a²}(1+{1;√2})","{q;4πε₀a²}(1−{1;√2})","{q;4πε₀a²}({1;√2}−{1;2})"],"c":0,"s":"Let k = 1/(4πε₀). Field at D (top right) from each charge:\nFrom A (q/2, distance a): kq/(2a²), pointing along +x (away from A).\nFrom C (q/2, distance a): kq/(2a²), pointing along +y.\nFrom B (q, distance a√2): kq/(2a²) along the diagonal, so each of its x and y components is kq/(2a²) × 1/√2.\nEach total component = (kq/2a²)(1 + 1/√2), so E = √2 × (kq/2a²)(1 + 1/√2) = (kq/a²)(1/√2 + 1/2).\nOption (a)."},
{"y":"JEE Main 2022 · 28 Jun · Shift 2","tp":"efl","st":"Field of point charges and distributions","q":"Two point charges A and B of magnitude +8 × 10⁻⁶ C and −8 × 10⁻⁶ C respectively are placed at a distance d apart. The electric field at the middle point O between the charges is 6.4 × 10⁴ N C⁻¹. The distance 'd' between the point charges A and B is","o":["2.0 m","3.0 m","1.0 m","4.0 m"],"c":1,"s":"At the midpoint both fields point the same way (away from +8 μC, towards −8 μC), so they add.\nEach charge is at distance d/2: E = 2 × kq/(d/2)² = 8kq/d².\nd² = 8kq/E = 8 × 9×10⁹ × 8×10⁻⁶ / (6.4×10⁴) = 9.\nd = 3.0 m. Option (b)."},
{"y":"JEE Main 2022 · 29 Jun · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"A positive charge particle of 100 mg is thrown in opposite direction to a uniform electric field of strength 1 × 10⁵ N C⁻¹. If the charge on the particle is 40 μC and the initial velocity is 200 m s⁻¹, how much distance it will travel before coming to rest momentarily?","o":["1 m","5 m","10 m","0.5 m"],"c":3,"s":"Force on the charge F = qE = 40×10⁻⁶ × 1×10⁵ = 4 N, along E, so it opposes the motion.\nDeceleration a = F/m = 4/(100×10⁻⁶ kg) = 4×10⁴ m/s².\nDistance = v²/(2a) = 200²/(2 × 4×10⁴) = 4×10⁴/(8×10⁴) = 0.5 m.\nOption (d)."},
{"y":"JEE Main 2022 · 29 Jun · Shift 2","tp":"ecl","st":"Force between point charges","q":"Two points charges Q each are placed at a distance d apart. A third point charge q is placed at a distance x from mid-point on the perpendicular bisector. The value of x at which charge q will experience the maximum coulomb's force is","o":["x = d","x = {d;2}","x = {d;√2}","x = {d;2√2}"],"c":3,"s":"Each Q pulls or pushes q with force kQq/(x²+d²/4). The components along the line joining the two Q's cancel; the components along the bisector add.\nF = 2kQq·x/(x²+d²/4)^(3/2).\nFor maximum F, dF/dx = 0, which gives (x²+d²/4) − 3x² = 0, so 2x² = d²/4.\nx² = d²/8, so x = d/(2√2). Answer (d)."},
{"y":"JEE Main 2021 · 1 Sep · Shift 1","tp":"egs","st":"Electric flux","q":"A cube is placed inside an electric field, E⃗ = 150y²ĵ. The side of the cube is 0.5 m and is placed in the field as shown in the given figure. The charge inside the cube is","fig":{"w":340,"h":210,"alt":"A cube of side 0.5 m resting with its lower face on the xz plane at the origin, with x to the right, y up and z toward the viewer","d":[["l",30,170,310,170,"da"],["l",30,170,30,20,"da"],["l",30,170,6,194,"da"],["r",130,90,80,80],["r",154,70,80,80],["l",130,90,154,70],["l",210,90,234,70],["l",130,170,154,150],["l",210,170,234,150],["t",300,160,"x","s"],["t",38,26,"y","s"],["t",2,190,"z","s"]]},"o":["8.3 × 10⁻¹¹ C","3.8 × 10⁻¹¹ C","3.8 × 10⁻¹² C","8.3 × 10⁻¹² C"],"c":0,"s":"E has only a y-component, so only the two faces perpendicular to y carry flux. The cube sits with one face on y = 0 and the opposite face at y = 0.5 m.\nAt y = 0, E = 0, so that face gives no flux. At y = 0.5 m, E = 150 × 0.25 = 37.5 N/C and the face area is 0.5 × 0.5 = 0.25 m².\nNet outward flux φ = 37.5 × 0.25 = 9.375 N m²/C.\nGauss's law: q = ε₀φ = 8.85×10⁻¹² × 9.375 ≈ 8.3×10⁻¹¹ C. Answer (a)."},
{"y":"JEE Main 2021 · 26 Aug · Shift 1","tp":"ecn","st":"Induced charge and shielding","q":"A solid metal sphere of radius R having charge q is enclosed inside the concentric spherical shell of inner radius a and outer radius b (R < a < b). The approximate variation of electric field E⃗ as a function of distance r from centre O is given by","fig":{"w":340,"h":240,"alt":"Four graphs of electric field E against distance r with marks at R, a and b; (a) zero until R then decays all the way, (b) zero until b then decays, (c) decays from R to a, zero between a and b, then decays again beyond b, (d) rises up to R then decays, zero between a and b, then decays beyond b","d":[["l",26,94,159,94,"a"],["l",26,94,26,10,"a"],["t",6,16,"(a)","s"],["t",159,107,"r","es"],["t",30,12,"E","s"],["l",56,91,56,97],["l",91,91,91,97],["l",126,91,126,97],["t",56,107,"R","ms"],["t",91,107,"a","ms"],["t",126,107,"b","ms"],["l",56,94,56,30],["p","M56,30 C64,60 96,86 152,91"],["l",196,94,329,94,"a"],["l",196,94,196,10,"a"],["t",176,16,"(b)","s"],["t",329,107,"r","es"],["t",200,12,"E","s"],["l",226,91,226,97],["l",261,91,261,97],["l",296,91,296,97],["t",226,107,"R","ms"],["t",261,107,"a","ms"],["t",296,107,"b","ms"],["l",296,94,296,30],["p","M296,30 C302,60 321,86 322,91"],["l",26,214,159,214,"a"],["l",26,214,26,130,"a"],["t",6,136,"(c)","s"],["t",159,227,"r","es"],["t",30,132,"E","s"],["l",56,211,56,217],["l",91,211,91,217],["l",126,211,126,217],["t",56,227,"R","ms"],["t",91,227,"a","ms"],["t",126,227,"b","ms"],["l",56,214,56,150],["p","M56,150 C62,175 81,212 91,214"],["l",126,214,126,164],["p","M126,164 C132,186 151,206 152,211"],["l",196,214,329,214,"a"],["l",196,214,196,130,"a"],["t",176,136,"(d)","s"],["t",329,227,"r","es"],["t",200,132,"E","s"],["l",226,211,226,217],["l",261,211,261,217],["l",296,211,296,217],["t",226,227,"R","ms"],["t",261,227,"a","ms"],["t",296,227,"b","ms"],["p","M196,214 C206,211 214,170 226,156"],["l",226,214,226,156],["p","M226,156 C232,178 251,212 261,214"],["l",296,214,296,164],["p","M296,164 C302,186 321,206 322,211"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":2,"s":"Inside the metal sphere (r < R) the field is zero.\nFor R < r < a the field is that of charge q: E = q/(4πε₀r²), falling as 1/r².\nInside the metal of the shell (a < r < b) the field is zero.\nFor r > b the field is again q/(4πε₀r²), starting again from a finite value at r = b.\nThis is graph (c): zero, a drop-off from R to a, zero from a to b, then a fresh drop-off beyond b. Answer (c)."},
{"y":"JEE Main 2021 · 27 Aug · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"A uniformly charged disc of radius R having surface charge density σ is placed in the xy plane with its center at the origin. Find the electric field intensity along the z-axis at a distance Z from origin.","o":["E = {2ε₀;σ}({1;√(Z²+R²)} + Z)","E = {σ;2ε₀}(1 + {Z;√(Z²+R²)})","E = {σ;2ε₀}(1 − {Z;√(Z²+R²)})","E = {σ;2ε₀}({1;Z²+R²} + {1;Z²})"],"c":2,"s":"Take a thin ring of radius x and width dx on the disc: dq = σ·2πx dx.\nIts field on the axis is dE = (1/4πε₀)·dq·Z/(Z²+x²)^(3/2).\nIntegrate x from 0 to R: E = (σZ/2ε₀)·[1/Z − 1/√(Z²+R²)].\nSo E = (σ/2ε₀)(1 − Z/√(Z²+R²)). For R → ∞ this gives σ/2ε₀, as it should. Answer (c)."},
{"y":"JEE Main 2021 · 27 Aug · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"In Millikan's oil drop experiment, what is viscous force acting on an uncharged drop of radius 2.0 × 10⁻⁵ m and density 1.2 × 10³ kg m⁻³? Take viscosity of liquid = 1.8 × 10⁻⁵ N s m⁻². (Neglect buoyancy due to air).","o":["5.8 × 10⁻¹⁰ N","3.9 × 10⁻¹⁰ N","1.8 × 10⁻¹⁰ N","3.8 × 10⁻¹¹ N"],"c":1,"s":"The drop falls at constant (terminal) speed, so the viscous force equals its weight (buoyancy neglected).\nMass m = (4/3)πr³ρ = (4/3) × 3.14 × (2×10⁻⁵)³ × 1.2×10³ ≈ 4.0×10⁻¹¹ kg.\nF = mg = 4.0×10⁻¹¹ × 9.8 ≈ 3.9×10⁻¹⁰ N. Answer (b)."},
{"y":"JEE Main 2021 · 27 Aug · Shift 2","tp":"efl","st":"Field of point charges and distributions","q":"Figure shows a rod AB, which is bent in a 120° circular arc of radius R. A charge (−Q) is uniformly distributed over rod AB. What is the electric field E⃗ at the centre of curvature O?","fig":{"w":340,"h":240,"alt":"Circular arc AB of radius R centred at O, subtending 120 degrees, symmetric about the x-axis, with OA and OB each at 60 degrees to the axis","d":[["l",60,236,60,6,"a"],["l",60,120,310,120,"a"],["p","M115.0,24.7 A110,110 0 0 1 115.0,215.3","B"],["l",60,120,115,24.7,"d"],["l",60,120,115,215.3,"d"],["t",48,124,"O","es"],["t",119,22.7,"A"],["t",119,227.3,"B"],["t",92,106,"60°","s"],["t",92,142,"60°","s"],["t",300,114,"x","es"],["t",66,14,"y","s"],["t",88,170,"R","s"],["t",190,124,"−Q on arc","s"]]},"o":["{3√3Q;8π²ε₀R²}(î)","{3√3Q;8πε₀R²}(î)","−{3√3Q;8π²ε₀R²}(î)","{3√3Q;16π²ε₀R²}(î)"],"c":0,"s":"The arc subtends 120° at O, so its half-angle is 60°. Charge per unit length λ = Q/(R·2π/3) = 3Q/(2πR).\nFor a symmetric arc the field at the centre is E = (2kλ/R)·sin60° along the axis of symmetry (the sideways parts cancel).\nE = 2 × (1/4πε₀) × 3Q/(2πR) × (√3/2) × 1/R = 3√3Q/(8π²ε₀R²).\nThe charge is negative, so the field points towards the arc, i.e. along +x, which is î. Answer (a)."},
{"y":"JEE Main 2021 · 31 Aug · Shift 2","tp":"egs","st":"Statements, matching and subjective","q":"Choose the incorrect statement.\n(A) The electric lines of force entering into a Gaussian surface provide negative flux.\n(B) A charge 'q' is placed at the centre of a cube. The flux through all the faces will be the same.\n(C) In a uniform electric field net flux through a closed Gaussian surface containing no net charge, is zero.\n(D) When electric field is parallel to a Gaussian surface, it provides a finite non-zero flux.\nChoose the most appropriate answer from the options given below.","o":["(B) and (D) only","(C) and (D) only","(A) and (C) only","(D) only"],"c":3,"s":"(A) is true: flux = E·A is negative where lines enter the surface.\n(B) is true: by symmetry every face of the cube gets the same share, q/6ε₀.\n(C) is true: as many lines leave as enter, so the net flux is zero when no charge is enclosed.\n(D) is false: if E is parallel to the surface, the angle between E and the area vector is 90°, so E·A = 0.\nOnly (D) is incorrect. Answer (d)."},
{"y":"JEE Main 2021 · 22 Jul · Shift 2","tp":"efl","st":"Electric dipole","q":"An electric dipole is placed on x-axis in proximity to a line charge of linear charge density 3.0 × 10⁻⁶ C/m. Line charge is placed on z-axis and positive and negative charge of dipole is at a distance of 10 mm and 12 mm from the origin respectively. If total force of 4 N is exerted on the dipole, find out the amount of positive or negative charge of the dipole.","o":["4.44 μC","8.8 μC","0.485 mC","815.1 nC"],"c":0,"s":"Field of a line charge: E = 2kλ/r = λ/(2πε₀r).\nBoth charges lie on the same side of the line. The +q at 10 mm is pushed outwards and the −q at 12 mm is pulled inwards, so the forces oppose each other along the x-axis.\nF = q·2kλ(1/0.010 − 1/0.012) = q × 2 × 9×10⁹ × 3×10⁻⁶ × (100 − 83.3) = q × 9×10⁵ N/C.\nq = 4/(9×10⁵) = 4.44×10⁻⁶ C = 4.44 μC. Answer (a)."},
{"y":"JEE Main 2021 · 25 Jul · Shift 2","tp":"efl","st":"Electric dipole","q":"Two ideal electric dipoles A and B, having their dipole moment p₁ and p₂ respectively are placed on a plane with their centres O as shown in the figure. At point C on the axis of dipole A, the resultant electric field is making an angle of 37° with the axis. The ratio of the dipole moment of A and B, {p₁;p₂} is (Take sin37° = {3;5})","fig":{"w":340,"h":200,"alt":"Dipole A along the horizontal axis through O with point C on that axis far to the right, and dipole B vertical through O with its negative charge on top and positive charge below","d":[["l",40,100,300,100],["l",150,45,150,155],["c",110,100,3,"F"],["c",190,100,3,"F"],["c",150,60,3,"F"],["c",150,140,3,"F"],["t",104,92,"A","es"],["t",100,115,"−","es"],["t",196,115,"+","s"],["t",158,64,"−  B","s"],["t",158,148,"+","s"],["t",150,116,"O","ms"],["t",295,92,"C","es"]]},"o":["{4;3}","{3;2}","{2;3}","{3;8}"],"c":2,"s":"Point C is on the axis of A and on the equatorial line of B.\nField of A at C (axial): E₁ = 2kp₁/r³, along the axis.\nField of B at C (equatorial): E₂ = kp₂/r³, perpendicular to the axis.\nThe resultant makes 37° with the axis, so tan37° = E₂/E₁ = 3/4.\nkp₂/(2kp₁) = 3/4, so p₂/p₁ = 3/2 and p₁/p₂ = 2/3. Answer (c)."},
{"y":"JEE Main 2021 · 27 Jul · Shift 2","tp":"efl","st":"Field of point charges and distributions","q":"What will be the magnitude of electric field at point O as shown in figure? Each side of the figure is l and perpendicular to each other.","fig":{"w":340,"h":200,"alt":"Charges at the eight points around O of a square grid of side l: A minus q, B plus q, C plus 2q, D plus q, G plus 2q, H minus q, F plus q, E plus 2q","d":[["l",115,55,115,110],["l",115,110,170,110],["l",170,110,170,55],["l",170,55,225,55],["l",170,110,225,110],["l",225,110,225,165],["l",170,110,170,165],["l",170,165,115,165],["c",115,55,3,"F"],["c",115,110,3,"F"],["c",170,55,3,"F"],["c",225,55,3,"F"],["c",225,110,3,"F"],["c",225,165,3,"F"],["c",170,165,3,"F"],["c",115,165,3,"F"],["c",170,110,2.5],["t",115,45,"A (−q)","ms"],["t",108,114,"B (+q)","es"],["t",170,45,"C (+2q)","ms"],["t",225,45,"D (+q)","ms"],["t",233,114,"G (+2q)","s"],["t",225,184,"H (−q)","ms"],["t",170,184,"F (+q)","ms"],["t",115,184,"E (+2q)","ms"],["t",176,104,"O","s"],["t",108,86,"l","es"],["t",142,126,"l","ms"],["t",177,86,"l","s"],["t",197,126,"l","ms"],["t",177,146,"l","s"]]},"o":["{q;4πε₀·2l²}","{1;4πε₀}·{q;2l²}(2√2 − 1)","{1;4πε₀}·{q;l²}","{1;4πε₀}·{2q;2l²}(√2)"],"c":1,"s":"Put O at the origin. The charges are: A(−l, l) = −q, B(−l, 0) = +q, C(0, l) = +2q, D(l, l) = +q, G(l, 0) = +2q, H(l, −l) = −q, F(0, −l) = +q, E(−l, −l) = +2q.\nA and H are both −q at opposite corners: their fields at O cancel.\nB and G: net kq/l² towards −x. C and F: net kq/l² towards −y.\nD and E lie on one diagonal: net kq/(2l²) along the direction (+1, +1)/√2, because E (2q) wins over D (q).\nEx = Ey = −kq/l² + kq/(2√2 l²). Magnitude = √2·(kq/l²)(1 − 1/(2√2)) = (kq/2l²)(2√2 − 1).\nE = (1/4πε₀)(q/2l²)(2√2 − 1). Answer (b)."},
{"y":"JEE Main 2021 · 16 Mar · Shift 2","tp":"efl","st":"Field of point charges and distributions","q":"Find out the surface charge density at the intersection of point x = 3 m plane and x-axis, in the region of uniform line charge of 8 nC/m lying along the z-axis in free space.","o":["47.88 C m⁻²","0.424 nC m⁻²","0.07 nC m⁻²","4.0 nC m⁻²"],"c":1,"s":"The line charge along the z-axis gives a radial field E = λ/(2πε₀r) = 2kλ/r.\nAt r = 3 m: E = 2 × 9×10⁹ × 8×10⁻⁹/3 = 48 N/C.\nThe surface charge density (flux density) there is σ = ε₀E = 8.85×10⁻¹² × 48 = 4.24×10⁻¹⁰ C/m² = 0.424 nC/m². Answer (b)."},
{"y":"JEE Main 2021 · 18 Mar · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"An oil drop of radius 2 mm with a density 3 g cm⁻³ is held stationary under a constant electric field 3.55 × 10⁵ V m⁻¹ in the Millikan's oil drop experiment. What is the number of excess electrons that the oil drop will possess? Consider g = 9.81 m/s²","o":["17.3 × 10¹⁰","1.73 × 10¹²","1.73 × 10¹⁰","48.8 × 10¹¹"],"c":2,"s":"The drop is stationary, so qE = mg, with q = ne.\nm = (4/3)πr³ρ = (4/3)π(2×10⁻³)³ × 3000 ≈ 1.005×10⁻⁴ kg.\nmg = 1.005×10⁻⁴ × 9.81 ≈ 9.86×10⁻⁴ N.\nq = mg/E = 9.86×10⁻⁴/(3.55×10⁵) ≈ 2.78×10⁻⁹ C.\nn = q/e = 2.78×10⁻⁹/(1.6×10⁻¹⁹) ≈ 1.73×10¹⁰. Answer (c)."},
{"y":"JEE Main 2021 · 24 Feb · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"A cube of side 'a' has point charges +Q located at each of its vertices except at the origin where the charge is −Q. The electric field at the centre of cube is","fig":{"w":340,"h":240,"alt":"A cube of side a with charge plus Q at seven vertices and minus Q at the vertex at the origin, with x up, z to the right and y toward the viewer","d":[["l",150,150,240,150],["l",150,150,105,190],["l",150,150,150,60],["l",240,150,195,190],["l",240,150,240,60],["l",105,190,195,190],["l",105,190,105,100],["l",195,190,195,100],["l",150,60,240,60],["l",150,60,105,100],["l",240,60,195,100],["l",105,100,195,100],["l",150,150,150,20,"a"],["l",150,150,300,150,"a"],["l",150,150,66,226,"a"],["t",156,18,"x","s"],["t",302,154,"z","s"],["t",60,226,"y","es"],["c",150,150,3,"F"],["c",240,150,3,"F"],["c",105,190,3,"F"],["c",195,190,3,"F"],["c",150,60,3,"F"],["c",240,60,3,"F"],["c",105,100,3,"F"],["c",195,100,3,"F"],["t",158,166,"−Q","s"],["t",156,56,"+Q","s"],["t",246,146,"+Q","s"],["t",246,56,"+Q","s"],["t",100,204,"+Q","es"],["t",98,96,"+Q","es"],["t",200,204,"+Q","s"],["t",200,96,"+Q","s"]]},"o":["{−2Q;3√3πε₀a²}(x̂ + ŷ + ẑ)","{2Q;3√3πε₀a²}(x̂ + ŷ + ẑ)","{Q;3√3πε₀a²}(x̂ + ŷ + ẑ)","{−Q;3√3πε₀a²}(x̂ + ŷ + ẑ)"],"c":0,"s":"If all eight vertices carried +Q, the field at the centre would be zero by symmetry.\nThe actual cube = (all +Q) + (a charge −2Q placed at the origin vertex). So the field is that of −2Q alone.\nDistance from a vertex to the centre: r² = 3a²/4. Magnitude = (1/4πε₀)(2Q)/(3a²/4) = 2Q/(3πε₀a²).\nThe field of a negative charge points towards it, i.e. along −(x̂ŷẑ)/√3 (the origin is at the corner, axes along the edges).\nE = −2Q/(3√3 πε₀a²)(x̂ + ŷ + ẑ). Answer (a)."},
{"y":"JEE Main 2021 · 25 Feb · Shift 2","tp":"egs","st":"Electric flux","q":"A charge 'q' is placed at one corner of a cube as shown in figure. The flux of electrostatic field E⃗ through the shaded area is","fig":{"w":340,"h":240,"alt":"A cube with charge q at the corner at the origin; the shaded area is a triangle on the top face together with a triangle on the right face","d":[["l",150,150,150,60],["l",150,150,240,150],["l",150,150,105,190],["l",150,60,240,60],["l",150,60,105,100],["l",240,150,240,60],["l",240,150,195,190],["l",240,60,195,100],["l",105,190,105,100],["l",105,190,195,190],["l",105,100,195,100],["l",195,190,195,100],["p","M150,60 L240,60 L195,100 Z","f"],["p","M240,60 L195,100 L195,190 Z","f"],["l",150,150,150,20,"a"],["l",150,150,310,150,"a"],["l",150,150,66,226,"a"],["t",156,18,"Z","s"],["t",312,154,"Y","s"],["t",60,226,"X","es"],["c",150,150,3.5,"F"],["t",156,168,"q","s"]]},"o":["{q;8ε₀}","{q;48ε₀}","{q;4ε₀}","{q;24ε₀}"],"c":3,"s":"A charge at a corner is shared by 8 identical cubes, so the flux through this cube is q/(8ε₀).\nThe three faces that meet at q have zero flux (the field lies in their planes). The other three faces share q/8ε₀ equally by symmetry: q/(24ε₀) each.\nThe shaded area is half of the top face plus half of the right face (each half carries half the flux by symmetry).\nFlux = ½(q/24ε₀) + ½(q/24ε₀) = q/(24ε₀). Answer (d)."},
{"y":"JEE Main 2021 · 26 Feb · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Find the electric field at point P (as shown in figure) on the perpendicular bisector of a uniformly charged thin wire of length L carrying a charge Q. The distance of the point P from the centre of the rod is a = {√3;2}L.","fig":{"w":340,"h":200,"alt":"A vertical uniformly charged rod of length L with centre O and a point P at distance a to the right on the perpendicular bisector","d":[["r",60,20,10,160,"f"],["l",36,20,36,180,"b"],["t",28,104,"L","es"],["c",65,100,2.5,"F"],["t",72,114,"O","s"],["l",65,100,280,100,"d"],["c",280,100,3,"F"],["t",284,94,"P","s"],["l",90,70,270,70,"b"],["t",180,64,"a","ms"],["t",65,196,"Q","ms"]]},"o":["{Q;3πε₀L²}","{√3Q;4πε₀L²}","{Q;4πε₀L²}","{Q;2√3πε₀L²}"],"c":3,"s":"For a finite rod, the field at distance a on the perpendicular bisector is E = kQ/(a√(a²+L²/4)).\nHere a = (√3/2)L, so a² + L²/4 = 3L²/4 + L²/4 = L², and the square root is L.\nE = (1/4πε₀)·Q/((√3/2)L·L) = (1/4πε₀)·2Q/(√3L²).\nE = Q/(2√3 πε₀L²). Answer (d)."},
{"y":"JEE Main 2020 · 2 Sep · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"A charged particle (mass m and charge q) moves along X-axis with velocity v₀. When it passes through the origin it enters a region having uniform electric field E⃗ = −Eĵ which extends upto x = d. Equation of path of electron in the region x > d is","o":["y = {qEd;mv₀²}(x − d)","y = {qEd;mv₀²}({d;2} − x)","y = {qEd;mv₀²}x","y = {qEd²;mv₀²}x"],"c":1,"s":"In 0 < x < d the force is qE along −y and the speed along x stays v₀, so the time taken is t = d/v₀.\nAt x = d: y₁ = −½(qE/m)(d/v₀)² = −qEd²/(2mv₀²) and v_y = −qEd/(mv₀).\nBeyond x = d there is no field, so the path is a straight line with slope v_y/v₀ = −qEd/(mv₀²).\ny = y₁ + slope·(x − d) = −qEd²/(2mv₀²) − (qEd/mv₀²)(x − d) = (qEd/mv₀²)(d/2 − x). Answer (b)."},
{"y":"JEE Main 2020 · 4 Sep · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"Two charged thin infinite plane sheets of uniform surface charge density σ₊ and σ₋, where |σ₊| > |σ₋|, intersect at right angle. Which of the following best represents the electric field lines for this system","fig":{"w":340,"h":244,"alt":"Four field line patterns drawn around two crossing sheets: (a) concentric ellipses, (b) tall nested diamonds, (c) concentric circles, (d) wide nested diamonds","d":[["l",10,62,158,62],["l",84,6,84,118],["t",158,58,"σ₊","es"],["t",88,12,"σ₋","s"],["t",4,14,"(a)","s"],["p","M64,62 A20,13 0 1 1 104,62 A20,13 0 1 1 64,62 Z",""],["p","M46,62 A38,25 0 1 1 122,62 A38,25 0 1 1 46,62 Z",""],["p","M28,62 A56,38 0 1 1 140,62 A56,38 0 1 1 28,62 Z",""],["l",86,49,82,49,"a"],["l",86,37,82,37,"a"],["l",86,24,82,24,"a"],["l",180,62,328,62],["l",254,6,254,118],["t",328,58,"σ₊","es"],["t",258,12,"σ₋","s"],["t",174,14,"(b)","s"],["l",268,62,254,36,"a"],["l",240,62,254,36,"a"],["l",240,62,254,88,"a"],["l",268,62,254,88,"a"],["l",280,62,254,20,"a"],["l",228,62,254,20,"a"],["l",228,62,254,104,"a"],["l",280,62,254,104,"a"],["l",292,62,254,6,"a"],["l",216,62,254,6,"a"],["l",216,62,254,118,"a"],["l",292,62,254,118,"a"],["l",10,184,158,184],["l",84,128,84,240],["t",158,180,"σ₊","es"],["t",88,134,"σ₋","s"],["t",4,136,"(c)","s"],["c",84,184,16],["l",86,168,82,168,"a"],["c",84,184,32],["l",86,152,82,152,"a"],["c",84,184,48],["l",86,136,82,136,"a"],["l",180,184,328,184],["l",254,128,254,240],["t",328,180,"σ₊","es"],["t",258,134,"σ₋","s"],["t",174,136,"(d)","s"],["l",254,170,280,184,"a"],["l",254,170,228,184,"a"],["l",254,198,228,184,"a"],["l",254,198,280,184,"a"],["l",254,158,300,184,"a"],["l",254,158,208,184,"a"],["l",254,210,208,184,"a"],["l",254,210,300,184,"a"],["l",254,146,320,184,"a"],["l",254,146,188,184,"a"],["l",254,222,188,184,"a"],["l",254,222,320,184,"a"]]},"o":["Pattern (a)","Pattern (b)","Pattern (c)","Pattern (d)"],"c":1,"s":"An infinite sheet gives a uniform field σ/2ε₀ on each side, normal to the sheet: away from the positive sheet and towards the negative one.\nSo in each quadrant the resultant field has a fixed size and direction: the field lines are straight and parallel there, not circles or ellipses. This rules out (a) and (c).\nThe σ₊ sheet gives the larger component, normal to itself, so every line makes more than 45° with the σ₊ sheet and the lines run steeply. The lines bend as they cross the σ₋ sheet, giving the tall nested-diamond pattern of (b).\nPattern (d) has lines flatter than 45°, which would need |σ₋| > |σ₊|. Answer (b)."},
{"y":"JEE Main 2020 · 4 Sep · Shift 2","tp":"efl","st":"Field lines and motion in a field","q":"A particle of charge q and mass m is subjected to an electric field E = E₀(1 − ax²) in the x-direction, where a and E₀ are constants. Initially the particle was at rest at x = 0. Other than the initial position the kinetic energy of the particle becomes zero when the distance of the particle from the origin is","o":["√{2;a}","√{1;a}","a","√{3;a}"],"c":3,"s":"Work done by the field from 0 to x: W = q∫E dx = qE₀(x − ax³/3).\nThe particle starts from rest, so its kinetic energy equals W.\nKE = 0 again when x − ax³/3 = 0. With x ≠ 0 this gives ax²/3 = 1.\nx² = 3/a, so x = √(3/a). Answer (d)."},
{"y":"JEE Main 2020 · 6 Sep · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Charges Q₁ and Q₂ are at points A and B of a right angle triangle OAB (see figure). The resultant electric field at point O is perpendicular to the hypotenuse, then Q₁/Q₂ is proportional to","fig":{"w":340,"h":200,"alt":"Right angled triangle OAB with the right angle at O, A directly above O at distance x1 carrying Q1 and B to the right of O at distance x2 carrying Q2","d":[["l",50,170,50,30],["l",50,170,270,170],["l",50,30,270,170],["t",52,22,"A  Q₁","s"],["t",40,104,"x₁","es"],["t",160,186,"x₂","ms"],["t",276,176,"B  Q₂","s"],["t",38,174,"O","es"]]},"o":["{x₁³;x₂³}","{x₂;x₁}","{x₁;x₂}","{x₂²;x₁²}"],"c":2,"s":"Put O at the origin with A on the y-axis (OA = x₁) and B on the x-axis (OB = x₂).\nFields at O: E₁ = kQ₁/x₁² along the y-axis and E₂ = kQ₂/x₂² along the x-axis. The resultant makes angle α with the x-axis, tanα = E₁/E₂ = Q₁x₂²/(Q₂x₁²).\nThe hypotenuse AB has direction (x₂, −x₁), so a line perpendicular to it has direction (x₁, x₂): tanα = x₂/x₁.\nEquate: Q₁x₂²/(Q₂x₁²) = x₂/x₁, so Q₁/Q₂ = x₁/x₂. Answer (c)."},
{"y":"JEE Main 2020 · 6 Sep · Shift 2","tp":"egs","st":"Gauss's law and symmetric bodies","q":"Consider the force F on a charge 'q' due to a uniformly charged spherical shell of radius R carrying charge Q distributed uniformly over it. Which one of the following statements is true for F, if 'q' is placed at distance r from the centre of the shell?","o":["F = {Qq;4πε₀R²} for r < R","{qQ;4πε₀R²} > F > 0 for r < R","F = {Qq;4πε₀r²} for r > R","F = {Qq;4πε₀r²} for all r"],"c":2,"s":"By Gauss's law, outside a uniformly charged shell the field is the same as if all the charge Q were at the centre: E = Q/(4πε₀r²) for r > R.\nSo F = qE = Qq/(4πε₀r²) for r > R, which is statement (c).\nInside the shell (r < R) the field is zero, so F = 0 there; statements (a), (b) and (d) all fail for r < R. Answer (c)."},
{"y":"JEE Main 2020 · 7 Jan · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Two infinite planes each with uniform surface charge density +σ are kept in such a way that the angle between them is 30°. The electric field in the region shown between them is given by","fig":{"w":340,"h":200,"alt":"Two planes seen edge on meeting at 30 degrees at a vertex on the right: one horizontal, one rising to the upper left, both carrying plus sigma, with x and y axes at the right","d":[["l",30,150,200,150],["l",200,150,53,65],["t",30,168,"+σ","s"],["t",34,62,"+σ","s"],["t",150,143,"30°","s"],["p","M170,150 A30,30 0 0 0 174,135"],["l",265,165,265,40,"a"],["l",265,165,335,165,"a"],["t",270,48,"y","s"],["t",332,158,"x","es"]]},"o":["{σ;ε₀}[(1 + {√3;2})ŷ + {x̂;2}]","{σ;2ε₀}[(1 + √3)ŷ + {x̂;2}]","{σ;2ε₀}[(1 + √3)ŷ − {x̂;2}]","{σ;2ε₀}[(1 − {√3;2})ŷ − {x̂;2}]"],"c":3,"s":"Each plane gives a field σ/2ε₀, normal to the plane and pointing away from it (σ is positive).\nHorizontal plane: in the wedge (above it) the field is (σ/2ε₀)ŷ.\nInclined plane (30° to the horizontal, rising to the left): the wedge lies below it, and the unit normal pointing away from the plane there is (−sin30°, −cos30°) = (−½, −√3/2). Field = (σ/2ε₀)(−x̂/2 − (√3/2)ŷ).\nAdd: E = (σ/2ε₀)[(1 − √3/2)ŷ − x̂/2]. Answer (d)."},
{"y":"JEE Main 2020 · 8 Jan · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Three charged particles A, B and C with charges −4q, 2q and −2q are present on the circumference of a circle of radius d. The charged particles A, C and centre O of the circle formed an equilateral triangle as shown in figure. Electric field at O along x-direction is","fig":{"w":340,"h":240,"alt":"A circle of radius d centred at O with A minus 4q at 30 degrees above the x-axis, C minus 2q at 30 degrees below it and B plus 2q at 150 degrees","d":[["c",150,120,95],["l",20,120,330,120,"a"],["l",150,228,150,10,"a"],["l",150,120,232.3,72.5],["l",150,120,232.3,167.5],["l",150,120,67.7,72.5],["c",232.3,72.5,3,"F"],["c",232.3,167.5,3,"F"],["c",67.7,72.5,3,"F"],["t",238.3,68.5,"A (−4q)","s"],["t",238.3,179.5,"C (−2q)","s"],["t",63.7,66.5,"B (2q)","es"],["t",176,114,"30°","s"],["t",176,136,"30°","s"],["t",110,112,"150°","s"],["t",326,114,"x","es"],["t",156,16,"y","s"],["t",144,134,"O","es"]]},"o":["{√3q;4πε₀d²}","{3√3q;4πε₀d²}","{√3q;πε₀d²}","{2√3q;πε₀d²}"],"c":2,"s":"Use units of kq/d². Fields point towards a negative charge and away from a positive one.\nA (−4q at 30° above +x): 4 units towards A: (4cos30°, 4sin30°).\nC (−2q at 30° below +x): 2 units towards C: (2cos30°, −2sin30°).\nB (+2q at 150°): 2 units away from B: (2cos30°, −2sin30°).\nx-components: (4 + 2 + 2)(√3/2) = 4√3. y-components: 2 − 1 − 1 = 0.\nE = 4√3 · q/(4πε₀d²) = √3 q/(πε₀d²) along +x. Answer (c)."},
{"y":"JEE Main 2020 · 8 Jan · Shift 2","tp":"efl","st":"Field lines and motion in a field","q":"A particle of mass m and charge q is released from rest in a uniform electric field. If there is no other force on the particle, the dependence of its speed v on the distance x travelled by it is correctly given by (graphs are schematic and not drawn to scale)","fig":{"w":340,"h":236,"alt":"Four graphs of speed v against distance x: (a) a straight line through the origin, (b) a curve bending upward, (c) a curve rising steeply then flattening, (d) an S shaped curve","d":[["l",26,94,159,94,"a"],["l",26,94,26,10,"a"],["t",6,16,"(a)","s"],["t",159,107,"x","es"],["t",30,12,"v","s"],["l",26,94,131,26],["l",196,94,329,94,"a"],["l",196,94,196,10,"a"],["t",176,16,"(b)","s"],["t",329,107,"x","es"],["t",200,12,"v","s"],["p","M196,94 Q266,88 301,26"],["l",26,212,159,212,"a"],["l",26,212,26,128,"a"],["t",6,134,"(c)","s"],["t",159,225,"x","es"],["t",30,130,"v","s"],["p","M26,212 C34,167 71,147 131,142"],["l",196,212,329,212,"a"],["l",196,212,196,128,"a"],["t",176,134,"(d)","s"],["t",329,225,"x","es"],["t",200,130,"v","s"],["p","M196,212 C251,210 241,142 301,142"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":2,"s":"The force qE is constant, so by the work-energy theorem qEx = ½mv².\nHence v = √(2qEx/m), i.e. v ∝ √x.\nThe graph of v against x starts at the origin, rises steeply and then flattens (a parabola lying on its side). This is graph (c). Answer (c)."},
{"y":"JEE Main 2020 · 9 Jan · Shift 1","tp":"efl","st":"Electric dipole","q":"An electric dipole of moment p⃗ = (−î − 3ĵ + 2k̂) × 10⁻²⁹ C m is at the origin (0, 0, 0). The electric field due to this dipole at r⃗ = +î + 3ĵ + 5k̂ (note that r⃗·p⃗ = 0) is parallel to","o":["(+î − 3ĵ − 2k̂)","(−î − 3ĵ + 2k̂)","(+î + 3ĵ − 2k̂)","(−î + 3ĵ − 2k̂)"],"c":2,"s":"r·p = (1)(−1) + (3)(−3) + (5)(2) = −1 − 9 + 10 = 0, so the point lies on the equatorial plane of the dipole.\nOn the equatorial plane the field is E = −kp/r³, i.e. antiparallel to p.\nSo E is parallel to −p, that is (î + 3ĵ − 2k̂). Answer (c)."},
{"y":"JEE Main 2020 · 9 Jan · Shift 1","tp":"egs","st":"Gauss's law and symmetric bodies","q":"Consider a sphere of radius R which carries a uniform charge density ρ. If a sphere of radius {R;2} is carved out of it, as shown, the ratio {|E_A|;|E_B|} of magnitude of electric field E_A and E_B, respectively, at points A and B due to the remaining portion is","fig":{"w":340,"h":250,"alt":"A sphere of radius R with centre A and a spherical cavity of radius R/2 whose centre is R/2 above A; point B is on the surface directly below A","d":[["c",170,120,100],["c",170,70,50,"d"],["l",170,10,170,244,"d"],["c",170,70,2.5,"F"],["c",170,120,2.5,"F"],["c",170,220,2.5,"F"],["l",170,70,122,70,"a"],["t",146,62,"R/2","ms"],["l",170,120,80,152,"da"],["t",112,150,"R","s"],["t",176,134,"A","s"],["t",176,238,"B","s"]]},"o":["{21;34}","{18;54}","{17;54}","{18;34}"],"c":3,"s":"A is the centre of the big sphere; the cavity centre is R/2 above A. B is on the surface, R below A. Use superposition: remaining = full sphere (+ρ) + cavity sphere (−ρ).\nAt A: the full sphere gives 0. A is on the surface of the cavity sphere (radius R/2), where a ball of density ρ gives ρ(R/2)/(3ε₀) = ρR/(6ε₀). So E_A = ρR/(6ε₀).\nAt B: the full sphere gives ρR/(3ε₀). The cavity charge ρ(4/3)π(R/2)³ = πρR³/6, at distance 3R/2, gives (πρR³/6)/(4πε₀·9R²/4) = ρR/(54ε₀) in the opposite sense.\nE_B = ρR/(3ε₀) − ρR/(54ε₀) = 17ρR/(54ε₀).\nE_A/E_B = (1/6)/(17/54) = 9/17 = 18/34. Answer (d)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 1","tp":"ecl","st":"Equilibrium and motion of charges","q":"The bob of a simple pendulum has mass 2 g and a charge of 5.0 μC. It is at rest in a uniform horizontal electric field of intensity 2000 V m⁻¹. At equilibrium, the angle that the pendulum makes with the vertical is (take g = 10 m s⁻²)","o":["tan⁻¹(0.2)","tan⁻¹(0.5)","tan⁻¹(2.0)","tan⁻¹(5.0)"],"c":1,"s":"In equilibrium the bob is acted on by weight mg (down), the electric force qE (horizontal) and the tension.\ntanθ = qE/(mg) = (5.0×10⁻⁶ × 2000)/(2×10⁻³ × 10) = 10⁻²/(2×10⁻²) = 0.5.\nθ = tan⁻¹(0.5). Answer (b)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 2","tp":"efl","st":"Electric dipole","q":"An electric dipole is formed by two equal and opposite charges q with separation d. The charges have same mass m. It is kept in a uniform electric field E. If it is slightly rotated from its equilibrium orientation, then its angular frequency ω is","o":["√{2qE;md}","√{qE;2md}","2√{qE;md}","√{qE;md}"],"c":0,"s":"For a small angle θ the torque is τ = −pE sinθ ≈ −(qd)Eθ.\nMoment of inertia about the centre: I = 2 × m(d/2)² = md²/2.\nSHM: ω² = qdE/I = qdE/(md²/2) = 2qE/(md).\nω = √(2qE/(md)). Answer (a)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 2","tp":"evp","st":"Potential energy and work","q":"A positive point charge is released from rest at a distance r₀ from a positive line charge with uniform density. The speed (v) of the point charge, as a function of instantaneous distance r from line charge, is proportional to","o":["v ∝ ln(r/r₀)","v ∝ √(ln(r/r₀))","v ∝ e^(+r/r₀)","v ∝ (r/r₀)"],"c":1,"s":"Field of a line charge: E = λ/(2πε₀r).\nWork done by the field as the charge moves from r₀ to r: W = q∫E dr = (qλ/2πε₀) ln(r/r₀).\nThis equals the kinetic energy: ½mv² = (qλ/2πε₀) ln(r/r₀).\nSo v = √[(qλ/πε₀m) ln(r/r₀)], i.e. v ∝ √(ln(r/r₀)). Answer (b)."},
{"y":"JEE Main 2019 · 9 Apr · Shift 2","tp":"efl","st":"Electric dipole","q":"Four point charges −q, +q, +q and −q are placed on y-axis at y = −2d, y = −d, y = +d and y = +2d, respectively. The magnitude of the electric field E at a point on the x-axis at x = D, with D ≫ d, will behave as","o":["E ∝ {1;D³}","E ∝ {1;D}","E ∝ {1;D⁴}","E ∝ {1;D²}"],"c":2,"s":"Group the charges into two dipoles: (−q at −2d, +q at −d) has moment qd along +y; (+q at +d, −q at +2d) has moment qd along −y.\nThe point on the x-axis is (nearly) on the equatorial line of each, so each gives about kqd/D³, in opposite directions: the 1/D³ terms cancel.\nNet charge and net dipole moment are both zero, so the leading term is the quadrupole term. The two dipoles are 3d apart, so what survives is smaller by a factor of about d/D.\nE ∝ (1/D³)(d/D) ∝ 1/D⁴. Answer (c)."},
{"y":"JEE Main 2019 · 10 Apr · Shift 2","tp":"efl","st":"Field lines and motion in a field","q":"A simple pendulum of length L is placed between the plates of a parallel plate capacitor having electric field E, as shown in figure. Its bob has mass m and charge q. The time period of the pendulum is given by","fig":{"w":340,"h":230,"alt":"A simple pendulum of length L with a bob of mass m and charge q hanging between two vertical capacitor plates, positive on the left and negative on the right, with the field E pointing to the right","d":[["l",100,30,100,190,"B"],["l",240,30,240,190,"B"],["l",150,22,190,22,"B"],["l",170,22,170,150],["c",170,150,6,"F"],["t",180,154,"m, q","s"],["t",176,92,"L","s"],["l",110,208,230,208,"a"],["t",170,224,"E","ms"],["t",92,50,"+","es"],["t",92,90,"+","es"],["t",92,130,"+","es"],["t",92,170,"+","es"],["t",248,50,"−","s"],["t",248,90,"−","s"],["t",248,130,"−","s"],["t",248,170,"−","s"]]},"o":["2π√{L;g − qE/m}","2π√{L;√(g² + (qE/m)²)}","2π√{L;g + qE/m}","2π√{L;√(g² − q²E²/m²)}"],"c":1,"s":"The bob feels gravity mg (down) and the electric force qE (horizontal). These are perpendicular, so the effective acceleration is g_eff = √(g² + (qE/m)²).\nThe pendulum swings about the new equilibrium direction as if gravity had this value.\nT = 2π√(L/g_eff) = 2π√(L/√(g² + (qE/m)²)). Answer (b)."},
{"y":"JEE Main 2019 · 12 Apr · Shift 1","tp":"ecn","st":"Induced charge and shielding","q":"Shown in the figure is a shell made of a conductor. It has inner radius a and outer radius b, and carries charge Q. At its centre is a dipole p⃗ as shown. In this case","fig":{"w":340,"h":230,"alt":"A thick conducting spherical shell with inner radius a and outer radius b and a small dipole arrow p at its centre","d":[["c",170,115,100],["c",170,115,66],["l",170,128,170,98,"a"],["t",178,110,"p","s"],["l",170,115,236,115,"d"],["t",204,110,"a","ms"],["l",170,115,241,44,"d"],["t",214,70,"b","s"]]},"o":["surface charge density on the inner surface of the shell is zero everywhere","surface charge density on the inner surface is uniform and equal to {Q/2;4πa²}","electric field outside the shell is the same as that of a point charge at the centre of the shell","surface charge density on the outer surface depends on |p⃗|"],"c":2,"s":"The dipole is neutral, so the induced charge on the inner surface adds up to zero overall, but it is not zero everywhere: it is non-uniform (negative near the dipole's positive end and positive near its negative end). So (a) and (b) are false.\nThe shell carries Q and its inner surface holds net zero, so the outer surface holds Q. Inside the metal E = 0, so this charge spreads uniformly over the outer surface whatever p is; (d) is false.\nOutside, the field is that of a uniformly charged sphere, the same as a point charge Q at the centre. Answer (c)."},
{"y":"JEE Main 2019 · 12 Apr · Shift 2","tp":"egs","st":"Non-uniform charge distributions","q":"Let a total charge 2Q be distributed in a sphere of radius R, with the charge density given by ρ(r) = kr, where r is the distance from the centre. Two charges A and B, of −Q each, are placed on diametrically opposite points, at equal distance a, from the centre. If A and B do not experience any force, then","o":["a = 8^(−1/4) R","a = 2^(−1/4) R","a = {3R;2^(1/4)}","a = R/√3"],"c":0,"s":"Total charge: 2Q = ∫₀ᴿ kr·4πr² dr = πkR⁴, so k = 2Q/(πR⁴).\nCharge inside radius a: q_in = πka⁴ = 2Qa⁴/R⁴.\nForce on A from the sphere (attractive, towards the centre): (1/4πε₀)·Q·q_in/a² = (1/4πε₀)·2Q²a²/R⁴.\nForce on A from B (repulsive, distance 2a): (1/4πε₀)·Q²/(4a²).\nNo net force: 2a²/R⁴ = 1/(4a²), so a⁴ = R⁴/8 and a = 8^(−1/4) R. Answer (a)."},
{"y":"JEE Main 2019 · 9 Jan · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"For a uniformly charged ring of radius R, the electric field on its axis has the largest magnitude at a distance h from its centre. Then value of h is","o":["{R;√5}","{R;√2}","R","R√2"],"c":1,"s":"On the axis, E = kQh/(h²+R²)^(3/2).\nFor the maximum set dE/dh = 0: (h²+R²) − 3h² = 0, so R² = 2h².\nh = R/√2. Answer (b)."},
{"y":"JEE Main 2019 · 9 Jan · Shift 2","tp":"efl","st":"Field of point charges and distributions","q":"Two point charges q₁(√10 μC) and q₂(−25 μC) are placed on the x-axis at x = 1 m and x = 4 m respectively. The electric field (in V/m) at a point y = 3 m on y-axis is [Take {1;4πε₀} = 9×10⁹ N m² C⁻²]","o":["(63î − 27ĵ) × 10²","(81î − 81ĵ) × 10²","(−63î + 27ĵ) × 10²","(−81î + 81ĵ) × 10²"],"c":0,"s":"Take P = (0, 3). Distances: to q₁ at (1, 0), r₁ = √10; to q₂ at (4, 0), r₂ = 5.\nE₁ = 9×10⁹ × √10×10⁻⁶/10 = 900√10 V/m, away from q₁ along (−1, 3)/√10: E₁ = −900î + 2700ĵ.\nE₂ = 9×10⁹ × 25×10⁻⁶/25 = 9000 V/m, towards q₂ (it is negative) along (4, −3)/5: E₂ = 7200î − 5400ĵ.\nSum = 6300î − 2700ĵ = (63î − 27ĵ) × 10². Answer (a)."},
{"y":"JEE Main 2019 · 10 Jan · Shift 2","tp":"efl","st":"Electric dipole","q":"Charges −q and +q located at A and B, respectively, constitute an electric dipole. Distance AB = 2a, O is the mid point of the dipole and OP is perpendicular to AB. A charge Q is placed at P where OP = y and y ≫ 2a. The charge Q experiences an electrostatic force F. If Q is now moved along the equatorial line to P′ such that OP′ = {y;3}, force on Q will be close to ({y;3} ≫ 2a)","o":["27F","3F","{F;3}","9F"],"c":0,"s":"P and P′ both lie on the equatorial line, far from the dipole (y ≫ 2a).\nThere the dipole field is E = kp/y³, so the force F = QE ∝ 1/y³.\nWhen the distance becomes y/3: F′ = F × (y/(y/3))³ = 27F. Answer (a)."},
{"y":"JEE Main 2019 · 12 Jan · Shift 1","tp":"efl","st":"Electric dipole","q":"Determine the electric dipole moment of the system of three charges, placed on the vertices of an equilateral triangle, as shown in the figure.","fig":{"w":340,"h":230,"alt":"Equilateral triangle of side l with plus q at the origin on the left, plus q on the x-axis at the right and minus 2q at the top vertex","d":[["l",50,205,50,12,"a"],["l",50,205,320,205,"a"],["l",50,205,240,205,"B"],["l",50,205,145,40],["l",145,40,240,205],["t",36,222,"+q","es"],["t",240,222,"+q","ms"],["t",152,36,"−2q","s"],["t",86,116,"l","es"],["t",204,116,"l","s"],["t",145,220,"l","ms"],["t",318,198,"x","es"],["t",56,16,"y","s"]]},"o":["2qlĵ","(ql){î+ĵ;√2}","√3ql{ĵ−î;√2}","−√3qlĵ"],"c":3,"s":"The dipole moment is p = Σ qᵢrᵢ. Put +q at the origin, +q at (l, 0) and −2q at (l/2, √3 l/2).\np = q(0) + q(lî) − 2q[(l/2)î + (√3/2)lĵ]\n= qlî − qlî − √3 qlĵ = −√3 qlĵ.\n(The net charge is zero, so p does not depend on the choice of origin.) Answer (d)."},
{"y":"JEE Main 2018 · Online","tp":"egs","st":"Electric flux","q":"A charge Q is placed at a distance {a;2} above the centre of the square surface of edge a as shown in the figure. The electric flux through the square surface is","fig":{"w":340,"h":210,"alt":"A square surface of edge a drawn in perspective with a point charge Q a distance a/2 directly above its centre","d":[["p","M60,165 L230,165 L290,115 L120,115 Z","f"],["c",175,140,2,"F"],["c",175,45,3,"F"],["l",175,45,175,138,"d"],["t",183,98,"a/2","s"],["t",183,40,"Q","s"],["l",60,185,230,185,"b"],["t",145,200,"a","ms"]]},"o":["{Q;3ε₀}","{Q;6ε₀}","{Q;ε₀}","{Q;2ε₀}"],"c":1,"s":"Imagine a cube of edge a with Q at its centre. Since Q is a/2 above the centre of the square, the square is exactly one face of this cube.\nTotal flux from Q through the cube = Q/ε₀, shared equally by the 6 faces.\nFlux through one face = Q/(6ε₀). Answer (b)."},
{"y":"JEE Main 2018 · Online","tp":"egs","st":"Non-uniform charge distributions","q":"A solid ball of radius R has a charge density ρ given by ρ = ρ₀(1 − {r;R}) for 0 ≤ r ≤ R. The electric field outside the ball is","o":["{ρ₀R³;12ε₀r²}","{4ρ₀R³;3ε₀r²}","{3ρ₀R³;4ε₀r²}","{ρ₀R³;ε₀r²}"],"c":0,"s":"Total charge: Q = ∫₀ᴿ ρ₀(1 − r/R)·4πr² dr = 4πρ₀(R³/3 − R³/4) = πρ₀R³/3.\nOutside the ball, Gauss's law gives E = Q/(4πε₀r²) = (πρ₀R³/3)/(4πε₀r²).\nE = ρ₀R³/(12ε₀r²). Answer (a)."},
{"y":"JEE Main 2018 · Online","tp":"efl","st":"Field lines and motion in a field","q":"A body of mass M and charge q is connected to a spring of spring constant k. It is oscillating along x-direction about its equilibrium position, taken to be at x = 0, with an amplitude A. An electric field E is applied along the x-direction. Which of the following statements is correct?","o":["The total energy of the system is {1;2}Mω²A² − {1;2}{q²E²;k}.","The new equilibrium position is at a distance {2qE;k} from x = 0.","The new equilibrium position is at a distance {qE;2k} from x = 0.","The total energy of the system is {1;2}Mω²A² + {1;2}{q²E²;k}."],"c":3,"s":"With the field, the net force is −kx + qE = −k(x − qE/k), so the new equilibrium position is x₀ = qE/k. This rules out (b) and (c).\nThe body now oscillates about x₀. Besides the oscillation energy ½Mω²A² (with ω² = k/M), the system holds the spring energy of the shifted equilibrium, ½kx₀² = ½q²E²/k.\nTotal energy = ½Mω²A² + ½q²E²/k, which is statement (d), the official answer."},
{"y":"JEE Main 2017","tp":"efl","st":"Electric dipole","q":"An electric dipole has a fixed dipole moment p⃗, which makes angle θ with respect to x-axis. When subjected to an electric field E⃗₁ = Eî, it experiences a torque T⃗₁ = τk̂. When subjected to another electric field E⃗₂ = √3E₁ĵ it experiences a torque T⃗₂ = −T⃗₁. The angle θ is","o":["30°","45°","60°","90°"],"c":2,"s":"Write p = p(cosθ î + sinθ ĵ). The torque is T = p × E.\nField 1 (Eî): T₁ = −pE sinθ k̂.\nField 2 (√3Eĵ): T₂ = p cosθ × √3E k̂ = √3 pE cosθ k̂.\nGiven T₂ = −T₁: √3 pE cosθ = pE sinθ, so tanθ = √3.\nθ = 60°. Answer (c)."},
{"y":"JEE Main 2017 · Online","tp":"egs","st":"Electric flux","q":"Four closed surfaces and corresponding charge distributions are shown below.\nLet the respective electric fluxes through the surfaces be φ₁, φ₂, φ₃ and φ₄. Then","fig":{"w":340,"h":270,"alt":"Four closed surfaces S1 to S4: S1 encloses 2q; S2 encloses q, minus q, q and q; S3 encloses q and q with 5q outside; S4 encloses 8q, minus 2q and minus 4q with 3q outside","d":[["p","M20,30 Q40,16 62,22 L125,18 Q136,48 128,75 L40,86 Q30,62 20,52 Z"],["c",85,48,2,"F"],["t",90,52,"2q","s"],["t",75,104,"S₁","ms"],["p","M185,28 Q200,8 225,14 Q245,24 262,10 Q282,20 292,40 Q300,70 280,86 L205,90 Q182,70 185,28 Z"],["c",205,28,2,"F"],["t",209,32,"q","s"],["c",262,32,2,"F"],["t",266,36,"−q","s"],["c",205,68,2,"F"],["t",209,72,"q","s"],["c",272,68,2,"F"],["t",276,72,"q","s"],["t",240,106,"S₂","ms"],["p","M15,160 Q30,148 50,152 L60,158 Q70,172 88,160 L130,156 Q150,160 148,190 L145,216 L22,218 Q12,190 15,160 Z"],["c",28,198,2,"F"],["t",32,202,"q","s"],["c",128,198,2,"F"],["t",132,202,"q","s"],["c",80,146,2,"F"],["t",84,142,"5q","s"],["t",80,236,"S₃","ms"],["p","M212,132 Q222,122 250,125 L288,128 Q300,158 304,186 Q308,214 284,238 Q250,250 226,244 Q206,222 214,196 Q220,166 212,132 Z"],["c",234,146,2,"F"],["t",238,150,"8q","s"],["c",258,188,2,"F"],["t",262,192,"−2q","s"],["c",236,226,2,"F"],["t",240,230,"−4q","s"],["c",318,160,2,"F"],["t",322,164,"3q","s"],["t",252,262,"S₄","ms"]]},"o":["φ₁ = φ₂ = φ₃ = φ₄","φ₁ > φ₃; φ₂ < φ₄","φ₁ > φ₂ > φ₃ > φ₄","φ₁ < φ₂ = φ₃ > φ₄"],"c":0,"s":"Flux through a closed surface = (charge enclosed)/ε₀. Charges outside a surface do not change its net flux.\nS₁ encloses 2q. S₂ encloses q − q + q + q = 2q. S₃ encloses q + q = 2q (the 5q lies outside the notch). S₄ encloses 8q − 2q − 4q = 2q (the 3q lies outside).\nAll four enclose 2q, so φ₁ = φ₂ = φ₃ = φ₄ = 2q/ε₀. Answer (a)."},
{"y":"JEE Main 2016","tp":"egs","st":"Non-uniform charge distributions","q":"The region between two concentric spheres of radii 'a' and 'b', respectively (see figure), has volume charge density ρ = {A;r}, where A is a constant and r is the distance from the centre. At the centre of the spheres is a point charge Q. The value of A such that the electric field in the region between the spheres will be constant, is","fig":{"w":340,"h":230,"alt":"Two concentric spheres of radii a and b with a point charge Q at the centre","d":[["c",170,115,100],["c",170,115,50],["c",170,115,2.5,"F"],["t",160,128,"Q","es"],["l",170,115,220,115],["t",196,110,"a","ms"],["l",170,115,241,186],["t",214,160,"b","s"]]},"o":["{Q;2πa²}","{Q;2π(b²−a²)}","{2Q;π(a²−b²)}","{2Q;πa²}"],"c":0,"s":"At radius r (a < r < b) the enclosed charge is Q + ∫ₐʳ (A/r′)·4πr′² dr′ = Q + 2πA(r² − a²).\nE = [Q + 2πA(r² − a²)]/(4πε₀r²) = (Q − 2πAa²)/(4πε₀r²) + A/(2ε₀).\nFor E to be independent of r, the 1/r² term must vanish: Q = 2πAa².\nA = Q/(2πa²). Answer (a)."},
{"y":"JEE Main 2015","tp":"efl","st":"Field lines and motion in a field","q":"A long cylindrical shell carries positive surface charge σ in the upper half and negative surface charge −σ in the lower half. The electric field lines around the cylinder will look like figure given in (Figures are schematic and not drawn to scale)","fig":{"w":340,"h":240,"alt":"Four sketches of field lines around a cylinder with plus charge on the top half and minus charge on the bottom half: (a) nearly straight lines passing by, (b) radial lines from top and bottom plus side loops, (c) closed loops from top to bottom on both sides, (d) radial lines out of the whole cylinder","d":[["c",87,58,20],["l",67,58,107,58],["t",87,52,"+ + +","ms"],["t",87,73,"− − −","ms"],["t",4,14,"(a)","s"],["l",8,14,162,14,"a"],["l",8,26,162,26,"a"],["l",8,90,162,90,"a"],["l",8,102,162,102,"a"],["l",87,36,87,24,"a"],["l",87,92,87,80,"a"],["c",257,58,20],["l",237,58,277,58],["t",257,52,"+ + +","ms"],["t",257,73,"− − −","ms"],["t",174,14,"(b)","s"],["l",276.1,47,293.4,37,"a"],["l",293.4,79,276.1,69,"a"],["l",268,38.9,278,21.6,"a"],["l",278,94.4,268,77.1,"a"],["l",257,36,257,16,"a"],["l",257,100,257,80,"a"],["l",246,38.9,236,21.6,"a"],["l",236,94.4,246,77.1,"a"],["l",237.9,47,220.6,37,"a"],["l",220.6,79,237.9,69,"a"],["p","M277,52 C317,28 317,88 277,64","a"],["p","M237,52 C197,28 197,88 237,64","a"],["c",87,178,20],["l",67,178,107,178],["t",87,172,"+ + +","ms"],["t",87,193,"− − −","ms"],["t",4,134,"(c)","s"],["p","M91,158 C150,125 150,231 91,198","a"],["p","M83,158 C23,125 23,231 83,198","a"],["p","M91,158 C180,100 180,256 91,198","a"],["p","M83,158 C-6,100 -6,256 83,198","a"],["c",257,178,20],["l",237,178,277,178],["t",257,172,"+ + +","ms"],["t",257,193,"− − −","ms"],["t",174,134,"(d)","s"],["l",279,178,301,178,"a"],["l",272.6,162.4,288.1,146.9,"a"],["l",257,156,257,134,"a"],["l",241.4,162.4,225.9,146.9,"a"],["l",235,178,213,178,"a"],["l",241.4,193.6,225.9,209.1,"a"],["l",257,200,257,222,"a"],["l",272.6,193.6,288.1,209.1,"a"]]},"o":["Figure (a)","Figure (b)","Figure (c)","Figure (d)"],"c":2,"s":"Field lines start on positive charge and end on negative charge. Here the + half is on top and the − half on the bottom, so the lines leave the upper half, curve round both sides and return to the lower half, like the lines of a dipole.\nThe net charge is zero, so no lines go off to infinity: this rules out (b) and (d), where lines spread out radially. (a) shows nearly straight lines running past the cylinder, which does not match a charge-free source.\nFigure (c) shows closed loops from + to − on both sides. Answer (c)."},
{"y":"JEE Main 2015 · Online","tp":"efl","st":"Field of point charges and distributions","q":"A thin disc of radius b = 2a has a concentric hole of radius a in it (see figure). It carries uniform surface charge σ on it. If the electric field on its axis at height h (h << a) from its centre is given as Ch then value of C is","fig":{"w":340,"h":120,"alt":"A flat disc with a concentric circular hole, with a dotted axis through its centre; the hole has radius a and the disc radius b","d":[["p","M40,64 A130,40 0 1 1 300,64 A130,40 0 1 1 40,64 Z",""],["p","M105,64 A65,20 0 1 1 235,64 A65,20 0 1 1 105,64 Z",""],["l",170,8,170,118,"d"],["l",170,64,235,64],["t",203,58,"a","ms"],["l",170,64,40,64],["t",100,58,"b","ms"],["t",176,16,"h","s"]]},"o":["{σ;aε₀}","{σ;2aε₀}","{σ;4aε₀}","{σ;8aε₀}"],"c":2,"s":"The axial field of a full disc of radius R is (σ/2ε₀)[1 − h/√(h²+R²)].\nThe holed disc = disc of radius b minus disc of radius a: E = (σ/2ε₀)[h/√(h²+a²) − h/√(h²+b²)].\nFor h << a: √(h²+a²) ≈ a and √(h²+b²) ≈ b = 2a, so E ≈ (σh/2ε₀)(1/a − 1/2a) = σh/(4aε₀).\nSo C = σ/(4aε₀). Answer (c)."},
{"y":"JEE Main 2015 · Online","tp":"efl","st":"Field of point charges and distributions","q":"A wire of length L(= 20 cm), is bent into a semi-circular arc. If the two equal halves of the arc, were each to be uniformly charged with charges ±Q, [|Q| = 10³ε₀ coulomb where ε₀ is the permittivity (in SI units) of free space] the net electric field at the centre O of the semi-circular arc would be","fig":{"w":340,"h":170,"alt":"A semicircular arc above the x-axis with centre O; the left quarter carries plus Q and the right quarter minus Q","d":[["p","M70,130 A100,100 0 0 1 270,130","B"],["l",40,130,310,130,"a"],["l",170,130,170,10,"da"],["t",176,148,"O","s"],["t",108,54,"+Q","ms"],["t",236,54,"−Q","ms"],["t",306,124,"x","es"],["t",176,16,"y","s"]]},"o":["(50×10³ N/C)ĵ","(25×10³ N/C)î","(25×10³ N/C)ĵ","(50×10³ N/C)î"],"c":1,"s":"The arc length is πR = 0.20 m, so R = 0.2/π m. Each half (a quarter circle) has charge Q, so λ = Q/(πR/2) = 2Q/(πR).\nFrom the figure the left half is +Q and the right half is −Q. The field of each quarter at O has magnitude √2 kλ/R, pointing right-down for the + quarter and right-up for the − quarter. The y-components cancel and the x-components add.\nE = 2kλ/R = 2 × (1/4πε₀) × 2Q/(πR²) = Q/(π²ε₀R²).\nWith R² = 0.04/π²: E = Q/(0.04 ε₀) = 25 Q/ε₀ = 25×10³ N/C along +x. Answer (b)."},
{"y":"JEE Main 2014 · Online","tp":"egs","st":"Gauss's law and symmetric bodies","q":"The magnitude of the average electric field normally present in the atmosphere just above the surface of the Earth is about 150 N/C, directed inward towards the center of Earth. This gives the total net surface charge carried by the Earth to be [Given ε₀ = 8.85 × 10⁻¹² C²/N-m², R_E = 6.37 × 10⁶ m]","o":["+670 kC","−670 kC","−680 kC","+680 kC"],"c":2,"s":"Just outside a charged sphere, E = Q/(4πε₀R²) in magnitude.\nQ = 4πε₀R²E = 4π × 8.85×10⁻¹² × (6.37×10⁶)² × 150 ≈ 6.8×10⁵ C (about 680 kC).\nThe field points inward (towards the Earth), so the charge is negative.\nQ ≈ −680 kC. Answer (c)."},
{"y":"JEE Advanced 2014","tp":"egs","st":"Gauss's law and symmetric bodies","q":"Charges Q, 2Q and 4Q are uniformly distributed in three dielectric solid spheres 1, 2 and 3 of radii R/2, R and 2R respectively, as shown in figure. If magnitudes of the electric fields at point P at a distance R from the centre of spheres 1, 2 and 3 are E₁, E₂ and E₃ respectively, then","fig":{"w":340,"h":225,"alt":"Three solid spheres of radii R/2, R and 2R carrying Q, 2Q and 4Q, each with a point P at distance R from its centre: outside sphere 1, on the surface of sphere 2, inside sphere 3","d":[["c",50,120,15],["c",140,120,30],["c",255,120,60],["l",50,120,50,92,"a"],["l",140,120,140,92,"a"],["l",255,120,255,92,"a"],["t",50,84,"P","ms"],["t",140,84,"P","ms"],["t",255,84,"P","ms"],["t",56,108,"R","s"],["t",146,108,"R","s"],["t",261,108,"R","s"],["t",50,196,"Sphere 1","ms"],["t",50,210,"Q, R/2","ms"],["t",140,196,"Sphere 2","ms"],["t",140,210,"2Q, R","ms"],["t",255,196,"Sphere 3","ms"],["t",255,210,"4Q, 2R","ms"]]},"o":["E₁ > E₂ > E₃","E₃ > E₁ > E₂","E₂ > E₁ > E₃","E₃ > E₂ > E₁"],"c":2,"s":"Sphere 1: P (distance R) is outside the ball of radius R/2, so E₁ = kQ/R².\nSphere 2: P is on the surface (radius R), so E₂ = k(2Q)/R² = 2kQ/R².\nSphere 3: P is inside (R < 2R), so E₃ = k(4Q)R/(2R)³ = kQ/(2R²).\nHence E₂ > E₁ > E₃. Answer (c)."},
{"y":"JEE Main 2013 · Online","tp":"efl","st":"Field of point charges and distributions","q":"The surface charge density of a thin charged disc of radius R is σ. The value of the electric field at the centre of the disc is {σ;2ε₀}. With respect to the field at the centre, the electric field along the axis at a distance R from the centre of the disc","o":["reduces by 70.7%","reduces by 29.3%","reduces by 9.7%","reduces by 14.6%"],"c":0,"s":"The axial field of a disc is E = (σ/2ε₀)[1 − z/√(z²+R²)].\nAt z = R: E = (σ/2ε₀)(1 − 1/√2) = 0.293 × (σ/2ε₀).\nSo the field is 29.3% of the central value, i.e. it reduces by 100 − 29.3 = 70.7%. Answer (a)."},
{"y":"AIEEE 2012 · Online","tp":"egs","st":"Gauss's law and symmetric bodies","q":"In a uniformly charged sphere of total charge Q and radius R, the electric field E is plotted as a function of distance from the centre. The graph which would correspond to the above will be","fig":{"w":340,"h":236,"alt":"Four graphs of E against r: (a) decaying from a large value, (b) straight rise to R then smooth decay, (c) straight rise to R then a drop to zero, (d) a smooth bell shaped curve","d":[["l",26,94,159,94,"a"],["l",26,94,26,10,"a"],["t",6,16,"(a)","s"],["t",159,107,"r","es"],["t",30,12,"E","s"],["p","M38,14 C42,44 66,86 136,91"],["l",196,94,329,94,"a"],["l",196,94,196,10,"a"],["t",176,16,"(b)","s"],["t",329,107,"r","es"],["t",200,12,"E","s"],["l",196,94,236,39],["p","M236,39 C244,59 271,82 306,88"],["l",236,91,236,97],["t",236,107,"R","ms"],["l",26,212,159,212,"a"],["l",26,212,26,128,"a"],["t",6,134,"(c)","s"],["t",159,225,"r","es"],["t",30,130,"E","s"],["l",26,212,66,157],["l",66,157,66,212],["t",66,225,"R","ms"],["l",196,212,329,212,"a"],["l",196,212,196,128,"a"],["t",176,134,"(d)","s"],["t",329,225,"r","es"],["t",200,130,"E","s"],["p","M196,212 C221,137 251,137 306,212"],["t",251,225,"R","ms"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"Inside (r < R): E = Qr/(4πε₀R³), which rises linearly from zero at the centre.\nAt r = R: E = Q/(4πε₀R²), the maximum value, with no sudden jump.\nOutside (r > R): E = Q/(4πε₀r²), falling as 1/r².\nSo E rises linearly up to R and then decays smoothly: graph (b). Answer (b)."},
{"y":"JEE Main 2011","tp":"egs","st":"Electric flux","q":"Consider an electric field E⃗ = E₀x̂, where E₀ is a constant. The flux through the shaded area (as shown in the figure) due to this field is","fig":{"w":340,"h":240,"alt":"A tilted rectangular shaded area with corners at (0,0,0), (0,a,0), (a,a,a) and (a,0,a) in x, y, z axes","d":[["l",150,150,240,150],["l",240,150,195,100],["l",195,100,105,100],["l",105,100,150,150],["p","M150,150 L240,150 L195,100 L105,100 Z","f"],["l",150,150,150,20,"a"],["l",150,150,300,150,"a"],["l",150,150,66,226,"a"],["t",156,18,"z","s"],["t",302,154,"y","s"],["t",60,226,"x","es"],["t",156,170,"(0,0,0)","s"],["t",240,170,"(0,a,0)","ms"],["t",105,92,"(a,0,a)","ms"],["t",195,92,"(a,a,a)","ms"]]},"o":["2E₀a²","√2E₀a²","E₀a²","{E₀a²;√2}"],"c":2,"s":"The shaded region has vertices (0,0,0), (0,a,0), (a,a,a) and (a,0,a): a rectangle.\nIts sides are a (along y) and a√2 (along (a,0,a)), so its area is √2 a².\nA normal to it is n = (x̂ − ẑ)/√2 (perpendicular to both ŷ and x̂ + ẑ).\nFlux = E·n·A = E₀(1/√2)(√2 a²) = E₀a². Answer (c)."},
{"y":"AIEEE 2011","tp":"efl","st":"Field lines and motion in a field","q":"A wooden block performs SHM on a frictionless surface with frequency, ν₀. The block carries a charge +Q on its surface. If now a uniform electric field E⃗ is switched on as shown, then the SHM of the block will be","fig":{"w":340,"h":150,"alt":"A charged block on a frictionless surface attached by a spring to a wall on the right, with an electric field E pointing to the right","d":[["l",20,120,320,120],["r",40,80,50,40,"f"],["t",65,104,"+Q","ms"],["p","M90,100 L110,100 L118,84 L130,116 L142,84 L154,116 L166,84 L178,116 L186,100 L270,100"],["l",270,70,270,120,"B"],["l",60,40,130,40,"a"],["t",150,44,"E","s"]]},"o":["of the same frequency and with shifted mean position.","of the same frequency and with the same mean position.","of changed frequency and with shifted mean position.","of changed frequency and with the same mean position."],"c":0,"s":"Without the field the block oscillates about the natural length of the spring with ω₀ = √(k/m).\nThe field adds a constant extra force QE to the right. The net force becomes −kx + QE = −k(x − QE/k).\nSo the motion is still SHM with the same k and m, hence the same frequency, but about a new mean position shifted by QE/k. Answer (a)."},
{"y":"AIEEE 2010","tp":"egs","st":"Non-uniform charge distributions","q":"Let there be a spherically symmetric charge distribution with charge density varying as ρ(r) = ρ₀({5;4} − {r;R}) upto r = R, and ρ(r) = 0 for r > R, where r is the distance from the origin. The electric field at a distance r (r < R) from the origin is given by","o":["{ρ₀r;3ε₀}({5;4} − {r;R})","{4πρ₀r;3ε₀}({5;3} − {r;R})","{ρ₀r;4ε₀}({5;3} − {r;R})","{4ρ₀r;3ε₀}({5;4} − {r;R})"],"c":2,"s":"By Gauss's law, E·4πr² = q_in/ε₀.\nq_in = ∫₀ʳ ρ₀(5/4 − r′/R)·4πr′² dr′ = 4πρ₀(5r³/12 − r⁴/(4R)).\nE = q_in/(4πε₀r²) = (ρ₀/ε₀)(5r/12 − r²/(4R)) = (ρ₀r/4ε₀)(5/3 − r/R). Answer (c)."},
{"y":"AIEEE 2010","tp":"efl","st":"Field of point charges and distributions","q":"A thin semi-circular ring of radius r has a positive charge q distributed uniformly over it. The net field E⃗ at the centre O is","fig":{"w":340,"h":170,"alt":"A thin semicircular ring above the x-axis with centre O, with unit vectors i to the right and j upward","d":[["p","M70,130 A100,100 0 0 1 270,130","B"],["l",30,130,320,130,"a"],["l",170,130,170,10,"a"],["t",176,148,"O","s"],["t",316,124,"î","es"],["t",176,16,"ĵ","s"]]},"o":["{q;2π²ε₀r²}ĵ","{q;4π²ε₀r²}ĵ","−{q;4π²ε₀r²}ĵ","−{q;2π²ε₀r²}ĵ"],"c":3,"s":"Charge per unit length λ = q/(πr). The field of each element at O points away from it; the x-components cancel by symmetry.\nThe y-component of each element is −dE sinθ, so E = ∫₀^π (kλ r dθ/r²) sinθ = (kλ/r)·2 = 2kλ/r = 2kq/(πr²).\nE = 2q/(4π²ε₀r²) = q/(2π²ε₀r²).\nThe charge lies in the upper half, so the field at O points down: −ĵ. Answer (d)."},
{"y":"IIT-JEE 2010","tp":"ecl","st":"Equilibrium and motion of charges","q":"A tiny spherical oil drop carrying a net charge q is balanced in still air with a vertical uniform electric field of strength {81π;7}×10⁵ V m⁻¹. When the field is switched off, the drop is observed to fall with terminal velocity 2 × 10⁻³ m s⁻¹. Given g = 9.8 m s⁻², viscosity of the air = 1.8 × 10⁻⁵ N s m⁻² and the density of oil = 900 kg m⁻³, the magnitude of q is","o":["1.6 × 10⁻¹⁹ C","3.2 × 10⁻¹⁹ C","4.8 × 10⁻¹⁹ C","8.0 × 10⁻¹⁹ C"],"c":3,"s":"With the field off, the drop falls at terminal speed: weight = viscous force (air buoyancy neglected): (4/3)πr³ρg = 6πηrv.\nr² = 9ηv/(2ρg) = 9 × 1.8×10⁻⁵ × 2×10⁻³/(2 × 900 × 9.8) = 1.84×10⁻¹¹ m², so r ≈ 4.29×10⁻⁶ m.\nmg = (4/3)π(4.29×10⁻⁶)³ × 900 × 9.8 ≈ 2.9×10⁻¹² N.\nWith the field on, qE = mg, so q = 2.9×10⁻¹²/[(81π/7)×10⁵] = 2.9×10⁻¹²/(3.64×10⁶) ≈ 8.0×10⁻¹⁹ C. Answer (d)."},
{"y":"IIT-JEE 2010","tp":"efl","st":"Field of point charges and distributions","q":"A uniformly charged thin spherical shell of radius R carries uniform surface charge density of σ per unit area. It is made of two hemispherical shells, held together by pressing them with force F (see figure). F is proportional to","fig":{"w":220,"h":90,"alt":"A sphere split along a vertical dashed line into two hemispheres, with equal forces F pressing the two halves together from left and right","d":[["c",110,45,35],["l",110,8,110,82,"d"],["l",12,45,73,45,"a"],["l",208,45,147,45,"a"],["t",12,36,"F"],["t",208,36,"F","e"]]},"o":["{1;ε₀}σ²R²","{1;ε₀}σ²R","{1;ε₀}{σ²;R}","{1;ε₀}{σ²;R²}"],"c":0,"s":"Take one hemisphere. The outward electric pressure on a charged surface is σ²/(2ε₀).\nThe net force on the hemisphere = pressure × projected area πR².\nF = {σ²/2ε₀} × πR² = πσ²R²/(2ε₀).\nSo F is proportional to σ²R²/ε₀. Answer: option (a)."},
{"y":"AIEEE 2009","tp":"egs","st":"Non-uniform charge distributions","q":"Let ρ(r) = {Q;πR⁴} r be the charge density distribution for a solid sphere of radius R and total charge Q. For a point 'p' inside the sphere at distance r₁ from the centre of the sphere, the magnitude of electric field is","o":["0","{Q;4πε₀r₁²}","{Qr₁²;4πε₀R⁴}","{Qr₁²;3πε₀R⁴}"],"c":2,"s":"Charge inside radius r₁: q = ∫ρ·4πr²dr = (4Q/R⁴)∫r³dr (0 to r₁) = Qr₁⁴/R⁴.\nGauss's law: E × 4πr₁² = q/ε₀.\nE = Qr₁⁴/(4πε₀R⁴r₁²) = Qr₁²/(4πε₀R⁴).\nAnswer: option (c)."},
{"y":"IIT-JEE 2009","tp":"egs","st":"Electric flux","q":"A disk of radius a/4 having a uniformly distributed charge 6 C is placed in the xy-plane with its centre at (−a/2, 0, 0). A rod of length a carrying a uniformly distributed charge 8 C is placed on the x-axis from x = a/4 to x = 5a/4. Two point charges −7 C and 3 C are placed at (a/4, −a/4, 0) and (−3a/4, 3a/4, 0), respectively. Consider a cubical surface formed by six surfaces x = ± a/2, y = ± a/2, z = ± a/2. The electric flux through this cubical surface is","o":["{−2 C;ε₀}","{2 C;ε₀}","{10 C;ε₀}","{12 C;ε₀}"],"c":0,"s":"Flux = (charge inside the cube)/ε₀.\nDisk: its centre lies on the face x = −a/2, so half of it (3 C) is inside.\nRod: only x = a/4 to a/2 is inside, which is 1/4 of its length, so 2 C.\nPoint charge −7 C at (a/4, −a/4, 0) is inside. The 3 C charge at x = −3a/4 is outside.\nTotal inside = 3 + 2 − 7 = −2 C, so flux = −2 C/ε₀. Answer: option (a)."},
{"y":"AIEEE 2008","tp":"egs","st":"Gauss's law and symmetric bodies","q":"A thin spherical shell of radius R has charge Q spread uniformly over its surface. Which of the following graphs most closely represents the electric field E(r) produced by the shell in the range 0 ≤ r < ∞, where r is the distance from the centre of the shell?","fig":{"w":340,"h":240,"alt":"Four graphs of E against r. (a) rises smoothly to a peak at R then falls; (b) zero up to R, then jumps to a peak and falls; (c) constant up to R then falls; (d) rises linearly to a peak at R then falls","d":[["t",10,18,"(a)","s"],["l",35,98,35,22,"a"],["l",35,98,160,98,"a"],["t",40,24,"E(r)","s"],["t",162,102,"r","s"],["t",95,112,"R","ms"],["t",31,110,"O","es"],["p","M35 98 Q70 94 95 38"],["p","M95 38 Q107 86 155 92"],["t",180,18,"(b)","s"],["l",205,98,205,22,"a"],["l",205,98,330,98,"a"],["t",210,24,"E(r)","s"],["t",332,102,"r","s"],["t",265,112,"R","ms"],["t",201,110,"O","es"],["l",265,98,265,38],["p","M265 38 Q277 86 325 92"],["t",10,136,"(c)","s"],["l",35,216,35,140,"a"],["l",35,216,160,216,"a"],["t",40,142,"E(r)","s"],["t",162,220,"r","s"],["t",95,230,"R","ms"],["t",31,228,"O","es"],["p","M35 160 H95"],["p","M95 160 Q109 204 155 210"],["t",180,136,"(d)","s"],["l",205,216,205,140,"a"],["l",205,216,330,216,"a"],["t",210,142,"E(r)","s"],["t",332,220,"r","s"],["t",265,230,"R","ms"],["t",201,228,"O","es"],["l",205,216,265,156],["p","M265 156 Q277 204 325 210"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"Inside a thin shell no charge is enclosed, so E = 0 for r < R.\nJust outside, E = Q/(4πε₀R²), which is not zero, so E jumps at r = R.\nFor r > R, E falls as 1/r².\nOnly graph (b) is zero up to R, then jumps and decays as 1/r². Answer: option (b)."},
{"y":"IIT-JEE 2007","tp":"ecn","st":"Induced charge and shielding","q":"Consider a neutral conducting sphere. A positive point charge is placed outside the sphere. The net charge on the sphere is then","o":["negative and distributed uniformly over the surface of the sphere","negative and appears only at the point on the sphere closest to the point charge","negative and distributed non-uniformly over the entire surface of the sphere","zero."],"c":3,"s":"The sphere was neutral and no charge is added to it.\nThe outside charge only causes induction: negative charge gathers on the near side and an equal positive charge on the far side.\nThe total charge of the sphere stays zero. Answer: option (d)."},
{"y":"IIT-JEE 2007","tp":"egs","st":"Gauss's law and symmetric bodies","q":"A spherical portion has been removed from a solid sphere having a charge distributed uniformly in its volume as shown in the figure. The electric field inside the emptied space is","fig":{"w":200,"h":180,"alt":"A solid sphere with a small spherical cavity cut out near its lower right edge","d":[["c",100,90,70],["c",128,118,18]]},"o":["zero everywhere","non-zero and uniform","non-uniform","zero at its center."],"c":1,"s":"Treat the body as a full sphere of density +ρ plus a small sphere of density −ρ filling the cavity.\nInside a uniform sphere E = ρr⃗/(3ε₀), measured from its own centre.\nIn the cavity: E = ρr⃗₁/(3ε₀) − ρr⃗₂/(3ε₀) = ρ(r⃗₁ − r⃗₂)/(3ε₀) = ρd⃗/(3ε₀), where d⃗ joins the two centres.\nThis is the same at every point, so the field is non-zero and uniform. Answer: option (b)."},
{"y":"AIEEE 2006","tp":"efl","st":"Electric dipole","q":"An electric dipole is placed at an angle of 30° to a non-uniform electric field. The dipole will experience","o":["a torque only","a translational force only in the direction of the field","a translational force only in a direction normal to the direction of the field","a torque as well as a translational force."],"c":3,"s":"At 30° to the field, the torque p × E is not zero.\nIn a non-uniform field the forces on +q and −q have different magnitudes, so the net force is not zero.\nSo the dipole feels both a torque and a translational force. Answer: option (d)."},
{"y":"AIEEE 2005","tp":"efl","st":"Field of point charges and distributions","q":"Two point charges +8q and −2q are located at x = 0 and x = L respectively. The location of a point on the x axis at which the net electric field due to these two point charges is zero is","o":["8L","4L","2L","{L;4}"],"c":2,"s":"The field can be zero only outside the pair, on the side of the smaller charge (−2q), so x > L.\nEqual magnitudes: 8q/x² = 2q/(x − L)².\nSo 4(x − L)² = x², which gives 2(x − L) = x, so x = 2L.\nAnswer: option (c)."},
{"y":"AIEEE 2005","tp":"ecl","st":"Equilibrium and motion of charges","q":"A charged ball B hangs from a silk thread S, which makes an angle θ with a large charged conducting sheet P, as shown in the figure. The surface charge density σ of the sheet is proportional to","fig":{"w":240,"h":175,"alt":"A vertical charged sheet P with plus signs; a thread S from the sheet carries a ball B and makes angle theta with the sheet","d":[["l",38,8,38,150,"B"],["t",30,20,"+","ms"],["t",30,36,"+","ms"],["t",30,52,"+","ms"],["t",30,68,"+","ms"],["t",30,84,"+","ms"],["t",30,100,"+","ms"],["t",30,116,"+","ms"],["t",30,132,"+","ms"],["t",30,148,"+","ms"],["l",38,30,38,138,"d"],["l",38,30,84.5,129.7],["c",84.5,129.7,6,"F"],["t",50,64,"θ"],["t",68,86,"S"],["t",94.5,141.7,"B"],["t",12,84,"P"],["t",38,166,"sheet","ms"]]},"o":["sinθ","tanθ","cosθ","cotθ"],"c":1,"s":"Forces on the ball: weight mg (down), tension T (along the thread), electric force qE (horizontal).\nNear a large conducting sheet E = σ/ε₀.\nT cosθ = mg and T sinθ = qσ/ε₀.\nDividing: tanθ = qσ/(ε₀mg), so σ ∝ tanθ. Answer: option (b)."},
{"y":"IIT-JEE 2005","tp":"efl","st":"Field of point charges and distributions","q":"Three infinitely long charge sheets are placed as shown in figure. The electric field at point P is","fig":{"w":300,"h":175,"alt":"Three horizontal sheets seen edge on: sigma at z=3a, minus 2 sigma at z=a, minus sigma at z=-a; point P lies between z=a and z=3a","d":[["l",100,160,100,8,"da"],["t",106,12,"Z"],["l",20,30,290,30],["l",20,80,290,80],["l",20,105,292,105,"da"],["l",20,130,290,130],["t",24,24,"σ"],["t",24,74,"−2σ"],["t",24,124,"−σ"],["t",286,24,"Z = 3a","es"],["t",286,74,"Z = a","es"],["t",286,150,"Z = −a","es"],["t",290,100,"X","e"],["c",135,55,2.5,"F"],["t",142,59,"P"]]},"o":["{2σ;ε₀} k̂","{4σ;ε₀} k̂","−{2σ;ε₀} k̂","−{4σ;ε₀} k̂"],"c":2,"s":"Each sheet gives a field σ/(2ε₀) (for charge σ) pointing away from a positive sheet and towards a negative one.\nP lies between z = a and z = 3a. The σ sheet above pushes P down: σ/(2ε₀) along −k̂.\nThe −2σ sheet below attracts P downward: σ/ε₀ along −k̂.\nThe −σ sheet at z = −a attracts P downward: σ/(2ε₀) along −k̂.\nTotal = −(1/2 + 1 + 1/2)σ/ε₀ k̂ = −2σ/ε₀ k̂. Answer: option (c)."},
{"y":"AIEEE 2004","tp":"ecl","st":"Equilibrium and motion of charges","q":"A charged oil drop is suspended in a uniform field of 3 × 10⁴ V/m so that it neither falls nor rises. The charge on the drop will be (take the mass of the charge = 9.9 × 10⁻¹⁵ kg and g = 10 m/s²)","o":["1.6 × 10⁻¹⁸ C","3.2 × 10⁻¹⁸ C","3.3 × 10⁻¹⁸ C","4.8 × 10⁻¹⁸ C"],"c":2,"s":"The drop is in equilibrium, so qE = mg.\nq = mg/E = (9.9 × 10⁻¹⁵ × 10)/(3 × 10⁴) = 3.3 × 10⁻¹⁸ C.\nAnswer: option (c)."},
{"y":"IIT-JEE 2004","tp":"efl","st":"Field of point charges and distributions","q":"Six charges of equal magnitude, 3 positive and 3 negative are to be placed on PQRSTU corners of a regular hexagon, such that field at the centre is double that of what it would have been if only one +ve charge is placed at R.","fig":{"w":200,"h":170,"alt":"A regular hexagon with corners P, Q, R, S, T, U going clockwise from the upper left, and its centre O","d":[["p","M69.0 31.3 L131.0 31.3 L162.0 85.0 L131.0 138.7 L69.0 138.7 L38.0 85.0 Z"],["c",100,85,2,"F"],["t",105,99,"O","s"],["t",61,27.3,"P","e"],["t",139,27.3,"Q"],["t",170,89,"R"],["t",139,150.7,"S"],["t",61,150.7,"T","e"],["t",30,89,"U","e"]]},"o":["+, +, +, −, −, −","−, +, +, −, −, −","−, +, +, −, +, −","+, −, +, −, +, −"],"c":2,"s":"Let E be the field of one charge at the centre. Opposite corners are P-S, Q-T, R-U.\nTwo opposite corners with the same sign cancel. Two opposite corners with opposite signs add to 2E, pointing from the + corner towards the − corner.\nA single + at R gives E pointing from R towards U, so we need 2E along R to U.\nOption (c): P(−) S(−) cancel, Q(+) T(+) cancel, R(+) U(−) give 2E along R to U. This is correct.\nThe other options fail: (a) gives 4E, (b) gives 2√3 E, (d) gives zero. Answer: option (c)."},
{"y":"IIT-JEE 2004","tp":"egs","st":"Gauss's law and symmetric bodies","q":"A Gaussian surface in the figure is shown by dotted line. The electric field on the surface will be","fig":{"w":240,"h":170,"alt":"A dotted closed Gaussian surface enclosing charges q1 and minus q1, with charge q2 outside it","d":[["c",100,95,65,"d"],["c",125,80,2.5,"F"],["t",131,78,"q₁"],["c",80,120,2.5,"F"],["t",50,134,"−q₁"],["c",185,32,2.5,"F"],["t",192,36,"q₂"]]},"o":["due to q₁ and q₂ only","due to q₂ only","zero","due to all."],"c":3,"s":"Gauss's law says only that the total flux depends on the enclosed charge (q₁ and −q₁ here).\nThe electric field at a point is produced by all charges, inside and outside, including q₂.\nSo the field on the surface is due to all charges. Answer: option (d)."},
{"y":"AIEEE 2003","tp":"egs","st":"Electric flux","q":"If the electric flux entering and leaving an enclosed surface respectively is φ₁ and φ₂, the electric charge inside the surface will be","o":["(φ₂ − φ₁)ε₀","{φ₁ + φ₂;ε₀}","{φ₂ − φ₁;ε₀}","(φ₁ + φ₂)ε₀"],"c":0,"s":"Net outward flux = φ₂ − φ₁ (leaving minus entering).\nGauss's law: net flux = q/ε₀.\nSo q = (φ₂ − φ₁)ε₀. Answer: option (a)."},
{"y":"IIT-JEE 2003","tp":"ecn","st":"Induced charge and shielding","q":"A metallic shell has a point charge q kept inside its cavity. Which one of the following diagrams correctly represents the electric lines of force?","fig":{"w":340,"h":250,"alt":"Four diagrams of a thick metal shell with charge q inside the cavity. (a) lines of force run straight through the metal; (b) lines go straight to the inner wall and radial lines leave the outer surface; (c) lines curve to meet the inner wall at right angles and radial lines leave the outer surface; (d) like (c) but one line passes straight through the metal","d":[["t",13,25,"(a)","s"],["c",95,65,46],["c",95,65,33],["c",87,70,2.5,"F"],["t",91,84,"q","s"],["l",87,70,153.9,31,"a"],["l",87,70,61,6.1,"a"],["l",87,70,39.3,104,"a"],["l",87,70,129,123.9,"a"],["t",173,25,"(b)","s"],["c",255,65,46],["c",255,65,33],["c",247,70,2.5,"F"],["t",251,84,"q","s"],["l",247,70,283.6,48.5,"a"],["l",294.8,42,312.2,32,"a"],["l",247,70,238.5,36.4,"a"],["l",232,25.2,222,7.8,"a"],["l",247,70,228,83.9,"a"],["l",217.3,91.4,200.9,102.9,"a"],["l",247,70,271.5,93.6,"a"],["l",278,104.8,288,122.2,"a"],["t",13,145,"(c)","s"],["c",95,185,46],["c",95,185,33],["c",87,190,2.5,"F"],["t",91,204,"q","s"],["p","M87 190 Q111.5 175.5 123.6 168.5","a"],["l",134.8,162,152.2,152,"a"],["p","M87 190 Q85.5 168.5 78.5 156.4","a"],["l",72,145.2,62,127.8,"a"],["p","M87 190 Q79.4 195.9 68.0 203.9","a"],["l",57.3,211.4,40.9,222.9,"a"],["p","M87 190 Q104.5 201.5 111.5 213.6","a"],["l",118,224.8,128,242.2,"a"],["t",173,145,"(d)","s"],["c",255,185,46],["c",255,185,33],["c",247,190,2.5,"F"],["t",251,204,"q","s"],["p","M247 190 Q271.5 175.5 283.6 168.5","a"],["l",294.8,162,312.2,152,"a"],["p","M247 190 Q245.5 168.5 238.5 156.4","a"],["l",232,145.2,222,127.8,"a"],["p","M247 190 Q239.4 195.9 228.0 203.9","a"],["l",217.3,211.4,200.9,222.9,"a"],["l",247,190,289,243.9,"a"]]},"o":["Diagram (a)","Diagram (b)","Diagram (c)","Diagram (d)"],"c":2,"s":"Inside the metal E = 0, so no line of force can pass through the shell wall.\nLines from q end on the induced −q on the inner surface and meet the metal surface at right angles.\nThe induced +q on the outer surface starts new lines that go radially outward.\nDiagram (c) shows this. Answer: option (c)."},
{"y":"IIT-JEE 2001","tp":"efl","st":"Field lines and motion in a field","q":"Three positive charges of equal value q are placed at the vertices of an equilateral triangle. The resulting lines of force should be sketched as in","fig":{"w":340,"h":250,"alt":"Four sketches for three equal positive charges at the corners of an equilateral triangle. (a) curved lines joining the charges; (b) lines leaving each charge and also running to the centre; (c) lines spreading outward from each charge with none through the centre; (d) closed circles around each charge","d":[["t",13,25,"(a)","s"],["p","M95 35 L69 80 L121 80 Z"],["p","M95 35 Q60.0 35.5 69 80"],["p","M69 80 Q95.0 102.0 121 80"],["p","M121 80 Q130.0 35.5 95 35"],["c",95,35,3.5,"F"],["c",69,80,3.5,"F"],["c",121,80,3.5,"F"],["t",173,25,"(b)","s"],["l",255,35,255,65,"a"],["l",255,35,269.9,13.7,"a"],["l",255,35,255,9,"a"],["l",255,35,240.1,13.7,"a"],["l",229,80,255,65,"a"],["l",229,80,203.1,77.7,"a"],["l",229,80,206.5,93,"a"],["l",229,80,218,103.6,"a"],["l",281,80,255,65,"a"],["l",281,80,292,103.6,"a"],["l",281,80,303.5,93,"a"],["l",281,80,306.9,77.7,"a"],["c",255,35,3.5,"F"],["c",229,80,3.5,"F"],["c",281,80,3.5,"F"],["t",13,145,"(c)","s"],["l",95,155,116.4,137,"a"],["l",95,155,106.8,129.6,"a"],["l",95,155,95,127,"a"],["l",95,155,83.2,129.6,"a"],["l",95,155,73.6,137,"a"],["l",69,200,42.7,190.4,"a"],["l",69,200,41.1,202.4,"a"],["l",69,200,44.8,214,"a"],["l",69,200,52.9,222.9,"a"],["l",69,200,64.1,227.6,"a"],["l",121,200,125.9,227.6,"a"],["l",121,200,137.1,222.9,"a"],["l",121,200,145.2,214,"a"],["l",121,200,148.9,202.4,"a"],["l",121,200,147.3,190.4,"a"],["c",95,155,3.5,"F"],["c",69,200,3.5,"F"],["c",121,200,3.5,"F"],["t",173,145,"(d)","s"],["c",255,155,8],["c",255,155,14],["c",255,155,20],["c",229,200,8],["c",229,200,14],["c",229,200,20],["c",281,200,8],["c",281,200,14],["c",281,200,20],["c",255,155,2.5,"F"],["c",229,200,2.5,"F"],["c",281,200,2.5,"F"]]},"o":["Diagram (a)","Diagram (b)","Diagram (c)","Diagram (d)"],"c":2,"s":"All three charges are positive, so lines start on the charges and go away; none join two like charges (so (a) is wrong).\nBy symmetry the field at the centre of the triangle is zero, so no line passes through the centre (so (b) is wrong).\nClosed circles around the charges are not lines of force (so (d) is wrong).\nThe lines spread outward from each charge and bend away from each other, as in diagram (c). Answer: option (c)."},
{"y":"IIT-JEE 1997","tp":"efl","st":"Field lines and motion in a field","q":"An electron of mass mₑ, initially at rest, moves through a certain distance in a uniform electric field in time t₁. A proton of mass mₚ, also initially at rest, takes time t₂ to move through an equal distance in this uniform electric field. Neglecting the effect of gravity, the ratio of t₂/t₁ is nearly equal to","o":["1","(mₚ/mₑ)^(1/2)","(mₑ/mₚ)^(1/2)","1836"],"c":1,"s":"The force on each is eE, so a = eE/m.\nd = ½at² gives t = √(2d/a) = √(2dm/eE), so t ∝ √m.\nt₂/t₁ = √(mₚ/mₑ) (≈ 43). Answer: option (b)."},
{"y":"JEE Advanced 2024","tp":"efl","st":"Electric dipole","q":"A small electric dipole p⃗₀, having a moment of inertia I about its center, is kept at a distance r from the center of a spherical shell of radius R. The surface charge density σ is uniformly distributed on the spherical shell. The dipole is initially oriented at a small angle θ as shown in the figure. While staying at a distance r, the dipole is free to rotate about its center. If released from rest, then which of the following statement(s) is(are) correct?\n[ε₀ is the permittivity of free space.]","fig":{"w":220,"h":200,"alt":"A small dipole p0 tilted by a small angle theta from the radial direction, at distance r above the centre O of a spherical shell of radius R","d":[["c",110,145,45],["c",110,145,2,"F"],["t",116,160,"O","s"],["l",110,145,110,12,"d"],["l",30,145,30,50,"b"],["t",24,100,"r","e"],["l",103,64,116,36,"a"],["t",121,44,"p₀"],["t",96,34,"θ","e"],["l",110,145,144,167],["t",134,150,"R"]]},"o":["The dipole will undergo small oscillations at any finite value of r.","The dipole will undergo small oscillations at any finite value of r > R.","The dipole will undergo small oscillations with an angular frequency of √{2σp₀;ε₀I} at r = 2R.","The dipole will undergo small oscillations with an angular frequency of √{σp₀;100ε₀I} at r = 10R."],"c":[1,3],"s":"Outside the shell (r > R) the field is radial: E = σR²/(ε₀r²). Inside, E = 0.\nFor r > R a small tilt θ from the field gives a restoring torque −p₀Eθ, so ω = √(p₀E/I): small oscillations. For r < R there is no field, so no oscillation, and (a) is false; (b) is true.\nAt r = 2R: E = σ/(4ε₀), ω = √(σp₀/(4ε₀I)), so (c) is false.\nAt r = 10R: E = σ/(100ε₀), ω = √(σp₀/(100ε₀I)), so (d) is true.\nAnswer: (b) and (d)."},
{"y":"JEE Advanced 2019","tp":"egs","st":"Electric flux","q":"A charged shell of radius R carries a total charge Q. Given φ as the flux of electric field through a closed cylindrical surface of height h, radius r and with its center same as that of the shell. Here, center of cylinder is a point on the axis of the cylinder which is equidistant from its top and bottom surfaces. Which of the following option(s) is/are correct? [ε₀ is the permittivity of free space]","o":["If h > 2R and r = {4R;5} then φ = {Q;5ε₀}","If h > 2R and r = {3R;5} then φ = {Q;5ε₀}","If h < {8R;5} and r = {3R;5} then φ = 0","If h > 2R and r > R then φ = {Q;ε₀}"],"c":[1,2,3],"s":"Flux = (charge of the shell inside the cylinder)/ε₀.\nFor h > 2R the cylinder covers the shell's full height. The shell part inside is two polar caps with sinθ < r/R. Each cap has area 2πR²(1 − cosθ).\n(a) r = 4R/5: cosθ = 3/5, caps hold 2×(1/5) = 2/5 of Q, so φ = 2Q/(5ε₀). False.\n(b) r = 3R/5: cosθ = 4/5, caps hold 2×(1/10) = 1/5 of Q, so φ = Q/(5ε₀). True.\n(c) h < 8R/5 and r = 3R/5: the cylinder lies entirely inside the shell (corner distance < R), so φ = 0. True.\n(d) h > 2R and r > R: the cylinder encloses the whole shell, φ = Q/ε₀. True.\nAnswer: (b), (c), (d)."},
{"y":"JEE Advanced 2019","tp":"efl","st":"Electric dipole","q":"An electric dipole with dipole moment {p₀;√2}(î + ĵ) is held fixed at the origin O in the presence of a uniform electric field of magnitude E₀. If the potential is constant on a circle of radius R centered at the origin as shown in figure, then the correct statement(s) is/are (ε₀ is permittivity of free space. R ≫ dipole size)","fig":{"w":240,"h":220,"alt":"A circle of radius R centred on the origin with a dipole at the origin pointing along the 45 degree line; point A on the circle along the dipole direction and point B at 135 degrees","d":[["c",120,110,80],["l",28,110,228,110,"a"],["l",120,205,120,12,"a"],["t",224,104,"x","e"],["t",126,18,"y"],["l",63.4,53.4,176.6,166.6,"d"],["l",120,110,142,88,"aB"],["c",176.6,53.4,3,"F"],["c",63.4,53.4,3,"F"],["t",182.6,49.4,"A"],["t",57.4,49.4,"B","e"],["t",114,124,"O","e"],["t",150,140,"R"]]},"o":["The magnitude of total electric field on any two points of the circle will be same.","Total electric field at point A is E⃗(A) = √2 E₀(î + ĵ)","R = ({p₀;4πε₀E₀})^(1/3)","Total electric field at point B is E⃗(B) = 0"],"c":[2,3],"s":"On the circle, dipole potential = p₀cosα/(4πε₀R²) (α from the dipole axis). The uniform field adds −E₀R cos(α′).\nFor the total to be constant, E⃗₀ must point along the dipole and p₀/(4πε₀R²) = E₀R, so R³ = p₀/(4πε₀E₀). (c) is true.\nAt B (perpendicular to the dipole): dipole field = p₀/(4πε₀R³) = E₀ opposite to p, uniform field E₀ along p, so net zero. (d) is true.\nAt A (on the axis): dipole gives 2E₀ and uniform field E₀ in the same direction, so 3E₀ along (î + ĵ)/√2, not √2E₀(î + ĵ) (magnitude 2E₀). (b) is false.\nOn the circle the field is radial with magnitude 3E₀|cosα|, not constant. (a) is false.\nAnswer: (c), (d)."},
{"y":"JEE Advanced 2018","tp":"egs","st":"Electric flux","q":"An infinitely long thin non-conducting wire is parallel to the z-axis and carries a uniform line charge density λ. It pierces a thin non-conducting spherical shell of radius R in such a way that the arc PQ subtends an angle 120° at the centre O of the spherical shell, as shown in the figure. The permittivity of free space is ε₀. Which of the following statements is (are) true?","fig":{"w":260,"h":220,"alt":"A spherical shell with centre O and a vertical dashed line charge lambda passing through it to the left of the centre, cutting the shell at P and Q so that angle POQ is 120 degrees; the z axis passes through O","d":[["c",150,110,80],["l",110,6,110,214,"d"],["l",150,214,150,6,"da"],["t",154,14,"z"],["t",116,14,"λ"],["l",150,110,110,40.7],["l",150,110,110,179.3],["c",150,110,2,"F"],["t",156,124,"O","s"],["c",110,40.7,3,"F"],["c",110,179.3,3,"F"],["t",100,36.7,"P","e"],["t",100,191.3,"Q","e"],["t",124,114,"120°","s"],["t",126,78,"R","s"]]},"o":["The electric flux through the shell is {√3Rλ;ε₀}","The z-component of the electric field is zero at all the points on the surface of the shell","The electric flux through the shell is {√2Rλ;ε₀}","The electric field is normal to the surface of the shell at all points"],"c":[0,1],"s":"Arc PQ = 120°, so the wire is at distance R cos60° = R/2 from O.\nLength of wire inside the shell = 2R sin60° = √3R, so enclosed charge = √3Rλ.\nFlux = √3Rλ/ε₀: (a) true, (c) false.\nThe field of an infinite line is perpendicular to the wire, so it has no z-component: (b) true.\nIt is along the radial line from the wire, which is not along the sphere's normal everywhere: (d) false.\nAnswer: (a), (b)."},
{"y":"JEE Advanced 2015","tp":"egs","st":"Gauss's law and symmetric bodies","q":"Consider a uniform spherical charge distribution of radius R₁ centred at the origin O. In this distribution, a spherical cavity of radius R₂, centred at P with distance OP = a = R₁ − R₂ (see figure) is made. If the electric field inside the cavity at position r⃗ is E⃗(r⃗), then the correct statement(s) is(are)","fig":{"w":260,"h":220,"alt":"A large uniformly charged sphere of radius R1 with centre O and a small spherical cavity of radius R2 centred at P, with OP = a","d":[["c",130,120,95],["c",130,120,2,"F"],["t",134,136,"O","s"],["l",130,120,225,120],["t",180,114,"R₁"],["c",78,68,22],["c",78,68,2,"F"],["t",84,82,"P","s"],["l",78,68,78,46],["t",82,58,"R₂","s"],["l",130,120,78,68,"d"],["t",100,104,"a","s"]]},"o":["E⃗ is uniform, its magnitude is independent of R₂ but its direction depends on r⃗.","E⃗ is uniform, its magnitude depends on R₂ and its direction depends on r⃗.","E⃗ is uniform, its magnitude is independent of a but its direction depends on r⃗.","E⃗ is uniform and both its magnitude and direction depend on a⃗."],"c":3,"s":"Fill the cavity with +ρ and −ρ. Inside the cavity E⃗ = ρr⃗₁/(3ε₀) − ρr⃗₂/(3ε₀) = ρa⃗/(3ε₀), where a⃗ = OP.\nThis is the same at all points of the cavity (uniform), so the direction does not depend on the position r⃗.\nIts magnitude ρa/(3ε₀) does not depend on R₂, but depends on a, and its direction is along a⃗.\nSo only (d) is correct. Answer: option (d)."},
{"y":"JEE Advanced 2015","tp":"ecl","st":"Equilibrium and motion of charges","q":"The figures below depict two situations in which two infinitely long static line charges of constant positive line charge density λ are kept parallel to each other. In their resulting electric field, point charges q and −q are kept in equilibrium between them. The point charges are confined to move in the x direction only. If they are given a small displacement about their equilibrium positions, then the correct statement(s) is(are)","fig":{"w":340,"h":130,"alt":"Two situations, each with two parallel line charges lambda: on the left a charge +q midway between them, on the right a charge minus q midway between them; the x axis runs horizontally","d":[["l",30,16,30,116],["l",130,16,130,116],["t",30,12,"λ","ms"],["t",130,12,"λ","ms"],["l",12,70,152,70,"da"],["t",156,74,"x"],["c",80,70,3,"F"],["t",80,90,"+q","ms"],["l",200,16,200,116],["l",300,16,300,116],["t",200,12,"λ","ms"],["t",300,12,"λ","ms"],["l",182,70,322,70,"da"],["t",326,74,"x"],["c",250,70,3,"F"],["t",250,90,"−q","ms"]]},"o":["Both charges execute simple harmonic motion.","Both charges will continue moving in the direction of their displacement.","Charge +q executes simple harmonic motion while charge −q continues moving in the direction of its displacement.","Charge −q executes simple harmonic motion while charge +q continues moving in the direction of its displacement."],"c":2,"s":"Midway between two equal positive lines the field is zero (equilibrium).\n+q displaced towards one line: the nearer line repels it more, so the net force points back to the middle and is proportional to the displacement. This is SHM.\n−q displaced towards one line: the nearer line attracts it more, so the force is along the displacement and it keeps moving away.\nAnswer: option (c)."},
{"y":"JEE Advanced 2014","tp":"efl","st":"Field of point charges and distributions","q":"Let E₁(r), E₂(r) and E₃(r) be the respective electric fields at a distance r from a point charge Q, an infinitely long wire with constant linear charge density λ, and an infinite plane with uniform surface charge density σ. If E₁(r₀) = E₂(r₀) = E₃(r₀) at a given distance r₀, then","o":["Q = 4σπr₀²","r₀ = {λ;2πσ}","E₁(r₀/2) = 2E₂(r₀/2)","E₂(r₀/2) = 4E₃(r₀/2)"],"c":2,"s":"E₁ = Q/(4πε₀r²), E₂ = λ/(2πε₀r), E₃ = σ/(2ε₀) (constant).\nE₁(r₀) = E₃: Q = 2πσr₀², so (a) is false. E₂(r₀) = E₃: r₀ = λ/(πσ), so (b) is false.\nLet the common value be E. At r₀/2: E₁ = 4E, E₂ = 2E, E₃ = E.\nSo E₁ = 2E₂ (c is true), and E₂ = 2E₃ not 4E₃ (d is false). Answer: option (c)."},
{"y":"JEE Advanced 2013","tp":"efl","st":"Field of point charges and distributions","q":"Two non-conducting solid spheres of radii R and 2R, having uniform volume charge densities ρ₁ and ρ₂ respectively, touch each other. The net electric field at a distance 2R from the centre of the smaller sphere, along the line joining the centres of the spheres, is zero. The ratio {ρ₁;ρ₂} can be","o":["−4","−{32;25}","{32;25}","4"],"c":[1,3],"s":"Centres are 3R apart. The point is 2R from the small centre, either between the spheres or on the far side of the small sphere.\nCase 1, between: distance from big centre is R (inside it). Small sphere: ρ₁R/(12ε₀) one way; big sphere: ρ₂R/(3ε₀) the other way. Zero gives ρ₁/12 = ρ₂/3, so ρ₁/ρ₂ = 4.\nCase 2, far side: distance from big centre is 5R (outside it). Small: ρ₁R/(12ε₀); big: charge (32/3)πR³ρ₂ gives 8ρ₂R/(75ε₀), both in the same direction. Zero gives ρ₁/12 = −8ρ₂/75, so ρ₁/ρ₂ = −32/25.\nAnswer: (b) and (d)."},
{"y":"IIT-JEE 2012","tp":"egs","st":"Electric flux","q":"A cubical region of side a has its centre at the origin. It encloses three fixed point charges, −q at (0, −{a;4}, 0), +3q at (0, 0, 0) and −q at (0, +{a;4}, 0). Choose the correct option(s).","o":["The net electric flux crossing the plane x = +{a;2} is equal to the net electric flux crossing the plane x = −{a;2}.","The net electric flux crossing the plane y = +{a;2} is more than the net electric flux crossing the plane y = −{a;2}.","The net electric flux crossing the entire region is {q;ε₀}.","The net electric flux crossing the plane z = +{a;2} is equal to the net electric flux crossing the plane x = +{a;2}."],"c":[0,2,3],"s":"The charges lie on the y-axis, symmetric about the origin.\n(a) Symmetric about the plane x = 0, so the two x-faces get equal flux. True.\n(b) Symmetric about y = 0 too (−q at ±a/4), so the y-faces get equal flux. False.\n(c) Total charge = −q + 3q − q = q, so total flux = q/ε₀. True.\n(d) The set-up is the same for x and z (charges on the y-axis), so the faces z = +a/2 and x = +a/2 get equal flux. True.\nAnswer: (a), (c), (d)."},
{"y":"IIT-JEE 2010","tp":"efl","st":"Field lines and motion in a field","q":"A few electric field lines for a system of two charges Q₁ and Q₂ fixed at two different points on the x-axis are shown in the figure. These lines suggest that","fig":{"w":300,"h":160,"alt":"Field lines leave Q1 on the left; many curve around and run to Q2 on the right, which has fewer lines","d":[["c",70,80,4,"F"],["c",235,80,4,"F"],["t",64,100,"Q₁","e"],["t",241,100,"Q₂"],["l",70,80,235,80,"a"],["p","M70 80 C100 36 205 36 235 80","a"],["p","M70 80 C90 10 215 10 235 80","a"],["p","M70 80 C100 124 205 124 235 80","a"],["p","M70 80 C90 150 215 150 235 80","a"],["l",70,80,28,56,"a"],["l",70,80,22,80,"a"],["l",70,80,28,104,"a"],["l",70,80,40,34,"a"],["l",70,80,40,126,"a"],["l",290,40,238,76,"a"],["l",290,120,238,84,"a"]]},"o":["|Q₁| > |Q₂|","|Q₁| < |Q₂|","at a finite distance to the left of Q₁ the electric field is zero","at a finite distance to the right of Q₂ the electric field is zero"],"c":[0,3],"s":"Lines run from Q₁ to Q₂, so the charges are opposite. More lines leave Q₁ than end on Q₂, so |Q₁| > |Q₂|: (a) true.\nFor unlike charges the zero-field point lies outside the pair, on the side of the smaller charge. That is to the right of Q₂: (d) true, (c) false.\nAnswer: (a), (d)."},
{"y":"IIT-JEE 1998","tp":"efl","st":"Field lines and motion in a field","q":"A positively charged thin metal ring of radius R is fixed in the xy plane with its centre at the origin O. A negatively charged particle P is released from rest at the point (0, 0, z₀) where z₀ > 0. Then the motion of P is","o":["periodic, for all values of z₀ satisfying 0 < z₀ < ∞","simple harmonic, for all values of z₀ satisfying 0 < z₀ ≤ R","approximately simple harmonic, provided z₀ ≪ R","such that P crosses O and continues to move along the negative z axis towards z = −∞"],"c":[0,2],"s":"On the axis the ring's field is E = kQz/(R² + z²)^(3/2), so the force on the negative particle always points towards O.\nThe particle passes through O, is pulled back on the other side, and oscillates between +z₀ and −z₀. So the motion is periodic: (a) true, (d) false.\nFor z₀ ≪ R: F ≈ −(kQq/R³)z, which is proportional to −z, so it is approximately SHM: (c) true.\nFor larger z₀ the force is not linear in z, so (b) is false.\nAnswer: (a), (c)."},
{"y":"IIT-JEE 1998","tp":"egs","st":"Gauss's law and symmetric bodies","q":"A non-conducting solid sphere of radius R is uniformly charged. The magnitude of the electric field due to the sphere at a distance r from its centre","o":["increases as r increases, for r < R","decreases as r increases, for 0 < r < ∞","decreases as r increases, for R < r < ∞","is discontinuous at r = R."],"c":[0,2],"s":"Inside (r < R): E = ρr/(3ε₀), which increases with r. (a) true, (b) false.\nOutside (r > R): E = Q/(4πε₀r²), which decreases with r. (c) true.\nAt r = R both formulas give Q/(4πε₀R²), so E is continuous. (d) false.\nAnswer: (a), (c)."},
{"y":"IIT-JEE 1996","tp":"ecn","st":"Induced charge and shielding","q":"A metallic solid sphere is placed in a uniform electric field. The lines of force follow the path(s) shown in figure as","fig":{"w":280,"h":170,"alt":"A metal sphere in a uniform field with four lines of force labelled 1 to 4 from the left; lines 1, 2 and 3 pass through the sphere, line 4 bends to meet the surface and does not enter it","d":[["c",140,82,52],["l",12,40,262,40,"a"],["p","M12 68 H100 Q140 96 180 68 H262","a"],["l",12,96,262,96,"a"],["p","M12 124 H62 Q92 124 106 114","a"],["p","M174 114 Q188 124 218 124 H262","a"],["t",2,44,"1"],["t",2,72,"2"],["t",2,100,"3"],["t",2,128,"4"],["t",268,44,"1"],["t",268,72,"2"],["t",268,100,"3"],["t",268,128,"4"]]},"o":["1","2","3","4."],"c":3,"s":"Inside a metal E = 0, so lines cannot go through the sphere.\nLines must end on (or start from) the surface at right angles to it.\nOnly path 4 meets the surface perpendicularly and does not enter the sphere. Paths 1, 2 and 3 go through the conductor.\nAnswer: option (d)."},
{"y":"JEE Main 2025 · 7 Apr · Shift 2","tp":"egs","st":"Electric flux","q":"The electric field in a region is given by E⃗ = (2î + 3ĵ + 6k̂) × 10³ N/C. The flux of the field through a rectangular surface parallel to x-z plane is 6.0 N m² C⁻¹. The area of the surface is ______ cm².","n":20,"s":"A surface parallel to the x-z plane has its normal along ĵ, so only the y-component of E gives flux.\nFlux = E_y × A, so A = 6.0/E_y.\nE_y = 3 × 10³ N/C, so A = 6.0/(3 × 10³) = 2 × 10⁻³ m² = 20 cm²."},
{"y":"JEE Main 2025 · 24 Jan · Shift 1","tp":"egs","st":"Electric flux","q":"A square loop of sides a = 1 m is held normally in front of a point charge q = 1 C. The flux of the electric field through the shaded region is {5;p} × {1;ε₀} N m²/C, where the value of p is ______.","fig":{"w":300,"h":205,"alt":"A square of side a divided into four equal quarters. The two lower quarters are shaded, and so is the triangle in the upper left quarter bounded by the left edge, the horizontal middle line and the diagonal to the centre. The point charge q is on the normal through the centre, a/2 in front","d":[["p","M60 100 H200 V170 H60 Z","f"],["p","M60 30 V100 H130 Z","f"],["r",60,30,140,140],["l",130,30,130,170],["l",60,100,200,100],["l",60,30,130,100,"d"],["c",130,100,3,"F"],["t",138,94,"q (a/2 in front)","s"],["t",130,24,"a","ms"],["l",44,30,44,100,"b"],["t",40,68,"a/2","es"]]},"n":48,"s":"The charge is on the normal through the loop's centre, a/2 away, so the loop is one face of a cube with q at its centre.\nFlux through the whole cube = q/ε₀, so through one face = q/(6ε₀).\nThe shaded part is the lower half (1/2 of the face) plus a triangle that is half of the upper-left quarter (1/8). By symmetry about the diagonal the triangle gets half the quarter's flux. Shaded fraction = 5/8.\nFlux = (5/8) × 1/(6ε₀) = (5/48)(1/ε₀).\nSo p = 48."},
{"y":"JEE Main 2024 · 4 Apr · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"An infinite plane sheet of charge having uniform surface charge density + σₛ C/m² is placed on x-y plane. Another infinitely long line charge having uniform linear charge density + λₑ C/m is placed at z = 4 m plane and parallel to y-axis. If the magnitude values |σₛ| = 2 |λₑ| then at point (0, 0, 2), the ratio of magnitudes of electric field values due to sheet charge to that of line charge is π√n : 1. The value of n is ______.","n":16,"s":"Sheet: E₁ = σₛ/(2ε₀).\nThe point (0, 0, 2) is 4 − 2 = 2 m from the line, so E₂ = λₑ/(2πε₀ × 2) = λₑ/(4πε₀).\nE₁/E₂ = [σₛ/(2ε₀)] × [4πε₀/λₑ] = 2πσₛ/λₑ = 2π × 2 = 4π.\nπ√n = 4π gives √n = 4, so n = 16."},
{"y":"JEE Main 2024 · 5 Apr · Shift 2","tp":"efl","st":"Electric dipole","q":"The electric field at point p due to an electric dipole is E. The electric field at point R on equatorial line will be {E;x}. The value of x is ______.","fig":{"w":300,"h":240,"alt":"A dipole with minus q and plus q on a horizontal line, centre O, point P on that line at distance r from O, point Q at distance r above O and point R at distance 2r above O on the perpendicular bisector","d":[["l",40,190,270,190],["c",100,190,4,"F"],["c",180,190,4,"F"],["c",140,190,2,"F"],["c",215,190,3,"F"],["t",100,208,"−q","ms"],["t",180,208,"+q","ms"],["t",140,208,"O","ms"],["t",222,184,"P"],["l",140,190,140,40,"d"],["c",140,120,3,"F"],["c",140,50,3,"F"],["t",148,124,"Q"],["t",148,54,"R"],["l",120,190,120,50,"b"],["t",114,124,"2r","e"],["l",160,190,160,120,"b"],["t",166,160,"r"],["l",140,226,215,226,"b"],["t",178,238,"r","ms"]]},"n":16,"s":"P is on the axis at distance r from the centre: E = 2kp/r³.\nR is on the equatorial line at distance 2r: E_R = kp/(2r)³ = kp/(8r³).\nE_R/E = (kp/8r³)/(2kp/r³) = 1/16.\nSo E_R = E/16 and x = 16."},
{"y":"JEE Main 2024 · 6 Apr · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"Three infinitely long charged thin sheets are placed as shown in figure. The magnitude of electric field at the point P is {xσ;ε₀}. The value of x is ______. (all quantities are measured in SI units).","fig":{"w":320,"h":160,"alt":"Three parallel sheets seen edge on at x = -a (minus sigma), x = a (minus 2 sigma) and x = 3a (sigma); origin O between the first two and point P between x = a and x = 3a","d":[["l",60,22,60,132],["l",140,22,140,132],["l",220,22,220,132],["t",60,16,"−σ","ms"],["t",140,16,"−2σ","ms"],["t",220,16,"σ","ms"],["l",20,77,300,77,"da"],["t",298,70,"X","e"],["c",100,77,2.5,"F"],["t",100,92,"O","ms"],["c",180,77,2.5,"F"],["t",180,68,"P","ms"],["t",60,150,"x = −a","ms"],["t",140,150,"x = a","ms"],["t",220,150,"x = 3a","ms"]]},"n":2,"s":"Each sheet gives a field of magnitude σ_sheet/(2ε₀). P is between x = a and x = 3a.\nSheet −σ (x = −a) attracts P to the left: σ/(2ε₀).\nSheet −2σ (x = a) attracts P to the left: 2σ/(2ε₀) = σ/ε₀.\nSheet +σ (x = 3a) repels P to the left: σ/(2ε₀).\nAll point the same way: total = (1/2 + 1 + 1/2)σ/ε₀ = 2σ/ε₀. So x = 2."},
{"y":"JEE Main 2024 · 8 Apr · Shift 1","tp":"egs","st":"Electric flux","q":"An electric field, E⃗ = {2î + 6ĵ + 8k̂;√6} passes through the surface of 4 m² area having unit vector, n̂ = ({2î + ĵ + k̂;√6}). The electric flux for that surface is ______ V m.","n":12,"s":"Flux = E⃗ · n̂ A.\nE⃗ · n̂ = (2×2 + 6×1 + 8×1)/6 = 18/6 = 3 V/m.\nFlux = 3 × 4 = 12 V m."},
{"y":"JEE Main 2024 · 8 Apr · Shift 2","tp":"efl","st":"Field of point charges and distributions","q":"If the net electric field at point P along Y axis is zero, then the ratio of |q₂/q₃| is {8;5√x}, where x = ______.","fig":{"w":240,"h":195,"alt":"A triangle with point P at the top, charge plus q2 at the lower left and minus q3 at the lower right; the perpendicular from P is 4 cm and meets the base 2 cm from q2 and 3 cm from q3","d":[["l",60,150,110,50,"d"],["l",185,150,110,50,"d"],["l",110,50,110,150],["p","M110 142 H118 V150"],["l",60,150,185,150],["c",60,150,3,"F"],["c",185,150,3,"F"],["t",110,42,"P","ms"],["t",116,104,"4 cm","s"],["t",60,168,"+q₂","ms"],["t",185,168,"−q₃","ms"],["t",85,184,"2 cm","ms"],["t",148,184,"3 cm","ms"]]},"n":5,"s":"From the figure P is 4 cm above the base. Distance to q₂ = √(2² + 4²) = √20 cm; distance to q₃ = √(3² + 4²) = 5 cm.\nThe vertical components of the two fields must cancel (q₂ is positive, so its field has an upward part; q₃ is negative, so its field has a downward part).\nk|q₂|/20 × 4/√20 = k|q₃|/25 × 4/5.\n|q₂|/|q₃| = (20√20)/(125) = 8/(5√5).\nSo x = 5."},
{"y":"JEE Main 2024 · 9 Apr · Shift 2","tp":"egs","st":"Electric flux","q":"An electric field E⃗ = (2xî) N C⁻¹ exists in space. A cube of side 2 m is placed in the space as per figure given below. The electric flux through the cube is ______ N m²/C.","fig":{"w":300,"h":175,"alt":"Axes with origin O; a cube of side 2 m whose left face is 2 m from the origin along x, drawn in perspective","d":[["l",40,135,292,135,"a"],["l",40,135,40,8,"a"],["t",286,128,"X","e"],["t",46,14,"Y"],["t",34,148,"O","e"],["p","M110 135 H180 V65 H110 Z"],["p","M130 117 H200 V47 H130 Z"],["l",110,65,130,47],["l",180,65,200,47],["l",180,135,200,117],["l",110,135,130,117,"d"],["l",40,22,110,22,"b"],["t",75,16,"2 m","ms"],["l",110,158,180,158,"b"],["t",145,171,"2 m","ms"]]},"n":16,"s":"E has only an x-component, so only the two faces perpendicular to x give flux. Each has area 4 m².\nFrom the figure the cube spans x = 2 m to x = 4 m.\nFlux out of the face at x = 4: (2×4)×4 = 32. Flux into the face at x = 2: (2×2)×4 = 16.\nNet flux = 32 − 16 = 16 N m²/C (Gauss: ∇·E = 2, times volume 8 = 16)."},
{"y":"JEE Main 2024 · 1 Feb · Shift 2","tp":"ecl","st":"Equilibrium and motion of charges","q":"Suppose a uniformly charged wall provides a uniform electric field of 2 × 10⁴ N/C normally. A charged particle of mass 2 g being suspended through a silk thread of length 20 cm and remain stayed at a distance of 10 cm from the wall. Then the charge on the particle will be {1;√x} μC, where x = ______. [use g = 10 m/s²]","n":3,"s":"sinθ = 10/20 = 1/2, so θ = 30°.\nEquilibrium: T cosθ = mg, T sinθ = qE, so qE = mg tanθ.\nq = mg tan30°/E = (2×10⁻³ × 10 × 0.577)/(2×10⁴) = 5.77×10⁻⁷ C = 0.577 μC = 1/√3 μC.\nSo x = 3."},
{"y":"JEE Main 2024 · 27 Jan · Shift 2","tp":"efl","st":"Electric dipole","q":"Two charges of −4 μC and +4 μC are placed at the points A(1, 0, 4) m and B(2, −1, 5) m located in an electric field E⃗ = 0.20 î V/cm. The magnitude of the torque acting on the dipole is 8√α × 10⁻⁵ N m, where α = ______.","n":2,"s":"Dipole moment p⃗ = q × (vector from −q to +q) = 4×10⁻⁶ × (B − A) = 4×10⁻⁶ (î − ĵ + k̂) C m.\nE⃗ = 0.20 V/cm = 20 V/m along î.\nτ⃗ = p⃗ × E⃗ = 4×10⁻⁶ × 20 × (î − ĵ + k̂) × î = 8×10⁻⁵ (ĵ + k̂).\n|τ| = 8×10⁻⁵ × √2 N m = 8√2 × 10⁻⁵ N m.\nSo α = 2."},
{"y":"JEE Main 2024 · 29 Jan · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"An electron is moving under the influence of the electric field of a uniformly charged infinite plane sheet S having surface charge density +σ. The electron at t = 0 is at a distance of 1 m from S and has a speed of 1 m/s. The maximum value of σ if the electrons strikes S at t = 1 s is α[{mε₀;e}] C/m², the value of α is ______.","n":8,"s":"The sheet attracts the electron with constant acceleration a = eE/m = eσ/(2ε₀m).\nTo reach S at t = 1 s, the largest a occurs when the electron starts moving away from S (moving towards S would need a = 0).\nTaking distance from S: 0 = 1 + (1)(1) − ½a(1)², so a = 4 m/s².\neσ/(2ε₀m) = 4 gives σ = 8 mε₀/e.\nSo α = 8."},
{"y":"JEE Advanced 2024","tp":"egs","st":"Electric flux","q":"A charge is kept at the central point P of a cylindrical region. The two edges subtend a half-angle θ at P, as shown in the figure. When θ = 30°, then the electric flux through the curved surface of the cylinder is φ. If θ = 60°, then the electric flux through the curved surface becomes φ/√n, where the value of n is ______.","fig":{"w":220,"h":235,"alt":"A cylinder with a charge at its central point P; lines from P to the edges of the two end faces make half-angle theta with the axis","d":[["p","M60 35 A50 10 0 0 1 160 35 A50 10 0 0 1 60 35"],["p","M60 195 A50 10 0 0 0 160 195"],["l",60,35,60,195],["l",160,35,160,195],["l",110,18,110,215,"d"],["c",110,115,2.5,"F"],["t",100,119,"P","e"],["l",110,115,160,35,"d"],["l",110,115,60,35,"d"],["l",110,115,160,195,"d"],["l",110,115,60,195,"d"],["t",114,84,"θ","s"],["t",114,152,"θ","s"]]},"n":3,"s":"Flux through one flat end face = (q/ε₀) × (1 − cosθ)/2 (the face is a spherical cap of half-angle θ as seen from q).\nCurved surface = q/ε₀ − 2 × (q/ε₀)(1 − cosθ)/2 = (q/ε₀) cosθ.\nθ = 30°: φ = (√3/2) q/ε₀. θ = 60°: φ′ = (1/2) q/ε₀.\nφ/φ′ = √3, so φ′ = φ/√3 and n = 3."},
{"y":"JEE Main 2023 · 10 Apr · Shift 2","tp":"efl","st":"Field lines and motion in a field","q":"An electron revolves around an infinite cylindrical wire having uniform linear charge density 2 × 10⁻⁸ C m⁻¹ in circular path under the influence of attractive electrostatic field. The velocity of electron with which it is revolving is ______ × 10⁶ m s⁻¹. (Given mass of electron = 9 × 10⁻³¹ kg)","n":8,"s":"Field of the wire: E = λ/(2πε₀r) = 2kλ/r.\nThe attraction gives the centripetal force: eE = mv²/r, so v² = 2keλ/m (independent of r).\nv² = 2 × 9×10⁹ × 1.6×10⁻¹⁹ × 2×10⁻⁸/(9×10⁻³¹) = 6.4×10¹³.\nv = 8 × 10⁶ m/s."},
{"y":"JEE Main 2023 · 13 Apr · Shift 1","tp":"efl","st":"Field of point charges and distributions","q":"A thin infinite sheet charge and an infinite line charge of respective charge densities +σ and +λ are placed parallel at 5 m distance from each other. Points 'P' and 'Q' are at {3;π} m and {4;π} m perpendicular distances from line charge towards sheet charge, respectively. E(P) and E(Q) are the magnitudes of resultant electric field intensities at point 'P' and 'Q', respectively. If {E(P);E(Q)} = {4;a} for 2|σ| = |λ|, then the value of a is ______.","n":6,"s":"Between the two, the line's field points towards the sheet and the sheet's field points towards the line, so they subtract.\nSheet: σ/(2ε₀) = λ/(4ε₀) everywhere.\nLine at P: λ/(2πε₀ × 3/π) = λ/(6ε₀). Line at Q: λ/(2πε₀ × 4/π) = λ/(8ε₀).\nE(P) = λ/4 − λ/6 = λ/12 (in units of 1/ε₀). E(Q) = λ/4 − λ/8 = λ/8.\nE(P)/E(Q) = 8/12 = 2/3 = 4/a, so a = 6."},
{"y":"JEE Main 2023 · 24 Jan · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"A stream of positively charged particles having {q;m} = 2 × 10¹¹ C kg⁻¹ and velocity v⃗₀ = 3 × 10⁷ î m s⁻¹ is deflected by an electric field 1.8 ĵ kV m⁻¹. The electric field exists in a region of 10 cm along x direction. Due to the electric field, the deflection of the charge particles in the y direction is ______ mm.","n":2,"s":"Time in the field: t = 0.10/(3×10⁷) = 3.33×10⁻⁹ s.\nAcceleration: a = (q/m)E = 2×10¹¹ × 1800 = 3.6×10¹⁴ m/s².\ny = ½at² = ½ × 3.6×10¹⁴ × (3.33×10⁻⁹)² = 2×10⁻³ m.\nDeflection = 2 mm."},
{"y":"JEE Main 2023 · 25 Jan · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"A uniform electric field of 10 N/C is created between two parallel charged plates. An electron enters the field symmetrically between the plates with a kinetic energy 0.5 eV. The length of each plate is 10 cm. The angle (θ) of deviation of the path of electron as it comes out of the field is ______ (in degree).","n":45,"s":"Along the plates the speed stays vₓ; across them a = eE/m for time t = L/vₓ.\ntanθ = v_y/vₓ = (eEL/m vₓ)/vₓ = eEL/(mvₓ²) = eEL/(2 KE).\neEL = 10 × 0.1 = 1 eV, and 2 KE = 1 eV.\ntanθ = 1, so θ = 45°."},
{"y":"JEE Main 2023 · 30 Jan · Shift 2","tp":"egs","st":"Electric flux","q":"A cuboid lies in a region with electric field E⃗ = (2x²î − 4yĵ + 6k̂) N/C. One corner of the cuboid is at the origin and its edges lie along the x, y and z axes. The magnitude of charge within the cuboid is nε₀ C. The value of n is ______. (if dimension of cuboid is 1 × 2 × 3 m³).","n":12,"s":"Flux through faces perpendicular to x (area 2×3 = 6): at x = 1, E_x = 2 gives +12; at x = 0, E_x = 0 gives 0.\nFaces perpendicular to y (area 1×3 = 3): at y = 2, E_y = −8 gives −24; at y = 0, E_y = 0 gives 0.\nFaces perpendicular to z (area 1×2 = 2): E_z = 6 on both, so +12 and −12 cancel.\nNet flux = 12 − 24 = −12 = q/ε₀, so |q| = 12ε₀ and n = 12."},
{"y":"JEE Main 2023 · 31 Jan · Shift 1","tp":"egs","st":"Electric flux","q":"Expression for an electric field is given by E⃗ = 4000x² î {V;m}. The electric flux through the cube of side 20 cm when placed in electric field (cube with one corner at the origin and edges along the axes, so x runs from 0 to 20 cm) is ______ V cm.","n":640,"s":"E is along x, so only the faces perpendicular to x give flux. Each has area (0.2)² = 0.04 m².\nAt x = 0, E = 0. At x = 0.2 m, E = 4000 × 0.04 = 160 V/m.\nFlux = 160 × 0.04 = 6.4 V m = 640 V cm."},
{"y":"JEE Main 2022 · 25 Jul · Shift 1","tp":"egs","st":"Gauss's law and symmetric bodies","q":"The volume charge density of a sphere of radius 6 m is 2 μC cm⁻³. The number of lines of force per unit surface area coming out from the surface of the sphere is ______ × 10¹⁰ N C⁻¹. [Given : Permittivity of vacuum ε₀ = 8.85 × 10⁻¹² C² N⁻¹ m⁻²]","n":45,"s":"Lines per unit area = E at the surface = ρR/(3ε₀).\nρ = 2 μC/cm³ = 2×10⁻⁶/10⁻⁶ C/m³ = 2 C/m³.\nE = (2 × 6)/(3 × 8.85×10⁻¹²) = 4.52×10¹¹ = 45.2 × 10¹⁰ N/C.\nSo the value is about 45."},
{"y":"JEE Main 2022 · 27 Jul · Shift 1","tp":"egs","st":"Gauss's law and symmetric bodies","q":"A long cylindrical volume contains a uniformly distributed charge of density ρ C m⁻³. The electric field inside the cylindrical volume at a distance x = {2ε₀;ρ} m from its axis is ______ V m⁻¹.","n":1,"s":"Gauss's law with a coaxial cylinder of radius x and length L: E × 2πxL = ρπx²L/ε₀.\nSo E = ρx/(2ε₀).\nPut x = 2ε₀/ρ: E = (ρ/2ε₀)(2ε₀/ρ) = 1 V/m."},
{"y":"JEE Main 2022 · 27 Jul · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor with width 4 cm, length 8 cm and separation between the plates of 4 mm is connected to a battery of 20 V. A dielectric slab of dielectric constant 5 having length 1 cm, width 4 cm and thickness 4 mm is inserted between the plates of parallel plate capacitor. The electrostatic energy of this system will be ______ ε₀ J. (Where ε₀ is the permittivity of free space)","n":240,"s":"The battery keeps V = 20 V. The slab fills the gap, so the capacitor is two capacitors in parallel.\nWith slab: area 1×4 = 4 cm² = 4×10⁻⁴ m², C₁ = 5ε₀(4×10⁻⁴)/d. Without slab: area 7×4 = 28×10⁻⁴ m², C₂ = ε₀(28×10⁻⁴)/d.\nd = 4×10⁻³ m: C = ε₀(20 + 28)×10⁻⁴/(4×10⁻³) = 1.2ε₀.\nU = ½CV² = ½ × 1.2ε₀ × 400 = 240ε₀ J."},
{"y":"JEE Advanced 2022","tp":"egs","st":"Electric flux","q":"A charge q is surrounded by a closed surface consisting of an inverted cone of height h and base radius R, and a hemisphere of radius R as shown in the figure. The electric flux through the conical surface is {nq;6ε₀} (in SI units). The value of n is ______.","fig":{"w":240,"h":225,"alt":"A hemisphere of radius R sitting on the circular base of an inverted cone of height h with apex O; the charge q is at the centre of the base","d":[["p","M40 80 A80 80 0 0 1 200 80"],["l",40,80,200,80,"d"],["l",40,80,120,200],["l",200,80,120,200],["c",120,80,3,"F"],["t",126,74,"q"],["t",162,74,"R","ms"],["l",20,80,20,200,"b"],["t",14,144,"h","e"],["t",126,216,"O"]]},"n":3,"s":"The charge sits at the centre of the circular base, which is also the centre of the hemisphere.\nTotal flux through the closed surface = q/ε₀.\nBy symmetry the hemisphere takes half of it: q/(2ε₀).\nThe cone takes the rest: q/(2ε₀) = 3q/(6ε₀).\nSo n = 3."},
{"y":"JEE Main 2021 · 20 Jul · Shift 1","tp":"efl","st":"Field lines and motion in a field","q":"A body having specific charge 8 μC g⁻¹ is resting on a frictionless plane at a distance 10 cm from the wall (as shown in the figure). It starts moving towards the wall when a uniform electric field of 100 V m⁻¹ is applied horizontally towards the wall. If the collision of the body with the wall is perfectly elastic, then the time period of the motion will be ______ s.","fig":{"w":300,"h":115,"alt":"A body on a frictionless floor 10 cm from a brick wall, with an electric field of 100 V/m pointing toward the wall","d":[["l",10,70,290,70],["r",232,12,48,58,"f"],["r",50,48,34,22],["t",67,63,"Body","ms"],["l",96,38,200,38,"a"],["t",148,30,"100 V/m","ms"],["l",84,90,232,90,"b"],["t",158,106,"10 cm","ms"]]},"n":1,"s":"Specific charge = 8 μC/g = 8×10⁻³ C/kg.\na = (q/m)E = 8×10⁻³ × 100 = 0.8 m/s².\nTime to reach the wall: 0.1 = ½(0.8)t², so t = 0.5 s.\nAfter an elastic bounce it returns with the same speed, slows down at 0.8 m/s² and stops at the start after another 0.5 s.\nPeriod = 0.5 + 0.5 = 1 s."},
{"y":"JEE Main 2021 · 22 Jul · Shift 2","tp":"egs","st":"Gauss's law and symmetric bodies","q":"The total charge enclosed in an incremental volume of 2 × 10⁻⁹ m³ located at the origin is ______ nC, if electric flux density of its field is found as\nD⃗ = e^(−x) sin y î − e^(−x) cos y ĵ + 2z k̂ C/m².","n":4,"s":"Gauss's law in differential form: charge density ρ = divergence of D = ∂Dx/∂x + ∂Dy/∂y + ∂Dz/∂z.\n∂Dx/∂x = −e^(−x) sin y, ∂Dy/∂y = +e^(−x) sin y, ∂Dz/∂z = 2.\nThe first two terms cancel, so ρ = 2 C/m³ (the same everywhere).\nCharge = ρ × volume = 2 × 2 × 10⁻⁹ C = 4 × 10⁻⁹ C = 4 nC."},
{"y":"JEE Main 2021 · 17 Mar · Shift 2","tp":"egs","st":"Electric flux","q":"The electric field in a region is given by E⃗ = {2;5}E₀ î + {3;5}E₀ ĵ with E₀ = 4.0 × 10³ N/C. The flux of this field through a rectangular surface area 0.4 m² parallel to the Y-Z plane is ______ N m² C⁻¹.","n":640,"s":"Flux = E · A. A surface parallel to the Y-Z plane has its normal along the x-axis, so only the x-component of the field passes through it.\nEx = (2/5)E₀ = 0.4 × 4.0 × 10³ = 1600 N/C.\nFlux = Ex × A = 1600 × 0.4 = 640 N m² C⁻¹."},
{"y":"JEE Main 2021 · 24 Feb · Shift 2","tp":"egs","st":"Electric flux","q":"A point charge of +12 μC is at a distance 6 cm vertically above the centre of a square of side 12 cm as shown in figure. The magnitude of the electric flux through the square will be ______ × 10³ N m²/C.","fig":{"w":340,"h":170,"alt":"A point charge +q hangs 6 cm above the centre of a horizontal square of side 12 cm","d":[["p","M80 140 L220 140 L260 105 L120 105 Z","f"],["c",170,40,4,"F"],["t",178,36,"+q"],["l",170,44,170,121,"da"],["t",176,86,"6 cm","s"],["c",170,122.5,2,"F"],["t",150,160,"12 cm","ms"],["t",252,130,"12 cm","s"]]},"n":226,"s":"Imagine the square as one face of a cube of side 12 cm. The charge is exactly 6 cm above the face centre, so it sits at the centre of the cube.\nTotal flux from the charge = q/ε₀, shared equally by the 6 faces of the cube.\nFlux through one face = q/(6ε₀) = 12 × 10⁻⁶ / (6 × 8.85 × 10⁻¹²) ≈ 2.26 × 10⁵ N m²/C.\nThat is 226 × 10³ N m²/C."},
{"y":"JEE Main 2021 · 25 Feb · Shift 1","tp":"egs","st":"Electric flux","q":"The electric field in a region is given by E⃗ = ({3;5}E₀ î + {4;5}E₀ ĵ) N/C. The ratio of flux of reported field through the rectangular surface of area 0.2 m² (parallel to y-z plane) to that of the surface of area 0.3 m² (parallel to x-z plane) is a : b, where a = ______. [Here î, ĵ and k̂ are unit vectors along x, y and z-axes respectively]","n":1,"s":"A surface parallel to the y-z plane has its normal along x, so it only takes the x-component: flux₁ = (3/5)E₀ × 0.2 = 0.12E₀.\nA surface parallel to the x-z plane has its normal along y, so it only takes the y-component: flux₂ = (4/5)E₀ × 0.3 = 0.24E₀.\nRatio = 0.12 : 0.24 = 1 : 2, so a : b = 1 : 2.\nHence a = 1."},
{"y":"JEE Main 2020 · 9 Jan · Shift 2","tp":"egs","st":"Electric flux","q":"An electric field E⃗ = 4x î − (y² + 1) ĵ N/C passes through the box shown in figure. The flux of the electric field through surfaces ABCD and BCGF are marked as φI and φII respectively. The difference between (φI − φII) is (in N m²/C) ______.","fig":{"w":340,"h":175,"alt":"Box with corners A(0,0,2), B(3,0,2), C(3,2,2), D(0,2,2), E(0,0,0), F(3,0,0), G(3,2,0), H(0,2,0); top face ABCD and side face BCGF at x = 3","d":[["p","M140 40 L245 40 L201 68 L96 68 Z","f"],["p","M245 40 L201 68 L201 138 L245 110 Z","f"],["l",140,40,245,40,null],["l",245,40,201,68,null],["l",201,68,96,68,null],["l",96,68,140,40,null],["l",245,40,245,110,null],["l",201,68,201,138,null],["l",96,68,96,138,null],["l",245,110,201,138,null],["l",201,138,96,138,null],["l",140,110,245,110,"d"],["l",140,110,96,138,"d"],["l",140,40,140,110,"d"],["l",245,110,290,110,"a"],["t",294,114,"x"],["l",140,40,140,12,"a"],["t",146,14,"z"],["l",96,138,70,156,"a"],["t",58,164,"y"],["t",134,36,"A (0,0,2)","es"],["t",250,36,"B (3,0,2)","s"],["t",92,64,"D (0,2,2)","es"],["t",206,64,"C (3,2,2)","s"],["t",148,124,"E (0,0,0)","s"],["t",250,112,"F (3,0,0)","s"],["t",208,150,"G (3,2,0)","s"],["t",98,154,"H (0,2,0)","s"]]},"n":48,"s":"Flux through a face = E · A with the normal along the face's outward direction.\nFace ABCD is the top face (z = 2), with normal along z. E has no z-component, so φI = 0.\nFace BCGF is the face x = 3 (area 2 × 2 = 4 m²), normal along x. Ex = 4x = 12 N/C there, so φII = 12 × 4 = 48 N m²/C.\nThe difference between the two fluxes has magnitude |φI − φII| = 48 N m²/C."},
{"y":"JEE Advanced 2020","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two large circular discs separated by a distance of 0.01 m are connected to a battery via a switch as shown in the figure. Charged oil drops of density 900 kg m⁻³ are released through a tiny hole at the center of the top disc. Once some oil drops achieve terminal velocity, the switch is closed to apply a voltage of 200 V across the discs. As a result, an oil drop of radius 8 × 10⁻⁷ m stops moving vertically and floats between the discs. The number of electrons present in this oil drop is ______. (neglect the buoyancy force, take acceleration due to gravity = 10 m s⁻² and charge on an electron e = 1.6 × 10⁻¹⁹ C)","fig":{"w":340,"h":160,"alt":"Two horizontal discs 0.01 m apart joined through a switch to a 200 V battery, with an oil drop floating between them","d":[["r",190,60,100,8,"f"],["r",190,120,100,8,"f"],["l",190,64,125,64],["l",100,64,60,64],["l",100,64,120,52],["t",92,46,"Switch","s"],["l",60,64,60,92],["l",48,92,72,92,"B"],["l",54,99,66,99,"B"],["l",60,99,60,124],["l",60,124,190,124],["t",78,100,"200 V","s"],["c",240,94,3,"F"],["t",248,92,"drop","s"],["l",304,68,304,120,"b"],["t",310,98,"0.01 m","s"]]},"n":6,"s":"The drop floats, so the upward electric force balances its weight: n e E = m g, with E = V/d.\nMass: m = ρ × (4/3)πr³ = 900 × 4.19 × (8 × 10⁻⁷)³ ≈ 1.93 × 10⁻¹⁵ kg.\nField: E = 200/0.01 = 2 × 10⁴ V/m.\nn = mg/(eE) = (1.93 × 10⁻¹⁵ × 10)/(1.6 × 10⁻¹⁹ × 2 × 10⁴) ≈ 6."},
{"y":"JEE Advanced 2020","tp":"egs","st":"Non-uniform charge distributions","q":"A circular disc of radius R carries surface charge density σ(r) = σ₀(1 − {r;R}), where σ₀ is a constant and r is the distance from the center of the disc. Electric flux through a large spherical surface that encloses the charged disc completely is φ₀. Electric flux through another spherical surface of radius {R;4} and concentric with the disc is φ. Then the ratio {φ₀;φ} is ______.","n":6.4,"s":"By Gauss's law, flux = (charge inside)/ε₀. A ring of radius r and width dr holds charge σ(r) · 2πr dr.\nWhole disc: Q = 2πσ₀ ∫₀ᴿ (r − r²/R) dr = 2πσ₀(R²/2 − R²/3) = πσ₀R²/3.\nWithin radius R/4: q = 2πσ₀(r²/2 − r³/3R) at r = R/4 = 2πσ₀R²(1/32 − 1/192) = 5πσ₀R²/96.\nφ₀/φ = Q/q = (π/3)/(5π/96) = 96/15 = 6.4."},
{"y":"JEE Advanced 2020","tp":"efl","st":"Electric dipole","q":"One end of a spring of negligible unstretched length and spring constant k is fixed at the origin (0, 0). A point particle of mass m carrying a positive charge q is attached at its other end. The entire system is kept on a smooth horizontal surface. When a point dipole p⃗ pointing towards the charge q is fixed at the origin, the spring gets stretched to a length l and attains a new equilibrium position (see figure). If the point mass is now displaced slightly by Δl << l from its equilibrium position and released, it is found to oscillate at frequency {1;δ}√{k;m}. The value of δ is ______.","fig":{"w":340,"h":150,"alt":"A dipole p at the origin pointing along +x, and a spring from the origin to a charge q at distance l on the x-axis","d":[["l",30,100,325,100,"a"],["l",30,100,30,20,"a"],["t",329,104,"x"],["t",36,22,"y"],["t",4,118,"(0, 0)","s"],["l",36,84,66,84,"a"],["t",50,76,"p","ms"],["p","M30 100 L50 100 L56 90 L66 110 L76 90 L86 110 L96 90 L106 110 L116 90 L126 110 L136 90 L146 110 L156 90 L166 110 L176 90 L186 110 L196 90 L206 110 L216 90 L226 110 L236 100 L260 100"],["c",262,100,5,"F"],["t",262,86,"q","ms"],["l",30,128,262,128,"b"],["t",146,124,"l","ms"]]},"n":3.14,"s":"On its axis the dipole's field is E = 2kp/x³ (k = 1/4πε₀) along p, so it pushes the charge q away from the origin: F = qp/(2πε₀x³).\nEquilibrium at x = l: k·l = qp/(2πε₀l³).\nNet force F(x) = qp/(2πε₀x³) − kx. Its slope at l is dF/dx = −3qp/(2πε₀l⁴) − k = −3k − k = −4k (using qp/(2πε₀l³) = kl).\nSo the effective spring constant is 4k, and f = (1/2π)√(4k/m) = (1/π)√(k/m).\nComparing with (1/δ)√(k/m) gives δ = π ≈ 3.14."},
{"y":"JEE Advanced 2018","tp":"efl","st":"Field lines and motion in a field","q":"A particle of mass 10⁻³ kg and charge 1.0 C is initially at rest. At time t = 0, the particle comes under the influence of an electric field E⃗(t) = E₀ sin ωt î, where E₀ = 1.0 N C⁻¹ and ω = 10³ rad s⁻¹. Consider the effect of only the electrical force on the particle. Then the maximum speed, in m s⁻¹, attained by the particle at subsequent times is ______.","n":2,"s":"Acceleration a = qE/m = (qE₀/m) sin ωt = 10³ sin(10³t) m/s².\nIntegrate from rest: v = (qE₀/mω)(1 − cos ωt) = (1 × 1/(10⁻³ × 10³))(1 − cos ωt) = 1 − cos ωt.\nThe speed is largest when cos ωt = −1, giving v = 1 − (−1) = 2 m/s."},
{"y":"JEE Advanced 2015","tp":"egs","st":"Electric flux","q":"An infinitely long uniform line charge distribution of charge per unit length λ lies parallel to the y-axis in the y-z plane at z = {√3;2}a (see figure). If the magnitude of the flux of the electric field through the rectangular surface ABCD lying in the x-y plane with its centre at the origin is {λL;nε₀} (ε₀ = permittivity of free space), then the value of n is ______.","fig":{"w":340,"h":205,"alt":"Rectangle ABCD of sides L along y and a along x lying in the x-y plane centred at O, with a line charge parallel to y at height √3a/2 above it","d":[["l",150,160,150,18,"a"],["t",156,20,"z"],["l",150,160,320,160,"a"],["t",324,164,"y"],["l",150,160,104,194,"a"],["t",92,202,"x"],["p","M118 140 L238 140 L182 180 L62 180 Z","f"],["t",54,188,"A","e"],["t",186,192,"B"],["t",242,138,"C"],["t",112,136,"D","e"],["t",156,176,"O","s"],["c",150,160,2,"F"],["l",118,129,238,129,"b"],["t",178,124,"L","ms"],["l",62,172,118,132,"b"],["t",84,150,"a","ms"],["l",30,70,310,70,"B"],["t",312,66,"λ"],["l",270,160,270,70,"b"],["t",276,118,"√3a/2","s"],["t",210,62,"line charge","ms"]]},"n":6,"s":"The rectangle is a flat surface. Look at it end-on along the y-direction: the line charge is a point at height h = (√3/2)a above the centre, and the rectangle has half-width a/2.\nThe angle subtended at the line by each half: tan θ = (a/2)/(√3a/2) = 1/√3, so θ = 30°. The whole width subtends 60°.\nTotal flux from a length L of the line = λL/ε₀ spread over all 360°. The flux through the rectangle is the fraction 60/360 = 1/6 of it.\nFlux = (1/6)(λL/ε₀) = λL/(6ε₀), so n = 6."},
{"y":"IIT-JEE 2012","tp":"egs","st":"Gauss's law and symmetric bodies","q":"An infinitely long solid cylinder of radius R has a uniform volume charge density ρ. It has a spherical cavity of radius R/2 with its centre on the axis of the cylinder, as shown in the figure.\nThe magnitude of the electric field at the point P, which is at a distance 2R from the axis of the cylinder, is given by the expression {23ρR;16kε₀}. The value of k is ______.","fig":{"w":340,"h":185,"alt":"Vertical cylinder of radius R with a spherical cavity of radius R/2 at its centre; point P lies at distance 2R from the axis along y","d":[["p","M110 40 Q170 12 230 40 Q170 68 110 40","d"],["p","M110 150 Q170 182 230 150"],["l",110,40,110,150,"d"],["l",230,40,230,150,"d"],["c",170,95,30],["l",170,95,170,8,"a"],["t",176,12,"z"],["l",170,95,318,95,"a"],["t",322,99,"y"],["l",170,95,128,132,"a"],["t",114,146,"x"],["l",170,95,149,74,"a"],["t",146,70,"R/2","e"],["l",170,70,230,70,"b"],["t",200,66,"R","ms"],["c",290,95,3,"F"],["t",292,86,"P"],["l",170,112,290,112,"b"],["t",230,126,"2R","ms"]]},"n":6,"s":"Use superposition: full cylinder (density +ρ) plus a sphere of density −ρ filling the cavity.\nCylinder, outside, at distance 2R from the axis: E₁ = ρR²/(2ε₀ · 2R) = ρR/(4ε₀) (by Gauss's law, charge per length = ρπR²).\nCavity sphere, charge −ρ(4/3)π(R/2)³ = −ρπR³/6, at distance 2R from its centre: E₂ = (ρπR³/6)/(4πε₀(2R)²) = ρR/(96ε₀), pointing opposite to E₁.\nE = ρR/(4ε₀) − ρR/(96ε₀) = (24 − 1)ρR/(96ε₀) = 23ρR/(96ε₀).\nCompare with 23ρR/(16kε₀): 16k = 96, so k = 6."},
{"y":"IIT-JEE 2009","tp":"egs","st":"Non-uniform charge distributions","q":"A solid sphere of radius R has a charge Q distributed in its volume with a charge density ρ = κr^a, where κ and a are constants and r is the distance from its centre. If the electric field at r = R/2 is {1;8} times that at r = R, find the value of a.","n":2,"s":"Charge inside radius r: q(r) = ∫₀ʳ κr′ᵃ · 4πr′² dr′ = 4πκ r^(a+3)/(a+3).\nGauss's law: E(r) = q(r)/(4πε₀r²) ∝ r^(a+3)/r² = r^(a+1).\nSo E(R/2)/E(R) = (1/2)^(a+1) = 1/8 = (1/2)³.\nTherefore a + 1 = 3, so a = 2."},
{"y":"JEE Main 2025 · 29 Jan · Shift 1","tp":"egs","st":"Statements, matching and subjective","q":"Match List-I with List-II.\nList-I\n(A) Electric field inside (distance r > 0 from center) of a uniformly charged spherical shell with surface charge density σ, and radius R\n(B) Electric field at distance r > 0 from, a uniformly charged infinite plane sheet with surface charge density σ.\n(C) Electric field outside (distance r > 0 from center) of a uniformly charged spherical shell with surface charge density σ, and radius R.\n(D) Electric field between 2 oppositely charged infinite plane parallel sheets with uniform surface charge density σ.\nList-II\n(I) σ/ε₀\n(II) σ/2ε₀\n(III) 0\n(IV) {σ;ε₀r²}\nChoose the correct answer from the options given below.","o":["(A)-(IV), (B)-(II), (C)-(III), (D)-(I)","(A)-(II), (B)-(I), (C)-(IV), (D)-(III)","(A)-(IV), (B)-(I), (C)-(III), (D)-(II)","(A)-(III), (B)-(II), (C)-(IV), (D)-(I)"],"c":3,"s":"(A) Inside a uniformly charged shell the field is zero: (III).\n(B) An infinite plane sheet gives E = σ/2ε₀ at any distance: (II).\n(C) Outside the shell all charge acts like a point charge at the centre: E = (σ·4πR²)/(4πε₀r²) = σR²/(ε₀r²), which falls as 1/r². Of the given entries this is (IV), the one with the 1/(ε₀r²) form.\n(D) Between two oppositely charged parallel sheets the fields add: σ/2ε₀ + σ/2ε₀ = σ/ε₀: (I).\nSo A-III, B-II, C-IV, D-I: option (d)."},
{"y":"JEE Advanced 2025","tp":"efl","st":"Statements, matching and subjective","q":"List-I shows four configurations, each consisting of a pair of ideal electric dipoles. Each dipole has a dipole moment of magnitude p, oriented as marked by arrows in the figures. In all the configurations the dipoles are fixed such that they are at a distance 2r apart along the x direction. The midpoint of the line joining the two dipoles is X. The possible resultant electric fields E⃗ at X are given in List-II. (In the figure x points to the right and y points up; î and ĵ are the unit vectors along x and y.)\nChoose the option that describes the correct match between the entries in List-I to those in List-II.\nList-I (P, Q, R, S): the four configurations in the figure\nList-II\n(1) E⃗ = 0\n(2) E⃗ = −{p;2πε₀r³} ĵ\n(3) E⃗ = −{p;4πε₀r³}(î − ĵ)\n(4) E⃗ = {p;4πε₀r³}(2î − ĵ)\n(5) E⃗ = {p;πε₀r³} î","fig":{"w":340,"h":200,"alt":"Four pairs of dipoles 2r apart along x with midpoint X: P both point up; Q left up and right down; R left up and right pointing +x; S both pointing +x","d":[["t",10,44,"(P)"],["l",40,40,140,40,"d"],["c",90,40,2,"F"],["t",90,18,"X","ms"],["l",40,70,140,70,"b"],["t",90,82,"2r","ms"],["l",40,54,40,26,"a"],["l",140,54,140,26,"a"],["t",180,44,"(Q)"],["l",210,40,310,40,"d"],["c",260,40,2,"F"],["t",260,18,"X","ms"],["l",210,70,310,70,"b"],["t",260,82,"2r","ms"],["l",210,54,210,26,"a"],["l",310,26,310,54,"a"],["t",10,134,"(R)"],["l",40,130,140,130,"d"],["c",90,130,2,"F"],["t",90,108,"X","ms"],["l",40,160,140,160,"b"],["t",90,172,"2r","ms"],["l",40,144,40,116,"a"],["l",126,130,154,130,"a"],["t",180,134,"(S)"],["l",210,130,310,130,"d"],["c",260,130,2,"F"],["t",260,108,"X","ms"],["l",210,160,310,160,"b"],["t",260,172,"2r","ms"],["l",196,130,224,130,"a"],["l",296,130,324,130,"a"]]},"o":["P → 3, Q → 1, R → 2, S → 4","P → 4, Q → 5, R → 3, S → 1","P → 2, Q → 1, R → 4, S → 5","P → 2, Q → 1, R → 3, S → 5"],"c":2,"s":"Field of a dipole of moment p at distance r: on its axis E = 2p/(4πε₀r³) along p; on its equatorial line E = p/(4πε₀r³) opposite to p. Let k₀ = p/(4πε₀r³).\nP: X is on the equatorial line of both dipoles (both point up), so E = −k₀ĵ − k₀ĵ = −2k₀ĵ = −p/(2πε₀r³) ĵ: (2).\nQ: the dipoles are opposite, so the two equatorial fields cancel: E = 0: (1).\nR: left dipole (up) gives −k₀ĵ; right dipole (along +x) has X on its axis, giving +2k₀î. E = k₀(2î − ĵ): (4).\nS: both along +x, X on the axis of both: E = 2k₀î + 2k₀î = 4k₀î = p/(πε₀r³) î: (5).\nSo P→2, Q→1, R→4, S→5: option (c)."},
{"y":"JEE Advanced 2018","tp":"efl","st":"Statements, matching and subjective","q":"The electric field E is measured at a point P(0, 0, d) generated due to various charge distributions and the dependence of E on d is found to be different for different charge distributions. List-I contains different relations between E and d. List-II describes different electric charge distributions, along with their locations. Match the functions in List-I with the related charge distributions in List-II.\nList-I\nP. E is independent of d\nQ. E ∝ {1;d}\nR. E ∝ {1;d²}\nS. E ∝ {1;d³}\nList-II\n1. A point charge Q at the origin\n2. A small dipole with point charges Q at (0, 0, l) and −Q at (0, 0, −l). Take 2l << d\n3. An infinite line charge coincident with the x-axis, with uniform linear charge density λ\n4. Two infinite wires carrying uniform linear charge density parallel to the x-axis. The one along (y = 0, z = l) has a charge density +λ and the one along (y = 0, z = −l) has charge density −λ. Take 2l << d\n5. Infinite plane charge coincident with the xy-plane with uniform surface charge density","o":["P → 5; Q → 3, 4; R → 1; S → 2","P → 5; Q → 3; R → 1, 4; S → 2","P → 5; Q → 3; R → 1, 2; S → 4","P → 4; Q → 2, 3; R → 1; S → 5"],"c":1,"s":"P: an infinite plane gives a uniform field σ/2ε₀, independent of d: 5.\nQ: an infinite line charge gives E = λ/2πε₀d ∝ 1/d: 3.\nR: a point charge gives E ∝ 1/d²: 1. Two long parallel wires with opposite charges (separation 2l << d) behave like a line dipole, whose field falls as 1/d²: 4.\nS: a small point dipole gives E ∝ 1/d³: 2.\nSo P→5; Q→3; R→1, 4; S→2: option (b)."},
{"y":"IIT-JEE 2008","tp":"egs","st":"Non-uniform charge distributions","q":"The nuclear charge (Ze) is non-uniformly distributed within a nucleus of radius R. The charge density ρ(r) (charge per unit volume) is dependent only on the radial distance r from the centre of the nucleus as shown in figure (ρ = d for r ≤ a, then falling linearly to zero at r = R). The electric field is only along the radial direction.\nThe electric field at r = R is","fig":{"w":340,"h":160,"alt":"Graph of charge density ρ against r: constant value d up to r = a, then falling linearly to zero at r = R","d":[["l",40,130,310,130,"a"],["l",40,130,40,12,"a"],["t",46,16,"ρ(r)","s"],["t",312,134,"r","s"],["l",40,45,130,45,"B"],["l",130,45,250,130,"B"],["l",130,45,130,130,"d"],["l",250,130,250,100,"d"],["t",34,49,"d","e"],["t",130,146,"a","ms"],["t",250,146,"R","ms"],["t",34,134,"0","es"]]},"o":["independent of a","directly proportional to a","directly proportional to a²","inversely proportional to a"],"c":0,"s":"Gauss's law: at r = R the closed surface encloses the whole nuclear charge Ze, whatever the shape of ρ(r) inside.\nSo E(R) = Ze/(4πε₀R²).\nThis contains no a, so the field at r = R is independent of a."},
{"y":"IIT-JEE 2008","tp":"egs","st":"Non-uniform charge distributions","q":"The nuclear charge (Ze) is non-uniformly distributed within a nucleus of radius R. The charge density ρ(r) (charge per unit volume) is dependent only on the radial distance r from the centre of the nucleus as shown in figure (ρ = d for r ≤ a, then falling linearly to zero at r = R). The electric field is only along the radial direction.\nFor a = 0, the value d (maximum value of ρ as shown in the figure) is","fig":{"w":340,"h":160,"alt":"Graph of charge density ρ against r: constant value d up to r = a, then falling linearly to zero at r = R","d":[["l",40,130,310,130,"a"],["l",40,130,40,12,"a"],["t",46,16,"ρ(r)","s"],["t",312,134,"r","s"],["l",40,45,130,45,"B"],["l",130,45,250,130,"B"],["l",130,45,130,130,"d"],["l",250,130,250,100,"d"],["t",34,49,"d","e"],["t",130,146,"a","ms"],["t",250,146,"R","ms"],["t",34,134,"0","es"]]},"o":["{3Ze;4πR³}","{3Ze;πR³}","{4Ze;3πR³}","{Ze;3πR³}"],"c":1,"s":"For a = 0 the density falls linearly from d at the centre to zero at r = R: ρ(r) = d(1 − r/R).\nTotal charge: Ze = ∫₀ᴿ d(1 − r/R) 4πr² dr = 4πd(R³/3 − R³/4) = 4πd R³/12 = πdR³/3.\nSo d = 3Ze/(πR³)."},
{"y":"IIT-JEE 2008","tp":"egs","st":"Non-uniform charge distributions","q":"The nuclear charge (Ze) is non-uniformly distributed within a nucleus of radius R. The charge density ρ(r) (charge per unit volume) is dependent only on the radial distance r from the centre of the nucleus as shown in figure (ρ = d for r ≤ a, then falling linearly to zero at r = R). The electric field is only along the radial direction.\nThe electric field within the nucleus is generally observed to be linearly dependent on r. This implies","fig":{"w":340,"h":160,"alt":"Graph of charge density ρ against r: constant value d up to r = a, then falling linearly to zero at r = R","d":[["l",40,130,310,130,"a"],["l",40,130,40,12,"a"],["t",46,16,"ρ(r)","s"],["t",312,134,"r","s"],["l",40,45,130,45,"B"],["l",130,45,250,130,"B"],["l",130,45,130,130,"d"],["l",250,130,250,100,"d"],["t",34,49,"d","e"],["t",130,146,"a","ms"],["t",250,146,"R","ms"],["t",34,134,"0","es"]]},"o":["a = 0","a = {R;2}","a = R","a = {2R;3}"],"c":2,"s":"Inside the nucleus E(r) = q(r)/(4πε₀r²).\nFor r ≤ a the density is constant (= d), so q = (4/3)πr³d and E = dr/(3ε₀), which is linear in r.\nBeyond r = a the density falls, so E is no longer proportional to r.\nFor E to be linear everywhere inside the nucleus, the constant-density region must reach the surface: a = R."},
{"y":"JEE Main 2025 · 2 Apr · Shift 2","tp":"efl","st":"Statements, matching and subjective","q":"Given below are two statements : one is labelled as Assertion (A) and the other is labelled as Reason (R).\nAssertion (A) : Net dipole moment of a polar linear isotropic dielectric substance is not zero even in the absence of an external electric field.\nReason (R) : In absence of an external electric field, the different permanent dipoles of a polar dielectric substance are oriented in random directions.\nIn the light of the above statements, choose the most appropriate answer from the options given below :","o":["Both (A) and (R) are correct but (R) is not the correct explanation of (A)","(A) is not correct but (R) is correct","(A) is correct but (R) is not correct","Both (A) and (R) are correct and (R) is the correct explanation of (A)"],"c":1,"s":"In a polar dielectric each molecule has a permanent dipole moment.\nWithout an external field, thermal motion makes these dipoles point in random directions, so (R) is true.\nBecause of the random directions their vector sum is zero, so the net dipole moment of the substance is zero. Hence (A) is false.\nAnswer: (A) is not correct but (R) is correct."},
{"y":"JEE Main 2025 · 7 Apr · Shift 2","tp":"ecn","st":"Statements, matching and subjective","q":"Given below are two statements : one is labelled as Assertion (A) and the other is labelled as Reason (R).\nAssertion (A) : The outer body of an air craft is made of metal which protects persons sitting inside from lightning-strikes.\nReason (R) : The electric field inside the cavity enclosed by a conductor is zero.\nIn the light of the above statements, choose the most appropriate answer from the options given below :","o":["(A) is correct but (R) is not correct","Both (A) and (R) are correct and (R) is the correct explanation of (A)","(A) is not correct but (R) is correct","Both (A) and (R) are correct but (R) is not the correct explanation of (A)"],"c":1,"s":"The metal body of the aircraft is a closed conductor, so it works as an electrostatic shield.\nThe field inside the cavity enclosed by a conductor is zero (charge and fields stay on the outer surface), so (R) is true.\nBecause of this, the people inside feel no field when lightning strikes the body: (R) is exactly why (A) is true.\nBoth are correct and (R) explains (A)."},
{"y":"JEE Main 2023 · 12 Apr · Shift 1","tp":"efl","st":"Statements, matching and subjective","q":"Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R.\nAssertion A : If an electric dipole of dipole moment 30 × 10⁻⁵ C m is enclosed by a closed surface, the net flux coming out of the surface will be zero.\nReason R : Electric dipole consists of two equal and opposite charges.\nIn the light of above statements, choose the correct answer from the options given below.","o":["A is false but R is true.","A is true but R is false.","Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is NOT the correct explanation of A."],"c":2,"s":"A dipole is made of +q and −q, so R is true.\nThe net charge inside the closed surface is q + (−q) = 0.\nBy Gauss's law the net flux through the surface is (net charge)/ε₀ = 0, so A is true. The value of the dipole moment does not matter.\nA is true because the two charges are equal and opposite, so R explains A."},
{"y":"JEE Main 2022 · 28 Jun · Shift 1","tp":"efl","st":"Statements, matching and subjective","q":"Given below are two statements :\nStatement-I : A point charge is brought in an electric field. At a point near to the charge, the field may increase if the charge is positive.\nStatement-II : An electric dipole is placed in a non-uniform electric field. The net electric force on the dipole will not be zero.\nChoose the correct answer from the options given below.","o":["Both statement-I and statement-II are true.","Both statement-I and statement-II are false.","Statement-I is true but statement-II is false.","Statement-I is false but statement-II is true."],"c":0,"s":"Statement I: the resultant field is the vector sum of the original field and the field of the new charge. Near a positive charge, at points where the two fields point the same way, the total field is larger. So it may increase: true.\nStatement II: in a non-uniform field the two charges of the dipole feel different fields, so the forces +qE₁ and −qE₂ do not cancel. The net force is not zero: true.\nBoth statements are true."},
{"y":"JEE Main 2021 · 26 Feb · Shift 2","tp":"egs","st":"Statements, matching and subjective","q":"Given below are two statements:\nStatement I : An electric dipole is placed at the centre of a hollow sphere. The flux of electric field through the sphere is zero but the electric field is not zero anywhere in the sphere.\nStatement II : If R is the radius of a solid metallic sphere and Q be the total charge on it. The electric field at any point on the spherical surface of radius r (< R) is zero but the electric flux passing through this closed spherical surface of radius r is not zero.\nIn the light of above statements, choose the correct answer from the options given below.","o":["Both Statement I and Statement II are true.","Statement I is true but Statement II is false.","Both Statement I and Statement II are false.","Statement I is false but Statement II is true."],"c":1,"s":"Statement I: the dipole has zero net charge, so the net flux through the sphere is zero. Its field is not zero at points around it (it only cancels in the net flux). True.\nStatement II: inside a solid metallic sphere the field is zero everywhere. Flux = ∮E·dA = 0 for a surface of radius r < R (also no charge inside it). So the flux is zero, not non-zero. False.\nStatement I is true but Statement II is false."},
{"y":"IIT-JEE 1982","tp":"efl","st":"Statements, matching and subjective","q":"A thin fixed ring of radius 1 metre has a positive charge 1 × 10⁻⁵ coulomb uniformly distributed over it. A particle of mass 0.9 g and having a negative charge of 1 × 10⁻⁶ coulomb is placed on the axis at a distance of 1 cm from the centre of the ring. Show that the motion of the negatively charged particle is approximately simple harmonic. Calculate the time period of oscillations.","a":"0.628 s","s":"On the axis at distance x from the centre the ring's field is E = Qx/(4πε₀(R² + x²)^(3/2)), directed away from the centre.\nFor x << R (x = 1 cm, R = 1 m): E ≈ Qx/(4πε₀R³).\nThe force on the negative charge −q is towards the centre: F = −qQx/(4πε₀R³) = −κx. A force proportional to displacement and opposite to it means (approximately) simple harmonic motion.\nκ = qQ/(4πε₀R³) = 9 × 10⁹ × 10⁻⁵ × 10⁻⁶/1 = 0.09 N/m.\nT = 2π√(m/κ) = 2π√(0.9 × 10⁻³/0.09) = 2π × 0.1 = 0.628 s."},
{"y":"IIT-JEE 1979","tp":"efl","st":"Statements, matching and subjective","q":"A charged particle is free to move in an electric field. Will it always move along an electric line of force?","o":["Yes","No"],"c":1,"s":"The force on the charge is along the tangent to the line of force at each point, so it starts moving along the line.\nBut the velocity does not follow the force instantly: the particle's inertia carries it along its present direction.\nIf the line of force is curved, the particle leaves the line (it needs a sideways force to turn, and the field gives only a force along the tangent).\nIt follows a line of force only when the line is straight (or the field is uniform) and it starts from rest. So the answer is No."},
{"y":"IIT-JEE 1979","tp":"efl","st":"Statements, matching and subjective","q":"A pendulum bob of mass 80 mg and carrying a charge of 2 × 10⁻⁸ coulomb is at rest in a horizontal uniform electric field of 20,000 volt/metre. Find the tension in the thread of the pendulum and the angle it makes with the vertical. (Take g = 9.8 ms⁻²)","a":"T ≈ 8.8 × 10⁻⁴ N (≈ 9 × 10⁻⁴ N); angle with the vertical θ = tan⁻¹(0.51) ≈ 27°","s":"Three forces act on the bob: weight mg down, electric force qE horizontal, and tension T along the thread.\nmg = 80 × 10⁻⁶ × 9.8 = 7.84 × 10⁻⁴ N and qE = 2 × 10⁻⁸ × 2 × 10⁴ = 4 × 10⁻⁴ N.\nAt rest, T balances the resultant: T = √((mg)² + (qE)²) = √(61.5 + 16) × 10⁻⁴ ≈ 8.8 × 10⁻⁴ N ≈ 9 × 10⁻⁴ N.\nAngle with the vertical: tan θ = qE/mg = 4/7.84 ≈ 0.51, so θ ≈ 27°."},
{"y":"IIT-JEE 1988","tp":"efl","st":"Statements, matching and subjective","q":"A ring of radius R carries a uniformly distributed charge +Q. A point charge −q is placed on the axis of the ring at a distance 2R from the centre of the ring and released from rest. The particle executes a simple harmonic motion along the axis of the ring.","o":["True","False"],"c":1,"s":"Simple harmonic motion needs a restoring force proportional to the displacement from the centre.\nOn the axis, F = qQx/(4πε₀(R² + x²)^(3/2)) towards the centre. This is proportional to x only when x << R.\nHere the particle starts at x = 2R, which is not small compared with R, so F is not proportional to x.\nThe particle does oscillate through the centre, but the motion is not simple harmonic. The statement is false."},
{"y":"IIT-JEE 1988","tp":"efl","st":"Statements, matching and subjective","q":"An electric line of force in the x-y plane is given by the equation x² + y² = 1. A particle with unit positive charge, initially at rest at the point x = 1, y = 0 in the x-y plane, will move along the circular line of force.","o":["True","False"],"c":1,"s":"A positive charge released from rest at (1, 0) feels a force along the tangent to the circle, so it starts moving along the tangent.\nTo keep moving round the circle it would need a force towards the centre, but the field is tangent to the circle everywhere and supplies none. Because of its inertia the particle leaves the circle and moves away along a (curved) path outside the line of force.\nA charged particle follows a line of force only when the line is straight. The statement is false."},
{"y":"IIT-JEE 1983","tp":"ecn","st":"Statements, matching and subjective","q":"A small metal ball is suspended in a uniform electric field with the help of an insulated thread. If high energy X-ray beam falls on the ball, the ball will be deflected in the direction of the field.","o":["True","False"],"c":0,"s":"High-energy X-rays knock electrons out of the metal (photoelectric emission).\nThe ball loses electrons, so it becomes positively charged.\nA positive charge feels a force along the electric field, so the ball is deflected in the direction of the field. The statement is true."},
{"y":"JEE Main 2025 · 2 Apr · Shift 2","tp":"evp","st":"Field-potential relation and equipotentials","q":"Two large plane parallel conducting plates are kept 10 cm apart as shown in figure. The potential difference between them is V. The potential difference between the points A and B (shown in the figure) is","fig":{"w":340,"h":185,"alt":"Two parallel vertical plates 10 cm apart. Point A is 3 cm above C, B is 4 cm to the right of C, and AB is 5 cm","d":[["l",60,26,60,150,"B"],["l",280,26,280,150,"B"],["l",130,64,130,130,"d"],["l",130,130,218,130],["l",130,64,218,130,"d"],["l",130,118,142,118],["l",142,118,142,130],["t",134,60,"A"],["t",130,146,"C","ms"],["t",218,146,"B","ms"],["t",122,100,"3 cm","es"],["t",174,146,"4 cm","ms"],["t",186,92,"5 cm","s"],["l",60,166,280,166,"b"],["t",170,180,"10 cm","ms"]]},"o":["{1;4}V","1 V","{2;5}V","{3;4}V"],"c":2,"s":"Between the plates the field is uniform and horizontal: E = V/d = V/(10 cm).\nA and C lie on the same vertical line, so they are at the same potential (equipotential, perpendicular to the field).\nSo the potential difference between A and B equals that between C and B, which are 4 cm apart along the field.\nΔV = E × 4 cm = (V/10) × 4 = 2V/5."},
{"y":"JEE Main 2025 · 3 Apr · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"The electrostatic potential on the surface of uniformly charged spherical shell of radius R = 10 cm is 120 V. The potential at the centre of shell, at a distance r = 5 cm from centre, and at a distance r = 15 cm from the centre of the shell respectively, are","o":["120 V, 120 V, 80 V","40 V, 40 V, 80 V","0 V, 120 V, 40 V","0 V, 0 V, 80 V"],"c":0,"s":"Inside a uniformly charged shell the field is zero, so the potential is constant and equals the surface value: 120 V at the centre and at r = 5 cm.\nOutside, V = kQ/r ∝ 1/r. On the surface (r = 10 cm) V = 120 V.\nAt r = 15 cm: V = 120 × (10/15) = 80 V.\nAnswer: 120 V, 120 V, 80 V."},
{"y":"JEE Main 2025 · 7 Apr · Shift 1","tp":"evp","st":"Potential energy and work","q":"Two charges q₁ and q₂ are separated by a distance of 30 cm. A third charge q₃ initially at 'C' as shown in the figure, is moved along the circular path of radius 40 cm from C to D. If the difference in potential energy due to movement of q₃ from C to D is given by {q₃K;4πε₀}, the value of K is","fig":{"w":340,"h":205,"alt":"q1 at A, q2 at B on a horizontal line with AB = 30 cm; q3 moves along a quarter circle of radius 40 cm centred at A from C (directly above A) to D (on the line AB, 40 cm from A)","d":[["l",60,160,60,20],["l",60,160,200,160],["p","M60 20 A140 140 0 0 1 200 160","d"],["c",60,160,3,"F"],["c",165,160,3,"F"],["c",60,20,4,"F"],["c",200,160,2,"F"],["t",54,150,"q₁","es"],["t",165,150,"q₂","ms"],["t",68,18,"q₃"],["t",52,24,"C","es"],["t",60,174,"A","ms"],["t",165,174,"B","ms"],["t",200,174,"D","ms"],["t",52,92,"40 cm","es"],["l",60,186,165,186,"b"],["t",112,200,"30 cm","ms"]]},"o":["6q₁","6q₂","8q₁","8q₂"],"c":3,"s":"The circle is centred on q₁ (radius AC = AD = 40 cm), so q₁ is at the same distance 0.4 m from C and from D: its contribution to the potential energy does not change.\nOnly q₂ matters. Distance from q₂ to C: √(0.3² + 0.4²) = 0.5 m. Distance from q₂ to D: 0.4 − 0.3 = 0.1 m.\nΔU = U_D − U_C = (q₃q₂/4πε₀)(1/0.1 − 1/0.5) = (q₃q₂/4πε₀)(10 − 2) = q₃(8q₂)/(4πε₀).\nSo K = 8q₂."},
{"y":"JEE Main 2025 · 7 Apr · Shift 2","tp":"efl","st":"Electric dipole","q":"A dipole with two electric charges of 2 μC magnitude each, with separation distance 0.5 μm, is placed between the plates of a capacitor such that its axis is parallel to an electric field established between the plates when a potential difference of 5 V is applied. Separation between the plates is 0.5 mm. If the dipole is rotated by 30° from the axis, it tends to realign in the direction due to torque. The value of torque is","o":["5 × 10⁻³ Nm","2.5 × 10⁻⁹ Nm","2.5 × 10⁻¹² Nm","5 × 10⁻⁹ Nm"],"c":3,"s":"Field between the plates: E = V/d = 5/(0.5 × 10⁻³) = 10⁴ V/m.\nDipole moment: p = q × l = 2 × 10⁻⁶ × 0.5 × 10⁻⁶ = 10⁻¹² C m.\nTorque: τ = pE sin θ = 10⁻¹² × 10⁴ × sin 30° = 10⁻⁸ × 0.5 = 5 × 10⁻⁹ N m."},
{"y":"JEE Main 2025 · 22 Jan · Shift 2","tp":"efl","st":"Electric dipole","q":"For a short dipole placed at origin O, the dipole moment p⃗ is along x-axis, as shown in the figure. If the electric potential and electric field at A are V₀ and E₀, respectively, then the correct combination of the electric potential and electric field, respectively, at point B on the y-axis is given by","fig":{"w":340,"h":190,"alt":"Short dipole at the origin along +x; point A on the x-axis at distance r and point B on the y-axis at distance 2r","d":[["l",80,150,310,150,"a"],["l",80,150,80,14,"a"],["t",314,154,"x"],["t",86,16,"y"],["l",84,138,114,138,"a"],["t",99,130,"p","ms"],["t",68,166,"O","es"],["c",135,150,3,"F"],["t",135,166,"A","ms"],["c",80,40,3,"F"],["t",88,44,"B"],["l",80,160,135,160,"b"],["t",107,176,"r","ms"],["l",62,150,62,40,"b"],["t",56,98,"2r","es"]]},"o":["zero and {E₀;16}","{V₀;2} and {E₀;16}","zero and {E₀;8}","V₀ and {E₀;4}"],"c":0,"s":"At A (on the axis, distance r): V₀ = kp/r² and E₀ = 2kp/r³, where k = 1/4πε₀.\nB is on the perpendicular bisector (equatorial line) of the dipole, at distance 2r. There the potential is zero.\nThe equatorial field is E = kp/(2r)³ = kp/(8r³).\nSince kp/r³ = E₀/2, E = (1/8)(E₀/2) = E₀/16.\nSo the potential is zero and the field is E₀/16."},
{"y":"JEE Main 2025 · 22 Jan · Shift 2","tp":"evp","st":"Potential energy and work","q":"Two charges 7 μC and −4 μC are placed at (−7 cm, 0, 0) and (7 cm, 0, 0) respectively. Given, ε₀ = 8.85 × 10⁻¹² C² N⁻¹ m⁻², the electrostatic potential energy of the charge configuration is","o":["−1.2 J","−1.8 J","−1.5 J","−2.0 J"],"c":1,"s":"Distance between the charges: r = 7 + 7 = 14 cm = 0.14 m.\nU = q₁q₂/(4πε₀r) with 1/(4πε₀) ≈ 9 × 10⁹ N m²/C².\nU = 9 × 10⁹ × (7 × 10⁻⁶)(−4 × 10⁻⁶)/0.14 = −9 × 10⁹ × 28 × 10⁻¹²/0.14 = −0.252/0.14 = −1.8 J."},
{"y":"JEE Main 2025 · 23 Jan · Shift 2","tp":"evp","st":"Potential energy and work","q":"Two point charges −4 μC and 4 μC, constituting an electric dipole, are placed at (−9, 0, 0) cm and (9, 0, 0) cm in a uniform electric field of strength 10⁴ NC⁻¹. The work done on the dipole in rotating it from the equilibrium through 180° is","o":["16.4 mJ","12.4 mJ","18.4 mJ","14.4 mJ"],"c":3,"s":"Dipole moment: p = q × (separation) = 4 × 10⁻⁶ × 0.18 = 7.2 × 10⁻⁷ C m.\nPotential energy U = −pE cos θ. At stable equilibrium (θ = 0) U = −pE; after rotating by 180° U = +pE.\nWork done = change in U = 2pE = 2 × 7.2 × 10⁻⁷ × 10⁴ = 1.44 × 10⁻² J = 14.4 mJ."},
{"y":"JEE Main 2025 · 24 Jan · Shift 2","tp":"evp","st":"Potential energy and work","q":"In the first configuration (1) as shown in the figure, four identical charges (q₀) are kept at the corners A, B, C and D of square of side length 'a'. In the second configuration (2), the same charges are shifted to mid points G, E, H and F, of the square. If K = {1;4πε₀}, the difference between the potential energies of configuration (2) and (1) is given by:","fig":{"w":340,"h":160,"alt":"Two squares: in configuration 1 the four charges +q0 sit at the corners A, B, C, D; in configuration 2 they sit at the mid-points G, E, H, F of the sides","d":[["r",40,34,80,80],["r",210,34,80,80],["c",40,34,3.5,"F"],["t",35,28,"A +q₀","es"],["c",120,34,3.5,"F"],["t",125,28,"B +q₀","s"],["c",120,114,3.5,"F"],["t",125,128,"C +q₀","s"],["c",40,114,3.5,"F"],["t",35,128,"D +q₀","es"],["c",80,34,1.6],["c",120,74,1.6],["c",80,114,1.6],["c",40,74,1.6],["t",80,49,"G","ms"],["t",114,78,"E","es"],["t",80,108,"H","ms"],["t",46,78,"F","s"],["c",80,74,1.6,"F"],["t",84,70,"O","s"],["t",205,28,"A","es"],["t",295,28,"B","s"],["t",295,128,"C","s"],["t",205,128,"D","es"],["c",250,34,3.5,"F"],["t",250,26,"G +q₀","ms"],["c",290,74,3.5,"F"],["t",298,78,"E +q₀","s"],["c",250,114,3.5,"F"],["t",250,128,"H +q₀","ms"],["c",210,74,3.5,"F"],["t",202,78,"F +q₀","es"],["c",250,74,1.6,"F"],["t",254,70,"O","s"],["t",80,152,"Configuration (1)","ms"],["t",250,152,"Configuration (2)","ms"]]},"o":["{Kq₀²;a}(4√2 − 2)","{Kq₀²;a}(3 − √2)","{Kq₀²;a}(3√2 − 2)","{Kq₀²;a}(4 − 2√2)"],"c":2,"s":"Potential energy = sum of Kq₀²/distance over all 6 pairs.\nConfiguration 1 (corners): 4 sides of length a and 2 diagonals of length √2a: U₁ = (Kq₀²/a)(4 + 2/√2) = (Kq₀²/a)(4 + √2).\nConfiguration 2 (mid-points): 4 neighbouring pairs a/√2 apart and 2 opposite pairs a apart: U₂ = (Kq₀²/a)(4√2 + 2).\nU₂ − U₁ = (Kq₀²/a)(4√2 + 2 − 4 − √2) = (Kq₀²/a)(3√2 − 2)."},
{"y":"JEE Main 2025 · 28 Jan · Shift 1","tp":"evp","st":"Field-potential relation and equipotentials","q":"Three infinitely long wires with linear charge density λ are placed along the x-axis, y-axis and z-axis respectively. Which of the following denotes an equipotential surface?","o":["(x² + y²)(y² + z²)(z² + x²) = constant","xy + yz + zx = constant","(x + y)(y + z)(z + x) = constant","xyz = constant"],"c":0,"s":"Potential of a long line charge at perpendicular distance s: V = −(λ/2πε₀) ln s + constant.\nThe distances of the point (x, y, z) from the x, y and z axes are √(y² + z²), √(z² + x²) and √(x² + y²).\nAdd the three potentials: V = −(λ/4πε₀) ln[(y² + z²)(z² + x²)(x² + y²)] + constant.\nV is constant when (x² + y²)(y² + z²)(z² + x²) = constant."},
{"y":"JEE Main 2025 · 29 Jan · Shift 2","tp":"efl","st":"Electric dipole","q":"An electric dipole is placed at a distance of 2 cm from an infinite plane sheet having positive charge density σ₀. Choose the correct option from the following.","fig":{"w":340,"h":150,"alt":"Vertical positively charged sheet at the left; a dipole with -q nearer the sheet and +q farther, lying along the line perpendicular to the sheet, 2 cm away","d":[["l",60,20,60,130,"B"],["t",48,32,"+","ms"],["t",48,52,"+","ms"],["t",48,72,"+","ms"],["t",48,92,"+","ms"],["t",48,112,"+","ms"],["t",60,144,"σ₀","ms"],["c",200,75,3,"F"],["c",270,75,3,"F"],["l",200,75,270,75,"d"],["t",200,64,"−q","ms"],["t",270,64,"+q","ms"],["l",60,100,200,100,"b"],["t",130,114,"2 cm","ms"]]},"o":["Potential energy and torque both are maximum.","Torque on dipole is zero and net force acts towards the sheet.","Potential energy of dipole is minimum and torque is zero.","Torque on dipole is zero and net force is directed away from the sheet."],"c":2,"s":"The sheet has positive charge, so its field is uniform and points away from the sheet (along +x).\nThe dipole moment points from −q to +q, which is also away from the sheet: p is parallel to E.\nTorque = p × E = 0, and U = −pE cos 0 = −pE is the minimum value (stable equilibrium).\nThe field is uniform, so the net force is zero. Answer: potential energy is minimum and torque is zero."},
{"y":"JEE Main 2024 · 27 Jan · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"An electric charge 10⁻⁶ μC is placed at origin (0, 0) m of X – Y co-ordinate system. Two points P and Q are situated at (√3, √3) m and (√6, 0) m respectively. The potential difference between the points P and Q will be","o":["√3 V","√6 V","3 V","0 V"],"c":3,"s":"The potential of a point charge depends only on the distance from it: V = kq/r.\nDistance of P: √(3 + 3) = √6 m. Distance of Q: √6 m.\nBoth points are at the same distance, so V_P = V_Q = 9 × 10⁹ × 10⁻¹²/√6 ≈ 3.7 × 10⁻³ V.\nPotential difference = 0 V."},
{"y":"JEE Main 2024 · 30 Jan · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"The electrostatic potential due to an electric dipole at a distance 'r' varies as","o":["{1;r³}","r","{1;r}","{1;r²}"],"c":3,"s":"The two charges of a dipole have opposite signs, so their potentials nearly cancel at a large distance r.\nV = kp cos θ/r², where p is the dipole moment.\nSo V ∝ 1/r². (The field varies as 1/r³.)"},
{"y":"JEE Main 2023 · 6 Apr · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"For a uniformly charged thin spherical shell, the electric potential (V) radially away from the centre (O) of shell can be graphically represented as","fig":{"w":340,"h":215,"alt":"Four V versus r graphs: (a) curve rising to a peak at r = R then falling linearly; (b) linear rise to R then falling hyperbola; (c) constant up to R then falling hyperbola; (d) constant up to R then falling straight line","d":[["l",25,85,160,85,"a"],["l",25,85,25,21,"a"],["t",21,25,"V","es"],["t",163,89,"r","s"],["t",95,97,"R","ms"],["l",95,85,95,29,"d"],["t",129,31,"(a)","ms"],["p","M25 79 Q75 77 95 30"],["l",95,30,150,81],["l",200,85,335,85,"a"],["l",200,85,200,21,"a"],["t",196,25,"V","es"],["t",338,89,"r","s"],["t",270,97,"R","ms"],["l",270,85,270,29,"d"],["t",304,31,"(b)","ms"],["l",200,85,270,30],["p","M270 30 Q285 65 330 75"],["l",25,190,160,190,"a"],["l",25,190,25,126,"a"],["t",21,130,"V","es"],["t",163,194,"r","s"],["t",95,202,"R","ms"],["l",95,190,95,134,"d"],["t",129,136,"(c)","ms"],["l",25,145,95,145],["p","M95 145 Q110 170 155 180"],["l",200,190,335,190,"a"],["l",200,190,200,126,"a"],["t",196,130,"V","es"],["t",338,194,"r","s"],["t",270,202,"R","ms"],["l",270,190,270,134,"d"],["t",304,136,"(d)","ms"],["l",200,145,270,145],["l",270,145,330,184]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":2,"s":"Inside a uniformly charged shell the field is zero, so V is constant (equal to its surface value kQ/R) for r ≤ R.\nOutside, V = kQ/r: it falls as 1/r, a curve (hyperbola) that starts at kQ/R at r = R without a jump.\nSo the graph is flat up to r = R and then a falling 1/r curve: graph (c). (Graph (d) has a straight line, which is wrong.)"},
{"y":"JEE Main 2023 · 8 Apr · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"Electric potential at a point 'P' due to a point charge of 5 × 10⁻⁹ C is 50 V. The distance of 'P' from the point charge is (Assume {1;4πε₀} = 9 × 10⁹ N m² C⁻²)","o":["3 cm","0.9 cm","9 cm","90 cm"],"c":3,"s":"V = (1/4πε₀) q/r, so r = (1/4πε₀) q/V.\nr = 9 × 10⁹ × 5 × 10⁻⁹/50 = 45/50 = 0.9 m = 90 cm."},
{"y":"JEE Main 2023 · 24 Jan · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"The electric potential at the centre of two concentric half rings of radii R₁ and R₂, having same linear charge density λ is","fig":{"w":340,"h":180,"alt":"Two concentric half rings of radii R1 and R2, both carrying uniform positive charge density λ, with the centre O at the middle of their straight edge","d":[["p","M60 150 A110 110 0 0 1 280 150"],["p","M100 150 A70 70 0 0 1 240 150"],["c",170,150,2,"F"],["t",176,166,"O","s"],["t",289.2,133,"+","ms"],["t",262.7,76.2,"+","ms"],["t",211.4,40.3,"+","ms"],["t",149,34.8,"+","ms"],["t",92.2,61.3,"+","ms"],["t",56.3,112.6,"+","ms"],["t",49.5,143.5,"+","ms"],["t",249.2,137.2,"+","ms"],["t",227.3,96.7,"+","ms"],["t",184.1,74.2,"+","ms"],["t",142.3,77.9,"+","ms"],["t",99.9,113.5,"+","ms"],["t",90.2,139.9,"+","ms"],["l",170,150,225,54.7],["l",170,150,205,89.4],["t",206,114,"R₁","s"],["t",222,78,"R₂","s"],["t",170,28,"+λ","ms"],["t",170,64,"+λ","ms"]]},"o":["{2λ;ε₀}","{λ;2ε₀}","{λ;4ε₀}","{λ;ε₀}"],"c":1,"s":"Potential at O is the sum over all charge elements: V = Σ k dq/r.\nEvery element of a half ring of radius R is at distance R from O, so V = k(total charge)/R.\nFor ring 1: charge λπR₁, so V₁ = kλπR₁/R₁ = kλπ = λ/(4ε₀). Likewise V₂ = λ/(4ε₀).\nV = V₁ + V₂ = λ/(4ε₀) + λ/(4ε₀) = λ/(2ε₀)."},
{"y":"JEE Main 2023 · 31 Jan · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"Which of the following correctly represents the variation of electric potential (V) of a charged spherical conductor of radius (R) with radial distance (r) from the center?","fig":{"w":340,"h":215,"alt":"Four V versus r graphs: (a) linear rise to R then falling curve; (b) single falling curve from r = 0; (c) zero up to R then a jump and falling curve; (d) constant up to R then falling curve","d":[["l",25,85,160,85,"a"],["l",25,85,25,21,"a"],["t",21,25,"V","es"],["t",163,89,"r","s"],["t",95,97,"R","ms"],["l",95,85,95,29,"d"],["t",129,31,"(a)","ms"],["l",25,85,95,30],["p","M95 30 Q110 65 155 75"],["l",200,85,335,85,"a"],["l",200,85,200,21,"a"],["t",196,25,"V","es"],["t",338,89,"r","s"],["t",270,97,"R","ms"],["l",270,85,270,29,"d"],["t",304,31,"(b)","ms"],["p","M204 27 Q225 71 330 79"],["l",25,190,160,190,"a"],["l",25,190,25,126,"a"],["t",21,130,"V","es"],["t",163,194,"r","s"],["t",95,202,"R","ms"],["l",95,190,95,134,"d"],["t",129,136,"(c)","ms"],["l",95,190,95,142],["p","M95 142 Q110 170 155 180"],["l",200,190,335,190,"a"],["l",200,190,200,126,"a"],["t",196,130,"V","es"],["t",338,194,"r","s"],["t",270,202,"R","ms"],["l",270,190,270,134,"d"],["t",304,136,"(d)","ms"],["l",200,145,270,145],["p","M270 145 Q285 170 330 180"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":3,"s":"A charged conductor is an equipotential: the field inside is zero, so V is constant for r ≤ R.\nOutside, V = kQ/r falls smoothly as 1/r and meets the constant value kQ/R at r = R (potential is continuous).\nSo V is flat up to R and then decays like 1/r: graph (d)."},
{"y":"JEE Main 2023 · 31 Jan · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"Considering a group of positive charges, which of the following statements is correct ?","o":["Net potential of the system cannot be zero at a point but net electric field can be zero at that point.","Net potential of the system at a point can be zero but net electric field can't be zero at that point.","Both the net potential and the net electric field cannot be zero at a point.","Both the net potential and the net field can be zero at a point."],"c":0,"s":"Potential is a scalar: every positive charge adds a positive term kq/r, so the sum can never be zero.\nElectric field is a vector: fields of different charges can point in opposite directions and cancel (for example at the midpoint of two equal positive charges).\nSo the net potential cannot be zero, but the net field can be zero."},
{"y":"JEE Advanced 2023","tp":"evp","st":"Potential of charges and distributions","q":"An electric dipole is formed by two charges +q and −q located in xy-plane at (0, 2) mm and (0, −2) mm, respectively, as shown in the figure. The electric potential at point P (100, 100) mm due to the dipole is V₀. The charges +q and −q are then moved to the points (−1, 2) mm and (1, −2) mm, respectively. What is the value of electric potential at P due to the new dipole?","fig":{"w":340,"h":195,"alt":"Original dipole with +q at (0, 2) mm and -q at (0, -2) mm; moved charges +q at (-1, 2) mm and -q at (1, -2) mm; point P far away at (100, 100) mm","d":[["l",110,120,300,120,"a"],["l",110,170,110,12,"a"],["t",304,124,"x"],["t",116,16,"y"],["l",110,120,270,30,"d"],["c",270,30,3,"F"],["t",264,24,"P (100, 100) mm","es"],["c",110,96,3,"F"],["c",110,144,3,"F"],["c",98,96,3],["c",122,144,3],["t",92,86,"+q (−1, 2) mm","es"],["t",116,90,"+q (0, 2) mm","s"],["t",104,160,"−q (0, −2) mm","es"],["t",128,160,"−q (1, −2) mm","s"],["t",170,188,"filled: original charges; open: moved charges","ms"]]},"o":["V₀/4","V₀/2","V₀/√2","3V₀/4"],"c":1,"s":"P is far from the charges (about 141 mm away, the charges are only a few mm apart), so use the dipole formula V = k p⃗·r̂/r², with r̂ = (î + ĵ)/√2.\nOriginal dipole: p = q(0, 4) mm (from −q to +q), so p·r̂ = 4q/√2 (mm units) and V₀ = k(4q/√2)/r².\nNew dipole: p′ = q[(−1 − 1), (2 − (−2))] mm = q(−2, 4) mm, so p′·r̂ = q(−2 + 4)/√2 = 2q/√2.\nThe distance is the same, so V = V₀ × (2/4) = V₀/2."},
{"y":"JEE Main 2022 · 26 Jul · Shift 2","tp":"ecn","st":"Charge sharing and earthing","q":"Two uniformly charged spherical conductors A and B of radii 5 mm and 10 mm are separated by a distance of 2 cm. If the spheres are connected by a conducting wire, then in equilibrium condition, the ratio of the magnitudes of the electric fields at the surface of the sphere A and B will be","o":["1 : 2","2 : 1","1 : 1","1 : 4"],"c":1,"s":"Joined by a wire, the two spheres reach the same potential V.\nFor a sphere, V = kq/R and the surface field is E = kq/R² = V/R.\nSo E_A/E_B = (V/R_A)/(V/R_B) = R_B/R_A = 10/5 = 2.\nThe ratio is 2 : 1."},
{"y":"JEE Main 2022 · 26 Jun · Shift 2","tp":"ecn","st":"Charge sharing and earthing","q":"Sixty four conducting drops each of radius 0.02 m and each carrying a charge of 5 μC are combined to form a bigger drop. The ratio of surface density of bigger drop to the smaller drop will be","o":["1 : 4","4 : 1","1 : 8","8 : 1"],"c":1,"s":"Volume is conserved: 64 × (4/3)πr³ = (4/3)πR³, so R = 4r = 0.08 m.\nCharge adds up: Q = 64q.\nSurface density σ = charge/(4π × radius²).\nσ_big/σ_small = (64q/R²)/(q/r²) = 64 × (r/R)² = 64/16 = 4.\nThe ratio is 4 : 1."},
{"y":"JEE Main 2022 · 29 Jun · Shift 2","tp":"evp","st":"Field-potential relation and equipotentials","q":"If the electric potential at any point (x, y, z) m in space is given by V = 3x² volt. The electric field at the point (1, 0, 3) m will be","o":["3 V m⁻¹, directed along positive x-axis","3 V m⁻¹, directed along negative x-axis","6 V m⁻¹, directed along positive x-axis","6 V m⁻¹, directed along negative x-axis"],"c":3,"s":"E = −∇V, so Eₓ = −∂V/∂x = −6x, and E_y = E_z = 0.\nAt x = 1: Eₓ = −6 V/m.\nThe magnitude is 6 V m⁻¹ and the minus sign means it points along the negative x-axis."},
{"y":"JEE Main 2021 · 26 Aug · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"The two thin coaxial rings, each of radius a and having charges +Q and −Q respectively are separated by a distance of s. The potential difference between the centres of the two rings is","o":["{Q;2πε₀}[{1;a} − {1;√(s²+a²)}]","{Q;4πε₀}[{1;a} − {1;√(s²+a²)}]","{Q;4πε₀}[{1;a} + {1;√(s²+a²)}]","{Q;2πε₀}[{1;a} + {1;√(s²+a²)}]"],"c":0,"s":"Every point of a ring of radius a is at distance a from its own centre, and √(s² + a²) from the other ring's centre.\nCentre of ring 1 (+Q): V₁ = kQ/a − kQ/√(s²+a²).\nCentre of ring 2 (−Q): V₂ = −kQ/a + kQ/√(s²+a²) = −V₁.\nV₁ − V₂ = 2kQ[1/a − 1/√(s²+a²)] = (Q/2πε₀)[1/a − 1/√(s²+a²)]."},
{"y":"JEE Main 2020 · 2 Sep · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"A charge Q is distributed over two concentric conducting thin spherical shells radii r and R (R > r). If the surface charge densities on the two shells are equal, the electric potential at the common centre is","o":["{1;4πε₀}{(R+r);2(R²+r²)}Q","{1;4πε₀}{(R+r);(R²+r²)}Q","{1;4πε₀}{(2R+r);(R²+r²)}Q","{1;4πε₀}{(R+2r);2(R²+r²)}Q"],"c":1,"s":"Let the common surface density be σ. Charges: q_r = 4πr²σ and q_R = 4πR²σ, so Q = 4πσ(r² + R²) and 4πσ = Q/(R² + r²).\nPotential at the centre = sum of the shell potentials (each shell's potential inside equals kq/radius):\nV = k[4πr²σ/r + 4πR²σ/R] = k·4πσ(r + R) = (1/4πε₀) Q(R + r)/(R² + r²)."},
{"y":"JEE Main 2020 · 3 Sep · Shift 1","tp":"ecn","st":"Charge sharing and earthing","q":"Two isolated conducting spheres S₁ and S₂ of radius {2;3}R and {1;3}R have 12 μC and −3 μC charges, respectively and are at a large distance from each other. They are now connected by a conducting wire. A long time after this is done, the charges on S₁ and S₂ are respectively","o":["4.5 μC on both","4.5 μC and −4.5 μC","3 μC and 6 μC","6 μC and 3 μC"],"c":3,"s":"Total charge is conserved: 12 + (−3) = 9 μC.\nAfter joining, both spheres have the same potential: kq₁/r₁ = kq₂/r₂, so q₁/q₂ = r₁/r₂ = (2R/3)/(R/3) = 2.\nq₁ + q₂ = 9 μC with q₁ = 2q₂ gives q₂ = 3 μC and q₁ = 6 μC."},
{"y":"JEE Main 2020 · 3 Sep · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"Consider a metallic hollow spheres of radii R and 4R hold charges Q₁ and Q₂ respectively. Given that surface charge density of the concentric spheres are equal, the potential difference V(R) − V(4R) is","o":["{3Q₁;16πε₀R}","{3Q₂;4πε₀R}","{Q₂;4πε₀R}","{3Q₁;4πε₀R}"],"c":0,"s":"Equal surface densities: Q₁/(4πR²) = Q₂/(4π(4R)²), so Q₂ = 16Q₁.\nV(R) = k(Q₁/R + Q₂/4R) and V(4R) = k(Q₁ + Q₂)/4R (outside the inner shell the field is that of Q₁ alone).\nV(R) − V(4R) = kQ₁(1/R − 1/4R) = 3kQ₁/(4R) = 3Q₁/(16πε₀R)."},
{"y":"JEE Main 2020 · 3 Sep · Shift 2","tp":"evp","st":"Potential energy and work","q":"Hydrogen ion and singly ionized helium atom are accelerated, from rest, through the same potential difference. The ratio of final speeds of hydrogen and helium ions is close to","o":["1 : 2","10 : 7","2 : 1","5 : 7"],"c":2,"s":"A charge q accelerated through a potential difference V gains kinetic energy qV: ½mv² = qV.\nSo v = √(2qV/m).\nBoth ions carry the same charge e, and a helium atom has about 4 times the mass of a hydrogen atom.\nv(H)/v(He) = √(m(He)/m(H)) = √4 = 2.\nThe ratio is 2 : 1, option (c)."},
{"y":"JEE Main 2020 · 4 Sep · Shift 1","tp":"evp","st":"Potential energy and work","q":"A two point charges 4q and −q are fixed on the x-axis at x = −{d;2} and x = {d;2}, respectively. If a third point charge 'q' is taken from the origin to x = d along the semicircle as shown in the figure, the energy of the charge will","fig":{"w":340,"h":150,"alt":"Charge 4q at x = -d/2, the origin O, charge -q at x = d/2 on the x-axis, and a semicircle from the origin to x = d above the axis","d":[["l",20,110,320,110,"a"],["l",140,110,140,30,"d"],["c",80,110,4,"F"],["c",200,110,4,"F"],["l",260,106,260,114],["p","M140 110 A60 60 0 0 1 260 110","a"],["t",80,128,"4q","m"],["t",140,128,"O","m"],["t",200,128,"−q","m"],["t",260,128,"x = d","m"],["t",318,104,"x","e"]]},"o":["increase by {3q²;4πε₀d}","decrease by {q²;4πε₀d}","decrease by {4q²;3πε₀d}","increase by {2q²;3πε₀d}"],"c":2,"s":"The change in the energy of the charge q depends only on the end points: ΔU = q(V_end − V_start).\nAt the origin: V₁ = k(4q/(d/2) − q/(d/2)) = 6kq/d.\nAt x = d: the distances are 3d/2 from 4q and d/2 from −q, so V₂ = k(8q/(3d) − 2q/d) = 2kq/(3d).\nΔU = kq²(2/3 − 6)/d = −16kq²/(3d) = −4q²/(3πε₀d), using k = 1/(4πε₀).\nThe energy decreases by 4q²/(3πε₀d), option (c)."},
{"y":"JEE Main 2020 · 5 Sep · Shift 1","tp":"evp","st":"Potential energy and work","q":"A solid sphere of radius R carries a charge Q + q distributed uniformly over its volume. A very small point like a piece of it of mass m gets detached from the bottom of the sphere and falls down vertically under gravity. This piece carries charge q. If it acquires a speed v when it has fallen through a vertical height y (see figure), then (assume the remaining portion to be spherical)","fig":{"w":340,"h":215,"alt":"A charged sphere of radius R with charge Q; a small piece with charge q at its bottom falls a vertical distance y with speed v","d":[["c",150,70,60],["c",150,70,2,"F"],["l",150,70,192,112],["t",172,84,"R"],["t",132,66,"Q","e"],["l",100,130,200,130,"d"],["c",150,130,3,"F"],["t",158,126,"q"],["l",90,130,90,200,"a"],["l",80,200,200,200,"d"],["t",80,170,"y","e"],["l",150,138,150,196,"a"],["t",158,176,"v"]]},"o":["v² = y[{qQ;4πε₀R²ym} + g]","v² = y[{qQ;4πε₀R(R+y)m} + g]","v² = 2y[{qQR;4πε₀(R+y)³m} + g]","v² = 2y[{qQ;4πε₀R(R+y)m} + g]"],"c":3,"s":"The remaining sphere (charge Q) acts like a point charge Q at its centre. The piece starts at distance R and ends at R + y.\nEnergy conservation: ½mv² = mgy + kQq/R − kQq/(R+y).\nThe last two terms combine to kQq·y/(R(R+y)).\nv² = 2gy + 2qQy/(4πε₀mR(R+y)).\nSo v² = 2y[qQ/(4πε₀R(R+y)m) + g], option (d)."},
{"y":"JEE Main 2020 · 5 Sep · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"Ten charges are placed on the circumference of a circle of radius R with constant angular separation between successive charges. Alternate charges 1, 3, 5, 7, 9 have charge (+q) each, while 2, 4, 6, 8, 10 have charge (−q) each. The potential V and the electric field E at the centre of the circle are respectively\n(Take V = 0 at infinity.)","o":["V = {10q;4πε₀R}; E = 0","V = 0; E = {10q;4πε₀R²}","V = 0; E = 0","V = {10q;4πε₀R}; E = {10q;4πε₀R²}"],"c":2,"s":"Potential is a scalar. Five +q and five −q charges are all at distance R, so V = 5kq/R − 5kq/R = 0.\nThe five +q charges sit at the corners of a regular pentagon (every 72°), so their fields at the centre cancel.\nThe five −q charges also form a regular pentagon, so their fields cancel too.\nHence V = 0 and E = 0, option (c)."},
{"y":"JEE Main 2020 · 6 Sep · Shift 2","tp":"efl","st":"Electric dipole","q":"Two identical electric point dipoles have dipole moments p⃗₁ = pî and p⃗₂ = −pî and are held on the x-axis at distance 'a' from each other. When released, they move along the x-axis with the direction of their dipole moments remaining unchanged. If the mass of each dipole is 'm', their speed when they are infinitely far apart is","o":["{p;a}√{1;πε₀ma}","{p;a}√{1;2πε₀ma}","{p;a}√{2;πε₀ma}","{p;a}√{3;2πε₀ma}"],"c":1,"s":"The field of p⃗₁ on its axis at distance a is E = 2kp/a³ (along +x).\nInteraction energy of p⃗₂ = −pî in it: U = −p⃗₂·E⃗ = +2kp²/a³ (positive, so they repel).\nAt infinity U = 0, so all of it becomes kinetic energy of the two dipoles: 2 × ½mv² = 2kp²/a³.\nv² = 2kp²/(ma³) = p²/(2πε₀ma³), so v = (p/a)√(1/(2πε₀ma)).\nOption (b)."},
{"y":"JEE Main 2020 · 8 Jan · Shift 1","tp":"egs","st":"Gauss's law and symmetric bodies","q":"In finding the electric field using Gauss law the formula |E⃗| = {q(enc);ε₀|A|} is applicable. In the formula ε₀ is permittivity of free space, A is the area of Gaussian surface and q(enc) is charge enclosed by the Gaussian surface. This equation can be used in which of the following situation?","o":["For any choice of Gaussian surface.","Only when the Gaussian surface is an equipotential surface.","Only when the Gaussian surface is an equipotential surface and |E⃗| is constant on the surface.","Only when |E⃗| = constant on the surface."],"c":2,"s":"Gauss's law is ∮E⃗·dA⃗ = q(enc)/ε₀. It reduces to E·A = q(enc)/ε₀ only if E is perpendicular to the surface everywhere and has the same magnitude everywhere on it.\nAn equipotential surface is everywhere perpendicular to the field, which gives the first condition.\nThe magnitude |E⃗| must also be constant on the surface for the second condition.\nBoth are needed, so the answer is (c)."},
{"y":"JEE Main 2020 · 8 Jan · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"Consider two charged metallic spheres S₁ and S₂ of radii R₁ and R₂, respectively. The electric fields E₁ (on S₁) and E₂ (on S₂) on their surfaces are such that E₁/E₂ = R₁/R₂. Then the ratio V₁ (on S₁)/V₂ (on S₂) of the electrostatic potentials on each sphere is","o":["(R₁/R₂)³","(R₂/R₁)","R₁/R₂","(R₁/R₂)²"],"c":3,"s":"For a charged metallic sphere, E = kQ/R² on the surface and V = kQ/R.\nSo V = E·R.\nV₁/V₂ = (E₁R₁)/(E₂R₂) = (E₁/E₂)(R₁/R₂) = (R₁/R₂)(R₁/R₂) = (R₁/R₂)².\nOption (d)."},
{"y":"JEE Main 2020 · 10 Jan · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"A charge Q is distributed over three concentric spherical shells of radii a, b, c (a < b < c) such that their surface charge densities are equal to one another. The total potential at a point at distance r from their common centre, where r < a, would be","o":["{Q;4πε₀(a+b+c)}","{Q;12πε₀}·{ab+bc+ca;abc}","{Q(a+b+c);4πε₀(a²+b²+c²)}","{Q(a²+b²+c²);4πε₀(a³+b³+c³)}"],"c":2,"s":"A point inside all the shells has potential V = k(Q₁/a + Q₂/b + Q₃/c), where each shell has charge 4πσ(radius)².\nSo V = 4πkσ(a + b + c) = σ(a+b+c)/ε₀.\nTotal charge Q = 4πσ(a² + b² + c²), so σ = Q/(4π(a²+b²+c²)).\nV = Q(a+b+c)/(4πε₀(a²+b²+c²)).\nOption (c)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 1","tp":"ecn","st":"Induced charge and shielding","q":"A solid conducting sphere, having a charge Q, is surrounded by an uncharged conducting hollow spherical shell. Let the potential difference between the surface of the solid sphere and that of the outer surface of the hollow shell be V. If the shell is now given a charge of −4Q, the new potential difference between the same two surfaces is","o":["4 V","V","2 V","−2 V"],"c":1,"s":"Let the solid sphere have radius a, and the shell have inner radius b. The shell is a conductor, so its outer surface is at the same potential as its inner surface.\nThe field in the gap a < r < b depends only on the charge Q of the inner sphere: E = kQ/r².\nSo the potential difference is V = kQ(1/a − 1/b), whatever charge the shell carries.\nCharge on the shell shifts the potential of both surfaces by the same amount and does not change the difference.\nThe difference stays V, option (b)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 2","tp":"evp","st":"Field-potential relation and equipotentials","q":"The electric field in a region is given by E⃗ = (Ax + B)î, where E is in N C⁻¹ and x is in meters. The values of constants are A = 20 SI unit and B = 10 SI unit. If the potential at x = 1 is V₁ and that at x = −5 is V₂, then V₁ − V₂ is","o":["−520 V","−48 V","180 V","320 V"],"c":2,"s":"V₁ − V₂ = V(1) − V(−5) = −∫ E dx taken from x = −5 to x = 1.\n= −∫(20x + 10)dx = −[10x² + 10x] from −5 to 1.\nAt x = 1: 10 + 10 = 20. At x = −5: 250 − 50 = 200.\nV₁ − V₂ = −(20 − 200) = 180 V, option (c)."},
{"y":"JEE Main 2019 · 9 Apr · Shift 1","tp":"evp","st":"Potential energy and work","q":"A system of three charges are placed as shown in the figure. If D >> d, the potential energy of the system is best given by","fig":{"w":340,"h":125,"alt":"Charges +q and -q a distance d apart on a line, with charge Q a distance D from the middle of the pair","d":[["l",20,70,320,70],["c",60,70,3,"F"],["c",150,70,3,"F"],["c",260,70,3,"F"],["t",60,60,"+q","m"],["t",150,60,"−q","m"],["t",260,60,"Q","m"],["l",60,70,60,98,"d"],["l",150,70,150,98,"d"],["l",60,95,150,95,"b"],["t",105,114,"d","m"],["l",105,30,105,70,"d"],["l",260,30,260,70,"d"],["l",105,34,260,34,"b"],["t",182,26,"D","m"]]},"o":["{1;4πε₀}[−{q²;d} − {qQd;D²}]","{1;4πε₀}[+{q²;d} + {qQd;D²}]","{1;4πε₀}[−{q²;d} − {qQd;2D²}]","{1;4πε₀}[−{q²;d} + {2qQd;D²}]"],"c":0,"s":"Add the three pair energies. D is measured from the middle of the +q, −q pair to Q.\nPair +q, −q: −kq²/d.\nPairs with Q: kqQ/(D + d/2) − kqQ/(D − d/2) = −kqQ·d/(D² − d²/4) ≈ −kqQd/D² for D >> d.\nU ≈ (1/4πε₀)[−q²/d − qQd/D²], option (a)."},
{"y":"JEE Main 2019 · 10 Apr · Shift 1","tp":"evp","st":"Potential energy and work","q":"A uniformly charged ring of radius 3a and total charge q is placed in xy-plane centred at origin. A point charge q is moving towards the ring along the z-axis and has speed v at z = 4a. The minimum value of v such that it crosses the origin is","o":["√({2;m}·{2;15}·{q²;4πε₀a})","√({2;m}·{1;5}·{q²;4πε₀a})","√({2;m}·{4;15}·{q²;4πε₀a})","√({2;m}·{1;15}·{q²;4πε₀a})"],"c":0,"s":"On the axis the potential of the ring is V = kq/√(9a² + z²).\nAt z = 4a: V = kq/(5a). At the centre (z = 0): V = kq/(3a).\nThe moving charge is repelled, and the potential is largest at the centre, so it only needs enough energy to just reach the centre.\n½mv² = q(V_centre − V_4a) = kq²(1/(3a) − 1/(5a)) = 2kq²/(15a).\nv = √( (2/m)·(2/15)·q²/(4πε₀a) ), option (a)."},
{"y":"JEE Main 2019 · 10 Apr · Shift 2","tp":"evp","st":"Potential energy and work","q":"In free space, a particle A of charge 1 μC is held fixed at a point P. Another particle B of the same charge and mass 4 mg is kept at a distance of 1 mm from P. If B is released, then its velocity at a distance of 9 mm from P is\n[Take {1;4πε₀} = 9×10⁹ N m² C⁻²]","o":["3.0 × 10⁴ m/s","1.0 m/s","1.5 × 10² m/s","2.0 × 10³ m/s"],"c":3,"s":"Energy conservation: ½mv² = kq²(1/r₁ − 1/r₂), with r₁ = 1 mm and r₂ = 9 mm.\nkq² = 9×10⁹ × (10⁻⁶)² = 9×10⁻³ J·m, and 1/r₁ − 1/r₂ = 1000 − 111 = 889 m⁻¹, so ½mv² = 8 J and v² = 16/m.\nWith m = 4 mg = 4×10⁻⁶ kg: v = √(16/(4×10⁻⁶)) = 2×10³ m/s.\nOption (d)."},
{"y":"JEE Main 2019 · 12 Apr · Shift 1","tp":"efl","st":"Electric dipole","q":"A point dipole p⃗ = p₀x̂ is kept at the origin. The potential and electric field due to this dipole on the y-axis at a distance d are, respectively (Take V = 0 at infinity)","o":["0, {−p⃗;4πε₀d³}","{|p⃗|;4πε₀d²}, {p⃗;4πε₀d³}","0, {p⃗;4πε₀d³}","{|p⃗|;4πε₀d²}, {−p⃗;4πε₀d³}"],"c":0,"s":"The y-axis is the perpendicular bisector of the dipole (it is along the x-axis). Every point on it is at the same distance from +q and −q, so V = 0.\nOn the equatorial line the field is E⃗ = −p⃗/(4πε₀d³), directed opposite to p⃗.\nSo the answer is 0 and −p⃗/(4πε₀d³), option (a)."},
{"y":"JEE Main 2019 · 10 Jan · Shift 2","tp":"evp","st":"Potential energy and work","q":"Four equal point charges Q each are placed in the xy plane at (0, 2), (4, 2), (4, −2) and (0, −2). The work required to put a fifth charge Q at the origin of the coordinate system will be","o":["{Q²;4πε₀}(1 + {1;√5})","{Q²;2√2πε₀}","{Q²;4πε₀}(1 + {1;√3})","{Q²;4πε₀}"],"c":0,"s":"Work needed = Q × (potential at the origin due to the four charges).\nDistances from the origin: 2 m (to (0,2)), 2 m (to (0,−2)), √20 = 2√5 m (to (4,2)) and 2√5 m (to (4,−2)).\nV = kQ(1/2 + 1/2 + 1/(2√5) + 1/(2√5)) = kQ(1 + 1/√5).\nW = QV = (Q²/4πε₀)(1 + 1/√5), option (a)."},
{"y":"JEE Main 2019 · 11 Jan · Shift 1","tp":"evp","st":"Potential energy and work","q":"Three charges Q, +q and +q are placed at the vertices of a right-angle isosceles triangle as shown in the figure. The net electrostatic energy of the configuration is zero, if the value of Q is","fig":{"w":340,"h":170,"alt":"Right-angled isosceles triangle with charge Q at the top vertex above the left +q, and the other +q at the right end of the base","d":[["l",90,20,90,130],["l",90,130,200,130],["l",90,20,200,130],["c",90,20,3,"F"],["c",90,130,3,"F"],["c",200,130,3,"F"],["t",82,18,"Q","e"],["t",82,134,"+q","e"],["t",208,134,"+q"]]},"o":["+q","−2q","{−√2q;√2+1}","{−q;1+√2}"],"c":2,"s":"Let the equal sides be a, so the hypotenuse (Q to the far +q) is a√2.\nTotal energy U = k[Qq/a + q²/a + Qq/(a√2)] = 0.\nQq(1 + 1/√2) = −q², so Q = −q/(1 + 1/√2) = −√2q/(√2 + 1).\nOption (c)."},
{"y":"JEE Main 2019 · 11 Jan · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"The given graph shows variation (with distance r from centre) of","fig":{"w":340,"h":150,"alt":"A circle of radius r0 with its centre marked, and a graph that is flat up to r0 then falls off with r","d":[["c",60,70,45],["c",60,70,2,"F"],["l",60,70,92,38],["t",82,68,"r₀","s"],["l",150,120,150,20],["l",150,120,320,120,"a"],["t",322,136,"r","e"],["l",150,40,210,40],["l",210,40,210,120,"d"],["p","M210 40 Q225 95 300 112"],["t",210,136,"r₀","ms"]]},"o":["Electric field of a uniformly charged spherical shell","Electric field of a uniformly charged sphere","Potential of a uniformly charged spherical shell","Potential of a uniformly charged sphere"],"c":2,"s":"The graph is constant up to r₀ and then falls smoothly as 1/r.\nFor a uniformly charged shell, the potential is constant inside (= kQ/r₀) and equals kQ/r outside: this matches.\nThe field of a shell is zero inside and falls as 1/r² outside, so it does not match.\nFor a solid sphere, the field rises linearly inside and the potential keeps changing inside, so those do not match either.\nThe graph shows the potential of a uniformly charged spherical shell, option (c)."},
{"y":"JEE Main 2019 · 11 Jan · Shift 2","tp":"efl","st":"Electric dipole","q":"An electric field of 1000 V/m is applied to an electric dipole at angle of 45°. The value of electric dipole moment is 10⁻²⁹ C m. What is the potential energy of the electric dipole?","o":["−10 × 10⁻²⁹ J","−7 × 10⁻²⁷ J","−20 × 10⁻¹⁸ J","−9 × 10⁻²⁰ J"],"c":1,"s":"Potential energy of a dipole in a field: U = −p⃗·E⃗ = −pE cosθ.\nU = −(10⁻²⁹)(1000)(cos 45°) = −10⁻²⁶ × 0.707.\nU ≈ −7.07 × 10⁻²⁷ J ≈ −7 × 10⁻²⁷ J, option (b)."},
{"y":"JEE Advanced 2019","tp":"evp","st":"Potential of charges and distributions","q":"A thin spherical insulating shell of radius R carries a uniformly distributed charge such that the potential at its surface is V₀. A hole with small area α4πR² (α << 1) is made on the shell without affecting the rest of the shell. Which one of the following statements is correct?","o":["The ratio of the potential at the center of the shell to that of the point at ½R from center towards the hole will be {1−α;1−2α}","The potential at the centre of shell is reduced by 2αV₀","The magnitude of electric field at the center of the shell is reduced by {αV₀;2R}","The magnitude of electric field at a point, located on a line passing through the hole and shell's center, on a distance 2R from the center of the spherical shell will be reduced by {αV₀;2R}"],"c":0,"s":"Shell with hole = full shell + a small charge −αQ at the hole. For the full shell, V₀ = kQ/R.\nThe removed charge αQ is at distance R from the centre: it lowers the potential there by kαQ/R = αV₀, so V(centre) = V₀(1 − α).\nThe point ½R from the centre towards the hole is ½R from the hole: reduction = kαQ/(R/2) = 2αV₀, so V = V₀(1 − 2α).\nRatio = (1 − α)/(1 − 2α), so (a) is correct.\n(b) is wrong (reduction is αV₀). In (c) and (d) the field change is kαQ/R² = αV₀/R, not αV₀/(2R)."},
{"y":"JEE Main 2018","tp":"evp","st":"Potential of charges and distributions","q":"Three concentric metal shells A, B and C of respective radii, a, b and c (a < b < c) have surface charge densities +σ, −σ and +σ respectively. The potential of shell B is","o":["{σ;ε₀}[{a²−b²;a} + c]","{σ;ε₀}[{a²−b²;b} + c]","{σ;ε₀}[{b²−c²;b} + a]","{σ;ε₀}[{b²−c²;c} + a]"],"c":1,"s":"Charges: Q(A) = 4πσa², Q(B) = −4πσb², Q(C) = 4πσc².\nPotential on shell B = (potential of A and B at radius b) + (potential of C, which is constant inside C).\nV(B) = k(Q(A) + Q(B))/b + kQ(C)/c = (σ/ε₀)[(a² − b²)/b + c].\nOption (b)."},
{"y":"JEE Main 2017 · Online","tp":"evp","st":"Field-potential relation and equipotentials","q":"There is a uniform electrostatic field in a region. The potential at various points on a small sphere centred at P, in the region, is found to vary between the limits 589.0 V to 589.8 V. What is the potential at a point on the sphere whose radius vector makes an angle of 60° with the direction of the field?","o":["589.2 V","589.6 V","589.5 V","589.4 V"],"c":0,"s":"In a uniform field, V changes by E·Δx along the field. On the sphere, V = V(P) − Er cosθ, where θ is the angle between the radius vector and E.\nThe maximum and minimum are at θ = 0° and 180°, so V(P) = (589.0 + 589.8)/2 = 589.4 V and Er = 0.4 V.\nAt θ = 60°: V = 589.4 − 0.4 × cos 60° = 589.4 − 0.2 = 589.2 V.\nOption (a)."},
{"y":"JEE Main 2016 · Online","tp":"evp","st":"Field-potential relation and equipotentials","q":"The potential (in volts) of a charge distribution is given by\nV(z) = 30 − 5z² for |z| ≤ 1 m\nV(z) = 35 − 10|z| for |z| ≥ 1 m\nV(z) does not depend on x and y. If this potential is generated by a constant charge per unit volume ρ₀ (in units of ε₀) which is spread over a certain region, then choose the correct statement.","o":["ρ₀ = 20 ε₀ in the entire region","ρ₀ = 10 ε₀ for |z| ≤ 1 m and ρ₀ = 0 elsewhere","ρ₀ = 20 ε₀ for |z| ≤ 1 m and ρ₀ = 0 elsewhere","ρ₀ = 40 ε₀ in the entire region"],"c":1,"s":"For a potential depending only on z, Poisson's equation is d²V/dz² = −ρ/ε₀.\nFor |z| ≤ 1: V = 30 − 5z², so d²V/dz² = −10, giving ρ₀ = 10ε₀.\nFor |z| ≥ 1: V is linear in |z|, so d²V/dz² = 0 and ρ₀ = 0.\nOption (b)."},
{"y":"JEE Main 2016 · Online","tp":"evp","st":"Field-potential relation and equipotentials","q":"Within a spherical charge distribution of charge density ρ(r), N equipotential surfaces of potential V₀, V₀ + ΔV, V₀ + 2ΔV, ..., V₀ + NΔV (ΔV > 0), are drawn and have increasing radii r₀, r₁, r₂, ..., r(N), respectively. If the difference in the radii of the surfaces is constant for all values of V₀ and ΔV then","o":["ρ(r) = constant","ρ(r) ∝ {1;r²}","ρ(r) ∝ {1;r}","ρ(r) ∝ r"],"c":2,"s":"Equal potential steps ΔV over equal radius steps Δr means E = ΔV/Δr is the same everywhere: E is constant.\nBy Gauss's law, E = kQ(enc)/r² = constant, so Q(enc) ∝ r².\nThen dQ/dr = 4πr²ρ ∝ 2r, which gives ρ ∝ 1/r.\nOption (c)."},
{"y":"JEE Main 2015 · Online","tp":"evp","st":"Field-potential relation and equipotentials","q":"An electric field E⃗ = (25î + 30ĵ) N C⁻¹ exists in a region of space. If the potential at the origin is taken to be zero then the potential at x = 2 m, y = 2 m is","o":["−130 V","−120 V","−140 V","−110 V"],"c":3,"s":"V = −∫E⃗·dr⃗ from the origin. For a uniform field, V = −(Eₓx + E_y y).\nV = −(25 × 2 + 30 × 2) = −(50 + 60) = −110 V.\nThe options print the unit as J, but potential is in volt. Option (d)."},
{"y":"JEE Main 2014","tp":"evp","st":"Field-potential relation and equipotentials","q":"Assume that an electric field E⃗ = 30x²î exists in space. Then the potential difference V_A − V₀ where V₀ is the potential at the origin and V_A the potential at x = 2 m is","o":["80 V","120 V","−120 V","−80 V"],"c":3,"s":"V_A − V₀ = −∫E dx from x = 0 to x = 2.\n= −∫30x² dx = −10x³ evaluated from 0 to 2.\n= −10 × 8 = −80 V (the options print J, but it is volt). Option (d)."},
{"y":"JEE Main 2013","tp":"evp","st":"Potential of charges and distributions","q":"A charge Q is uniformly distributed over a long rod AB of length L as shown in the figure. The electric potential at the point O lying at a distance L from the end A is","fig":{"w":340,"h":120,"alt":"Point O, then a gap of length L to end A of a charged rod AB of length L","d":[["l",30,50,310,50,"d"],["c",40,50,3,"F"],["t",40,38,"O","m"],["t",140,38,"A","m"],["t",240,38,"B","m"],["r",140,44,100,12,"f"],["l",40,50,40,90,"d"],["l",140,50,140,90,"d"],["l",240,50,240,90,"d"],["l",40,86,140,86,"b"],["t",90,104,"L","m"],["l",140,86,240,86,"b"],["t",190,104,"L","m"]]},"o":["{Q ln2;4πε₀L}","{Q ln2;8πε₀L}","{3Q;4πε₀L}","{Q;4πε₀L ln2}"],"c":0,"s":"Take a small piece dx of the rod at distance x from O, where L ≤ x ≤ 2L. Its charge is dq = (Q/L)dx.\nV = ∫ k dq/x = k(Q/L)∫dx/x from L to 2L = k(Q/L) ln(2L/L).\nV = Q ln2/(4πε₀L), option (a)."},
{"y":"JEE Main 2013 · Online","tp":"ecl","st":"Equilibrium and motion of charges","q":"Two small equal point charges of magnitude q are suspended from a common point on the ceiling by insulating massless strings of equal lengths. They come to equilibrium with each string making angle θ from the vertical. If the mass of each charge is m, then the electrostatic potential at the centre of line joining them will be ({1;4πε₀} = k)","o":["2√(k mg tanθ)","√(k mg tanθ)","4√({k mg;tanθ})","4√(k mg tanθ)"],"c":3,"s":"Let the distance between the charges be r. For one charge in equilibrium: tanθ = F/(mg) = kq²/(r²mg).\nSo q² = mg r² tanθ/k and q = r√(mg tanθ/k).\nPotential at the midpoint (each charge is r/2 away): V = 2kq/(r/2) = 4kq/r.\nV = 4k√(mg tanθ/k) = 4√(k mg tanθ). Option (d)."},
{"y":"JEE Main 2013 · Online","tp":"ecn","st":"Induced charge and shielding","q":"Consider a finite, insulated, uncharged conductor placed near a finite positively charged conductor. The uncharged body must have a potential","o":["less than the charged conductor and more than at infinity.","more than the charged conductor and less than at infinity.","more than the charged conductor and more than at infinity.","less than the charged conductor and less than at infinity."],"c":0,"s":"Electric field lines start on the positively charged conductor and potential falls along a field line.\nThe lines reaching the uncharged conductor come from the charged one, and lines leaving it go on to infinity (or end on the negative induced charge).\nSo its potential is lower than that of the charged conductor, but higher than the potential at infinity (zero).\nOption (a)."},
{"y":"IIT-JEE 2012","tp":"efl","st":"Field lines and motion in a field","q":"Two large vertical and parallel metal plates having a separation of 1 cm are connected to a DC voltage source of potential difference X. A proton is released at rest midway between the two plates. It is found to move at 45° to the vertical just after release. Then X is nearly","o":["1 × 10⁻⁵ V","1 × 10⁻⁷ V","1 × 10⁻⁹ V","1 × 10⁻¹⁰ V"],"c":2,"s":"Gravity gives the proton a vertical acceleration g. The plates give a horizontal acceleration a = eE/m = eX/(md).\nMotion at 45° to the vertical means the two accelerations are equal: eX/(md) = g.\nX = mgd/e = (1.67×10⁻²⁷)(9.8)(10⁻²)/(1.6×10⁻¹⁹) ≈ 1×10⁻⁹ V.\nOption (c)."},
{"y":"IIT-JEE 2012","tp":"evp","st":"Potential of charges and distributions","q":"Consider a thin spherical shell of radius R with its centre at the origin, carrying uniform positive surface charge density. The variation of the magnitude of the electric field |E⃗(r)| and the electric potential V(r) with the distance r from the centre, is best represented by which graph?","fig":{"w":340,"h":240,"alt":"Four small graphs (a) to (d), each with a solid curve for the field magnitude and a dashed curve for the potential against r, with R marked","d":[["t",10,28,"(a)"],["l",48,93,48,18,"a"],["l",48,93,165,93,"a"],["t",165,107,"r","es"],["t",96,107,"R","ms"],["t",52,22,"|E|, V","s"],["l",96,93,96,38],["p","M96 38 Q118 83 160 88"],["l",48,93,96,26,"d"],["p","M96 26 Q126 63 160 76","d"],["t",175,28,"(b)"],["l",213,93,213,18,"a"],["l",213,93,330,93,"a"],["t",330,107,"r","es"],["t",261,107,"R","ms"],["t",217,22,"|E|, V","s"],["l",213,53,261,53],["p","M261 53 Q286 86 325 90"],["l",213,26,261,26,"d"],["p","M261 26 Q291 63 325 76","d"],["t",10,140,"(c)"],["l",48,205,48,130,"a"],["l",48,205,165,205,"a"],["t",165,219,"r","es"],["t",96,219,"R","ms"],["t",52,134,"|E|, V","s"],["l",48,165,96,165],["p","M96 165 Q121 198 160 202"],["l",48,205,96,138,"d"],["p","M96 138 Q126 175 160 188","d"],["t",175,140,"(d)"],["l",213,205,213,130,"a"],["l",213,205,330,205,"a"],["t",330,219,"r","es"],["t",261,219,"R","ms"],["t",217,134,"|E|, V","s"],["l",261,205,261,150],["p","M261 150 Q283 195 325 200"],["l",213,138,261,138,"d"],["p","M261 138 Q291 175 325 188","d"],["t",170,232,"solid line: |E(r)|     dashed line: V(r)","ms"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":3,"s":"For a uniformly charged thin shell: E = 0 inside (r < R), jumps to σ/ε₀ at r = R, then falls as 1/r² outside.\nV is constant inside, equal to kQ/R, and falls as 1/r outside (V is continuous at R).\nGraph (d) shows E zero inside with a jump at R, and V flat inside then decreasing.\nIn (a) and (c) V rises inside; in (b) and (c) E is non-zero inside. Option (d)."},
{"y":"AIEEE 2011","tp":"evp","st":"Field-potential relation and equipotentials","q":"The electrostatic potential inside a charged spherical ball is given by φ = ar² + b where r is the distance from the centre; a, b are constants. Then the charge density inside the ball is","o":["−24πaε₀r","−6aε₀r","−24πaε₀","−6aε₀"],"c":3,"s":"The field is E = −dφ/dr = −2ar.\nGauss's law for a sphere of radius r with uniform density ρ: E·4πr² = (4/3)πr³ρ/ε₀, so ρ = 3ε₀E/r.\nρ = 3ε₀(−2ar)/r = −6aε₀.\nOption (d)."},
{"y":"AIEEE 2009","tp":"evp","st":"Potential energy and work","q":"Two points P and Q are maintained at the potentials of 10 V and −4 V respectively. The work done in moving 100 electrons from P to Q is","o":["−9.60 × 10⁻¹⁷ J","9.60 × 10⁻¹⁷ J","−2.24 × 10⁻¹⁶ J","2.24 × 10⁻¹⁶ J"],"c":3,"s":"Work done in moving a charge q from P to Q: W = q(V_Q − V_P).\nHere q = −100e = −1.6×10⁻¹⁷ C, V_Q − V_P = −4 − 10 = −14 V.\nW = (−1.6×10⁻¹⁷)(−14) = +2.24×10⁻¹⁶ J.\nOption (d)."},
{"y":"IIT-JEE 2008","tp":"evp","st":"Potential of charges and distributions","q":"Consider a system of three charges {q;3}, {q;3} and −{2q;3} placed at points A, B and C, respectively, as shown in the figure. Take O to be the centre of the circle of radius R and angle CAB = 60°","fig":{"w":340,"h":215,"alt":"Circle of radius R with centre O; A and B at opposite ends of a diameter, C on the circle on the negative x side, with the x and y axes","d":[["c",170,110,75],["l",132.5,175,207.5,45,"d"],["l",95,110,207.5,45],["l",95,110,132.5,175],["l",170,110,290,110,"d"],["l",170,195,170,18,"d"],["c",95,110,3,"F"],["c",132.5,175,3,"F"],["c",207.5,45,3,"F"],["t",82,114,"C","e"],["t",122,192,"A","m"],["t",214,40,"B"],["t",176,102,"O"],["t",296,114,"x"],["t",176,18,"y"],["t",132,128,"60°","s"]]},"o":["the electric field at point O is {q;8πε₀R²} directed along the negative x-axis","the potential energy of the system is zero","the magnitude of the force between the charges at C and B is {q²;54πε₀R²}","the potential at point O is {q;12πε₀R}"],"c":2,"s":"A and B are the ends of a diameter (the dotted line through O), so angle ACB = 90° and BC = AB sin 60° = √3 R.\nForce between C and B: k(q/3)(2q/3)/(3R²) = 2kq²/(27R²) = q²/(54πε₀R²). So (c) is correct.\nV at O = k(q/3 + q/3 − 2q/3)/R = 0, so (d) is wrong. The potential energy is not zero.\nField at O: A and B cancel; C gives k(2q/3)/R² = q/(6πε₀R²), not q/(8πε₀R²), so (a) is wrong."},
{"y":"AIEEE 2007","tp":"evp","st":"Field-potential relation and equipotentials","q":"The potential at a point x (measured in μm) due to some charges situated on the x-axis is given by\nV(x) = {20;x²−4} volt\nThe electric field E at x = 4 μm is given by","o":["(10/9) volt/μm and in the +ve x direction","(5/3) volt/μm and in the −ve x direction","(5/3) volt/μm and in the +ve x direction","(10/9) volt/μm in the −ve x direction"],"c":0,"s":"E = −dV/dx = 20 × 2x/(x² − 4)² = 40x/(x² − 4)².\nAt x = 4: E = 160/(16 − 4)² = 160/144 = 10/9 volt/μm.\nThe sign is positive, so E points along +x.\nOption (a). (The book prints 'x = 4 mm', but the units of V(x) are μm and the options in volt/μm need x = 4 μm.)"},
{"y":"AIEEE 2007","tp":"evp","st":"Potential of charges and distributions","q":"Charges are placed on the vertices of a square as shown. Let E⃗ be the electric field and V the potential at the centre. If the charges on A and B are interchanged with those on D and C respectively, then","fig":{"w":340,"h":180,"alt":"Square ABCD with charge q at A and B on the top edge and charge -q at D and C on the bottom edge","d":[["r",110,30,120,120],["t",116,46,"A"],["t",224,46,"B","e"],["t",116,144,"D"],["t",224,144,"C","e"],["t",110,22,"q","m"],["t",230,22,"q","m"],["t",110,166,"−q","m"],["t",230,166,"−q","m"]]},"o":["E⃗ changes, V remains unchanged","E⃗ remains unchanged, V changes","both E⃗ and V change","E⃗ and V remain unchanged"],"c":0,"s":"Initially A, B carry +q and D, C carry −q. The centre is equidistant from all four, so V = 0.\nThe field at the centre points from the +q side towards the −q side (from the top edge to the bottom edge).\nAfter the interchange A, B carry −q and D, C carry +q: V is still 0 (unchanged), but the field direction is reversed.\nSo E⃗ changes and V remains unchanged. Option (a)."},
{"y":"AIEEE 2007","tp":"evp","st":"Potential of charges and distributions","q":"An electric charge 10⁻³ μC is placed at the origin (0, 0) of X–Y co-ordinate system. Two points A and B are situated at (√2, √2) and (2, 0) respectively. The potential difference between the points A and B will be","o":["4.5 volt","9 volt","zero","2 volt"],"c":2,"s":"The potential of a point charge depends only on the distance from it.\nDistance of A: √(2 + 2) = 2. Distance of B: 2.\nBoth points are at the same distance, so V_A = V_B = kq/2.\nThe potential difference is zero. Option (c)."},
{"y":"IIT-JEE 2007","tp":"ecn","st":"Induced charge and shielding","q":"A long, hollow conducting cylinder is kept coaxially inside another long, hollow conducting cylinder of larger radius. Both the cylinders are initially electrically neutral.","o":["A potential difference appears between the two cylinders when a charge density is given to the inner cylinder.","A potential difference appears between the two cylinders when a charge density is given to the outer cylinder.","No potential difference appears between the two cylinders when a uniform line charge is kept along the axis of the cylinders.","No potential difference appears between the two cylinders when same charge density is given to both the cylinders."],"c":0,"s":"(a) Charge on the inner cylinder produces a field in the gap (induced opposite charge on the inner face of the outer one), so there is a potential difference. True.\n(b) Charge on the outer cylinder only: the field inside a charged cylindrical shell is zero, so no potential difference. False.\n(c) A line charge on the axis induces charge on the cylinders and a field appears in the gap, so a potential difference exists. False.\n(d) The field in the gap is due to the inner charge only, so a potential difference exists. False.\nOnly (a) is correct."},
{"y":"IIT-JEE 2007","tp":"evp","st":"Potential energy and work","q":"Positive and negative point charges of equal magnitude are kept at (0, 0, {a;2}) and (0, 0, −{a;2}) respectively. The workdone by the electric field when another positive point charge is moved from (−a, 0, 0) to (0, a, 0) is","o":["positive","negative","zero","depends on the path connecting the initial and final positions."],"c":2,"s":"The two charges form a dipole along the z-axis. The plane z = 0 is its perpendicular bisector and is an equipotential at V = 0.\nBoth (−a, 0, 0) and (0, a, 0) lie in this plane, so the potential difference is zero.\nWork W = q(V_i − V_f) = 0, whatever the path (the field is conservative).\nOption (c)."},
{"y":"AIEEE 2006","tp":"efl","st":"Field lines and motion in a field","q":"Two insulating plates are both uniformly charged in such a way that the potential difference between them is V₂ − V₁ = 20 V. (i.e. plate 2 is at a higher potential). The plates are separated by d = 0.1 m and can be treated as infinitely large. An electron is released from rest on the inner surface of plate 1. What is its speed when it hits plate 2?\n(e = 1.6 × 10⁻¹⁹ C, mₑ = 9.11 × 10⁻³¹ kg)","fig":{"w":340,"h":150,"alt":"Two parallel plates, 1 on the left and 2 on the right, separated by 0.1 m, with X and Y axes drawn beside them","d":[["r",100,20,12,100],["r",200,20,12,100],["t",106,138,"1","m"],["t",206,138,"2","m"],["l",112,60,200,60,"b"],["t",156,52,"0.1 m","ms"],["l",260,120,260,30,"a"],["t",266,34,"Y"],["l",260,120,320,120,"a"],["t",318,112,"X","e"]]},"o":["32 × 10⁻¹⁹ m/s","2.65 × 10⁶ m/s","7.02 × 10¹² m/s","1.87 × 10⁶ m/s"],"c":1,"s":"The electron moves towards the plate at higher potential and gains kinetic energy equal to e × (V₂ − V₁).\n½mv² = 1.6×10⁻¹⁹ × 20 = 3.2×10⁻¹⁸ J.\nv = √(2 × 3.2×10⁻¹⁸ / 9.11×10⁻³¹) = √(7.03×10¹²) ≈ 2.65×10⁶ m/s.\nOption (b)."},
{"y":"AIEEE 2005","tp":"evp","st":"Potential of charges and distributions","q":"Two thin wire rings each having a radius R are placed at a distance d apart with their axes coinciding. The charges on the two rings are +Q and −Q. The potential difference between the centers of the two rings is","o":["zero","{Q;4πε₀}[{1;R} − {1;√(R²+d²)}]","{QR;4πε₀d²}","{Q;2πε₀}[{1;R} − {1;√(R²+d²)}]"],"c":3,"s":"At the centre of the +Q ring: V₁ = kQ/R − kQ/√(R² + d²) (the −Q ring is at distance √(R² + d²)).\nBy symmetry the potential at the centre of the −Q ring is V₂ = −V₁.\nV₁ − V₂ = 2V₁ = 2kQ[1/R − 1/√(R² + d²)] = (Q/2πε₀)[1/R − 1/√(R² + d²)].\nOption (d)."},
{"y":"AIEEE 2004","tp":"evp","st":"Potential energy and work","q":"A charged particle q is shot towards another charged particle Q which is fixed, with a speed v. It approaches Q upto a closest distance r and then returns. If q were given a speed 2v, the closest distances of approach would be","o":["r","2r","r/2","r/4"],"c":3,"s":"At the closest distance all the kinetic energy has become electric potential energy: ½mv² = kQq/r.\nWith speed 2v: ½m(2v)² = 4 × ½mv² = kQq/r′.\nSo kQq/r′ = 4kQq/r, giving r′ = r/4.\nOption (d)."},
{"y":"AIEEE 2003","tp":"ecn","st":"Induced charge and shielding","q":"A thin spherical conducting shell of radius R has a charge q. Another charge Q is placed at the centre of the shell. The electrostatic potential at a point P at a distance R/2 from the centre of the shell is","o":["{2Q;4πε₀R}","{2Q;4πε₀R} − {2q;4πε₀R}","{2Q;4πε₀R} + {q;4πε₀R}","{(q+Q);4πε₀}·{2;R}"],"c":2,"s":"Charge Q at the centre induces −Q on the inner surface of the shell and +Q on the outer surface, so the outer surface carries q + Q.\nPotential at P (R/2 from the centre) = (Q at distance R/2) + (−Q on the shell at R) + ((q + Q) on the shell at R).\nV = kQ/(R/2) − kQ/R + k(q + Q)/R = 2kQ/R + kq/R.\nV = 2Q/(4πε₀R) + q/(4πε₀R), option (c)."},
{"y":"IIT-JEE 2002","tp":"evp","st":"Potential energy and work","q":"Two equal point charges are fixed at x = −a and x = +a on the axis. Another point charge Q is placed at the origin. The change in the electrical potential energy of Q, when it is displaced by a small distance x along the x-axis, is approximately proportional to","o":["x","x²","x³","1/x"],"c":1,"s":"Let the fixed charges be q. At position x the potential energy of Q is U = kqQ[1/(a − x) + 1/(a + x)] = 2kqQa/(a² − x²).\nFor small x: U ≈ (2kqQ/a)(1 + x²/a²).\nThe change in U from x = 0 is (2kqQ/a³)x², which is proportional to x².\nOption (b)."},
{"y":"IIT-JEE 2001","tp":"evp","st":"Field-potential relation and equipotentials","q":"A uniform electric field pointing in positive x-direction exists in a region. Let A be the origin, B be the point on the x-axis at x = +1 cm and C be the point on the y-axis at y = +1 cm. Then the potentials at the points A, B and C satisfy","o":["V_A < V_B","V_A > V_B","V_A < V_C","V_A > V_C"],"c":1,"s":"Potential falls in the direction of the electric field. B lies further along +x than A, so V_B < V_A, i.e. V_A > V_B.\nC is displaced from A along y, perpendicular to the field, so no work is done and V_C = V_A.\nSo only V_A > V_B is true. Option (b)."},
{"y":"IIT-JEE 2000","tp":"evp","st":"Potential energy and work","q":"Three charges Q, + q and + q are placed at the vertices of a right-angled isosceles triangle as shown. The net electrostatic energy of the configuration is zero if Q is equal to","fig":{"w":340,"h":170,"alt":"Right-angled isosceles triangle with charge Q at the top vertex above the left +q, and the other +q at the right end of the base of length a","d":[["l",90,20,90,120],["l",90,120,200,120],["l",90,20,200,120],["c",90,20,3,"F"],["c",90,120,3,"F"],["c",200,120,3,"F"],["t",82,18,"Q","e"],["t",82,124,"+q","e"],["t",208,124,"+q"],["l",90,142,200,142,"b"],["t",145,160,"a","m"]]},"o":["{−q;1+√2}","{−2q;2+√2}","−2q","+q"],"c":1,"s":"Equal sides a, hypotenuse a√2 (Q to the far +q).\nTotal energy U = k[Qq/a + q²/a + Qq/(a√2)] = 0.\nQ(1 + 1/√2) = −q, so Q = −q/(1 + 1/√2) = −√2q/(√2 + 1) = −2q/(2 + √2) after multiplying top and bottom by √2.\nOption (b)."},
{"y":"IIT-JEE 1997","tp":"evp","st":"Potential of charges and distributions","q":"A non-conducting ring of radius 0.5 m carries a total charge of 1.11 × 10⁻¹⁰ C distributed non-uniformly on its circumference, producing an electric field E⃗ everywhere in space. The value of the integral ∫ −E⃗·dl⃗ with the limits l = ∞ (lower) to l = 0 (upper), (l = 0 being centre of the ring) in volt is","o":["+2","−1","−2","zero."],"c":0,"s":"∫ from ∞ to 0 of (−E⃗·dl⃗) = V(0) − V(∞) = V(centre), since V(∞) = 0.\nEvery bit of charge is at distance R from the centre, so V = kQ/R whatever the distribution.\nV = 9×10⁹ × 1.11×10⁻¹⁰ / 0.5 ≈ 2 V.\nOption (a)."},
{"y":"IIT-JEE 1995","tp":"efl","st":"Field of point charges and distributions","q":"Two point charges +q and −q are held fixed at (−d, 0) and (d, 0) respectively of a x-y coordinate system. Then","o":["The electric field E at all points on x-axis has same direction.","Electric field at all points on y-axis is along x-axis.","Work has to be done in bringing a test charge from ∞ to the origin.","The dipole moment is 2qd along the x-axis."],"c":1,"s":"(a) Between the charges E points along +x, but beyond the −q charge the nearer −q dominates and E points along −x. So the direction changes. False.\n(b) On the y-axis the y-components of the two fields cancel, leaving a field along +x. True.\n(c) The potential at the origin is zero, so no work is needed to bring a test charge from infinity. False.\n(d) The dipole moment points from −q to +q, i.e. along −x, so it is not 'along the x-axis' as stated. False.\nOption (b)."},
{"y":"IIT-JEE 1983","tp":"ecn","st":"Induced charge and shielding","q":"A hollow metal sphere of radius 5 cm is charged such that the potential on its surface is 10 volt. The potential at the centre of the sphere is","o":["zero","10 volt","same as at a point 5 cm away from the surface","same as at a point 25 cm away from the surface"],"c":1,"s":"Inside a hollow charged conductor the field is zero, so the potential is the same everywhere inside, equal to the surface potential: 10 V.\n5 cm outside the surface (10 cm from centre) V = 10 × 5/10 = 5 V; 25 cm outside (30 cm from centre) V = 10 × 5/30 ≈ 1.7 V.\nOnly (b) is correct."},
{"y":"JEE Advanced 2025","tp":"egs","st":"Gauss's law and symmetric bodies","q":"Six infinitely large and thin non-conducting sheets are fixed in configurations I and II. As shown in the figure, the sheets carry uniform surface charge densities which are indicated in terms of σ₀. The separation between any two consecutive sheets is 1 μm. The various regions between the sheets are denoted as 1, 2, 3, 4 and 5. If σ₀ = 9 μC/m², then which of the following statements is/are correct?\n(Take permittivity of free space ε₀ = 9 × 10⁻¹² F/m)","fig":{"w":340,"h":185,"alt":"Two sets of six parallel sheets with charge densities marked on top and regions 1 to 5 between them: configuration I alternates +sigma0 and -sigma0, configuration II has sigma0/2, -sigma0, +sigma0, -sigma0, +sigma0, -sigma0/2","d":[["l",20,50,20,150],["t",20,44,"+σ₀","ms"],["l",46,50,46,150],["t",46,34,"−σ₀","ms"],["l",72,50,72,150],["t",72,44,"+σ₀","ms"],["l",98,50,98,150],["t",98,34,"−σ₀","ms"],["l",124,50,124,150],["t",124,44,"+σ₀","ms"],["l",150,50,150,150],["t",150,34,"−σ₀","ms"],["t",33,104,"1","ms"],["t",59,104,"2","ms"],["t",85,104,"3","ms"],["t",111,104,"4","ms"],["t",137,104,"5","ms"],["l",190,50,190,150],["t",190,44,"+σ₀/2","ms"],["l",216,50,216,150],["t",216,34,"−σ₀","ms"],["l",242,50,242,150],["t",242,44,"+σ₀","ms"],["l",268,50,268,150],["t",268,34,"−σ₀","ms"],["l",294,50,294,150],["t",294,44,"+σ₀","ms"],["l",320,50,320,150],["t",320,34,"−σ₀/2","ms"],["t",203,104,"1","ms"],["t",229,104,"2","ms"],["t",255,104,"3","ms"],["t",281,104,"4","ms"],["t",307,104,"5","ms"],["t",85,172,"Configuration I","ms"],["t",255,172,"Configuration II","ms"]]},"o":["In region 4 of the configuration I, the magnitude of the electric field is zero.","In region 3 of the configuration II, the magnitude of the electric field is {σ₀;ε₀}.","Potential difference between the first and the last sheets of the configuration I is 5 V.","Potential difference between the first and the last sheets of the configuration II is zero."],"c":[0],"s":"The total charge of each configuration is zero, so the field outside is zero and the field in a region equals (charge to its left)/ε₀. Here σ₀/ε₀ = 10⁶ V/m, i.e. 1 V across each 1 μm gap.\nConfiguration I: left charges are σ₀, 0, σ₀, 0, σ₀ for regions 1 to 5. Region 4 has zero field, so (a) is true.\nTotal potential difference I = 3 × 1 V = 3 V, not 5 V, so (c) is false.\nConfiguration II: left charges are σ₀/2, −σ₀/2, σ₀/2, −σ₀/2, σ₀/2, so region 3 has field σ₀/(2ε₀), not σ₀/ε₀: (b) is false. The potential difference is 0.5 V, not zero: (d) is false.\nOnly (a) is correct."},
{"y":"JEE Advanced 2025","tp":"ecn","st":"Charge sharing and earthing","q":"A positive point charge of 10⁻⁸ C is kept at a distance of 20 cm from the center of a neutral conducting sphere of radius 10 cm. The sphere is then grounded and the charge on the sphere is measured. The grounding is then removed and subsequently the point charge is moved by a distance of 10 cm further away from the center of the sphere along the radial direction. Taking {1;4πε₀} = 9 × 10⁹ Nm²/C² (where ε₀ is the permittivity of free space), which of the following statements is/are correct?","o":["Before the grounding, the electrostatic potential of the sphere is 450 V.","Charge flowing from the sphere to the ground because of grounding is 5 × 10⁻⁹ C.","After the grounding is removed, the charge on the sphere is −5 × 10⁻⁹ C.","The final electrostatic potential of the sphere is 300 V."],"c":[0,1,2],"s":"(a) The neutral sphere has net induced charge zero, so its potential is that of the outside charge at the centre: V = kq/d = 9×10⁹ × 10⁻⁸/0.2 = 450 V. True.\n(b), (c) Grounded: V = 0, so kQ'/R + kq/d = 0, giving Q' = −qR/d = −10⁻⁸ × 0.1/0.2 = −5×10⁻⁹ C. The sphere ends with −5×10⁻⁹ C, which means +5×10⁻⁹ C flowed out to the ground. Both true.\n(d) Charge moved to 30 cm: V = kq/0.3 + k(−5×10⁻⁹)/0.1 = 300 − 450 = −150 V, not 300 V. False.\nCorrect: (a), (b), (c)."},
{"y":"JEE Advanced 2022","tp":"evp","st":"Potential of charges and distributions","q":"Six charges are placed around a regular hexagon of side length a as shown in the figure. Five of them have charge q, and the remaining one has charge x. The perpendicular from each charge to the nearest hexagon side passes through the center O of the hexagon and is bisected by the side.\nWhich of the following statement(s) is (are) correct in SI units?","fig":{"w":340,"h":205,"alt":"Regular hexagon with centre O and six charges placed outside, one beyond each side, five marked q and the bottom one marked x","d":[["p","M132 110 L151 77.1 L189 77.1 L208 110 L189 142.9 L151 142.9 Z"],["l",170,44,170,176,"d"],["c",170,44.2,3,"F"],["t",170,36,"q","m"],["c",227,77.1,3,"F"],["t",236,76,"q",""],["c",227,142.9,3,"F"],["t",236,148,"q",""],["c",170,175.8,3,"F"],["t",170,192,"x","m"],["c",113,142.9,3,"F"],["t",104,148,"q","e"],["c",113,77.1,3,"F"],["t",104,76,"q","e"],["t",176,106,"O"],["t",206,134,"a","s"],["t",178,64,"90°","s"]]},"o":["When x = q, the magnitude of the electric field at O is zero.","When x = −q, the magnitude of the electric field at O is {q;6πε₀a²}.","When x = 2q, the potential at O is {7q;4√3πε₀a}.","When x = −3q, the potential at O is −{3q;4√3πε₀a}."],"c":[0,1,2],"s":"The perpendicular from a charge to the side is bisected by the side and passes through O, so each charge is at distance 2 × (apothem) = 2 × (√3a/2) = √3a from O.\n(a) Six equal charges at the corners of a regular hexagon: the fields cancel at O. True.\n(b) x = −q equals six charges q (zero field) plus −2q at the x position: E = k·2q/(3a²) = q/(6πε₀a²). True.\n(c) V = k(5q + 2q)/(√3a) = 7q/(4√3πε₀a). True.\n(d) V = k(5q − 3q)/(√3a) = 2q/(4√3πε₀a), which is positive, so the given value is wrong. False.\nCorrect: (a), (b), (c)."},
{"y":"JEE Advanced 2022","tp":"egs","st":"Non-uniform charge distributions","q":"In the figure, the inner (shaded) region A represents a sphere of radius r_A = 1, within which the electrostatic charge density varies with the radial distance r from the center as ρ_A = kr, where k is positive.\nIn the spherical shell B of outer radius r_B, the electrostatic charge density varies as ρ_B = {2k;r}.\nAssume that dimensions are taken care of. All physical quantities are in their SI units.\nWhich of the following statement(s) is(are) correct?","fig":{"w":340,"h":190,"alt":"Two concentric circles: the inner shaded sphere A of radius rA and the surrounding spherical shell B of outer radius rB","d":[["c",110,95,75],["c",110,95,50,"f"],["l",110,95,145,60],["t",136,70,"rA","s"],["l",110,95,163,148],["t",142,128,"rB","s"],["t",100,98,"A","m"],["t",46,98,"B","m"]]},"o":["If r_B = √{3;2}, then the electric field is zero everywhere outside B.","If r_B = 3/2, then the electric potential just outside B is {k;ε₀}.","If r_B = 2, then the total charge of the configuration is 15πk.","If r_B = 5/2, then the magnitude of the electric field just outside B is {13πk;ε₀}."],"c":[1],"s":"Charge in A: ∫₀¹ kr·4πr² dr = πk.\nCharge in B: ∫ from 1 to r_B of (2k/r)·4πr² dr = 4πk(r_B² − 1).\nTotal Q = πk(4r_B² − 3).\n(a) r_B² = 3/2: Q = 3πk ≠ 0, so the field outside is not zero. False.\n(b) r_B = 3/2: Q = 6πk, V = Q/(4πε₀r_B) = 6πk/(6πε₀) = k/ε₀. True.\n(c) r_B = 2: Q = 13πk, not 15πk. False.\n(d) r_B = 5/2: Q = 22πk, E = Q/(4πε₀r_B²) = 22k/(25ε₀), not 13πk/ε₀. False.\nOnly (b) is correct."},
{"y":"JEE Advanced 2022","tp":"evp","st":"Potential energy and work","q":"A disk of radius R with uniform positive charge density σ is placed on the xy plane with its center at the origin. The Coulomb potential along the z-axis is\nV(z) = {σ;2ε₀}(√(R²+z²) − z).\nA particle of positive charge q is placed initially at rest at a point on the z axis with z = z₀ and z₀ > 0. In addition to the Coulomb force, the particle experiences a vertical force F⃗ = −ck̂ with c > 0. Let β = {2cε₀;qσ}. Which of the following statement(s) is(are) correct?","o":["For β = {1;4} and z₀ = {25;7}R, the particle reaches the origin.","For β = {1;4} and z₀ = {3;7}R, the particle reaches the origin.","For β = {1;4} and z₀ = {R;√3}, the particle returns back to z = z₀.","For β > 1 and z₀ > 0, the particle always reaches the origin."],"c":[0,2,3],"s":"Potential energy: U(z) = qV + cz = (qσ/2ε₀)[√(R²+z²) − (1 − β)z]. Let f(z) = √(R²+z²) − (1 − β)z. The particle moves along z; force = −dU/dz.\nβ = 1/4: f′ = z/√(R²+z²) − 3/4 is zero at z = 3R/√7. f falls from f(0) = R to a minimum there, then rises, and f(z) = R again at z = 24R/7.\n(a) z₀ = 25R/7 > 24R/7, so f(z₀) > f(0): the particle gains enough energy to reach the origin. True.\n(b) z₀ = 3R/7: here f′ < 0, so the force pushes the particle away from the origin. False.\n(c) z₀ = R/√3: f′ < 0, the particle moves out, climbs the other side of the minimum and stops where f equals f(z₀), then returns. True.\n(d) β > 1: f′ > 0 for all z, so the net force always points towards the origin. True.\nCorrect: (a), (c), (d)."},
{"y":"JEE Main 2020 · 10 Jan · Shift 1","tp":"efl","st":"Electric dipole","q":"Two electric dipoles, A, B with respective dipole moments d⃗_A = −4qaî and d⃗_B = −2qaî are placed on the x-axis with a separation R, as shown in the figure\nThe distance from A at which both of them produce the same potential is","fig":{"w":340,"h":105,"alt":"Points A and B on the x-axis separated by R, with the x-axis arrow to the right","d":[["l",20,70,310,70,"a"],["t",314,66,"X"],["c",70,70,3,"F"],["c",230,70,3,"F"],["t",70,90,"A","m"],["t",230,90,"B","m"],["l",70,35,70,70,"d"],["l",230,35,230,70,"d"],["l",70,38,230,38,"b"],["t",150,30,"R","m"]]},"o":["{R;√2−1}","{R;√2+1}","{√2R;√2+1}","{√2R;√2−1}"],"c":3,"s":"On its axis a dipole has potential V = kp·r̂/r². Both dipole moments point along −x. Let the point be x from A.\nBetween A and B: V_A = −4kqa/x² is negative while V_B = +2kqa/(R − x)² is positive, so the potentials can never be equal there (only their magnitudes could be).\nTo the left of A: 4/x² = 2/(R + |x|)² has no solution because √2(R + |x|) = |x| is impossible.\nBeyond B both potentials are negative: 4/x² = 2/(x − R)², so x = √2(x − R) and x = √2R/(√2 − 1).\nOption (d)."},
{"y":"JEE Advanced 2017","tp":"egs","st":"Electric flux","q":"A point charge +Q is placed just outside an imaginary hemispherical surface of radius R as shown. Which of the following statements is/are correct?","fig":{"w":340,"h":180,"alt":"A hemispherical dome of radius R standing on a flat dashed base, with a point charge +Q just above its top","d":[["p","M80 150 A90 90 0 0 1 260 150"],["l",80,150,260,150,"d"],["l",170,150,170,64,"a"],["t",178,110,"R"],["c",170,46,4,"F"],["t",180,44,"+Q"]]},"o":["The circumference of the flat surface is an equipotential.","The component of the electric field normal to the flat surface is constant over the surface.","Total flux through the curved and the flat surfaces is Q/ε₀.","The electric flux passing through the curved surface of the hemisphere is −{Q;2ε₀}(1 − {1;√2})."],"c":[0,3],"s":"The charge is on the axis of the hemisphere, at distance R above the centre of the flat face (just outside the top of the dome).\n(a) Every point of the rim of the flat face is at the same distance √2 R from the charge, so the rim is an equipotential: true.\n(b) The angle between the field and the normal changes from point to point on the flat face, so the normal component is not constant: false.\n(c) The charge is outside the closed surface (curved + flat), so the total flux through it is zero, not Q/ε₀: false.\n(d) The flat face (radius R) is seen from the charge at a half-angle of 45°, so the flux through it is Q(1 − cos45°)/(2ε₀) = Q/(2ε₀)(1 − 1/√2), leaving the closed surface. The same amount enters through the curved surface, so its (outward) flux is −Q/(2ε₀)(1 − 1/√2): true.\nAnswer: (a) and (d)."},
{"y":"JEE Main 2015","tp":"evp","st":"Potential of charges and distributions","q":"A uniformly charged solid sphere of radius R has potential V₀ (measured with respect to ∞) on its surface. For this sphere the equipotential surfaces with potentials {3V₀;2}, {5V₀;4}, {3V₀;4} and {V₀;4} have radius R₁, R₂, R₃ and R₄ respectively. Then","o":["R₁ = 0 and R₂ < (R₄ − R₃)","2R < R₄","R₁ = 0 and R₂ > (R₄ − R₃)","R₁ ≠ 0 and (R₂ − R₁) > (R₄ − R₃)"],"c":[0,1],"s":"Inside the sphere V(r) = (V₀/2)(3 − r²/R²). Outside, V(r) = V₀R/r.\n3V₀/2: 3 − r²/R² = 3 gives r = 0, so R₁ = 0.\n5V₀/4: 3 − r²/R² = 5/2 gives R₂ = R/√2 ≈ 0.71R.\n3V₀/4 and V₀/4 are less than V₀, so these surfaces are outside: R₃ = 4R/3 and R₄ = 4R.\nR₄ − R₃ = 8R/3 ≈ 2.67R, which is greater than R₂, so (a) is true and (c) is false. R₁ = 0 makes (d) false.\n2R < 4R = R₄, so (b) is true. Answer: (a) and (b)."},
{"y":"JEE Advanced 2013","tp":"egs","st":"Gauss's law and symmetric bodies","q":"Two non-conducting spheres of radii R₁ and R₂ and carrying uniform volume charge densities +ρ and −ρ, respectively, are placed such that they partially overlap, as shown in the figure. At all points in the overlapping region,","fig":{"w":340,"h":200,"alt":"Two partly overlapping circles, the larger carrying charge density rho with radius R1 and the smaller carrying minus rho with radius R2, with the overlap shaded","d":[["c",105,100,80],["c",205,100,60],["p","M169 52 A60 60 0 0 0 169 148 A80 80 0 0 0 169 52 Z","f"],["t",70,100,"ρ","m"],["t",235,70,"−ρ","m"],["l",105,100,105,178,"a"],["t",112,150,"R₁"],["l",205,100,205,158,"a"],["t",212,140,"R₂"]]},"o":["the electrostatic field is zero.","the electrostatic potential is constant.","the electrostatic field is constant in magnitude.","the electrostatic field has same direction."],"c":[2,3],"s":"Inside a uniformly charged sphere the field at position r⃗ from its centre is ρr⃗/(3ε₀).\nAt a point in the overlap, with r⃗₁ and r⃗₂ measured from the centres of the +ρ and −ρ spheres: E⃗ = ρr⃗₁/(3ε₀) − ρr⃗₂/(3ε₀) = ρ(r⃗₁ − r⃗₂)/(3ε₀).\nr⃗₁ − r⃗₂ is the fixed vector from the centre of the +ρ sphere to the centre of the −ρ sphere, the same for every point.\nSo the field is not zero, has the same magnitude and the same direction everywhere in the overlap: (c) and (d) are true, (a) is false.\nA non-zero uniform field means the potential changes from point to point, so (b) is false. Answer: (c) and (d)."},
{"y":"IIT-JEE 2012","tp":"evp","st":"Potential of charges and distributions","q":"Six point charges are kept at the vertices of a regular hexagon of side L and centre O, as shown in the figure. Given that K = {1;4πε₀}{q;L²}, which of the following statement(s) is (are) correct?","fig":{"w":340,"h":210,"alt":"Regular hexagon ABCDEF of side L with charges A plus 2q, B plus q, C minus q, D minus 2q, E minus q, F plus q, centre O, line PR vertical and line ST horizontal through O","d":[["p","M140 68 L200 68 L230 120 L200 172 L140 172 L110 120 Z"],["l",170,120,140,68,"d"],["l",170,120,200,68,"d"],["l",170,120,230,120],["l",170,120,110,120],["l",170,120,200,172,"d"],["l",170,120,140,172,"d"],["l",170,68,170,172],["c",140,68,3,"F"],["c",200,68,3,"F"],["c",230,120,3,"F"],["c",200,172,3,"F"],["c",140,172,3,"F"],["c",110,120,3,"F"],["t",134,72,"F +q","e"],["t",206,72,"E −q"],["t",238,124,"D −2q"],["t",206,188,"C −q"],["t",134,188,"B +q","e"],["t",102,124,"A +2q","e"],["l",140,58,200,58,"b"],["t",170,50,"L","m"],["t",176,92,"P"],["t",176,160,"R"],["t",124,114,"S"],["t",208,114,"T"],["t",160,134,"O","e"]]},"o":["The electric field at O is 6K along OD.","The potential at O is zero.","The potential at all points on the line PR is same.","The potential at all points on the line ST is same."],"c":[0,1,2],"s":"From the figure the charges are A +2q, B +q, C −q, D −2q, E −q, F +q, each at distance L from O.\nField at O: A and D together give 2K + 2K = 4K along OD. B and E give 2K along OE, and C and F give 2K along OC. OE and OC are 60° on either side of OD, so their parts perpendicular to OD cancel and along OD they add 2 × 2K cos60° = 2K.\nTotal field = 4K + 2K = 6K along OD: (a) true.\nPotential at O = (k/L)(2q + q − q − 2q − q + q) = 0: (b) true.\nLine PR is the perpendicular bisector of FE, BC and AD, and each pair has equal and opposite charges, so V = 0 at every point of PR: (c) true.\nOn ST (the line AD) the points near A are at higher potential than those near D, so V is not the same: (d) false.\nAnswer: (a), (b) and (c)."},
{"y":"IIT-JEE 2011","tp":"ecn","st":"Charge sharing and earthing","q":"A spherical metal shell A of radius R_A and a solid metal sphere B of radius R_B (< R_A) are kept far apart and each is given charge +Q. Now they are connected by a thin metal wire. Then","o":["E_A^(inside) = 0","Q_A > Q_B","σ_A/σ_B = R_B/R_A","E_A^(on surface) < E_B^(on surface)"],"c":[0,1,2,3],"s":"The wire makes the potentials equal: kQ_A/R_A = kQ_B/R_B (k = 1/4πε₀), so Q_B = Q_A R_B/R_A.\nSince R_B < R_A, Q_B < Q_A, so (b) is true. The field inside a charged conducting shell is zero, so (a) is true.\nSurface charge density σ = Q/(4πR²): σ_A/σ_B = (Q_A/Q_B)(R_B²/R_A²) = (R_A/R_B)(R_B²/R_A²) = R_B/R_A, so (c) is true.\nThe field at the surface of a conductor is σ/ε₀. Since σ_A < σ_B (as R_B/R_A < 1), E_A < E_B at the surfaces: (d) is true.\nAll four statements are correct."},
{"y":"IIT-JEE 2011","tp":"egs","st":"Statements, matching and subjective","q":"Which of the following statement(s) is/are correct?","o":["If the electric field due to a point charge varies as r^(−2.5) instead of r⁻², then the Gauss law will still be valid.","The Gauss law can be used to calculate the field distribution around an electric dipole.","If the electric field between two point charges is zero somewhere, then the sign of the two charges is the same.","The workdone by the external force in moving a unit positive charge from point A at potential V_A to point B at potential V_B is (V_B − V_A)."],"c":[2,3],"s":"(a) Gauss's law holds because the field of a point charge falls as 1/r². With r^(−2.5) the flux through a sphere would depend on its radius: false.\n(b) Gauss's law is always true, but it helps to calculate the field only when the charge distribution has enough symmetry. A dipole has none: false.\n(c) If the field between two point charges is zero somewhere, the two fields cancel there, which is possible only if the charges have the same sign: true.\n(d) The external force just balances the electric force, so the work done by it equals the gain in potential energy: W = q(V_B − V_A) = V_B − V_A for a unit charge: true.\nAnswer: (c) and (d)."},
{"y":"IIT-JEE 2006","tp":"evp","st":"Field-potential relation and equipotentials","q":"A spherical symmetric charge system is centred at origin. Given, electric potential\nφ = {Q;4πε₀R₀} (r ≤ R₀),\nφ = {Q;4πε₀r} (r > R₀).","fig":{"w":340,"h":140,"alt":"Graph of potential against r, constant up to R0 and then falling smoothly","d":[["l",50,110,320,110,"a"],["l",50,110,50,10,"a"],["t",58,16,"φ"],["t",316,126,"r","e"],["l",50,35,150,35],["p","M150 35 Q175 80 300 103"],["l",150,35,150,110,"d"],["t",150,126,"R₀","m"]]},"o":["within r = 2R₀ total enclosed net charge is Q","electric field is discontinued at r = R₀","charge is only present at r = R₀","electrostatic energy is zero for r < R₀."],"c":[0,1,2,3],"s":"Inside (r ≤ R₀) the potential is constant, so E = −dφ/dr = 0 and no field energy is stored there: (d) is true. Gauss's law with E = 0 inside also means no charge lies inside r < R₀.\nOutside, φ = Q/(4πε₀r) is the potential of a total charge Q, so the net charge enclosed within r = 2R₀ is Q: (a) is true.\nOutside E = Q/(4πε₀r²), so just outside R₀ it is Q/(4πε₀R₀²), while just inside it is 0. The field jumps at r = R₀: (b) is true.\nSince there is no charge inside R₀ and none outside R₀ (the outside field is exactly that of charge Q at the centre), the whole charge Q must be a surface charge at r = R₀, a thin shell: (c) is true.\nAll four statements are correct. (The book's answer key lists only (a), (b) and (d).)"},
{"y":"IIT-JEE 1999","tp":"ecn","st":"Induced charge and shielding","q":"An ellipsoidal cavity is carved within a perfect conductor (figure). A positive charge q is placed at the centre of the cavity. The points A and B are on the cavity surface as shown in the figure. Then","fig":{"w":340,"h":200,"alt":"Ellipsoidal cavity with charge q at its centre, point A on the top wall close to the charge and point B at the right end of the cavity far from it","d":[["p","M50 100 A120 55 0 1 1 290 100 A120 55 0 1 1 50 100 Z"],["c",170,100,3,"F"],["t",176,116,"q"],["c",170,45,3,"F"],["t",170,36,"A","m"],["c",290,100,3,"F"],["t",296,96,"B"]]},"o":["electric field near A in the cavity = electric field near B in the cavity","charge density at A = charge density at B","potential at A = potential at B","total electric flux through the surface of the cavity is q/ε₀."],"c":[2,3],"s":"The wall of the cavity is the surface of a conductor, so it is an equipotential: V_A = V_B. Option (c) is true.\nThe field lines from q end on the induced negative charge. A is closer to q than B, so the field and the induced charge density are larger at A than at B: (a) and (b) are false.\nBy Gauss's law the flux through the cavity surface = enclosed charge/ε₀ = q/ε₀: (d) is true.\nAnswer: (c) and (d)."},
{"y":"IIT-JEE 1998","tp":"evp","st":"Potential of charges and distributions","q":"A charge +q is fixed at each of the points x = x₀, x = 3x₀, x = 5x₀, ..., x = ∞ on the x-axis, and a charge −q is fixed at each of the points x = 2x₀, x = 4x₀, x = 6x₀, ..., x = ∞. Here x₀ is a positive constant. Take the potential at a point due to a charge Q at a distance r from it to be Q/(4πε₀r). Then the potential at the origin due to the above system of charges is","o":["0","{q;8πε₀x₀ ln2}","∞","{q ln2;4πε₀x₀}"],"c":3,"s":"Add the potentials of all the charges at the origin:\nV = (q/4πε₀x₀)[1 − 1/2 + 1/3 − 1/4 + ...].\nThe series 1 − 1/2 + 1/3 − 1/4 + ... equals ln 2.\nSo V = q ln2/(4πε₀x₀): option (d)."},
{"y":"IIT-JEE 1992","tp":"evp","st":"Potential energy and work","q":"Two identical thin rings, each of radius R metre, are coaxially placed a distance R metre apart. If Q₁ coulomb and Q₂ coulomb, are respectively the charges uniformly spread on the two rings, the workdone in moving a charge q from the centre of one ring to that of the other is","o":["zero","{q(Q₁ − Q₂)(√2 − 1);4√2πε₀R}","{q√2(Q₁ + Q₂);4πε₀R}","{q(Q₁ + Q₂)(√2 + 1);4√2πε₀R}"],"c":1,"s":"Every point of the other ring is at distance √(R² + R²) = √2 R from the centre of a ring.\nPotential at the centre of ring 1: V₁ = (1/4πε₀)[Q₁/R + Q₂/(√2R)]. At the centre of ring 2: V₂ = (1/4πε₀)[Q₂/R + Q₁/(√2R)].\nMoving q from the centre of the ring carrying Q₂ to the centre of the ring carrying Q₁: W = q(V₁ − V₂).\nV₁ − V₂ = (Q₁ − Q₂)(1 − 1/√2)/(4πε₀R) = (Q₁ − Q₂)(√2 − 1)/(4√2 πε₀R).\nSo W = q(Q₁ − Q₂)(√2 − 1)/(4√2 πε₀R): option (b). (Moving the other way only changes the sign.)"},
{"y":"IIT-JEE 1989","tp":"ecn","st":"Induced charge and shielding","q":"A solid conducting sphere having a charge Q is surrounded by an uncharged concentric conducting hollow spherical shell. Let the potential difference between the surface of the solid sphere and that of the outer surface of the hollow shell be V. If the shell is now given a charge of −3Q, the new potential difference between the same two surfaces is","o":["V","2V","4V","−2V"],"c":0,"s":"The field in the gap between the sphere and the shell depends only on the charge Q of the inner sphere (the shell's inner surface carries −Q).\nSo the potential difference between the sphere and the shell is Q/(4πε₀)(1/a − 1/b) and does not depend on any extra charge given to the shell.\nA conducting shell is at one potential throughout, so the inner and outer surface of the shell are at the same potential.\nGiving the shell −3Q shifts the potentials of the shell and the sphere by the same amount, so the difference stays V: option (a)."},
{"y":"IIT-JEE 1987","tp":"ecl","st":"Equilibrium and motion of charges","q":"A charge q is placed at the centre of the line joining two equal charges Q. The system of the three charges will be in equilibrium if q is equal to","o":["−Q/2","−Q/4","+Q/4","+Q/2"],"c":1,"s":"Let the distance between the two Q charges be d. The middle charge is in equilibrium by symmetry.\nFor one Q charge, the repulsion from the other Q must be balanced by the pull of q, so q must be negative.\nkQ²/d² = kQ|q|/(d/2)² = 4kQ|q|/d²\nSo |q| = Q/4 and q = −Q/4: option (b)."},
{"y":"JEE Main 2025 · 28 Jan · Shift 2","tp":"efl","st":"Electric dipole","q":"An electric dipole of dipole moment 6 × 10⁻⁶ Cm is placed in uniform electric field of magnitude 10⁶ V/m. Initially, the dipole moment is parallel to electric field. The work that needs to be done on the dipole to make its dipole moment opposite to the field, will be ____ J.","n":12,"s":"Potential energy of a dipole: U = −pE cosθ.\nParallel: U₁ = −pE. Opposite: U₂ = +pE.\nWork needed = U₂ − U₁ = 2pE.\nW = 2 × 6×10⁻⁶ × 10⁶ = 12 J."},
{"y":"JEE Main 2024 · 9 Apr · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"At the centre of a half ring of radius R = 10 cm and linear charge density 4 nC m⁻¹, the potential is x π V. The value of x is ____.","n":36,"s":"Every element of the half ring is at the same distance R from the centre, so V = kQ/R.\nThe charge is Q = λ × πR, so V = kλπR/R = kλπ.\nV = 9×10⁹ × 4×10⁻⁹ × π = 36π volt.\nSo x = 36."},
{"y":"JEE Main 2024 · 31 Jan · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"The distance between charges +q and −q is 2l and between +2q and −2q is 4l. The electrostatic potential at point P at a distance r from centre O (r ≫ l) is −α[{ql;r²}]×10⁹ V where the value of α is ____.\n(Use {1;4πε₀} = 9×10⁹ Nm²C⁻²)","fig":{"w":340,"h":150,"alt":"Charges plus 2q, minus q, plus q and minus 2q on a line with centre O in the middle, and point P on a line making 60 degrees with the axis","d":[["l",20,110,320,110],["c",40,110,3,"F"],["c",100,110,3,"F"],["c",160,110,3,"F"],["c",220,110,3,"F"],["c",280,110,3,"F"],["t",40,128,"+2q","m"],["t",100,128,"−q","m"],["t",160,128,"O","m"],["t",220,128,"+q","m"],["t",280,128,"−2q","m"],["l",160,110,225,30],["c",225,30,3,"F"],["t",233,28,"P"],["t",172,100,"60°","s"]]},"n":27,"s":"The charges lie on a line with O at the centre: +2q at −2l, −q at −l, +q at +l, −2q at +2l.\nNet charge = 2q − q + q − 2q = 0, so far away only the dipole term is left.\nDipole moment (along x): p = Σqx = (2q)(−2l) + (−q)(−l) + (q)(l) + (−2q)(2l) = −4ql + ql + ql − 4ql = −6ql.\nV = k p cosθ/r² with θ = 60°: V = 9×10⁹ × (−6ql) × ½ / r² = −27×10⁹ (ql/r²) V.\nSo α = 27."},
{"y":"JEE Advanced 2024","tp":"evp","st":"Potential of charges and distributions","q":"An infinitely long thin wire, having a uniform charge density per unit length of 5 nC/m, is passing through a spherical shell of radius 1 m, as shown in the figure. A 10 nC charge is distributed uniformly over the spherical shell. If the configuration of the charges remains static, the magnitude of the potential difference between points P and R, in Volt, is ____.\n[Given: In SI units {1;4πε₀} = 9×10⁹, ln 2 = 0.7. Ignore the area pierced by the wire.]","fig":{"w":340,"h":260,"alt":"Spherical shell of radius 1 m with a long straight wire through its centre; point P is 0.5 m from the wire inside the shell and point R is 2 m from the wire outside","d":[["c",130,130,100],["l",130,130,130,12,"a"],["l",130,130,130,248,"a"],["t",136,22,"∞"],["t",136,246,"−∞"],["l",130,130,330,130],["c",180,130,3,"F"],["t",180,122,"P","m"],["c",330,130,3,"F"],["t",330,122,"R","e"],["l",130,144,180,144,"b"],["t",155,158,"0.5 m","ms"],["l",130,178,330,178,"b"],["t",230,194,"2 m","ms"],["l",130,130,60,60,"a"],["t",80,100,"1 m","e"]]},"n":171,"s":"The potential difference is the sum of the wire part and the shell part. P is inside the shell, 0.5 m from the wire. R is outside, 2 m from the wire and from the centre.\nWire: V_P − V_R = (λ/2πε₀) ln(2/0.5) = 2kλ ln4 = 2 × 9×10⁹ × 5×10⁻⁹ × 2 × 0.7 = 126 V.\nShell: inside, V = kQ/1 = 9×10⁹ × 10×10⁻⁹ = 90 V. At R, V = kQ/2 = 45 V. Difference = 45 V.\nBoth parts make P the higher potential, so they add: 126 + 45 = 171 V."},
{"y":"JEE Main 2023 · 8 Apr · Shift 1","tp":"efl","st":"Electric dipole","q":"An electric dipole of dipole moment 6.0 × 10⁻⁶ C m placed in a uniform electric field of 1.5 × 10³ N C⁻¹ in such a way that dipole moment is along electric field. The work done in rotating dipole by 180° in this field will be ____ m J.","n":18,"s":"Turning the dipole from θ = 0° to θ = 180° changes its energy from −pE to +pE.\nWork = 2pE = 2 × 6.0×10⁻⁶ × 1.5×10³ = 1.8×10⁻² J.\n1.8×10⁻² J = 18 mJ."},
{"y":"JEE Main 2023 · 10 Apr · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"Three concentric spherical metallic shells X, Y and Z of radius a, b and c respectively [a < b < c] have surface charge densities σ, −σ and σ, respectively. If the shells X and Z are at same potential. If the radii of X and Y are 2 cm and 3 cm, respectively. The radius of shell Z is ____ cm.","n":5,"s":"Charges: Q_X = 4πa²σ, Q_Y = −4πb²σ, Q_Z = 4πc²σ.\nV_X = k(Q_X/a + Q_Y/b + Q_Z/c) = (σ/ε₀)(a − b + c).\nV_Z = k(Q_X + Q_Y + Q_Z)/c = (σ/ε₀)(a² − b² + c²)/c.\nV_X = V_Z gives ac − bc + c² = a² − b² + c², so c(a − b) = (a − b)(a + b) and c = a + b.\nc = 2 + 3 = 5 cm."},
{"y":"JEE Main 2023 · 12 Apr · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"64 identical drops each charged upto potential of 10 mV combined to form a bigger drop. The potential of the bigger drop will be ____ mV.","n":160,"s":"Charge is conserved: Q = 64q. Volume is conserved: R³ = 64r³, so R = 4r.\nV = kQ/R = k × 64q/(4r) = 16 × (kq/r).\nEach small drop has kq/r = 10 mV, so V = 16 × 10 = 160 mV."},
{"y":"JEE Main 2023 · 29 Jan · Shift 2","tp":"egs","st":"Non-uniform charge distributions","q":"For a charged spherical ball, electrostatic potential inside the ball varies with r as V = 2ar² + b. Here, a and b are constant and r is the distance from the center. The volume charge density inside the ball is −λaε. The value of λ is ____.\n(ε = permittivity of the medium)","n":12,"s":"Field: E = −dV/dr = −4ar (along the radius).\nE grows in proportion to r, so the density is uniform and E = ρr/(3ε) inside (Gauss's law).\nρ = 3εE/r = 3ε(−4a) = −12aε.\nComparing with ρ = −λaε gives λ = 12."},
{"y":"JEE Main 2022 · 25 Jun · Shift 2","tp":"evp","st":"Potential of charges and distributions","q":"27 identical drops are charged at 22 V each. They combine to form a bigger drop. The potential of the bigger drop will be ____ V.","n":198,"s":"Charge: Q = 27q. Volume: R³ = 27r³, so R = 3r.\nV = kQ/R = k × 27q/(3r) = 9 × (kq/r).\nV = 9 × 22 = 198 V."},
{"y":"JEE Main 2021 · 25 Feb · Shift 1","tp":"evp","st":"Potential of charges and distributions","q":"512 identical drops of mercury are charged to a potential of 2 V each. The drops are joined to form a single drop. The potential of this drop is ____ V.","n":128,"s":"Charge: Q = 512q. Volume: R³ = 512r³, so R = 8r.\nV = kQ/R = k × 512q/(8r) = 64 × (kq/r).\nV = 64 × 2 = 128 V."},
{"y":"JEE Main 2021 · 26 Feb · Shift 1","tp":"evp","st":"Potential energy and work","q":"In an electrical circuit, a battery is connected to pass 20 C of charge through it in a certain given time. The potential difference between two plates of the battery is maintained at 15 V. The work done by the battery is ____ J.","n":300,"s":"Work done in moving a charge q through a potential difference V is W = qV.\nW = 20 C × 15 V = 300 J."},
{"y":"JEE Main 2021 · 26 Feb · Shift 2","tp":"evp","st":"Potential energy and work","q":"27 similar drops of mercury are maintained at 10 V each. All these spherical drops combine into a single big drop. The potential energy of the bigger drops is ____ times that of a smaller drop.","n":243,"s":"Small drop: charge q, radius r. Big drop: charge 27q, radius R = 3r.\nEnergy of a charged sphere: U = (1/2)QV = Q²/(8πε₀R).\nU_big/U_small = (27q)²/(3r) ÷ q²/r = 729/3 = 243."},
{"y":"JEE Advanced 2021","tp":"evp","st":"Field-potential relation and equipotentials","q":"Two point charges −Q and +{Q;√3} are placed in the xy-plane at the origin (0, 0) and a point (2, 0), respectively, as shown in the figure. This results in an equipotential circle of radius R and potential V = 0 in the xy-plane with its centre at (b, 0). All lengths are measured in metres.\nThe value of R is ____ metre.","fig":{"w":340,"h":200,"alt":"x and y axes with charge minus Q at the origin, charge plus Q over root 3 at x = 2, and a dashed circle centred at x = 3 passing around the second charge","d":[["l",20,100,330,100,"a"],["l",40,190,40,10,"a"],["t",326,116,"x","e"],["t",48,14,"y"],["c",40,100,3,"F"],["t",48,92,"−Q"],["c",140,100,3,"F"],["t",126,120,"+Q/√3"],["c",190,100,86.6,"d"]]},"n":1.73,"s":"At a point on the V = 0 circle: k(−Q/d₁ + (Q/√3)/d₂) = 0, so d₁ = √3 d₂ (d₁ from the origin, d₂ from (2, 0)).\nx² + y² = 3[(x − 2)² + y²] → 2x² + 2y² − 12x + 12 = 0 → (x − 3)² + y² = 3.\nSo the circle has centre (3, 0) and radius R = √3 = 1.73 m."},
{"y":"JEE Advanced 2021","tp":"evp","st":"Field-potential relation and equipotentials","q":"Two point charges −Q and +{Q;√3} are placed in the xy-plane at the origin (0, 0) and a point (2, 0), respectively, as shown in the figure. This results in an equipotential circle of radius R and potential V = 0 in the xy-plane with its centre at (b, 0). All lengths are measured in metres.\nThe value of b is ____ metre.","fig":{"w":340,"h":200,"alt":"x and y axes with charge minus Q at the origin, charge plus Q over root 3 at x = 2, and a dashed circle centred at x = 3 passing around the second charge","d":[["l",20,100,330,100,"a"],["l",40,190,40,10,"a"],["t",326,116,"x","e"],["t",48,14,"y"],["c",40,100,3,"F"],["t",48,92,"−Q"],["c",140,100,3,"F"],["t",126,120,"+Q/√3"],["c",190,100,86.6,"d"]]},"n":3,"s":"At a point on the V = 0 circle: k(−Q/d₁ + (Q/√3)/d₂) = 0, so d₁ = √3 d₂ (d₁ from the origin, d₂ from (2, 0)).\nx² + y² = 3[(x − 2)² + y²] → 2x² + 2y² − 12x + 12 = 0 → (x − 3)² + y² = 3.\nSo the centre is at (3, 0): b = 3 m (and R = √3 m)."},
{"y":"JEE Advanced 2020","tp":"evp","st":"Potential energy and work","q":"A point charge q of mass m is suspended vertically by a string of length l. A point dipole of dipole moment p⃗ is now brought towards q from infinity so that the charge moves away. The final equilibrium position of the system including the direction of the dipole, the angles and distances is shown in the figure. If the workdone in bringing the dipole to this position is N × (mgh), where g is the acceleration due to gravity, then the value of N is ____. (Note that for three coplanar forces keeping a point mass in equilibrium, {F;sinθ} is the same for all forces, where F is any one of the forces and θ is the angle between the other two forces.)","fig":{"w":340,"h":200,"alt":"Pendulum string of length l hanging from a top point to the dipole position, the string of charge q swung by angle alpha, the charge raised by h above the dipole level and the dipole pointing towards the charge","d":[["l",150,20,150,170,"d"],["l",150,20,265,116],["l",150,170,265,116,"d"],["l",150,170,300,170,"d"],["l",290,170,290,116,"b"],["t",296,148,"h"],["c",265,116,5,"F"],["t",274,108,"q"],["t",140,100,"l","e"],["t",216,56,"l"],["t",158,44,"α"],["l",150,170,190,151,"aB"],["t",142,186,"p⃗","e"],["t",172,190,"distance 2l sin(α/2)","s"]]},"n":2,"s":"Forces on q: weight mg (down), tension T (along the string) and the push F of the dipole (along the line joining them, away from the dipole).\nThe triangle (suspension point, dipole, q) is isosceles with sides l, l and top angle α. So the distance is r = 2l sin(α/2) and the line from the dipole to q makes angle α/2 with the horizontal.\nThe angle between mg and F is 90° + α/2, between T and F also 90° + α/2, and between mg and T it is 180° − α. So F/sinα = mg/cos(α/2), giving F = 2mg sin(α/2).\nOn the axis of a dipole F = q × 2kp/r³, and the interaction energy is U = kpq/r² = Fr/2 = (2mg sin(α/2))(2l sin(α/2))/2 = 2mgl sin²(α/2).\nThe charge rises by h = l(1 − cosα) = 2l sin²(α/2), so U = mgh.\nWork done = gain in gravitational energy + interaction energy = mgh + mgh = 2mgh. So N = 2."},
{"y":"JEE Main 2025 · 8 Apr · Shift 2","tp":"evp","st":"Statements, matching and subjective","q":"Given below are two statements : one is labelled as Assertion (A) and the other is labelled as Reason (R).\nAssertion (A) : Work done in moving a test charge between two points inside a uniformly charged spherical shell is zero, no matter which path is chosen.\nReason (R) : Electrostatic potential inside a uniformly charged spherical shell is constant and is same as that on the surface of the shell.\nIn the light of the above statements, choose the correct answer from the options given below","o":["A is false but R is true","A is true but R is false","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A"],"c":2,"s":"Inside a uniformly charged shell the field is zero, so the potential is constant and equal to the value on the surface: R is true.\nWork between two points = q × (potential difference) = 0, whatever the path, because the potential is the same everywhere inside: A is true.\nR is exactly the reason for A: option (c)."},
{"y":"JEE Main 2024 · 27 Jan · Shift 2","tp":"evp","st":"Statements, matching and subjective","q":"Given below are two statements : one is labelled as Assertion (A) and the other is labelled as Reason (R).\nAssertion (A) : Work done by electric field on moving a positive charge on an equipotential surface is always zero.\nReason (R) : Electric lines of force are always perpendicular to equipotential surfaces.\nIn the light of the above statements, choose the most appropriate answer from the options given below.","o":["Both (A) and (R) are correct and (R) is the correct explanation of (A).","Both (A) and (R) are correct but (R) is not the correct explanation of (A).","(A) is not correct but (R) is correct.","(A) is correct but (R) is not correct."],"c":0,"s":"On an equipotential surface ΔV = 0, so the work W = qΔV = 0: A is correct.\nField lines are perpendicular to equipotential surfaces (a field component along the surface would make V change along it): R is correct.\nBecause the force qE is perpendicular to any displacement along the surface, the work is zero. So R explains A: option (a)."},
{"y":"JEE Main 2022 · 29 Jul · Shift 1","tp":"ecn","st":"Statements, matching and subjective","q":"Given below are two statements.\nStatement I : Electric potential is constant within and at the surface of each conductor.\nStatement II : Electric field just outside a charged conductor is perpendicular to the surface of the conductor at every point.\nIn the light of the above statements, choose the most appropriate answer from the options given below.","o":["Both statement I and statement II are correct.","Both statement I and statement II are incorrect.","Statement I is correct but statement II is incorrect.","Statement I is incorrect but statement II is correct."],"c":0,"s":"In equilibrium E = 0 inside a conductor, so no work is needed to move a charge within it: the potential is the same inside and on the surface. Statement I is correct.\nIf the field just outside had a component along the surface, the surface charges would move. So in equilibrium it is perpendicular to the surface at every point. Statement II is correct.\nBoth statements are correct: option (a)."},
{"y":"AIEEE 2012","tp":"evp","st":"Statements, matching and subjective","q":"This question has Statement 1 and Statement 2. Of the four choices given after the statements, choose the one that best describes the two statements.\nAn insulating solid sphere of radius R has a uniformly positive charge density ρ. As a result of this uniform charge distribution there is a finite value of electric potential at the centre of the sphere, at the surface of the sphere and also at a point outside the sphere. The electric potential at infinity is zero.\nStatement 1 : When a charge q is taken from the centre to the surface of the sphere, its potential energy changes by {qρ;3ε₀}.\nStatement 2 : The electric field at a distance r (r < R) from the centre of the sphere is {ρr;3ε₀}.","o":["Statement 1 is true, Statement 2 is false.","Statement 1 is false, Statement 2 is true.","Statement 1 is true, Statement 2 is the correct explanation of Statement 1.","Statement 1 is true, Statement 2 is true; Statement 2 is not the correct explanation of Statement 1."],"c":1,"s":"Inside a uniformly charged sphere E = ρr/(3ε₀) (Gauss's law), so Statement 2 is true.\nPotential difference between the centre and the surface: V(0) − V(R) = ∫E dr from 0 to R = ρR²/(6ε₀).\nSo the change in potential energy is qρR²/(6ε₀), not qρ/(3ε₀) (which does not even have the dimension of energy). Statement 1 is false.\nStatement 1 false, Statement 2 true: option (b)."},
{"y":"AIEEE 2009","tp":"evp","st":"Statements, matching and subjective","q":"Statement-1 : For a charged particle moving from point P to point Q, the net work done by an electrostatic field on the particle is independent of the path connecting point P to point Q.\nStatement-2 : The net work done by a conservative force on an object moving along a closed loop is zero.\nThis question contains Statement-1 and Statement-2. Of the four choices given after the statements, choose the one that best describes the two statements.","o":["Statement-1 is true, Statement-2 is false","Statement-1 is true, Statement-2 is true; Statement-2 is the correct explanation of Statement-1","Statement-1 is true, Statement-2 is true; Statement-2 is not the correct explanation of Statement-1","Statement-1 is false, Statement-2 is true"],"c":2,"s":"Statement 1 is true: the electrostatic force is conservative, so the work from P to Q depends only on the end points.\nStatement 2 is true: for any conservative force the work around a closed loop is zero.\nStatement 2 is a general property of conservative forces. It does not say why the electrostatic force is conservative (that comes from Coulomb's law being a central force), so the official key does not treat it as the explanation of Statement 1.\nAnswer: option (c)."},
{"y":"IIT-JEE 2008","tp":"ecn","st":"Statements, matching and subjective","q":"Statement-1 : For practical purposes, the earth is used as a reference at zero potential in electrical circuits.\nStatement-2 : The electrical potential of a sphere of radius R with charge Q uniformly distributed on the surface is given by {Q;4πε₀R}.","o":["Statement-1 is true, Statement-2 is false","Statement-1 is true, Statement-2 is true; Statement-2 is the correct explanation of Statement-1","Statement-1 is true, Statement-2 is true; Statement-2 is not the correct explanation of Statement-1","Statement-1 is false, Statement-2 is true"],"c":1,"s":"Statement 2 is true: it is the potential of a charged conducting sphere.\nFor the earth R is very large (about 6400 km), so even a large charge added to or removed from it changes V = Q/(4πε₀R) by a negligible amount. Its potential stays practically constant, so it can be taken as the zero reference. Statement 1 is true and Statement 2 explains it.\nAnswer: option (b)."},
{"y":"IIT-JEE 2005","tp":"evp","st":"Statements, matching and subjective","q":"A conducting liquid bubble of radius a and thickness t (t ≪ a) is charged to potential V. If the bubble collapses to a droplet, find the potential on the droplet.","a":"V (a/3t)^(1/3)","s":"Charge on the bubble: Q = 4πε₀aV. Charge is conserved when it collapses.\nVolume of liquid = 4πa²t. Droplet of radius r: (4/3)πr³ = 4πa²t, so r = (3a²t)^(1/3).\nPotential of the droplet: V′ = Q/(4πε₀r) = aV/r = aV/(3a²t)^(1/3).\nV′ = V (a/3t)^(1/3)."},
{"y":"IIT-JEE 2004","tp":"evp","st":"Statements, matching and subjective","q":"Two uniformly charged plane sheets S₁ and S₂ having charge densities σ₁ and σ₂ (σ₁ > σ₂) are placed at a distance d parallel to each other. A charge q₀ is moved along a line of length a (a < d) at an angle 45° with the normal to S₁. Calculate the workdone by the electric field.","a":"q₀(σ₁ − σ₂)a/(2√2 ε₀)","s":"Each large sheet gives a uniform field σ/(2ε₀). Between the sheets the two fields partly cancel: E = (σ₁ − σ₂)/(2ε₀), along the normal.\nOnly the component of the displacement along the normal counts: a cos45° = a/√2.\nW = q₀ E a cos45° = q₀ (σ₁ − σ₂)/(2ε₀) × a/√2.\nW = q₀(σ₁ − σ₂)a/(2√2 ε₀)."},
{"y":"IIT-JEE 2003","tp":"efl","st":"Statements, matching and subjective","q":"A charge +Q is fixed at the origin of the co-ordinate system while a small electric dipole of dipole moment p⃗ pointing away from the charge along the x-axis is set free from a point far away from the origin.\n(a) Calculate the kinetic energy of the dipole when it reaches a point (d, 0).\n(b) Calculate the force on the charge +Q at this moment.","a":"(a) Qp/(4πε₀d²)   (b) (1/4πε₀)(2pQ/d³) î","s":"At (d, 0) the field of +Q is E = Q/(4πε₀d²) along +x, the same direction as p.\n(a) Energy of the dipole there U = −pE = −Qp/(4πε₀d²), and U = 0 far away. Energy conservation: KE = 0 − U = Qp/(4πε₀d²).\n(b) The force on the dipole is F = −dU/dd = −2Qp/(4πε₀d³), i.e. it is attracted towards Q (the nearer end of the dipole is negative).\nBy Newton's third law the force on +Q is 2pQ/(4πε₀d³) along +x (towards the dipole)."},
{"y":"IIT-JEE 2003","tp":"evp","st":"Statements, matching and subjective","q":"Charges +q and −q are located at the corners of a cube of side a as shown in the figure. Find the work done to separate the charges to infinity.","fig":{"w":260,"h":230,"alt":"Cube with alternating charges plus q and minus q at its eight corners","d":[["r",50,110,100,100],["l",90,70,190,70],["l",190,70,190,170],["l",50,110,90,70],["l",150,110,190,70],["l",150,210,190,170],["l",90,170,50,210,"d"],["l",90,170,190,170,"d"],["l",90,170,90,70,"d"],["c",50,110,2.5,"F"],["c",150,110,2.5,"F"],["c",50,210,2.5,"F"],["c",150,210,2.5,"F"],["c",90,70,2.5,"F"],["c",190,70,2.5,"F"],["c",90,170,2.5,"F"],["c",190,170,2.5,"F"],["t",44,108,"+q","e"],["t",156,124,"−q"],["t",44,222,"−q","e"],["t",154,224,"+q"],["t",84,62,"−q","e"],["t",196,66,"+q"],["t",96,186,"+q"],["t",196,184,"−q"]]},"a":"5.824 (q²/4πε₀a)","s":"Adjacent corners (opposite signs) and all other pairs: the 28 pairs are 12 edges (distance a, unlike charges), 12 face diagonals (a√2, like charges) and 4 body diagonals (a√3, unlike charges).\nPotential energy U = (kq²/a)[−12 + 12/√2 − 4/√3] = (kq²/a)(−12 + 8.485 − 2.309) = −5.824 kq²/a.\nTo separate all the charges to infinity the work needed is W = −U = 5.824 q²/(4πε₀a)."},
{"y":"IIT-JEE 2002","tp":"evp","st":"Statements, matching and subjective","q":"Four points charge + 8 μC, − 1 μC, − 1 μC, and + 8 μC are fixed at the points −√{27;2} m, −√{3;2} m, +√{3;2} m and +√{27;2} m respectively on the y-axis. A particle of mass 6 × 10⁻⁴ kg and charge + 0.1 μC moves along the x-direction. Its speed at x = + ∞ is v₀. Find the least value of v₀ for which the particle is at the origin. Find also the kinetic energy of the particle at the origin. Assume that space is gravity free.\nGiven {1;4πε₀} = 9 × 10⁹ Nm²/C².","a":"v₀ = 3 m/s; kinetic energy at the origin ≈ 2.5×10⁻⁴ J (about 3×10⁻⁴ J)","s":"At distance x on the x-axis: V(x) = 10⁻⁶k[16/√(x² + 13.5) − 2/√(x² + 1.5)].\nThe particle is repelled, so the least v₀ is set by the highest point of V on the x-axis. dV/dx = 0 gives 4(x² + 1.5) = x² + 13.5, so x² = 2.5.\nThere V_max = 10⁻⁶ × 9×10⁹ × (16/4 − 2/2) = 2.7×10⁴ V. Energy needed: qV_max = 0.1×10⁻⁶ × 2.7×10⁴ = 2.7×10⁻³ J = ½mv₀², so v₀² = 2 × 2.7×10⁻³/(6×10⁻⁴) = 9 and v₀ = 3 m/s.\nAt the origin V(0) = 9×10³ × (16/√13.5 − 2/√1.5) = 2.45×10⁴ V, so qV(0) = 2.45×10⁻³ J.\nKE at origin = 2.7×10⁻³ − 2.45×10⁻³ ≈ 2.5×10⁻⁴ J (about 3×10⁻⁴ J)."},
{"y":"IIT-JEE 1999","tp":"evp","st":"Statements, matching and subjective","q":"A non-conducting disc of radius a and uniform positive surface charge density σ is placed on the ground, with its axis vertical. A particle of mass m and positive charge q is dropped, along the axis of the disc, from a height H with zero initial velocity. The particle has q/m = {4ε₀g;σ}.\n(a) Find the value of H if the particle just reaches the disc.\n(b) Sketch the potential energy of the particle as a function of its height and find its equilibrium position.","fig":{"w":340,"h":240,"alt":"Graph of potential energy against height: starts at 2mga, dips to a minimum of root 3 mga at height a over root 3, then rises steadily","d":[["l",50,220,320,220,"a"],["l",50,220,50,16,"a"],["t",58,18,"U"],["t",316,236,"z","e"],["p","M50 140 L55 143.6 L62.5 147.5 L78.9 150.7 L100 146.9 L125 135.8 L150 121.1 L200 87 L250 50.2 L275 31"],["l",78.9,150.7,78.9,220,"d"],["t",79,234,"a/√3","ms"],["l",50,150.7,78.9,150.7,"d"],["t",46,168,"√3 mga","e"],["t",46,138,"2mga","e"]]},"a":"(a) H = 4a/3   (b) equilibrium (stable) at height a/√3, where the potential energy is √3 mga","s":"Potential on the axis at height z: V(z) = (σ/2ε₀)(√(a² + z²) − z). Note qσ/(2ε₀) = 2mg.\n(a) Energy conservation from H to the disc (speed zero at both): mgH = q[V(0) − V(H)] = 2mg[a − √(a² + H²) + H]. This gives 2√(a² + H²) = 2a + H, so 3H² = 4aH and H = 4a/3.\n(b) Total potential energy U(z) = mgz + qV = mg[2√(a² + z²) − z]. U(0) = 2mga, and for large z it grows like mgz.\ndU/dz = 0: 2z/√(a² + z²) = 1, so z = a/√3.\nThere U = √3 mga, the minimum of the curve: a stable equilibrium at height a/√3."},
{"y":"IIT-JEE 1998","tp":"ecn","st":"Statements, matching and subjective","q":"A conducting sphere S₁ of radius r is attached to an insulating handle. Another conducting sphere S₂ of radius R is mounted on an insulating stand. S₂ is initially uncharged. S₁ is given a charge Q, brought into contact with S₂, and removed. S₁ is recharged such that the charge on it is again Q, and it is again brought into contact with S₂ and removed. This procedure is repeated n times.\n(a) Find the electrostatic energy of S₂ after n such contacts.\n(b) What is the limiting value of this energy as n → ∞?","a":"(a) U = (Q²R/(8πε₀r²))[1 − (R/(R+r))ⁿ]²   (b) Q²R/(8πε₀r²)","s":"On contact the two spheres reach the same potential, so the total charge divides in proportion to the radii: S₂ gets the fraction R/(R + r).\nLet q_n be the charge on S₂ after n contacts: q_n = (R/(R + r))(q_(n−1) + Q), with q₀ = 0. Summing the geometric series gives q_n = (QR/r)[1 − (R/(R + r))ⁿ].\n(a) Energy of S₂: U = q_n²/(8πε₀R) = (Q²R/(8πε₀r²))[1 − (R/(R + r))ⁿ]².\n(b) As n → ∞ the bracket tends to 1: U → Q²R/(8πε₀r²). (Then S₂ is at the potential Q/(4πε₀r) of the charged S₁ and no more charge flows.)"},
{"y":"IIT-JEE 1993","tp":"evp","st":"Statements, matching and subjective","q":"A circular ring of radius R with uniform positive charge density λ per unit length is located in the y-z plane with its centre at the origin O. A particle of mass m and positive charge q is projected from the point P(R√3, 0, 0) on the positive x-axis directly towards O, with an initial speed v. Find the smallest (non-zero) value of the speed v such that the particle does not return to P.","a":"√(qλ/(2ε₀m))","s":"Potential on the axis of a ring of charge 2πRλ: V(x) = λR/(2ε₀√(R² + x²)).\nAt P (x = √3R): V_P = λR/(2ε₀ × 2R) = λ/(4ε₀). At O: V_O = λ/(2ε₀), the highest value on the axis.\nThe positive particle is repelled, so it must climb to O. If it just reaches O it is pushed on beyond it and does not come back.\n½mv² = q(V_O − V_P) = qλ/(4ε₀), so v = √(qλ/(2ε₀m))."},
{"y":"IIT-JEE 1992","tp":"evp","st":"Statements, matching and subjective","q":"(a) A charge of Q coulomb is uniformly distributed over a spherical volume of radius R metre. Obtain an expression for the energy of the system.\n(b) What will be the corresponding expression for the energy needed to completely disassemble the planet earth against the gravitational pull amongst its constituent particles? Assume the earth to be a sphere of uniform mass density. Calculate this energy, given the product of the mass and the radius of the earth to be 2.5 × 10³¹ kg/m.\n(c) If the same charge Q coulomb as in part (a) above is given to a spherical conductor of the same radius R, what would be the energy of the system?","a":"(a) 3Q²/(20πε₀R)   (b) 3GM²/(5R) = (3/5)gMR ≈ 1.5×10³² J   (c) Q²/(8πε₀R)","s":"(a) Build the sphere layer by layer. Charge inside radius r is Qr³/R³; the layer dr carries 3Qr²dr/R³. dU = (1/4πε₀)(Qr³/R³)(3Qr²dr/R³)/r = 3Q²r⁴dr/(4πε₀R⁶). Integrating from 0 to R: U = 3Q²/(20πε₀R).\n(b) Replace Q²/(4πε₀) by GM² (attraction instead of repulsion): the energy needed is 3GM²/(5R). Using GM = gR²: 3GM²/(5R) = (3/5)gMR = 0.6 × 9.8 × 2.5×10³¹ ≈ 1.5×10³² J.\n(c) In a conductor all the charge sits on the surface: U = Q²/(8πε₀R)."},
{"y":"IIT-JEE 1991","tp":"evp","st":"Statements, matching and subjective","q":"Two fixed charges −2Q and Q are located at the points with coordinates (−3a, 0) and (+3a, 0) respectively in the x-y plane.\n(a) Show that all points in the x - y plane, where the electric potential due to the two charges is zero, lie on a circle. Find its radius and the location of its centre.\n(b) Give the expression V(x) at a general point on the x-axis and sketch the function V(x) on the whole x-axis.\n(c) If a particle of charge +q starts from rest at the centre of the circle, show by a short quantitative argument that the particle will eventually cross the circle. Find its speed when it does so.","fig":{"w":340,"h":220,"alt":"Sketch of V against x: negative and falling to minus infinity at x = -3a, rising through zero at a to plus infinity at 3a, then falling through zero at 9a and tending to zero from below","d":[["l",10,110,330,110,"a"],["t",326,126,"x","e"],["l",130,215,130,5,"a"],["t",136,14,"V"],["l",70,10,70,215,"d"],["l",190,10,190,215,"d"],["p","M12 114 Q55 125 68 212"],["p","M72 212 C75 150 110 118 130 114 C150 108 185 70 188 8"],["p","M192 8 C200 80 250 106 310 110 L335 113"],["t",70,128,"−3a","ms"],["t",150,128,"a","ms"],["t",190,128,"3a","ms"],["t",310,128,"9a","ms"]]},"a":"(a) circle of radius 4a, centre (5a, 0)   (b) V(x) = (1/4πε₀)[−2Q/|x+3a| + Q/|x−3a|]   (c) the particle crosses the circle at (9a, 0) with speed √(qQ/(8πε₀ma))","s":"(a) V = 0 where −2Q/d₁ + Q/d₂ = 0, i.e. d₁ = 2d₂ (d₁ from (−3a, 0), d₂ from (3a, 0)). Then (x + 3a)² + y² = 4[(x − 3a)² + y²], which simplifies to x² + y² − 10ax + 9a² = 0, i.e. (x − 5a)² + y² = (4a)². A circle of radius 4a with centre (5a, 0).\n(b) V(x) = (1/4πε₀)[−2Q/|x + 3a| + Q/|x − 3a|]. V → −∞ at x = −3a, V → +∞ at x = 3a, V = 0 at x = a and x = 9a, and V → 0 (from below) as x → ±∞.\n(c) At the centre (5a, 0): V = (Q/4πε₀)(−2/8a + 1/2a) = Q/(16πε₀a) > 0. The field there is Q/(4πε₀)(1/4a² − 2/64a²) = 7Q/(128πε₀a²) along +x, so the charge moves along the x-axis. For 3a < x < 9a, V(x) = Q(9a − x)/(4πε₀(x² − 9a²)) is positive and decreasing (dV/dx < 0), reaching 0 at x = 9a, which is on the circle. So the charge keeps speeding up and crosses the circle at (9a, 0).\nEnergy: ½mv² = q[V(5a) − 0] = qQ/(16πε₀a), so v = √(qQ/(8πε₀ma)), where m is the mass of the particle."},
{"y":"IIT-JEE 1990","tp":"ecn","st":"Statements, matching and subjective","q":"Three concentric spherical metallic shells A, B and C of radii a, b and c (a < b < c) have surface charge densities σ, −σ and σ respectively.\n(i) Find the potential of the three shells A, B and C.\n(ii) If the shells A and C are at the same potential, obtain the relation between the radii a, b and c.","a":"(i) V_A = σ(a − b + c)/ε₀, V_B = σ[(a² − b²)/b + c]/ε₀, V_C = σ(a² − b² + c²)/(ε₀c)   (ii) c = a + b","s":"Charges: Q_A = 4πa²σ, Q_B = −4πb²σ, Q_C = 4πc²σ (k = 1/4πε₀).\nV_C = k(Q_A + Q_B + Q_C)/c = σ(a² − b² + c²)/(ε₀c).\nV_B = k(Q_A + Q_B)/b + kQ_C/c = σ(a² − b²)/(ε₀b) + σc/ε₀.\nV_A = kQ_A/a + kQ_B/b + kQ_C/c = (σ/ε₀)(a − b + c).\n(ii) V_A = V_C: a − b + c = (a² − b² + c²)/c, so c(a − b) = a² − b² = (a − b)(a + b). Hence c = a + b."},
{"y":"IIT-JEE 1987","tp":"evp","st":"Statements, matching and subjective","q":"Three point charges q, 2q and 8q are to be placed on a 9 cm long straight line. Find the positions where the charges should be placed such that the potential energy of this system is minimum. In this situation, what is the electric field at the position of the charge q due to the other two charges?","a":"2q and 8q at the ends, q between them 3 cm from 2q (6 cm from 8q); the electric field at q is zero","s":"All charges are positive, so the energy is lowest when they are as far apart as possible: 2q and 8q at the two ends, 9 cm apart. Compare which charge goes in the middle: with q in the middle the minimum energy is 3.78 kq²/cm, with 2q in the middle 4.15, with 8q in the middle 5.41 (same units). So q goes in the middle.\nLet q be at distance x from 2q: U = kq²[2/x + 8/(9 − x) + 16/9] (x in cm).\ndU/dx = 0: 2/x² = 8/(9 − x)², so 9 − x = 2x and x = 3 cm.\nSo q is 3 cm from 2q and 6 cm from 8q.\nField at q: due to 2q it is k·2q/3² and due to 8q it is k·8q/6² = k·2q/9 (per cm²), in opposite directions. The net field is zero."},
{"y":"IIT-JEE 1985","tp":"evp","st":"Statements, matching and subjective","q":"Two fixed, equal, positive charges, each of magnitude 5 × 10⁻⁵ C are located at points A and B separated by a distance of 6 m. An equal and opposite charge moves towards them along the line COD, the perpendicular bisector of the line AB. The moving charge, when it reaches the point C at a distance of 4 m from O, has a kinetic energy of 4 joule. Calculate the distance of the farthest point D which the negative charge will reach before returning towards C.","fig":{"w":340,"h":220,"alt":"Charges plus q at A (top) and B (bottom), 6 m apart, with the moving negative charge on the perpendicular bisector line D O C, C being 4 m from O","d":[["l",170,30,170,190,"d"],["l",40,110,310,110],["c",170,30,4,"F"],["c",170,190,4,"F"],["t",178,34,"A  +q"],["t",178,196,"B  +q"],["t",160,104,"O","e"],["c",290,110,4,"F"],["t",290,98,"C  −q","m"],["t",50,98,"D","m"],["l",210,30,210,190,"b"],["t",216,76,"6 m"],["l",170,128,290,128,"b"],["t",230,146,"4 m","m"]]},"a":"8.48 m","s":"Let q = 5×10⁻⁵ C. A and B are 3 m from O on either side. The moving charge −q at distance y from O has U = −2kq²/√(9 + y²).\n2kq² = 2 × 9×10⁹ × (5×10⁻⁵)² = 45 J·m.\nAt C (y = 4): √25 = 5, so U_C = −45/5 = −9 J. Total energy = 4 − 9 = −5 J.\nAt the farthest point D the KE is zero: −45/√(9 + y²) = −5, so √(9 + y²) = 9 and y² = 72.\nOD = √72 = 8.48 m."},
{"y":"IIT-JEE 1981","tp":"evp","st":"Statements, matching and subjective","q":"A charge Q is distributed over two concentric hollow spheres of radii r and R (> r) such that the surface charge densities are equal. Find the potential at the common centre.","a":"V = Q(r + R)/(4πε₀(r² + R²))","s":"Equal surface density σ: q₁ = 4πr²σ on the inner sphere and q₂ = 4πR²σ on the outer sphere.\nTotal Q = 4πσ(r² + R²), so σ = Q/(4π(r² + R²)).\nPotential at the centre: V = k(q₁/r + q₂/R) = (σ/ε₀)(r + R).\nV = Q(r + R)/(4πε₀(r² + R²))."},
{"y":"IIT-JEE 1981","tp":"evp","st":"Statements, matching and subjective","q":"The workdone in carrying a point charge from one point to another in an electrostatic field depends on the path along which the point charge is carried.","o":["True","False"],"c":1,"s":"The electrostatic force is conservative.\nThe work done in carrying a charge from A to B equals q(V_B − V_A) (by the external agent), which depends only on the end points.\nSo it does not depend on the path: the statement is false."},
{"y":"IIT-JEE 1992","tp":"evp","st":"Statements, matching and subjective","q":"The electric potential V at any point x, y, z (all in metre) in space is given by V = 4x² volt. The electric field at the point (1 m, 0, 2 m) is ____ V/m.","n":-8,"s":"E = −∇V, so E_x = −∂V/∂x = −8x, and E_y = E_z = 0.\nAt x = 1 m: E_x = −8 V/m.\nThe field is 8 V/m in the negative x-direction."},
{"y":"IIT-JEE 1989","tp":"evp","st":"Statements, matching and subjective","q":"A point charge q moves from point P to point S along the path PQRS (figure) in a uniform electric field E⃗ pointing parallel to the positive direction of the X-axis. The coordinates of the points P, Q, R and S are (a, b, 0), (2a, 0, 0), (a, −b, 0) and (0, 0, 0) respectively. The workdone by the field in the above process is given by the expression ____.","fig":{"w":340,"h":180,"alt":"Path P to Q to R to S in a uniform field pointing along the positive x-axis, with S at the origin, P at (a, b), Q at (2a, 0) and R at (a, -b)","d":[["l",20,15,320,15,"a"],["l",20,70,320,70,"a"],["l",20,110,320,110,"a"],["l",20,165,320,165,"a"],["l",20,90,330,90,"a"],["l",60,175,60,5,"a"],["t",326,86,"X","e"],["t",66,12,"Y"],["l",140,50,220,90],["l",220,90,140,130],["l",140,130,60,90],["t",134,44,"P","e"],["t",226,86,"Q"],["t",134,146,"R","e"],["t",52,104,"S","e"],["t",300,60,"E⃗"]]},"a":"−qEa","s":"The field is uniform and the electrostatic force is conservative, so the work depends only on the end points P and S.\nDisplacement from P to S along the field direction: Δx = 0 − a = −a.\nW = qE × Δx = −qEa."},
{"y":"IIT-JEE 1984","tp":"evp","st":"Statements, matching and subjective","q":"Figure shows lines of constant potential in a region in which an electric field is present. The values of the potential are written in brackets. Of the points A, B and C, the magnitude of the electric field is greatest at the point ____.","fig":{"w":280,"h":170,"alt":"Four curved equipotential lines labelled 50 V, 40 V, 30 V and 10 V, with points A, B and C; the lines are closest together near B","d":[["p","M50 20 Q130 80 50 140"],["p","M100 20 Q190 80 100 140"],["p","M150 20 Q250 80 150 140"],["p","M200 20 Q260 80 200 140"],["t",50,14,"50 V","ms"],["t",100,14,"40 V","ms"],["t",150,14,"30 V","ms"],["t",200,14,"10 V","ms"],["c",156,45,2.5,"F"],["t",162,43,"A"],["c",215,80,2.5,"F"],["t",221,78,"B"],["c",192,125,2.5,"F"],["t",198,123,"C"]]},"o":["A","B","C"],"c":1,"s":"The field is E = −dV/dr: its magnitude is the potential difference divided by the gap between neighbouring equipotential lines. So E is largest where the lines are closest together.\nIn the figure the lines are closest around B (between 30 V and 10 V), and further apart near A and C.\nThe field is greatest at B."},
{"y":"JEE Main 2025 · 3 Apr · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor is filled equally (half) with two dielectrics of dielectric constants ε₁ and ε₂, as shown in figures. The distance between the plates is d and area of each plate is A. If capacitance in first configuration and second configuration are C₁ and C₂ respectively, then {C₁;C₂} is","fig":{"w":340,"h":260,"alt":"First configuration: capacitor with two dielectric layers eps2 above eps1 stacked between the plates. Second configuration: two dielectrics eps2 and eps1 side by side between the plates","d":[["t",20,16,"First configuration","s"],["l",170,22,170,44],["l",80,44,260,44,"B"],["r",80,44,180,30],["l",80,74,260,74,"d"],["t",170,64,"ε₂","m"],["t",170,94,"ε₁","m"],["l",80,104,260,104,"B"],["l",170,104,170,126],["t",20,146,"Second configuration","s"],["l",170,152,170,174],["l",80,174,260,174,"B"],["r",80,174,90,60],["r",170,174,90,60],["t",125,208,"ε₂","m"],["t",215,208,"ε₁","m"],["l",80,234,260,234,"B"],["l",170,234,170,254]]},"o":["{ε₁ε₂²;(ε₁ + ε₂)²}","{ε₁ε₂;ε₁ + ε₂}","{ε₀(ε₁ + ε₂);2}","{4ε₁ε₂;(ε₁ + ε₂)²}"],"c":3,"s":"First configuration: two layers, each of thickness d/2 and area A, are in series.\nC₁ = ε₀A/[(d/2)/ε₁ + (d/2)/ε₂] = 2ε₀Aε₁ε₂/[d(ε₁ + ε₂)].\nSecond configuration: two halves of area A/2 side by side are in parallel: C₂ = ε₀(A/2)ε₁/d + ε₀(A/2)ε₂/d = ε₀A(ε₁ + ε₂)/(2d).\nC₁/C₂ = [2ε₁ε₂/(ε₁ + ε₂)] × [2/(ε₁ + ε₂)] = 4ε₁ε₂/(ε₁ + ε₂)²: option (d)."},
{"y":"JEE Main 2025 · 3 Apr · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"Using a battery, a 100 pF capacitor is charged to 60 V and then the battery is removed. After that, a second uncharged capacitor is connected to the first capacitor in parallel. If the final voltage across the second capacitor is 20 V, its capacitance is (in pF)","o":["100","600","200","400"],"c":2,"s":"With the battery removed, the charge is fixed: Q = CV = 100 pF × 60 V = 6000 pC.\nIn parallel the capacitors share this charge at a common voltage of 20 V: (100 + C₂) × 20 = 6000.\n100 + C₂ = 300, so C₂ = 200 pF: option (c)."},
{"y":"JEE Main 2025 · 4 Apr · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"Three parallel plate capacitors C₁, C₂ and C₃ each of capacitance 5 μF are connected as shown in figure. The effective capacitance between points A and B, when the space between the parallel plates of C₁ capacitor is filled with a dielectric medium having dielectric constant of 4, is","fig":{"w":300,"h":160,"alt":"Circuit between A and B: C1 and C2 in series along the top wire, C3 on a lower wire in parallel with them","d":[["l",20,50,98,50],["l",98,38,98,62],["l",90,38,90,62],["l",98,50,170,50],["l",170,38,170,62],["l",178,38,178,62],["l",178,50,255,50],["l",45,50,45,120],["l",45,120,130,120],["l",130,108,130,132],["l",138,108,138,132],["l",138,120,255,120],["l",255,50,255,120],["c",45,50,2.5,"F"],["c",255,50,2.5,"F"],["t",14,54,"A","e"],["t",262,54,"B"],["t",94,30,"C₁","m"],["t",174,30,"C₂","m"],["t",134,102,"C₃","m"]]},"o":["7.5 μF","30 μF","9 μF","22.5 μF"],"c":2,"s":"With the dielectric (K = 4), C₁ becomes 4 × 5 = 20 μF.\nC₁ and C₂ are in series: (20 × 5)/(20 + 5) = 4 μF.\nThis series pair is in parallel with C₃: C_eff = 4 + 5 = 9 μF: option (c)."},
{"y":"JEE Main 2025 · 22 Jan · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel-plate capacitor of capacitance 40 µF is connected to a 100 V power supply. Now the intermediate space between the plates is filled with a dielectric material of dielectric constant K = 2. Due to the introduction of dielectric material, the extra charge and the change in the electrostatic energy in the capacitor, respectively, are","o":["4 mC and 0.2 J","2 mC and 0.2 J","8 mC and 2.0 J","2 mC and 0.4 J"],"c":0,"s":"The battery stays connected, so V = 100 V stays fixed.\nInitial charge Q₁ = CV = 40 µF × 100 V = 4 mC.\nWith the dielectric, C' = KC = 80 µF, so Q₂ = 80 µF × 100 V = 8 mC.\nExtra charge = 8 − 4 = 4 mC.\nChange in energy = ½(C' − C)V² = ½ × 40×10⁻⁶ × 10⁴ = 0.2 J.\nAnswer: 4 mC and 0.2 J, option (a)."},
{"y":"JEE Main 2025 · 22 Jan · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"Which one of the following is the correct dimensional formula for the capacitance in F? M, L, T and C stand for unit of mass, length, time and charge.","o":["[F] = [C²M⁻¹L⁻²T²]","[F] = [CM⁻²L⁻²T⁻²]","[F] = [CM⁻¹L⁻²T²]","[F] = [C²M⁻²L²T²]"],"c":0,"s":"Capacitance = charge/potential and potential = work/charge, so capacitance = (charge)²/work.\nDimensions of work = M L² T⁻².\n[F] = C² / (M L² T⁻²) = [C² M⁻¹ L⁻² T²].\nAnswer: option (a)."},
{"y":"JEE Main 2025 · 24 Jan · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Consider a parallel plate capacitor of area A (of each plate) and separation 'd' between the plates. If E is the electric field and ε₀ is the permittivity of free space between the plates, then potential energy stored in the capacitor is","o":["{1;2}ε₀E²Ad","ε₀E²Ad","{3;4}ε₀E²Ad","{1;4}ε₀E²Ad"],"c":0,"s":"The energy stored per unit volume in an electric field is ½ε₀E².\nThe field fills the volume between the plates, which is A × d.\nU = ½ε₀E² × Ad.\nAnswer: option (a)."},
{"y":"JEE Main 2025 · 24 Jan · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"A parallel plate capacitor was made with two rectangular plates, each with a length of l = 3 cm and breadth of b = 1 cm. The distance between the plates is 3 µm. Out of the following, which are the ways to increase the capacitance by a factor of 10?\nA. l = 30 cm, b = 1 cm, d = 1 µm\nB. l = 3 cm, b = 1 cm, d = 30 µm\nC. l = 6 cm, b = 5 cm, d = 3 µm\nD. l = 1 cm, b = 1 cm, d = 10 µm\nE. l = 5 cm, b = 2 cm, d = 1 µm\nChoose the correct answer from the options given below.","o":["C only","B and D only","A only","C and E only"],"c":3,"s":"C = ε₀lb/d, so compare lb/d (in cm² per µm).\nOriginal: 3 × 1 / 3 = 1.\nA: 30 × 1 / 1 = 30 (30 times, no).\nB: 3 × 1 / 30 = 0.1 (no).  D: 1 × 1 / 10 = 0.1 (no).\nC: 6 × 5 / 3 = 10 (yes).  E: 5 × 2 / 1 = 10 (yes).\nAnswer: C and E only, option (d)."},
{"y":"JEE Main 2025 · 28 Jan · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor of capacitance 1 µF is charged to a potential difference of 20 V. The distance between plates is 1 µm. The energy density between plates of capacitor is","o":["2 × 10² J/m³","1.8 × 10³ J/m³","2 × 10⁻⁴ J/m³","1.8 × 10⁵ J/m³"],"c":1,"s":"Electric field between the plates E = V/d = 20 / 10⁻⁶ = 2×10⁷ V/m.\nEnergy density u = ½ε₀E² = ½ × 8.85×10⁻¹² × (2×10⁷)².\nu = ½ × 8.85×10⁻¹² × 4×10¹⁴ ≈ 1.8×10³ J/m³.\nAnswer: option (b)."},
{"y":"JEE Main 2025 · 29 Jan · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor, C₁ = 6 µF is charged to a potential difference of V₀ = 5 V using a 5 V battery. The battery is removed and another capacitor, C₂ = 12 µF is inserted in place of the battery (C₁ and C₂ are joined through a switch S). When the switch 'S' is closed, the charge flows between the capacitors for some time until equilibrium condition is reached. What are the charges (q₁ and q₂) on the capacitors C₁ and C₂ when equilibrium condition is reached?","o":["q₁ = 20 µC, q₂ = 10 µC","q₁ = 15 µC, q₂ = 30 µC","q₁ = 10 µC, q₂ = 20 µC","q₁ = 30 µC, q₂ = 15 µC"],"c":2,"s":"Charge on C₁ at first: Q = C₁V₀ = 6 × 5 = 30 µC.\nOnce the switch closes, this total charge of 30 µC is shared and both capacitors reach the same potential V.\nV = 30 / (6 + 12) = 5/3 V.\nq₁ = 6 × 5/3 = 10 µC and q₂ = 12 × 5/3 = 20 µC.\nAnswer: option (c)."},
{"y":"JEE Main 2024 · 8 Apr · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A capacitor has air as dielectric medium and two conducting plates of area 12 cm² and they are 0.6 cm apart. When a slab of dielectric having area 12 cm² and 0.6 cm thickness is inserted between the plates, one of the conducting plates has to be moved by 0.2 cm to keep the capacitance same as in previous case. The dielectric constant of the slab is (Given ε₀ = 8.834 × 10⁻¹² F/m)","o":["1.50","1","0.66","1.33"],"c":0,"s":"Original capacitance C = ε₀A / 0.6 cm.\nThe slab fills the 0.6 cm gap and raises C, so to bring C back one plate is moved away by 0.2 cm. New gap = 0.8 cm.\nC' = ε₀A / [(0.8 − 0.6) + 0.6/K] = ε₀A / (0.2 + 0.6/K).\nSet C' = C: 0.2 + 0.6/K = 0.6, so 0.6/K = 0.4.\nK = 1.5. Answer: option (a)."},
{"y":"JEE Main 2024 · 9 Apr · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"A capacitor is made of a flat plate of area A and a second plate having a stair-like structure as shown in figure. If the area of each stair is {A;3} and the height of each stair is d, the capacitance of the arrangement is","fig":{"w":340,"h":175,"alt":"A flat bottom plate of area A and a top plate in three steps, each of area A/3, with gaps d, 2d and 3d above the flat plate","d":[["l",40,140,300,140,"B"],["p","M40 120 H127 V100 H214 V80 H300","B"],["t",83,113,"A/3","ms"],["t",170,93,"A/3","ms"],["t",257,73,"A/3","ms"],["l",30,120,30,140,"b"],["t",24,134,"d","e"],["l",118,120,118,100,"b"],["t",112,114,"d","e"],["l",205,100,205,80,"b"],["t",199,94,"d","e"],["t",170,160,"A","m"]]},"o":["{11ε₀A;20d}","{18ε₀A;11d}","{11ε₀A;18d}","{13ε₀A;17d}"],"c":2,"s":"The three stairs act as three capacitors in parallel, each of area A/3.\nTheir gaps from the flat plate are d, 2d and 3d.\nC = ε₀(A/3)(1/d + 1/2d + 1/3d) = (ε₀A/3d)(6 + 3 + 2)/6.\nC = (ε₀A/3d)(11/6) = 11ε₀A/18d.\nAnswer: option (c)."},
{"y":"JEE Main 2024 · 1 Feb · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two identical capacitors have same capacitance C. One of them is charged to the potential V and other to the potential 2V. The negative ends of both are connected together. When the positive ends are also joined together, the decrease in energy of the combined system is","o":["{1;2}CV²","2CV²","{3;4}CV²","{1;4}CV²"],"c":3,"s":"Charges: Q₁ = CV and Q₂ = 2CV. Joined like to like, so total charge = 3CV on total capacitance 2C.\nCommon potential V' = 3CV / 2C = 1.5V.\nInitial energy = ½CV² + ½C(2V)² = 2.5CV².\nFinal energy = ½(2C)(1.5V)² = 2.25CV².\nDecrease = 2.5CV² − 2.25CV² = ¼CV².\nAnswer: option (d)."},
{"y":"JEE Main 2023 · 10 Apr · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"The equivalent capacitance of the combination shown is","fig":{"w":340,"h":140,"alt":"Two terminals; a capacitor C in the top branch and one in the bottom branch near the left, and two capacitors C in vertical branches that join the top and bottom wires on the right side","d":[["l",60,20,60,110],["l",60,20,96,20],["l",96,12,96,28],["l",104,12,104,28],["l",104,20,280,20],["l",60,110,96,110],["l",96,102,96,118],["l",104,102,104,118],["l",104,110,280,110],["l",280,20,280,110],["l",20,65,60,65],["c",20,65,3,"F"],["l",280,65,320,65],["c",320,65,3,"F"],["l",170,20,170,55],["l",162,55,178,55],["l",162,63,178,63],["l",170,63,170,110],["t",182,63,"C","s"],["l",230,20,230,55],["l",222,55,238,55],["l",222,63,238,63],["l",230,63,230,110],["t",242,63,"C","s"],["t",100,11,"C","ms"],["t",100,128,"C","ms"]]},"o":["{C;2}","{5;3}C","2C","4C"],"c":2,"s":"Look at the two end terminals. The top C and the bottom C each connect the left rail to the right rail, so they are in parallel.\nThe two middle capacitors join the top wire to the bottom wire. Both of these wires are joined to the right rail, so both plates of each middle capacitor are at the same potential: they are shorted and carry no charge.\nC_eq = C + C = 2C.\nAnswer: option (c)."},
{"y":"JEE Main 2023 · 10 Apr · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"The distance between two plates of a capacitor is d and its capacitance is C₁, when air is the medium between the plates. If a metal sheet of thickness {2d;3} and of the same area as plate is introduced between the plates, the capacitance of the capacitor becomes C₂. The ratio {C₂;C₁} is","o":["1 : 1","2 : 1","3 : 1","4 : 1"],"c":2,"s":"Originally C₁ = ε₀A/d.\nA metal sheet of thickness t reduces the effective gap to d − t.\nNew gap = d − 2d/3 = d/3.\nC₂ = ε₀A/(d/3) = 3ε₀A/d = 3C₁.\nC₂ : C₁ = 3 : 1. Answer: option (c)."},
{"y":"JEE Main 2023 · 11 Apr · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor of capacitance 2 F is charged to a potential V. The energy stored in the capacitor is E₁. The capacitor is now connected to another uncharged identical capacitor in parallel combination. The energy stored in the combination is E₂. The ratio E₂/E₁ is","o":["2 : 1","1 : 2","1 : 4","2 : 3"],"c":1,"s":"Initially Q = CV and E₁ = Q²/2C.\nAfter joining the identical uncharged capacitor in parallel, the charge Q is shared, total capacitance = 2C.\nE₂ = Q²/(2 × 2C) = E₁/2.\nE₂ : E₁ = 1 : 2. Answer: option (b)."},
{"y":"JEE Main 2023 · 11 Apr · Shift 2","tp":"egs","st":"Electric flux","q":"A capacitor of capacitance C is charged to a potential V. The flux of the electric field through a closed surface enclosing the positive plate of the capacitor is","o":["Zero","{CV;ε₀}","{CV;2ε₀}","{2CV;ε₀}"],"c":1,"s":"By Gauss's law, the flux through a closed surface = (charge enclosed)/ε₀.\nThe surface encloses only the positive plate, which carries Q = CV.\nFlux = CV/ε₀.\nAnswer: option (b)."},
{"y":"JEE Main 2023 · 25 Jan · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor has plate area 40 cm² and plates separation 2 mm. The space between the plates is filled with a dielectric medium of a thickness 1 mm and dielectric constant 5. The capacitance of the system is","o":["{10;3}ε₀F","{3;10}ε₀F","24ε₀F","10ε₀F"],"c":0,"s":"For a slab of thickness t in a gap d: C = ε₀A / (d − t + t/K).\nA = 40×10⁻⁴ m², d = 2×10⁻³ m, t = 10⁻³ m, K = 5.\nDenominator = (2 − 1 + 1/5)×10⁻³ = 1.2×10⁻³ m.\nC = ε₀ × 40×10⁻⁴ / (1.2×10⁻³) = (10/3)ε₀ F.\nAnswer: option (a)."},
{"y":"JEE Advanced 2023","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A container has a base of 50 cm × 5 cm and height 50 cm. It has two parallel electrically conducting walls each of area 50 cm × 50 cm (these are the large faces, 5 cm apart). The remaining walls of the container are thin and non-conducting. The container is being filled with a liquid of dielectric constant 3 at a uniform rate of 250 cm³ s⁻¹. What is the value of the capacitance of the container after 10 seconds? [Given: Permittivity of free space ε₀ = 9 × 10⁻¹² C² N⁻¹ m⁻², the effects of the non-conducting walls on the capacitance are negligible]","o":["27 pF","63 pF","81 pF","135 pF"],"c":1,"s":"Volume of liquid after 10 s = 250 × 10 = 2500 cm³.\nBase area = 50 × 5 = 250 cm², so the liquid height h = 2500/250 = 10 cm.\nThe two conducting walls form two capacitors side by side (parallel): liquid part of area 50 × 10 = 500 cm² and air part of area 50 × 40 = 2000 cm². Gap = 5 cm.\nC = ε₀(K × 500 + 2000)×10⁻⁴ / 0.05 = 9×10⁻¹² × (3500×10⁻⁴)/0.05 = 9×10⁻¹² × 7.\nC = 63 pF. Answer: option (b)."},
{"y":"JEE Main 2022 · 25 Jul · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"A condenser of 2 µF capacitance is charged steadily from 0 to 5 C. Which of the following graph represents correctly the variation of potential difference (V) across its plates with respect to the charge (Q) on the condenser?","fig":{"w":340,"h":250,"alt":"Four small V versus Q graphs: (a) straight line to 2.5 at Q=5, (b) curve bending upward to 5 at Q=5, (c) straight line to 5 at Q=5, (d) curve bending over and flattening at 2.5","d":[["t",4,24,"(a)"],["l",30,100,130,100,"a"],["l",30,100,30,28,"a"],["t",34,23,"V (×10⁶ V)","s"],["t",134,114,"Q(C)","s"],["t",30,112,"0","ms"],["t",115,112,"5","ms"],["t",26,74,"2.5","es"],["t",26,44,"5","es"],["l",115,97,115,103],["l",30,100,115,70,"B"],["l",30,70,115,70,"d"],["l",115,70,115,100,"d"],["t",164,24,"(b)"],["l",190,100,290,100,"a"],["l",190,100,190,28,"a"],["t",194,23,"V (×10⁶ V)","s"],["t",294,114,"Q(C)","s"],["t",190,112,"0","ms"],["t",275,112,"5","ms"],["t",186,74,"2.5","es"],["t",186,44,"5","es"],["l",275,97,275,103],["p","M190 100 Q255 96 275 40","B"],["l",190,40,275,40,"d"],["l",275,40,275,100,"d"],["t",4,144,"(c)"],["l",30,220,130,220,"a"],["l",30,220,30,148,"a"],["t",34,143,"V (×10⁶ V)","s"],["t",134,234,"Q(C)","s"],["t",30,232,"0","ms"],["t",115,232,"5","ms"],["t",26,194,"2.5","es"],["t",26,164,"5","es"],["l",115,217,115,223],["l",30,220,115,160,"B"],["l",30,160,115,160,"d"],["l",115,160,115,220,"d"],["t",164,144,"(d)"],["l",190,220,290,220,"a"],["l",190,220,190,148,"a"],["t",194,143,"V (×10⁶ V)","s"],["t",294,234,"Q(C)","s"],["t",190,232,"0","ms"],["t",275,232,"5","ms"],["t",186,194,"2.5","es"],["t",186,164,"5","es"],["l",275,217,275,223],["p","M190 220 Q198 190 275 190","B"],["l",190,190,275,190,"d"],["l",275,190,275,220,"d"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":0,"s":"For a capacitor V = Q/C, so V is directly proportional to Q: the graph should be a straight line through the origin.\nAt Q = 5 C, V = 5 / (2×10⁻⁶) = 2.5×10⁶ V.\nA straight line from the origin to 2.5 (×10⁶ V) at Q = 5 C is the line drawn in graph (a).\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 25 Jul · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"Capacitance of an isolated conducting sphere of radius R₁ becomes n times when it is enclosed by a concentric conducting sphere of radius R₂ connected to earth. The ratio of their radii ({R₂;R₁}) is","o":["{n;n−1}","{2n;2n+1}","{n+1;n}","{2n+1;n}"],"c":0,"s":"Isolated sphere: C = 4πε₀R₁.\nWith the earthed outer shell: C' = 4πε₀R₁R₂/(R₂ − R₁).\nC' = nC gives R₂/(R₂ − R₁) = n, so R₂ = nR₂ − nR₁.\nR₂(n − 1) = nR₁, so R₂/R₁ = n/(n − 1).\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 26 Jul · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"The total charge on the system of capacitance C₁ = 1 µF, C₂ = 2 µF, C₃ = 4 µF and C₄ = 3 µF connected in parallel is (Assume a battery of 20 V is connected to the combination)","o":["200 µC","200 C","10 µC","10 C"],"c":0,"s":"In parallel the capacitances add: C = 1 + 2 + 4 + 3 = 10 µF.\nTotal charge Q = CV = 10 µF × 20 V = 200 µC.\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 26 Jul · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A source of potential difference V is connected to the combination of two identical capacitors as shown in the figure. When key K is closed, the total energy stored across the combination is E₁. Now key K is opened and dielectric of dielectric constant 5 is introduced between the plates of the two capacitors. The total energy stored across the combination is now E₂. The ratio E₁/E₂ will be","fig":{"w":340,"h":165,"alt":"A source V on the left, a key K in the top wire, and two identical capacitors C in parallel branches; the key sits between the middle branch and the right branch","d":[["l",60,30,170,30],["l",170,30,205,16],["c",170,30,2,"F"],["c",212,30,2],["l",212,30,260,30],["c",140,30,2,"F"],["l",140,30,140,72],["l",132,72,148,72],["l",132,80,148,80],["l",140,80,140,140],["l",260,30,260,72],["l",252,72,268,72],["l",252,80,268,80],["l",260,80,260,140],["l",60,140,260,140],["c",140,140,2,"F"],["l",60,30,60,80],["l",48,80,72,80],["l",54,88,66,88,"B"],["l",60,88,60,140],["t",44,88,"V","e"],["t",190,10,"K","m"],["t",152,80,"C"],["t",272,80,"C"]]},"o":["{1;10}","{2;5}","{5;13}","{5;26}"],"c":2,"s":"K closed: both capacitors are across V, so E₁ = ½(2C)V² = CV².\nK opened: the capacitor in the middle branch stays connected to the source (its V is fixed). The other one is cut off and keeps its charge CV.\nConnected one with K = 5: C' = 5C at voltage V, energy = ½(5C)V² = 2.5CV².\nIsolated one: charge CV fixed, C' = 5C, energy = (CV)²/(2 × 5C) = 0.1CV².\nE₂ = 2.6CV² = 13CV²/5, so E₁/E₂ = 5/13.\nAnswer: option (c)."},
{"y":"JEE Main 2022 · 28 Jul · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"Two capacitors, each having capacitance 40 µF are connected in series. The space between one of the capacitors is filled with dielectric material of dielectric constant K such that the equivalent capacitance of the system became 24 µF. The value of K will be","o":["1.5","2.5","1.2","3"],"c":0,"s":"The capacitor with the dielectric has capacitance 40K µF.\nSeries: (40 × 40K)/(40 + 40K) = 24.\n1600K = 24(40 + 40K) = 960 + 960K.\n640K = 960, so K = 1.5.\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 28 Jul · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A slab of dielectric constant K has the same cross-sectional area as the plates of a parallel plate capacitor and thickness {3;4}d, where d is the separation of the plates. The capacitance of the capacitor when the slab is inserted between the plates will be (Given C₀ = capacitance of capacitor with air as medium between plates.)","o":["{4KC₀;3+K}","{3KC₀;3+K}","{3+K;4KC₀}","{K;4+K}"],"c":0,"s":"With a slab of thickness t: C = ε₀A / (d − t + t/K).\nt = 3d/4: denominator = d/4 + 3d/(4K) = d(K + 3)/(4K).\nC = 4Kε₀A / (d(K + 3)) = 4KC₀/(3 + K), since C₀ = ε₀A/d.\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 29 Jul · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"Two identical thin metal plates have charge q₁ and q₂ respectively such that q₁ > q₂. The plates were brought close to each other to form a parallel plate capacitor of capacitance C. The potential difference between them is","o":["{q₁+q₂;C}","{q₁−q₂;C}","{q₁−q₂;2C}","{2(q₁−q₂);C}"],"c":2,"s":"When the plates are brought close, the charges rearrange. Each outer face carries (q₁ + q₂)/2.\nThe inner faces then carry +(q₁ − q₂)/2 and −(q₁ − q₂)/2.\nSo the charge on the capacitor is Q = (q₁ − q₂)/2.\nV = Q/C = (q₁ − q₂)/2C.\nAnswer: option (c)."},
{"y":"JEE Main 2022 · 24 Jun · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor is formed by two plates each of area 30π cm², separated by 1 mm. A material of dielectric strength 3.6 × 10⁷ V m⁻¹ is filled between the plates. If the maximum charge that can be stored on the capacitor without causing any dielectric breakdown is 7 × 10⁻⁶ C, the value of the dielectric constant of the material is\n[Use 1/(4πε₀) = 9 × 10⁹ N m² C⁻²]","o":["1.66","1.75","2.25","2.33"],"c":3,"s":"Field inside the dielectric E = σ/(Kε₀) = Q/(Kε₀A). At breakdown E = 3.6×10⁷ V/m, so K = Q/(ε₀AE).\nε₀ = 1/(4π × 9×10⁹), A = 30π×10⁻⁴ m², so ε₀A = 30π×10⁻⁴/(36π×10⁹) = 8.33×10⁻¹⁴.\nK = 7×10⁻⁶ / (8.33×10⁻¹⁴ × 3.6×10⁷) = 7×10⁻⁶ / (3×10⁻⁶) = 2.33.\nAnswer: option (d)."},
{"y":"JEE Main 2022 · 24 Jun · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"If the charge on a capacitor is increased by 2 C, the energy stored in it increases by 44%. The original charge on the capacitor is (in C)","o":["10","20","30","40"],"c":0,"s":"Energy U = Q²/2C, so U is proportional to Q².\n(Q + 2)²/Q² = 1.44, so (Q + 2)/Q = 1.2.\nQ + 2 = 1.2Q, so 0.2Q = 2 and Q = 10 C.\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 25 Jun · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"Two metallic plates form a parallel plate capacitor. The distance between the plates is 'd'. A metal sheet of thickness {d;2} and of area equal to area of each plate is introduced between the plates. What will be the ratio of the new capacitance to the original capacitance of the capacitor?","o":["2 : 1","1 : 2","1 : 4","4 : 1"],"c":0,"s":"Original C = ε₀A/d.\nA metal sheet of thickness d/2 cuts the effective gap to d − d/2 = d/2.\nNew C = ε₀A/(d/2) = 2ε₀A/d.\nRatio new : original = 2 : 1.\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 26 Jun · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two capacitors having capacitance C₁ and C₂ respectively are connected through a switch S. Initially, capacitor C₁ is charged to a potential difference V volt by a battery. The battery is then removed and the charged capacitor C₁ is now connected to uncharged capacitor C₂ by closing the switch S. The amount of charge on the capacitor C₂, after equilibrium, is","o":["{C₁C₂;C₁+C₂}V","{C₁+C₂;C₁C₂}V","(C₁ + C₂)V","(C₁ − C₂)V"],"c":0,"s":"Initial charge on C₁ is Q = C₁V.\nAfter S is closed the charge is shared, and both capacitors reach the same potential V'.\nV' = Q/(C₁ + C₂) = C₁V/(C₁ + C₂).\nCharge on C₂ = C₂V' = C₁C₂V/(C₁ + C₂).\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 26 Jun · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"Three capacitors of capacitance 10 µF, 15 µF and 20 µF are connected in series across a 13 V battery. The charge on the capacitor of capacitance 15 µF is","o":["60 µC","130 µC","260 µC","585 µC"],"c":0,"s":"In series, 1/C = 1/10 + 1/15 + 1/20 = (6 + 4 + 3)/60 = 13/60, so C = 60/13 µF.\nCharge from the battery Q = CV = (60/13) × 13 = 60 µC.\nIn series every capacitor carries the same charge, so the 15 µF capacitor has 60 µC.\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 26 Jun · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor with plate area A and plate separation d = 2 m has a capacitance of 4 µF. The new capacitance of the system if half of the space between them is filled with a dielectric material of dielectric constant K = 3 (as shown in figure) will be","fig":{"w":340,"h":185,"alt":"Two vertical plates separated by d; a dielectric slab K = 3 of thickness d/2 touches the right plate and fills its full height","d":[["l",100,20,100,140,"B"],["l",240,20,240,140,"B"],["r",170,20,70,120,"f"],["l",170,20,170,140],["t",205,85,"K = 3","m"],["l",100,158,240,158,"b"],["t",170,176,"d","m"]]},"o":["2 µF","32 µF","6 µF","8 µF"],"c":2,"s":"The slab fills half the gap (thickness d/2) over the full plate area, so the system is two capacitors in series.\nAir part: gap d/2, so C₁ = 2 × 4 = 8 µF.\nSlab part: gap d/2 with K = 3, so C₂ = 3 × 8 = 24 µF.\nC = C₁C₂/(C₁ + C₂) = 8 × 24 / 32 = 6 µF.\nAnswer: option (c)."},
{"y":"JEE Main 2022 · 27 Jun · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A force of 10 N acts on a charged particle placed between two plates of a charged capacitor. If one plate of capacitor is removed, then the force acting on that particle will be","o":["5 N","10 N","20 N","Zero"],"c":0,"s":"Each plate is a large sheet that produces a field σ/2ε₀. Between the plates the two fields add to σ/ε₀.\nIf one plate is removed, only one sheet is left and the field becomes half.\nForce = qE, so the force also becomes half: 10/2 = 5 N.\nAnswer: option (a)."},
{"y":"JEE Main 2022 · 29 Jun · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor filled with a medium of dielectric constant 10, is connected across a battery and is charged. The dielectric slab is replaced by another slab of dielectric constant 15. Then the energy of capacitor will","o":["increase by 50%","decrease by 15%","increase by 25%","increase by 33%"],"c":0,"s":"The battery stays connected, so V is constant.\nEnergy U = ½CV² is proportional to C, and C is proportional to K.\nU'/U = 15/10 = 1.5.\nSo the energy increases by 50%.\nAnswer: option (a)."},
{"y":"JEE Main 2021 · 1 Sep · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor is connected to a 20 V battery through a resistance of 10 Ω. It is found that the potential difference across the capacitor rises to 2 V in 1 µs. The capacitance of the capacitor is ______ µF. (Given ln(10/9) = 0.105)","o":["0.95","9.52","1.85","0.105"],"c":0,"s":"While charging, V_C = V₀(1 − e^(−t/RC)).\n2 = 20(1 − e^(−t/RC)) gives e^(−t/RC) = 0.9, so t/RC = ln(10/9) = 0.105.\nRC = t/0.105 = 10⁻⁶/0.105 s, so C = 10⁻⁶ / (0.105 × 10) F.\nC = 0.952×10⁻⁶ F ≈ 0.95 µF.\nAnswer: option (a)."},
{"y":"JEE Main 2021 · 26 Aug · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"The material filled between the plates of a parallel plate capacitor has resistivity 200 Ω m. The value of capacitance of the capacitor is 2 pF. If a potential difference of 40 V is applied across the plates of the capacitor, then the value of leakage current flowing out of the capacitor is (Given the value of relative permittivity of material is 50)","o":["0.9 mA","9.0 mA","9.0 µA","0.9 µA"],"c":0,"s":"Resistance of the material between the plates R = ρd/A.\nCapacitance C = Kε₀A/d, so d/A = Kε₀/C.\nR = ρKε₀/C = 200 × 50 × 8.85×10⁻¹² / (2×10⁻¹²) ≈ 4.4×10⁴ Ω.\nLeakage current I = V/R = 40 / (4.4×10⁴) ≈ 0.9×10⁻³ A = 0.9 mA.\nAnswer: option (a)."},
{"y":"JEE Main 2021 · 26 Aug · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel-plate capacitor with plate area A has separation d between the plates. Two dielectric slabs of dielectric constant K₁ and K₂ of same area A/2 and thickness d/2 are inserted in the space between the plates. The capacitance of the capacitor will be given by","fig":{"w":340,"h":160,"alt":"Two horizontal plates with +Q on top and -Q below, separated by d; on the right half of the gap two slabs K1 above K2 each of thickness d/2, the left half is air","d":[["l",40,30,300,30,"B"],["l",40,130,300,130,"B"],["r",170,30,110,50,"f"],["r",170,80,110,50,"f"],["t",225,60,"K₁","m"],["t",225,110,"K₂","m"],["t",105,84,"air","m"],["l",320,30,320,130,"b"],["t",326,84,"d"],["t",34,34,"+Q","e"],["t",34,134,"−Q","e"]]},"o":["{ε₀A;d}({1;2} + {K₁K₂;K₁+K₂})","{ε₀A;d}({1;2} + {2(K₁+K₂);K₁K₂})","{ε₀A;d}({1;2} + {K₁+K₂;K₁K₂})","{ε₀A;d}({1;2} + {K₁+K₂;2(K₁+K₂)})"],"c":0,"s":"The half of the plate area without slabs is an air capacitor: C_air = ε₀(A/2)/d = ε₀A/2d.\nThe other half has K₁ and K₂ stacked, each of thickness d/2 and area A/2, so they are in series. Each has C = Kε₀(A/2)/(d/2) = Kε₀A/d.\nSeries: (ε₀A/d) × K₁K₂/(K₁ + K₂).\nThe two halves are in parallel: C = (ε₀A/d)[1/2 + K₁K₂/(K₁ + K₂)].\nAnswer: option (a)."},
{"y":"JEE Main 2021 · 27 Aug · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"Three capacitors C₁ = 2 µF, C₂ = 6 µF and C₃ = 12 µF are connected as shown in figure (C₂ and C₃ are in series in the upper branch between A and B, C₁ is in the lower branch, and the battery V is connected across A and B). Find the ratio of the charges on capacitors C₁, C₂ and C₃ respectively.","fig":{"w":340,"h":182,"alt":"Between nodes A and B, an upper branch with C2 and C3 in series (point D between them) and a lower branch with C1; a battery V is connected across A and B through the outer loop","d":[["l",80,30,110,30],["l",110,22,110,38],["l",118,22,118,38],["l",118,30,150,30],["c",150,30,2,"F"],["l",150,30,182,30],["l",182,22,182,38],["l",190,22,190,38],["l",190,30,260,30],["l",80,30,80,110],["l",260,30,260,110],["c",80,70,2,"F"],["c",260,70,2,"F"],["l",80,110,166,110],["l",166,102,166,118],["l",174,102,174,118],["l",174,110,260,110],["l",80,70,30,70],["l",30,70,30,150],["l",30,150,140,150],["l",140,140,140,160],["l",148,145,148,155,"B"],["l",148,150,300,150],["l",300,150,300,70],["l",300,70,260,70],["t",114,20,"C₂","m"],["t",150,20,"D","m"],["t",186,20,"C₃","m"],["t",170,130,"C₁","m"],["t",72,66,"A","e"],["t",268,66,"B"],["t",144,174,"V","m"]]},"o":["3 : 4 : 4","2 : 3 : 3","2 : 1 : 1","1 : 2 : 2"],"c":3,"s":"C₂ and C₃ are in series: C₂₃ = (6 × 12)/(6 + 12) = 4 µF.\nThis 4 µF branch is in parallel with C₁ = 2 µF, so both branches have the same voltage V_AB.\nCharge on C₁ = 2V_AB. Charge on the 4 µF branch = 4V_AB, and in series C₂ and C₃ each carry this same charge.\nq₁ : q₂ : q₃ = 2 : 4 : 4 = 1 : 2 : 2.\nAnswer: option (d)."},
{"y":"JEE Main 2021 · 25 Jul · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor with plate area 'A' and distance of separation 'd' is filled with a dielectric. What is the capacity of the capacitor when permittivity of the dielectric varies as ε(x) = ε₀ + kx, for (0 < x ≤ {d;2})\nε(x) = ε₀ + k(d − x), for ({d;2} ≤ x ≤ d)","o":["{kA;2}ln({2ε₀;2ε₀−kd})","(ε₀ + {kd;2})^(2/kA)","{kA;2ln({2ε₀+kd;2ε₀})}","0"],"c":2,"s":"Thin layers of thickness dx are in series, so 1/C = ∫ dx/(ε(x)A).\nThe two halves of the gap are identical by symmetry: 1/C = (2/A)∫₀^(d/2) dx/(ε₀ + kx).\n= (2/kA) ln[(ε₀ + kd/2)/ε₀] = (2/kA) ln[(2ε₀ + kd)/(2ε₀)].\nSo C = kA / {2 ln[(2ε₀ + kd)/(2ε₀)]}.\nAnswer: option (c)."},
{"y":"JEE Main 2021 · 25 Jul · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"If q_f is the free charge on the capacitor plates and q_b is the bound charge on the dielectric slab of dielectric constant k placed between the capacitor plates, then bound charge q_b can be expressed as","o":["q_b = q_f(1 − {1;k})","q_b = q_f(1 + {1;k})","q_b = q_f(1 − {1;√k})","q_b = q_f(1 + {1;√k})"],"c":0,"s":"Free charge alone would give a field q_f/(ε₀A) between the plates.\nThe bound charge on the slab faces opposes it, so the net field is (q_f − q_b)/(ε₀A).\nWith a dielectric the field is reduced to E₀/k = q_f/(kε₀A).\nSo q_f − q_b = q_f/k, giving q_b = q_f(1 − 1/k).\nAnswer: option (a)."},
{"y":"JEE Main 2021 · 27 Jul · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two capacitors of capacities 2C and C are joined in parallel and charged up to potential V. The battery is removed and the capacitor of capacity C is filled completely with a medium of dielectric constant K. The potential difference across the capacitors will now be","o":["{3V;K+2}","{3V;K}","{V;K+2}","{V;K}"],"c":0,"s":"Total charge (battery removed, so it stays fixed): Q = (2C + C)V = 3CV.\nAfter filling, the capacitances are 2C and KC, still in parallel: C_total = (2 + K)C.\nNew potential V' = Q/C_total = 3CV/((K + 2)C) = 3V/(K + 2).\nAnswer: option (a)."},
{"y":"JEE Main 2021 · 27 Jul · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"In the reported figure, a capacitor is formed by placing a compound dielectric between the plates of parallel plate capacitor. The expression for the capacity of the said capacitor will be (Given, area of plate = A)","fig":{"w":340,"h":160,"alt":"Two vertical plates with three dielectric slabs side by side between them, constants K, 3K and 5K and thicknesses d, 2d and 3d, forming capacitors C1, C2, C3","d":[["l",60,26,60,116,"B"],["l",280,26,280,116,"B"],["r",60,26,36,90,"f"],["r",96,26,73,90,"f"],["r",169,26,111,90,"f"],["t",78,76,"K","m"],["t",132,76,"3K","m"],["t",224,76,"5K","m"],["t",78,20,"C₁","m"],["t",132,20,"C₂","m"],["t",224,20,"C₃","m"],["l",60,132,96,132,"b"],["t",78,148,"d","m"],["l",96,132,169,132,"b"],["t",132,148,"2d","m"],["l",169,132,280,132,"b"],["t",224,148,"3d","m"]]},"o":["{9Kε₀A;6d}","{15Kε₀A;6d}","{25Kε₀A;6d}","{15Kε₀A;34d}"],"c":3,"s":"The three slabs have thicknesses d, 2d, 3d and constants K, 3K, 5K, each covering the full plate area A, so they are in series.\n1/C = d/(Kε₀A) + 2d/(3Kε₀A) + 3d/(5Kε₀A) = (d/Kε₀A)(1 + 2/3 + 3/5).\n1 + 2/3 + 3/5 = (15 + 10 + 9)/15 = 34/15.\nC = 15Kε₀A/(34d).\nAnswer: option (d)."},
{"y":"JEE Main 2021 · 27 Jul · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A simple pendulum of mass m, length l and charge '+q' suspended in the electric field produced by two conducting parallel plates as shown. The value of deflection of pendulum in equilibrium position will be (C₁ and C₂ are the capacitances of the air gap and of the dielectric-filled part respectively.)","fig":{"w":340,"h":210,"alt":"Two vertical plates at potentials +V2 (left) and -V1 (right) separated by d; a dielectric of constant K and thickness t touches the left plate; a charged pendulum of length l and mass m hangs in the air gap","d":[["l",60,20,60,170,"B"],["l",250,20,250,170,"B"],["r",60,20,70,150,"f"],["t",95,50,"Medium","ms"],["t",95,64,"(K)","ms"],["t",52,98,"+V₂","e"],["t",258,98,"−V₁"],["l",160,20,220,20,"B"],["l",190,20,190,110],["c",190,110,6,"F"],["t",196,65,"l"],["t",200,128,"+q, m","s"],["t",215,155,"air"],["l",60,182,130,182,"b"],["t",95,178,"t","m"],["l",60,198,250,198,"b"],["t",155,194,"d","m"]]},"o":["tan⁻¹[{q;mg} × {C₂(V₁+V₂);(C₁+C₂)(d−t)}]","tan⁻¹[{q;mg} × {C₁(V₁+V₂);(C₁+C₂)(d−t)}]","tan⁻¹[{q;mg} × {C₂(V₂−V₁);(C₁+C₂)(d−t)}]","tan⁻¹[{q;mg} × {C₁(V₂−V₁);(C₁+C₂)(d−t)}]"],"c":0,"s":"The plates are at +V₂ and −V₁, so the potential difference is V₁ + V₂.\nThe air gap (C₁ = ε₀A/(d−t)) and the dielectric part (C₂ = Kε₀A/t) are in series. In series the voltage divides inversely to C, so the air gap gets V_air = (V₁ + V₂)C₂/(C₁ + C₂).\nField in air E = V_air/(d − t).\nThe bob is in equilibrium under mg, qE and tension: tanθ = qE/mg.\nθ = tan⁻¹[(q/mg) × C₂(V₁ + V₂)/((C₁ + C₂)(d − t))].\nAnswer: option (a)."},
{"y":"JEE Main 2021 · 16 Mar · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"For changing the capacitance of a given parallel plate capacitor, a dielectric material of dielectric constant K is used, which has the same area as the plates of the capacitor. The thickness of the dielectric slab is {3;4}d, where 'd' is the separation between the plates of parallel plate capacitor. The new capacitance (C') in terms of original capacitance (C₀) is given by the following relation.","o":["C' = {3+K;4K}C₀","C' = {4;3+K}C₀","C' = {4+K;3}C₀","C' = {4K;K+3}C₀"],"c":3,"s":"With a slab of thickness t: C' = ε₀A / (d − t + t/K).\nt = 3d/4: d − t + t/K = d/4 + 3d/(4K) = d(K + 3)/(4K).\nC' = 4Kε₀A/(d(K + 3)) = 4KC₀/(K + 3), since C₀ = ε₀A/d.\nAnswer: option (d)."},
{"y":"JEE Main 2021 · 24 Feb · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"Two equal capacitors are first connected in series and then in parallel. The ratio of the equivalent capacities in the two cases will be","o":["1 : 4","2 : 1","4 : 1","1 : 2"],"c":0,"s":"Let each capacitor be C.\nSeries: C_s = C/2. Parallel: C_p = 2C.\nC_s : C_p = (C/2) : 2C = 1 : 4.\nAnswer: option (a)."},
{"y":"JEE Main 2021 · 25 Feb · Shift 2","tp":"efl","st":"Field lines and motion in a field","q":"An electron with kinetic energy K₁ enters between parallel plates of a capacitor at an angle 'α' with the plates. It leaves the plates at angle 'β' with kinetic energy K₂. Then the ratio of kinetic energies K₁ : K₂ will be","o":["{sin²β;cos²α}","{cosβ;cosα}","{cosβ;sinα}","{cos²β;cos²α}"],"c":3,"s":"The field between the plates is perpendicular to the plates, so there is no force along the plates.\nThe velocity component parallel to the plates stays constant: v₁cosα = v₂cosβ.\nKinetic energy is proportional to v², so K₁/K₂ = v₁²/v₂² = cos²β/cos²α.\nAnswer: option (d)."},
{"y":"JEE Main 2020 · 2 Sep · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A 10 µF capacitor is fully charged to a potential difference of 50 V. After removing the source voltage it is connected to an uncharged capacitor in parallel. Now the potential difference across them becomes 20 V. The capacitance of the second capacitor is","o":["15 µF","20 µF","30 µF","10 µF"],"c":0,"s":"Charge on the first capacitor: Q = 10 µF × 50 V = 500 µC. This charge is conserved.\nAfter joining in parallel: Q = (10 + C)V' with V' = 20 V.\n500 = (10 + C) × 20, so 10 + C = 25.\nC = 15 µF.\nAnswer: option (a)."},
{"y":"JEE Main 2020 · 3 Sep · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"In the circuit shown in the figure, the total charge is 750 µC and the voltage across capacitor C₂ is 20 V. Then the charge on capacitor C₂ is","fig":{"w":340,"h":158,"alt":"Battery V in a loop with C1 = 15 microfarad in series with a parallel pair: C2 in the upper branch and C3 = 8 microfarad in the lower branch","d":[["l",40,40,80,40],["l",80,32,80,48],["l",88,32,88,48],["l",88,40,130,40],["c",130,40,2,"F"],["l",130,40,175,40],["l",175,32,175,48],["l",183,32,183,48],["l",183,40,230,40],["c",230,40,2,"F"],["l",130,40,130,75],["l",130,75,175,75],["l",175,67,175,83],["l",183,67,183,83],["l",183,75,230,75],["l",230,75,230,40],["l",230,40,270,40],["l",40,40,40,120],["l",40,120,140,120],["l",140,110,140,130],["l",148,115,148,125,"B"],["l",148,120,270,120],["l",270,120,270,40],["t",84,28,"C₁ = 15 µF","m"],["t",179,26,"C₂","m"],["t",179,98,"C₃ = 8 µF","m"],["t",144,146,"V","m"]]},"o":["450 µC","590 µC","160 µC","650 µC"],"c":1,"s":"C₁ is in series with the parallel pair C₂, C₃. The total charge 750 µC flows through C₁ and then splits between C₂ and C₃.\nC₂ and C₃ are in parallel, so both have 20 V across them.\nCharge on C₃ = 8 µF × 20 V = 160 µC.\nCharge on C₂ = 750 − 160 = 590 µC.\nAnswer: option (b)."},
{"y":"JEE Main 2020 · 4 Sep · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor C is fully charged with voltage V₀. After disconnecting the voltage source, it is connected in parallel with another uncharged capacitor of capacitance {C;2}. The energy loss in the process after the charge is distributed between the two capacitors is","o":["{1;3}CV₀²","{1;4}CV₀²","{1;2}CV₀²","{1;6}CV₀²"],"c":3,"s":"Initial energy U₁ = ½CV₀². Charge Q = CV₀ is conserved.\nAfter sharing, total capacitance = C + C/2 = 3C/2, so U₂ = Q²/(2 × 3C/2) = C²V₀²/(3C) = CV₀²/3.\nLoss = ½CV₀² − ⅓CV₀² = ⅙CV₀².\nAnswer: option (d)."},
{"y":"JEE Main 2020 · 5 Sep · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two capacitors of capacitances C and 2C are charged to potential differences V and 2V respectively. These are then connected in parallel in such a manner that the positive terminal of one is connected to the negative terminal of the other. The final energy of this configuration is","o":["{25;6}CV²","{3;2}CV²","zero","{9;2}CV²"],"c":1,"s":"Charges: Q₁ = CV and Q₂ = 2C × 2V = 4CV.\nJoined positive to negative, the charges partly cancel: net charge = 4CV − CV = 3CV.\nTotal capacitance = 3C, so the common potential V' = 3CV/3C = V.\nFinal energy = ½(3C)V² = 3CV²/2.\nAnswer: option (b)."},
{"y":"JEE Main 2020 · 5 Sep · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"In the circuit shown, charge on the 5 µF capacitor is (both 6 V batteries have their positive terminals towards the outer ends of the circuit, and the lower middle point is at 0 V)","fig":{"w":340,"h":180,"alt":"Two outer capacitors 2 microfarad and 4 microfarad in the top wire meeting at a middle point, a 5 microfarad capacitor from that point down to a 0 volt node, and a 6 volt battery in the bottom wire on each side","d":[["l",40,30,90,30],["l",90,22,90,38],["l",98,22,98,38],["l",98,30,150,30],["c",150,30,2,"F"],["l",150,30,190,30],["l",190,22,190,38],["l",198,22,198,38],["l",198,30,270,30],["l",150,30,150,70],["l",142,70,158,70],["l",142,78,158,78],["l",150,78,150,140],["c",150,140,2,"F"],["l",40,30,40,140],["l",40,140,81,140],["l",81,130,81,150],["l",89,135,89,145,"B"],["l",89,140,150,140],["l",150,140,211,140],["l",211,135,211,145,"B"],["l",219,130,219,150],["l",219,140,270,140],["l",270,140,270,30],["t",94,20,"2 µF","m"],["t",194,20,"4 µF","m"],["t",162,78,"5 µF"],["t",85,166,"6 V","m"],["t",215,166,"6 V","m"],["t",150,166,"0","m"]]},"o":["18.00 µC","10.90 µC","16.36 µC","5.45 µC"],"c":2,"s":"Take the lower middle point as 0 V. Each battery makes the outer end of the circuit +6 V.\nLet the potential of the top middle point M be V. The 2 µF and 4 µF capacitors are connected between the +6 V ends and M, and the 5 µF between M and 0 V.\nThe plates joined to M carry no net charge: 2(6 − V) + 4(6 − V) = 5V.\n36 − 6V = 5V, so V = 36/11 = 3.27 V.\nCharge on the 5 µF = 5 × 36/11 = 16.36 µC.\nAnswer: option (c)."},
{"y":"JEE Main 2020 · 5 Sep · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor has plate of length 'l', width 'w' and separation of plates is 'd'. It is connected to a battery of emf V. A dielectric slab of the same thickness 'd' and of dielectric constant K = 4 is being inserted between the plates of the capacitor. At what length of the slab inside plates, will the energy stored in the capacitor be two times the initial energy stored?","o":["2l/3","l/3","l/4","l/2"],"c":1,"s":"Let the slab be inside by length x. The part with slab and the part without are in parallel.\nC = ε₀w(l − x)/d + Kε₀wx/d = C₀[1 + (K − 1)x/l] = C₀(1 + 3x/l).\nThe battery stays connected, so U = ½CV² is proportional to C.\nFor U = 2U₀: 1 + 3x/l = 2, so x = l/3.\nAnswer: option (b)."},
{"y":"JEE Main 2020 · 7 Jan · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor has plates of area A separated by distance 'd' between them. It is filled with a dielectric which has a dielectric constant that varies as k(x) = K(1 + αx) where 'x' is the distance measured from one of the plates. If (αd) << 1, the total capacitance of the system is best given by the expression","o":["{Aε₀K;d}(1 + ({αd;2})²)","{AKε₀;d}(1 + {αd;2})","{Aε₀K;d}(1 + {α²d²;2})","{AKε₀;d}(1 + αd)"],"c":1,"s":"Thin layers of thickness dx are in series: 1/C = ∫₀^d dx/(ε₀K(1 + αx)A) = ln(1 + αd)/(ε₀KAα).\nFor αd << 1: ln(1 + αd) ≈ αd − (αd)²/2.\n1/C ≈ (d/ε₀KA)(1 − αd/2).\nSo C ≈ (ε₀KA/d)(1 − αd/2)⁻¹ ≈ (AKε₀/d)(1 + αd/2).\nAnswer: option (b)."},
{"y":"JEE Main 2020 · 8 Jan · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"Effective capacitance of parallel combination of two capacitors C₁ and C₂ is 10 µF. When these capacitors are individually connected to a voltage source of 1 V, the energy stored in the capacitor C₂ is 4 times that of C₁. If these capacitors are connected in series, their effective capacitance will be","o":["1.6 µF","8.4 µF","3.2 µF","4.2 µF"],"c":0,"s":"Parallel: C₁ + C₂ = 10 µF.\nEnergy at 1 V is ½C, so ½C₂ = 4 × ½C₁, giving C₂ = 4C₁.\n5C₁ = 10, so C₁ = 2 µF and C₂ = 8 µF.\nSeries: C = (2 × 8)/(2 + 8) = 1.6 µF.\nAnswer: option (a)."},
{"y":"JEE Main 2020 · 8 Jan · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"A capacitor is made of two square plates each of side 'a' making a very small angle α between them, as shown in figure. The capacitance will be close to","fig":{"w":340,"h":170,"alt":"Two square plates of side a: a horizontal lower plate at potential V2 and an upper plate at potential V1 tilted by a small angle alpha, with gap d at the left end","d":[["l",50,120,290,120,"B"],["l",50,95,290,25,"B"],["l",50,95,290,95,"d"],["t",130,91,"α"],["l",38,95,38,120,"b"],["t",32,112,"d","e"],["l",50,145,290,145,"b"],["t",170,162,"a","m"],["t",296,124,"V₂"],["t",296,28,"V₁"]]},"o":["{ε₀a²;d}(1 − {αa;4d})","{ε₀a²;d}(1 + {αa;d})","{ε₀a²;d}(1 − {αa;2d})","{ε₀a²;d}(1 − {3αa;2d})"],"c":2,"s":"Cut the plate into thin strips of width dx at distance x from the narrow end (gap d). The gap there is d + αx.\nEach strip has C = ε₀a dx/(d + αx), and the strips are in parallel.\nC = ε₀a ∫₀^a dx/(d + αx) = (ε₀a/α) ln(1 + αa/d).\nFor small α: ln(1 + αa/d) ≈ αa/d − (αa/d)²/2, so C ≈ (ε₀a²/d)(1 − αa/2d).\nAnswer: option (c)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"Voltage rating of a parallel plate capacitor is 500 V. Its dielectric can withstand a maximum electric field of 10⁶ V m⁻¹. The plate area is 10⁻⁴ m². What is the dielectric constant if the capacitance is 15 pF? (given ε₀ = 8.86 × 10⁻¹² C² N⁻¹ m⁻²)","o":["3.8","8.5","6.2","4.5"],"c":1,"s":"The gap must be at least d = V/E = 500 / 10⁶ = 5×10⁻⁴ m.\nC = Kε₀A/d, so K = Cd/(ε₀A).\nK = 15×10⁻¹² × 5×10⁻⁴ / (8.86×10⁻¹² × 10⁻⁴) = 7.5×10⁻¹⁵ / 8.86×10⁻¹⁶.\nK ≈ 8.46 ≈ 8.5.\nAnswer: option (b)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"A parallel plate capacitor has 1 µF capacitance. One of its two plates is given +2 µC charge and the other plate, +4 µC charge. The potential difference developed across the capacitor is","o":["3 V","2 V","5 V","1 V"],"c":3,"s":"Only the difference of the plate charges sets up the field between the plates.\nThe inner faces carry ±(4 − 2)/2 = ±1 µC, so the charge on the capacitor is Q = 1 µC.\nV = Q/C = 1 µC / 1 µF = 1 V.\nAnswer: option (d)."},
{"y":"JEE Main 2019 · 9 Apr · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor with capacitance 5 μF is charged to 5 μC. If the plates are pulled apart to reduce the capacitance to 2 μF, how much work is done?","o":["6.25 × 10⁻⁶ J","3.75 × 10⁻⁶ J","2.16 × 10⁻⁶ J","2.55 × 10⁻⁶ J"],"c":1,"s":"The capacitor is isolated, so its charge stays Q = 5 μC.\nInitial energy U₁ = Q²/2C₁ = (5×10⁻⁶)²/(2×5×10⁻⁶) = 2.5×10⁻⁶ J.\nFinal energy U₂ = Q²/2C₂ = (25×10⁻¹²)/(4×10⁻⁶) = 6.25×10⁻⁶ J.\nWork done = U₂ − U₁ = 3.75×10⁻⁶ J.\nAnswer: (b)"},
{"y":"JEE Main 2019 · 9 Apr · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"The parallel combination of two air filled parallel plate capacitors of capacitance C and nC is connected to a battery of voltage, V. When the capacitors are fully charged, the battery is removed and after that a dielectric material of dielectric constant K is placed between the two plates of the first capacitor. The new potential difference of the combined system is","o":["V","{(n+1)V;K+n}","{nV;K+n}","{V;K+n}"],"c":1,"s":"Total charge: Q = (C + nC)V = (n+1)CV. It stays the same after the battery is removed.\nThe dielectric makes the first capacitance KC, so the parallel combination is KC + nC = (K+n)C.\nNew potential difference V′ = Q/C_new = (n+1)CV/[(K+n)C] = (n+1)V/(K+n).\nAnswer: (b)"},
{"y":"JEE Main 2019 · 10 Apr · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"Figure shows charge (q) versus voltage (V) graph for series and parallel combination of two given capacitors. The capacitances are","fig":{"w":340,"h":180,"alt":"Charge q in microcoulomb against voltage V: line A rises to 500 at 10 V and line B rises to 80 at 10 V, both from the origin.","d":[["l",60,150,300,150,"a"],["l",60,150,60,12,"a"],["l",60,150,240,21],["l",60,150,272,126],["l",60,50,200,50,"d"],["l",200,150,200,50,"d"],["l",60,134,200,134,"d"],["l",200,146,200,154],["t",52,54,"500","es"],["t",52,138,"80","es"],["t",200,166,"10 V","ms"],["t",70,12,"q (μC)","s"],["t",304,154,"V (volt)","s"],["t",246,20,"A"],["t",276,126,"B"]]},"o":["50 μF and 30 μF","20 μF and 30 μF","60 μF and 40 μF","40 μF and 10 μF"],"c":3,"s":"On a q–V graph the slope is the capacitance. The parallel combination has the larger slope (line A), the series combination the smaller (line B).\nLine A: 500 μC at 10 V, so C₁ + C₂ = 50 μF.\nLine B: 80 μC at 10 V, so C₁C₂/(C₁+C₂) = 8 μF, giving C₁C₂ = 8 × 50 = 400.\nTwo numbers with sum 50 and product 400 are 40 and 10.\nAnswer: (d) 40 μF and 10 μF"},
{"y":"JEE Main 2019 · 12 Apr · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"Two identical parallel plate capacitors, of capacitance C each, have plates of area A, separated by a distance d. The space between the plates of the two capacitors, is filled with three dielectrics, of equal thickness and dielectric constants K₁, K₂ and K₃. The first capacitor is filled as shown in figure I, and the second one is filled as shown in figure II.\nIf these two modified capacitors are charged by the same potential V, the ratio of the energy stored in the two, would be (E₁ refers to capacitor (I) and E₂ to capacitor (II))","fig":{"w":340,"h":170,"alt":"Two capacitors between horizontal plates: figure I has three horizontal layers K1, K2, K3 stacked one above the other; figure II has three vertical columns K1, K2, K3 side by side.","d":[["l",24,30,146,30,"B"],["l",24,130,146,130,"B"],["l",184,30,306,30,"B"],["l",184,130,306,130,"B"],["r",30,30,110,33,"f"],["r",30,63,110,34,"f"],["r",30,97,110,33,"f"],["r",190,30,37,100,"f"],["r",227,30,36,100,"f"],["r",263,30,37,100,"f"],["t",85,51,"K₁","m"],["t",85,84,"K₂","m"],["t",85,118,"K₃","m"],["t",208,84,"K₁","m"],["t",245,84,"K₂","m"],["t",281,84,"K₃","m"],["t",85,154,"(I)","m"],["t",245,154,"(II)","m"]]},"o":["E₁/E₂ = {(K₁+K₂+K₃)(K₂K₃+K₃K₁+K₁K₂);K₁K₂K₃}","E₁/E₂ = {(K₁+K₂+K₃)(K₂K₃+K₃K₁+K₁K₂);9K₁K₂K₃}","E₁/E₂ = {9K₁K₂K₃;(K₁+K₂+K₃)(K₂K₃+K₃K₁+K₁K₂)}","E₁/E₂ = {K₁K₂K₃;(K₁+K₂+K₃)(K₂K₃+K₃K₁+K₁K₂)}"],"c":2,"s":"Same V, so the energy ratio equals the capacitance ratio: E₁/E₂ = C_I/C_II.\n(I): three layers of thickness d/3 in series. 1/C_I = (d/3ε₀A)(1/K₁+1/K₂+1/K₃), so C_I = 3ε₀A K₁K₂K₃/[d(K₁K₂+K₂K₃+K₃K₁)].\n(II): three side-by-side parts of area A/3 in parallel: C_II = ε₀A(K₁+K₂+K₃)/(3d).\nDivide: E₁/E₂ = 9K₁K₂K₃ / [(K₁+K₂+K₃)(K₂K₃+K₃K₁+K₁K₂)].\nAnswer: (c)"},
{"y":"JEE Main 2019 · 12 Apr · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"In the given circuit, the charge on 4 μF capacitor will be","fig":{"w":340,"h":180,"alt":"Circuit: a 4 microfarad capacitor in series with a parallel pair of 1 and 5 microfarad, in parallel with a 3 microfarad capacitor, all across a 10 V battery.","d":[["l",40,36,40,145],["l",250,36,250,145],["l",40,36,72,36],["l",72,28,72,44],["l",78,28,78,44],["l",78,36,110,36],["l",110,18,110,54],["l",200,18,200,54],["l",110,18,152,18],["l",152,10,152,26],["l",158,10,158,26],["l",158,18,200,18],["l",110,54,152,54],["l",152,46,152,62],["l",158,46,158,62],["l",158,54,200,54],["l",200,36,250,36],["l",40,100,142,100],["l",142,92,142,108],["l",148,92,148,108],["l",148,100,250,100],["l",40,145,142,145],["l",142,135,142,155],["l",148,140,148,150],["l",148,145,250,145],["c",110,36,2.4,"F"],["c",200,36,2.4,"F"],["c",40,100,2.4,"F"],["c",250,100,2.4,"F"],["t",75,24,"4 μF","m"],["t",155,8,"1 μF","m"],["t",155,76,"5 μF","m"],["t",145,118,"3 μF","m"],["t",145,172,"10 V","m"]]},"o":["9.6 μC","24 μC","5.4 μC","13.4 μC"],"c":1,"s":"The 1 μF and 5 μF are in parallel: 6 μF. This is in series with the 4 μF.\nSeries value = (4 × 6)/(4 + 6) = 2.4 μF.\nThis branch and the 3 μF branch are both directly across the 10 V battery, so the 3 μF does not affect it.\nCharge of the branch = 2.4 μF × 10 V = 24 μC, and series capacitors carry the same charge.\nCharge on 4 μF = 24 μC.\nAnswer: (b)"},
{"y":"JEE Main 2019 · 9 Jan · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor is made of two square plates of side a, separated by a distance d (d << a). The lower triangular portion is filled with a dielectric of dielectric constant K, as shown in the figure. Capacitance of this capacitor is","fig":{"w":340,"h":175,"alt":"Square plates a wide, separated by d; a right triangular wedge of dielectric K fills the lower part, thin at the left and full height d at the right.","d":[["l",60,30,250,30,"B"],["l",60,130,250,130,"B"],["p","M60 130 L250 130 L250 30 Z","f"],["t",205,118,"K","m"],["l",60,152,250,152,"b"],["t",155,168,"a","m"],["l",270,30,270,130,"b"],["t",278,84,"d"]]},"o":["{1;2}·{Kε₀a²;d}","{Kε₀a²;d(K−1)} ln K","{Kε₀a²;2d(K+1)}","{Kε₀a²;d} ln K"],"c":1,"s":"Cut the capacitor into thin strips of width dx at distance x from the thin end of the wedge. The dielectric thickness there is t = (d/a)x and the air gap is d − t.\nEach strip is air and dielectric in series: dC = ε₀a dx / [d − t + t/K] = ε₀a dx / [d − (d/a)(1 − 1/K)x].\nStrips are in parallel, so C = ∫ dC from 0 to a = [ε₀a²/(d(1 − 1/K))] ln K.\nSimplify: C = Kε₀a² ln K / [d(K − 1)].\nAnswer: (b)"},
{"y":"JEE Main 2019 · 10 Jan · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor of area 6 cm² and separation 3 mm. The gap is filled with three dielectric materials of equal thickness (see figure) with dielectric constants K₁ = 10, K₂ = 12 and K₃ = 14. The dielectric constant of a material which when fully inserted in the given capacitor, gives same capacitance would be","fig":{"w":340,"h":135,"alt":"Parallel plates 3 mm apart with three dielectric blocks K1, K2, K3 of equal width side by side between them.","d":[["l",60,30,280,30,"B"],["l",60,110,280,110,"B"],["r",60,30,73,80,"f"],["r",133,30,73,80,"f"],["r",206,30,74,80,"f"],["t",96,75,"K₁","m"],["t",169,75,"K₂","m"],["t",243,75,"K₃","m"],["l",300,30,300,110,"b"],["t",306,74,"3 mm"]]},"o":["36","12","4","14"],"c":1,"s":"The three materials sit side by side, each filling one third of the plate area, with the full gap 3 mm. So the three parts are capacitors in parallel.\nC = (ε₀A/3d)(K₁ + K₂ + K₃).\nOne material of constant K gives C = Kε₀A/d.\nEquate: K = (10 + 12 + 14)/3 = 12.\nAnswer: (b)"},
{"y":"JEE Main 2019 · 10 Jan · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor having capacitance 12 pF is charged by a battery to a potential difference of 10 V between its plates. The charging battery is now disconnected and a porcelain slab of dielectric constant 6.5 is slipped between the plates. The work done by the capacitor on the slab is","o":["508 pJ","692 pJ","560 pJ","600 pJ"],"c":0,"s":"After disconnection the charge stays fixed, so U = Q²/2C.\nInitial energy U₁ = ½CV² = ½ × 12×10⁻¹² × 100 = 600 pJ.\nWith the slab C becomes 6.5C, so U₂ = U₁/6.5 = 92.3 pJ.\nWork done by the capacitor on the slab = U₁ − U₂ = 600 − 92.3 ≈ 508 pJ.\nAnswer: (a)"},
{"y":"JEE Main 2019 · 11 Jan · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"In the figure shown below, the charge on the left plate of the 10 μF capacitor is −30 μC. The charge on the right plate of the 6 μF capacitor is","fig":{"w":340,"h":160,"alt":"Circuit: a 10 microfarad capacitor, then a parallel pair of 6 microfarad (upper) and 4 microfarad (lower), then a 2 microfarad capacitor, all in series.","d":[["l",15,80,42,80],["l",42,72,42,88],["l",48,72,48,88],["l",48,80,110,80],["l",110,80,150,45],["l",110,80,150,115],["l",150,45,187,45],["l",187,37,187,53],["l",193,37,193,53],["l",193,45,230,45],["l",150,115,187,115],["l",187,107,187,123],["l",193,107,193,123],["l",193,115,230,115],["l",230,45,270,80],["l",230,115,270,80],["l",270,80,294,80],["l",294,72,294,88],["l",300,72,300,88],["l",300,80,325,80],["c",110,80,2.4,"F"],["c",270,80,2.4,"F"],["t",45,102,"10 μF","m"],["t",190,30,"6 μF","m"],["t",190,140,"4 μF","m"],["t",297,102,"2 μF","m"]]},"o":["−18 μC","−12 μC","+12 μC","+18 μC"],"c":3,"s":"The 10 μF, the parallel pair (6 μF and 4 μF) and the 2 μF are in series.\nLeft plate of 10 μF is −30 μC, so its right plate is +30 μC.\nThe node formed by this plate and the left plates of the 6 μF and 4 μF is neutral, so those two left plates hold −30 μC in total.\nParallel capacitors have the same voltage, so charges are in the ratio 6 : 4: left plate of 6 μF = −18 μC, of 4 μF = −12 μC.\nSo the right plate of the 6 μF is +18 μC.\nAnswer: (d)"},
{"y":"JEE Main 2019 · 11 Jan · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"Seven capacitors, each of capacitance 2 μF, are to be connected in a configuration to obtain an effective capacitance of {6;13} μF. Which of the combinations, shown in figures below, will achieve the desired value ?","fig":{"w":340,"h":240,"alt":"Four options, each a group of parallel capacitors followed by a chain of series capacitors: (a) 3 parallel and 4 in series, (b) 5 parallel and 2 in series, (c) 4 parallel and 3 in series, (d) 2 parallel and 5 in series.","d":[["c",28,34,2.4,"F"],["l",28,34,55,34],["l",55,23,55,45],["l",105,23,105,45],["l",55,23,77,23],["l",77,19,77,27],["l",83,19,83,27],["l",83,23,105,23],["l",55,34,77,34],["l",77,30,77,38],["l",83,30,83,38],["l",83,34,105,34],["l",55,45,77,45],["l",77,41,77,49],["l",83,41,83,49],["l",83,45,105,45],["l",105,34,125,34],["l",125,34,137,34],["l",137,26,137,42],["l",143,26,143,42],["l",143,34,169,34],["l",169,26,169,42],["l",175,26,175,42],["l",175,34,201,34],["l",201,26,201,42],["l",207,26,207,42],["l",207,34,233,34],["l",233,26,233,42],["l",239,26,239,42],["l",239,34,268,34],["c",268,34,2.4,"F"],["t",6,38,"(a)","s"],["c",28,92,2.4,"F"],["l",28,92,55,92],["l",55,70,55,114],["l",105,70,105,114],["l",55,70,77,70],["l",77,66,77,74],["l",83,66,83,74],["l",83,70,105,70],["l",55,81,77,81],["l",77,77,77,85],["l",83,77,83,85],["l",83,81,105,81],["l",55,92,77,92],["l",77,88,77,96],["l",83,88,83,96],["l",83,92,105,92],["l",55,103,77,103],["l",77,99,77,107],["l",83,99,83,107],["l",83,103,105,103],["l",55,114,77,114],["l",77,110,77,118],["l",83,110,83,118],["l",83,114,105,114],["l",105,92,125,92],["l",125,92,137,92],["l",137,84,137,100],["l",143,84,143,100],["l",143,92,169,92],["l",169,84,169,100],["l",175,84,175,100],["l",175,92,204,92],["c",204,92,2.4,"F"],["t",6,96,"(b)","s"],["c",28,150,2.4,"F"],["l",28,150,55,150],["l",55,133.5,55,166.5],["l",105,133.5,105,166.5],["l",55,133.5,77,133.5],["l",77,129.5,77,137.5],["l",83,129.5,83,137.5],["l",83,133.5,105,133.5],["l",55,144.5,77,144.5],["l",77,140.5,77,148.5],["l",83,140.5,83,148.5],["l",83,144.5,105,144.5],["l",55,155.5,77,155.5],["l",77,151.5,77,159.5],["l",83,151.5,83,159.5],["l",83,155.5,105,155.5],["l",55,166.5,77,166.5],["l",77,162.5,77,170.5],["l",83,162.5,83,170.5],["l",83,166.5,105,166.5],["l",105,150,125,150],["l",125,150,137,150],["l",137,142,137,158],["l",143,142,143,158],["l",143,150,169,150],["l",169,142,169,158],["l",175,142,175,158],["l",175,150,201,150],["l",201,142,201,158],["l",207,142,207,158],["l",207,150,236,150],["c",236,150,2.4,"F"],["t",6,154,"(c)","s"],["c",28,208,2.4,"F"],["l",28,208,55,208],["l",55,202.5,55,213.5],["l",105,202.5,105,213.5],["l",55,202.5,77,202.5],["l",77,198.5,77,206.5],["l",83,198.5,83,206.5],["l",83,202.5,105,202.5],["l",55,213.5,77,213.5],["l",77,209.5,77,217.5],["l",83,209.5,83,217.5],["l",83,213.5,105,213.5],["l",105,208,125,208],["l",125,208,137,208],["l",137,200,137,216],["l",143,200,143,216],["l",143,208,169,208],["l",169,200,169,216],["l",175,200,175,216],["l",175,208,201,208],["l",201,200,201,216],["l",207,200,207,216],["l",207,208,233,208],["l",233,200,233,216],["l",239,200,239,216],["l",239,208,265,208],["l",265,200,265,216],["l",271,200,271,216],["l",271,208,300,208],["c",300,208,2.4,"F"],["t",6,212,"(d)","s"]]},"o":["Figure (a)","Figure (b)","Figure (c)","Figure (d)"],"c":0,"s":"Parallel groups add, series chains add as reciprocals. Count the capacitors in each figure (all 2 μF).\n(a) 3 in parallel = 6 μF; 4 in series = 0.5 μF. Series of the two: 6 × 0.5/6.5 = 6/13 μF. This matches.\n(b) 5 in parallel = 10; 2 in series = 1; result 10/11 μF.\n(c) 4 in parallel = 8; 3 in series = 2/3; result 8/13 μF.\n(d) 2 in parallel = 4; 5 in series = 0.4; result 4/11 μF.\nAnswer: (a)"},
{"y":"JEE Main 2019 · 12 Jan · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"In the figure shown, after the switch S is turned from position A to position B, the energy dissipated in the circuit in terms of capacitance C and total charge Q is","fig":{"w":340,"h":170,"alt":"Circuit: battery epsilon in the left branch; a switch S whose pole is connected to capacitor C can touch contact A (battery) or contact B (leading to capacitor 3C in the right branch).","d":[["l",50,30,130,30],["l",50,30,50,140],["l",50,30,50,82],["l",40,82,60,82],["l",45,88,55,88],["l",50,88,50,140],["l",50,140,260,140],["c",130,30,2.5,"F"],["c",200,30,2.5,"F"],["l",200,30,260,30],["l",260,30,260,140],["l",165,52,135,33],["l",165,52,165,70],["l",165,70,165,82],["l",157,82,173,82],["l",157,88,173,88],["l",165,88,165,140],["l",260,30,260,82],["l",252,82,268,82],["l",252,88,268,88],["l",260,88,260,140],["t",130,18,"A","m"],["t",200,18,"B","m"],["t",172,50,"S"],["t",38,89,"ε","e"],["t",180,92,"C"],["t",272,92,"3C"]]},"o":["{5Q²;8C}","{Q²;8C}","{3Q²;8C}","{3Q²;4C}"],"c":2,"s":"With the switch at A, capacitor C is charged by the battery to charge Q. Energy = Q²/2C.\nAt B the battery is out of the circuit and C shares its charge with the uncharged 3C.\nCommon potential = Q/(C + 3C) = Q/4C, so final energy = Q²/[2(4C)] = Q²/8C.\nEnergy dissipated = Q²/2C − Q²/8C = 3Q²/8C.\nAnswer: (c)"},
{"y":"JEE Main 2019 · 12 Jan · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"A parallel plate capacitor with plates of area 1 m² each, are at a separation of 0.1 m. If the electric field between the plates is 100 N C⁻¹, the magnitude of charge on each plate is\n(Take ε₀ = 8.85 × 10⁻¹² C²/N m²)","o":["8.85 × 10⁻¹⁰ C","7.85 × 10⁻¹⁰ C","9.85 × 10⁻¹⁰ C","6.85 × 10⁻¹⁰ C"],"c":0,"s":"Between the plates of an air capacitor E = σ/ε₀, so σ = ε₀E.\nCharge on each plate Q = σA = ε₀EA.\nQ = 8.85×10⁻¹² × 100 × 1 = 8.85×10⁻¹⁰ C.\nThe separation 0.1 m is not needed.\nAnswer: (a)"},
{"y":"JEE Main 2019 · 12 Jan · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"In the circuit shown, find C if the effective capacitance of the whole circuit is to be 0.5 μF. All values in the circuit are in μF.","fig":{"w":340,"h":170,"alt":"Network between A and B: capacitor C in series with two branches in parallel. Left branch: a vertical capacitor then two capacitors in parallel. Right branch: a horizontal capacitor then a section that has a vertical capacitor in series with a horizontal one, in parallel with a vertical capacitor.","d":[["c",15,38,2.4,"F"],["t",10,60,"A","m"],["l",15,38,37,38],["l",37,30,37,46],["l",43,30,43,46],["l",43,38,80,38],["l",80,38,107,38],["l",107,30,107,46],["l",113,30,113,46],["l",113,38,140,38],["l",140,38,250,38],["l",80,38,80,62],["l",72,62,88,62],["l",72,68,88,68],["l",80,68,80,95],["l",80,95,105,95],["l",80,95,80,107],["l",72,107,88,107],["l",72,113,88,113],["l",80,113,80,125],["l",105,95,105,107],["l",97,107,113,107],["l",97,113,113,113],["l",105,113,105,125],["l",80,125,105,125],["l",92,125,92,145],["l",92,145,285,145],["c",285,145,2.4,"F"],["t",296,149,"B"],["l",140,38,140,62],["l",132,62,148,62],["l",132,68,148,68],["l",140,68,140,92],["l",140,92,197,92],["l",197,84,197,100],["l",203,84,203,100],["l",203,92,250,92],["l",250,38,250,62],["l",242,62,258,62],["l",242,68,258,68],["l",250,68,250,92],["l",250,92,250,145],["c",80,38,2.4,"F"],["c",140,38,2.4,"F"],["c",250,92,2.4,"F"],["t",40,24,"C","m"],["t",110,24,"2","m"],["t",70,68,"2","e"],["t",74,113,"2","e"],["t",111,113,"2"],["t",130,68,"2","e"],["t",200,110,"2","m"],["t",262,68,"1"]]},"o":["{6;5} μF","4 μF","{7;11} μF","{7;10} μF"],"c":2,"s":"Find the network to the right of C, then put C in series with it.\nLeft branch: a 2 in series with two 2's in parallel (4): 2×4/6 = 4/3 μF.\nRight branch: the 1 is in parallel with (2 in series with 2 = 1), giving 2 μF; this is in series with the horizontal 2: 2×2/4 = 1 μF.\nThe two branches are in parallel: 4/3 + 1 = 7/3 μF.\nSeries with C: C(7/3)/(C + 7/3) = 1/2, so 7C/3 = C/2 + 7/6, (11/6)C = 7/6, C = 7/11 μF.\nAnswer: (c)"},
{"y":"JEE Main 2018","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor of capacitance 90 pF is connected to a battery of emf 20 V. If a dielectric material of dielectric constant K = {5;3} is inserted between the plates, the magnitude of the induced charge will be","o":["1.2 nC","0.3 nC","2.4 nC","0.9 nC"],"c":0,"s":"The battery stays connected, so V = 20 V.\nCharge on the plates with the dielectric: Q = KCV = (5/3)(90 pF)(20 V) = 3000 pC = 3 nC.\nInduced (surface) charge on the dielectric q = Q(1 − 1/K) = 3 nC × (1 − 3/5) = 1.2 nC.\nAnswer: (a)"},
{"y":"JEE Main 2018 · Online","tp":"ecp","st":"Capacitance and combinations","q":"The equivalent capacitance between A and B in the circuit given below, is","fig":{"w":340,"h":180,"alt":"Circuit between A and B: 6 microfarad in series, then two 5 microfarad capacitors and a 2 microfarad capacitor all connected between the same two nodes, then 2 microfarad and 4 microfarad capacitors in parallel to B.","d":[["c",15,40,2.4,"F"],["t",10,28,"A","m"],["l",15,40,45,40],["l",45,32,45,48],["l",51,32,51,48],["l",51,40,85,40],["l",85,40,187,40],["l",187,32,187,48],["l",193,32,193,48],["l",193,40,230,40],["l",230,40,285,40],["l",110,40,110,67],["l",102,67,118,67],["l",102,73,118,73],["l",110,73,110,100],["l",150,40,150,67],["l",142,67,158,67],["l",142,73,158,73],["l",150,73,150,100],["l",110,100,230,100],["l",230,40,230,100],["l",230,100,230,127],["l",222,127,238,127],["l",222,133,238,133],["l",230,133,230,160],["l",285,40,285,97],["l",277,97,293,97],["l",277,103,293,103],["l",285,103,285,160],["l",230,160,310,160],["c",310,160,2.4,"F"],["t",320,164,"B"],["c",110,40,2.4,"F"],["c",150,40,2.4,"F"],["c",230,40,2.4,"F"],["c",230,100,2.4,"F"],["c",285,160,2.4,"F"],["t",48,26,"6 μF","m"],["t",190,26,"2 μF","m"],["t",102,74,"5 μF","es"],["t",158,74,"5 μF","s"],["t",222,134,"2 μF","e"],["t",297,104,"4 μF","s"]]},"o":["5.4 μF","4.9 μF","3.6 μF","2.4 μF"],"c":3,"s":"Call P the node after the 6 μF and Q the node at the right end of the 2 μF.\nThe lower wire joins the bottom plates of both 5 μF capacitors to Q. So the two 5 μF and the 2 μF all lie between P and Q: 5 + 5 + 2 = 12 μF.\nBetween Q and B the 2 μF and 4 μF are in parallel: 6 μF.\nNow 6, 12 and 6 are in series: 1/C = 1/6 + 1/12 + 1/6 = 5/12.\nC = 12/5 = 2.4 μF.\nAnswer: (d)"},
{"y":"JEE Main 2018 · Online","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor with area 200 cm² and separation between the plates 1.5 cm, is connected across a battery of emf V. If the force of attraction between the plates is 25 × 10⁻⁶ N, the value of V is approximately\n(ε₀ = 8.85 × 10⁻¹² C²/N m²)","o":["150 V","100 V","250 V","300 V"],"c":2,"s":"Force of attraction between the plates F = ½QE = ½(ε₀AV/d)(V/d) = ε₀AV²/(2d²).\nV² = 2Fd²/(ε₀A) = 2 × 25×10⁻⁶ × (1.5×10⁻²)² / (8.85×10⁻¹² × 200×10⁻⁴).\nV² = 1.125×10⁻⁸ / 1.77×10⁻¹³ ≈ 6.4×10⁴.\nV ≈ 252 V ≈ 250 V.\nAnswer: (c)"},
{"y":"JEE Main 2018 · Online","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor C₁ = 1.0 μF is charged up to a voltage V = 60 V by connecting it to battery B through switch (1). Now C₁ is disconnected from battery and connected to a circuit consisting of two uncharged capacitors C₂ = 3.0 μF and C₃ = 6.0 μF through switch (2), as shown in the figure. The sum of final charges on C₂ and C₃ is","fig":{"w":340,"h":175,"alt":"Circuit: battery B on the left, capacitor C1 in the middle, and capacitors C2 and C3 in series on the right; a switch can connect the top of C1 to the battery (position 1) or to the C2, C3 branch (position 2).","d":[["l",40,30,125,30],["l",40,30,40,150],["l",40,30,40,92],["l",30,92,50,92],["l",35,98,45,98],["l",40,98,40,150],["l",40,150,270,150],["c",125,30,2.5,"F"],["c",195,30,2.5,"F"],["l",160,70,129,34,"a"],["l",160,70,193,34,"d"],["l",160,70,160,106,"d"],["l",160,106,160,109],["l",152,109,168,109],["l",152,115,168,115],["l",160,115,160,150],["l",195,30,270,30],["l",270,30,270,55],["l",262,55,278,55],["l",262,61,278,61],["l",270,61,270,85],["l",270,85,270,109],["l",262,109,278,109],["l",262,115,278,115],["l",270,115,270,150],["t",28,98,"B","e"],["t",120,60,"(1)","e"],["t",186,56,"(2)"],["t",172,116,"C₁"],["t",284,62,"C₂"],["t",284,116,"C₃"]]},"o":["20 μC","40 μC","36 μC","54 μC"],"c":1,"s":"Charge on C₁ after step 1: Q = 1.0 × 60 = 60 μC.\nC₂ and C₃ are in series: C_eq = 3 × 6/9 = 2 μF. C₁ now shares its charge with this series pair (in parallel with it).\nCommon voltage V′ = 60/(1 + 2) = 20 V.\nCharge taken by the C₂–C₃ branch = 2 μF × 20 V = 40 μC (series capacitors carry this same charge).\nThe charge that has moved to the pair is 40 μC.\nAnswer: (b)"},
{"y":"JEE Main 2017","tp":"ecp","st":"Capacitance and combinations","q":"A capacitance of 2 μF is required in an electrical circuit across a potential difference of 1.0 kV. A large number of 1 μF capacitors are available which can withstand a potential difference of not more than 300 V.\nThe minimum number of capacitors required to achieve this is","o":["2","16","24","32"],"c":3,"s":"Each capacitor can take at most 300 V. For 1000 V we need at least 1000/300 = 3.3, so 4 capacitors in series in one row (250 V each).\nOne row of 4 in series = 1/4 μF.\nFor 2 μF we need 2/(1/4) = 8 rows in parallel.\nTotal = 4 × 8 = 32 capacitors.\nAnswer: (d)"},
{"y":"JEE Main 2017 · Online","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"The energy stored in the electric field produced by a metal sphere is 4.5 J. If the sphere contains 4 μC charge, its radius will be\n[Take: {1;4πε₀} = 9 × 10⁹ N·m²/C²]","o":["32 mm","20 mm","16 mm","28 mm"],"c":2,"s":"Energy of a charged conducting sphere: U = Q²/(8πε₀R) = (1/4πε₀)·Q²/(2R).\nR = (9×10⁹)(4×10⁻⁶)² / (2 × 4.5) = 9×10⁹ × 16×10⁻¹² / 9.\nR = 16×10⁻³ m = 16 mm.\nAnswer: (c)"},
{"y":"JEE Main 2017 · Online","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A combination of parallel plate capacitors is maintained at a certain potential difference.\nWhen a 3 mm thick slab is introduced between all the plates, in order to maintain the same potential difference, the distance between the plates is increased by 2.4 mm. Find the dielectric constant of the slab.","fig":{"w":340,"h":130,"alt":"Chain A, D, C1, C, C2, E, C3, B in series along a line; a wire joins D to E over the top and another wire joins C to the point between C3 and B underneath.","d":[["l",15,70,60,70],["l",60,70,92,70],["l",92,62,92,78],["l",98,62,98,78],["l",98,70,130,70],["l",130,70,162,70],["l",162,62,162,78],["l",168,62,168,78],["l",168,70,200,70],["l",200,70,232,70],["l",232,62,232,78],["l",238,62,238,78],["l",238,70,270,70],["l",270,70,320,70],["l",60,70,60,30],["l",60,30,200,30],["l",200,30,200,70],["l",130,70,130,110],["l",130,110,270,110],["l",270,110,270,70],["c",15,70,2.4,"F"],["c",320,70,2.4,"F"],["c",60,70,2.4,"F"],["c",130,70,2.4,"F"],["c",200,70,2.4,"F"],["c",270,70,2.4,"F"],["t",10,88,"A"],["t",60,90,"D","m"],["t",120,90,"C","m"],["t",206,90,"E","m"],["t",326,88,"B","m"],["t",95,56,"C₁","m"],["t",165,56,"C₂","m"],["t",235,56,"C₃","m"]]},"o":["6","5","4","3"],"c":1,"s":"To keep the same potential difference with the same charge, the capacitance of each capacitor must stay unchanged.\nOriginally the gap is d (capacitance ε₀A/d).\nNow the gap is d + 2.4 mm, containing a 3 mm slab. Air gap = d + 2.4 − 3 = d − 0.6 mm.\nEffective gap = (d − 0.6) + 3/K must equal d, so 3/K = 0.6.\nK = 5.\nAnswer: (b)"},
{"y":"JEE Main 2016","tp":"ecp","st":"Capacitance and combinations","q":"A combination of capacitors is set up as shown in the figure. The magnitude of the electric field due to a point charge Q (having a charge equal to the sum of the charges on the 4 μF and 9 μF capacitors), at a point distant 30 m from it, would equal","fig":{"w":340,"h":190,"alt":"Circuit: three branches across an 8 V battery. Top branch: 4 microfarad in series with a parallel pair of 3 and 9 microfarad. Middle branch: 2 microfarad. Bottom branch: the 8 V battery.","d":[["l",50,42,50,150],["l",290,42,290,150],["l",50,42,77,42],["l",77,34,77,50],["l",83,34,83,50],["l",83,42,110,42],["l",110,22,110,62],["l",240,22,240,62],["l",110,22,172,22],["l",172,14,172,30],["l",178,14,178,30],["l",178,22,240,22],["l",110,62,172,62],["l",172,54,172,70],["l",178,54,178,70],["l",178,62,240,62],["l",240,42,290,42],["l",50,112,167,112],["l",167,104,167,120],["l",173,104,173,120],["l",173,112,290,112],["l",50,150,167,150],["l",167,140,167,160],["l",173,145,173,155],["l",173,150,290,150],["c",50,112,2.4,"F"],["c",290,112,2.4,"F"],["c",110,42,2.4,"F"],["c",240,42,2.4,"F"],["t",80,28,"4 μF","m"],["t",175,10,"3 μF","m"],["t",175,82,"9 μF","m"],["t",170,98,"2 μF","m"],["t",170,174,"8 V","m"]]},"o":["240 N/C","360 N/C","420 N/C","480 N/C"],"c":2,"s":"The top branch (4 μF in series with the parallel pair 3 μF + 9 μF = 12 μF) is across the 8 V battery, like the 2 μF branch.\nTop branch capacitance = 4 × 12/16 = 3 μF, charge = 3 × 8 = 24 μC. This is the charge on the 4 μF.\nVoltage on the 12 μF part = 24/12 = 2 V, so the charge on the 9 μF = 9 × 2 = 18 μC.\nQ = 24 + 18 = 42 μC.\nE = kQ/r² = 9×10⁹ × 42×10⁻⁶ / 30² = 420 N/C.\nAnswer: (c)"},
{"y":"JEE Main 2016 · Online","tp":"ecp","st":"Capacitance and combinations","q":"Three capacitors each of 4 μF are to be connected in such a way that the effective capacitance is 6 μF. This can be done by connecting them","o":["all in series","all in parallel","two in parallel and one in series","two in series and one in parallel"],"c":3,"s":"Two 4 μF in series give 4/2 = 2 μF. Adding the third 4 μF in parallel gives 2 + 4 = 6 μF.\nCheck the others: all in series = 4/3 μF; all in parallel = 12 μF; two in parallel (8 μF) in series with one (4 μF) = 8/3 μF.\nAnswer: (d)"},
{"y":"JEE Main 2016 · Online","tp":"ecp","st":"Capacitance and combinations","q":"Figure shows a network of capacitors where the numbers indicates capacitances in micro Farad. The value of capacitance C if the equivalent capacitance between point A and B is to be 1 μF is","fig":{"w":340,"h":170,"alt":"Network between A and B: capacitor C in series with two branches in parallel. Left branch: a vertical capacitor then two capacitors in parallel. Right branch: a horizontal capacitor then a section that has a vertical capacitor in series with a horizontal one, in parallel with a vertical capacitor.","d":[["c",15,38,2.4,"F"],["t",10,60,"A","m"],["l",15,38,37,38],["l",37,30,37,46],["l",43,30,43,46],["l",43,38,80,38],["l",80,38,107,38],["l",107,30,107,46],["l",113,30,113,46],["l",113,38,140,38],["l",140,38,250,38],["l",80,38,80,62],["l",72,62,88,62],["l",72,68,88,68],["l",80,68,80,95],["l",80,95,105,95],["l",80,95,80,107],["l",72,107,88,107],["l",72,113,88,113],["l",80,113,80,125],["l",105,95,105,107],["l",97,107,113,107],["l",97,113,113,113],["l",105,113,105,125],["l",80,125,105,125],["l",92,125,92,145],["l",92,145,285,145],["c",285,145,2.4,"F"],["t",296,149,"B"],["l",140,38,140,62],["l",132,62,148,62],["l",132,68,148,68],["l",140,68,140,92],["l",140,92,197,92],["l",197,84,197,100],["l",203,84,203,100],["l",203,92,250,92],["l",250,38,250,62],["l",242,62,258,62],["l",242,68,258,68],["l",250,68,250,92],["l",250,92,250,145],["c",80,38,2.4,"F"],["c",140,38,2.4,"F"],["c",250,92,2.4,"F"],["t",40,24,"C","m"],["t",110,24,"1","m"],["t",70,68,"8","e"],["t",74,113,"2","e"],["t",111,113,"2"],["t",130,68,"6","e"],["t",200,110,"12","m"],["t",262,68,"4"]]},"o":["{32;23} μF","{31;23} μF","{33;23} μF","{34;23} μF"],"c":0,"s":"Find the network to the right of C.\nBranch from the first node: 8 in series with two 2's in parallel (4): 8×4/12 = 8/3 μF.\nOther branch: the vertical 4 is in parallel with (6 in series with 12 = 4), giving 8 μF; this is in series with the horizontal 1: 8/9 μF.\nThe two branches are in parallel: 8/3 + 8/9 = 32/9 μF.\nSeries with C: C(32/9)/(C + 32/9) = 1, so 32C/9 = C + 32/9, (23/9)C = 32/9, C = 32/23 μF.\nAnswer: (a)"},
{"y":"JEE Main 2015","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"In the given circuit, charge Q₂ on the 2 μF capacitor changes as C is varied from 1 μF to 3 μF. Q₂ as a function of 'C' is given properly by (figures are drawn schematically and are not to scale)","fig":{"w":340,"h":265,"alt":"A circuit with capacitor C in series with a parallel pair of 1 and 2 microfarad and a battery E, followed by four graphs of charge Q2 against C: (a) convex rising, (b) falling, (c) straight rising, (d) concave rising and flattening.","d":[["l",60,35,60,78],["l",290,35,290,78],["l",60,35,82,35],["l",82,27,82,43],["l",88,27,88,43],["l",88,35,110,35],["l",110,18,110,52],["l",230,18,230,52],["l",110,18,167,18],["l",167,10,167,26],["l",173,10,173,26],["l",173,18,230,18],["l",110,52,167,52],["l",167,44,167,60],["l",173,44,173,60],["l",173,52,230,52],["l",230,35,290,35],["l",60,78,172,78],["l",172,68,172,88],["l",178,73,178,83],["l",178,78,290,78],["c",110,35,2.4,"F"],["c",230,35,2.4,"F"],["t",85,22,"C","m"],["t",170,10,"1 μF","m"],["t",170,72,"2 μF","m"],["t",205,124,"E","m"],["l",35,158,160,158,"a"],["l",35,158,35,102,"a"],["p","M60 134 Q118 134 130 110"],["l",60,158,60,134,"d"],["l",130,158,130,110,"d"],["t",31,116,"Q₂","es"],["t",165,162,"C","s"],["t",60,170,"1 μF","ms"],["t",130,170,"3 μF","ms"],["t",8,106,"(a)","s"],["l",205,158,330,158,"a"],["l",205,158,205,102,"a"],["p","M230 110 Q242 144 300 144"],["l",230,158,230,110,"d"],["l",300,158,300,144,"d"],["t",201,116,"Q₂","es"],["t",335,162,"C","s"],["t",230,170,"1 μF","ms"],["t",300,170,"3 μF","ms"],["t",178,106,"(b)","s"],["l",35,243,160,243,"a"],["l",35,243,35,187,"a"],["l",60,221,130,197],["l",60,243,60,221,"d"],["l",130,243,130,197,"d"],["t",31,201,"Q₂","es"],["t",165,247,"C","s"],["t",60,255,"1 μF","ms"],["t",130,255,"3 μF","ms"],["t",8,191,"(c)","s"],["l",205,243,330,243,"a"],["l",205,243,205,187,"a"],["p","M230 219 Q242 195 300 195"],["l",230,243,230,219,"d"],["l",300,243,300,195,"d"],["t",201,201,"Q₂","es"],["t",335,247,"C","s"],["t",230,255,"1 μF","ms"],["t",300,255,"3 μF","ms"],["t",178,191,"(d)","s"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":3,"s":"C is in series with the parallel pair 1 μF + 2 μF = 3 μF, across the battery E.\nVoltage across the pair = E·C/(C + 3) (in μF).\nQ₂ = 2 × that = 2EC/(C + 3).\nAt C = 1 μF, Q₂ = E/2, not zero. As C increases Q₂ rises, but the slope keeps falling and the curve flattens (towards 2E).\nA rising, concave curve that starts above zero is graph (d).\nAnswer: (d)"},
{"y":"JEE Main 2015 · Online","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"In figure is shown a system of four capacitors connected across a 10 V battery. Charge that will flow from switch S when it is closed is","fig":{"w":340,"h":170,"alt":"Four capacitors across a 10 V battery: top branch 2 microfarad then node a then 3 microfarad; bottom branch 3 microfarad then node b then 2 microfarad; a switch S joins a and b.","d":[["l",50,35,50,145],["l",290,35,290,145],["l",50,35,97,35],["l",97,27,97,43],["l",103,27,103,43],["l",103,35,170,35],["l",170,35,237,35],["l",237,27,237,43],["l",243,27,243,43],["l",243,35,290,35],["l",50,95,97,95],["l",97,87,97,103],["l",103,87,103,103],["l",103,95,170,95],["l",170,95,237,95],["l",237,87,237,103],["l",243,87,243,103],["l",243,95,290,95],["l",170,35,170,50],["l",170,50,180,72],["c",170,80,2.2,"F"],["l",170,80,170,95],["l",50,145,167,145],["l",167,135,167,155],["l",173,140,173,150],["l",173,145,290,145],["c",170,35,2.4,"F"],["c",170,95,2.4,"F"],["t",100,21,"2 μF","m"],["t",240,21,"3 μF","m"],["t",100,117,"3 μF","m"],["t",240,117,"2 μF","m"],["t",178,29,"a","s"],["t",178,112,"b","s"],["t",188,66,"S"],["t",170,167,"10 V","m"]]},"o":["5 μC from b to a","20 μC from a to b","5 μC from a to b","zero"],"c":0,"s":"Take the right rail as 0 V; the long plate of the battery is positive, so the left rail is at +10 V.\nTop branch (2 μF then 3 μF): the smaller capacitor takes the larger voltage, so the 3 μF has 4 V and V_a = 4 V.\nBottom branch (3 μF then 2 μF): the 2 μF has 6 V, so V_b = 6 V. Point b is higher.\nNodes a and b each hold zero net charge. After closing S the joined node is at x with zero net charge: 2(x−10) + 3x + 3(x−10) + 2x = 0, so x = 5 V.\nCharge now on node a = 2(5−10) + 3(5) = +5 μC; it was 0. So +5 μC flows from b to a.\nAnswer: (a)"},
{"y":"JEE Main 2014","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor is made of two circular plates separated by a distance of 5 mm and with a dielectric of dielectric constant 2.2 between them. When the electric field in the dielectric is 3 × 10⁴ V/m, the charge density of the positive plate will be close to","o":["6 × 10⁴ C/m²","6 × 10⁻⁷ C/m²","3 × 10⁻⁷ C/m²","3 × 10⁴ C/m²"],"c":1,"s":"With a dielectric, the field is E = σ/(Kε₀), where σ is the free charge density on the plate.\nσ = Kε₀E = 2.2 × 8.85×10⁻¹² × 3×10⁴.\nσ ≈ 5.8×10⁻⁷ C/m² ≈ 6×10⁻⁷ C/m².\nThe 5 mm separation is not needed.\nAnswer: (b)"},
{"y":"JEE Main 2014 · Online","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor is made of two plates of length l, width w and separated by distance d. A dielectric slab (dielectric constant K) that fits exactly between the plates is held near the edge of the plates. It is pulled into the capacitor by a force F = −{∂U;∂x}, where U is the energy of the capacitor when dielectric is inside the capacitor up to distance x (see figure). If the charge on the capacitor is Q then the force on the dielectric when it is near the edge is:","fig":{"w":340,"h":230,"alt":"Two vertical plates of length l separated by d with a dielectric slab pulled into the gap from the top by a distance x.","d":[["l",130,20,130,190,"B"],["l",190,20,190,190,"B"],["r",131,6,58,54,"f"],["l",215,20,215,60,"b"],["t",222,44,"x"],["t",160,36,"K","m"],["l",100,20,100,190,"b"],["t",92,108,"l","e"],["l",130,208,190,208,"b"],["t",160,224,"d","m"]]},"o":["{Q²d;2wl²ε₀}K","{Q²w;2dl²ε₀}(K−1)","{Q²d;2wl²ε₀}(K−1)","{Q²w;2dl²ε₀}K"],"c":2,"s":"The charge Q is fixed, so U = Q²/2C and F = −dU/dx = (Q²/2C²)(dC/dx).\nWith the slab in by x, the capacitor is two parts in parallel: C = ε₀w[l + (K−1)x]/d, so dC/dx = ε₀w(K−1)/d.\nNear the edge x ≈ 0, so C = ε₀wl/d.\nF = (Q²/2) · d²/(ε₀²w²l²) · ε₀w(K−1)/d = Q²d(K−1)/(2ε₀wl²).\nAnswer: (c)"},
{"y":"JEE Main 2013","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two capacitors C₁ and C₂ are charged to 120 V and 200 V respectively. It is found that by connecting them together the potential on each one can be made zero. Then","o":["9C₁ = 4C₂","5C₁ = 3C₂","3C₁ = 5C₂","3C₁ + 5C₂ = 0"],"c":2,"s":"For both potentials to become zero after joining, the charges must cancel exactly: join the plates of opposite sign.\nQ₁ = 120C₁ and Q₂ = 200C₂.\nNet charge zero: 120C₁ = 200C₂, so 3C₁ = 5C₂.\nAnswer: (c)"},
{"y":"IIT-JEE 2012","tp":"ecp","st":"Capacitance and combinations","q":"In the given circuit, a charge of +80 μC is given to the upper plate of the 4 μF capacitor. Then in the steady state, the charge on the upper plate of the 3 μF capacitor is","fig":{"w":340,"h":185,"alt":"A 4 microfarad capacitor with +80 microcoulomb on its upper plate, connected below to a parallel pair of 2 and 3 microfarad capacitors whose lower plates are earthed.","d":[["c",170,12,3],["l",170,15,170,42],["l",170,15,170,42],["l",162,42,178,42],["l",162,48,178,48],["l",170,48,170,75],["l",100,75,240,75],["l",100,75,100,102],["l",92,102,108,102],["l",92,108,108,108],["l",100,108,100,145],["l",240,75,240,102],["l",232,102,248,102],["l",232,108,248,108],["l",240,108,240,145],["l",100,145,240,145],["c",170,75,2.4,"F"],["c",170,145,2.4,"F"],["l",170,144,170,150],["l",158,150,182,150],["l",162,155,178,155],["l",166,160,174,160],["t",150,38,"+80 μC","e"],["t",184,50,"4 μF"],["t",88,108,"2 μF","e"],["t",254,108,"3 μF"]]},"o":["+32 μC","+40 μC","+48 μC","+80 μC"],"c":2,"s":"The +80 μC on the upper plate of the 4 μF induces −80 μC on its lower plate. So +80 μC is left on the connected upper plates of the 2 μF and 3 μF capacitors.\nThese two are in parallel (lower plates earthed), so they share the charge in proportion to their capacitance.\nCharge on 3 μF = (3/(2+3)) × 80 = 48 μC.\nAnswer: (c) +48 μC"},
{"y":"AIEEE 2012 · Online","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two circuits (a) and (b) have charged capacitors of capacitance C, 2C and 3C with open switches. Charges on each of the capacitor are as shown in the figures. On closing the switches","fig":{"w":340,"h":160,"alt":"Two circuits (a) and (b), each a loop with a switch, a left capacitor and a right capacitor, with the charges 2Q and Q marked on their upper plates. In (a) the capacitances are 3C and C; in (b) they are 2C and 2C.","d":[["l",30,30,30,120],["l",130,30,130,120],["l",30,120,130,120],["l",30,30,70,30],["l",70,30,90,18],["c",95,30,2.2,"F"],["l",95,30,130,30],["l",30,30,30,72],["l",22,72,38,72],["l",22,78,38,78],["l",30,78,30,120],["l",130,30,130,72],["l",122,72,138,72],["l",122,78,138,78],["l",130,78,130,120],["t",24,70,"2Q","e"],["t",24,86,"3C","e"],["t",138,70,"Q"],["t",138,86,"C"],["t",30,134,"L","m"],["t",130,134,"R","m"],["t",85,16,"S","m"],["l",190,30,190,120],["l",290,30,290,120],["l",190,120,290,120],["l",190,30,230,30],["l",230,30,250,18],["c",255,30,2.2,"F"],["l",255,30,290,30],["l",190,30,190,72],["l",182,72,198,72],["l",182,78,198,78],["l",190,78,190,120],["l",290,30,290,72],["l",282,72,298,72],["l",282,78,298,78],["l",290,78,290,120],["t",184,70,"2Q","e"],["t",184,86,"2C","e"],["t",298,70,"Q"],["t",298,86,"2C"],["t",190,134,"L","m"],["t",290,134,"R","m"],["t",245,16,"S","m"],["c",30,120,2.4,"F"],["c",130,120,2.4,"F"],["c",190,120,2.4,"F"],["c",290,120,2.4,"F"],["t",80,156,"(a)","m"],["t",240,156,"(b)","m"]]},"o":["No charge flows in (a) but charge flows from R to L in (b)","Charges flow from L to R in both (a) and (b)","Charges flow from R to L in (a) and from L to R in (b)","No charge flows in (a) but charge flows from L to R in (b)"],"c":2,"s":"On closing S, the plates joined by the switch (the charged upper plates) go to a common potential, so charge flows from the higher-potential capacitor to the lower one. Voltage = charge/capacitance.\n(a) Left: 2Q/3C = 0.67 Q/C. Right: Q/C. The right capacitor is higher, so charge flows from R side to L side.\n(b) Left: 2Q/2C = Q/C. Right: Q/2C. The left is higher, so charge flows from L to R.\nAnswer: (c)"},
{"y":"AIEEE 2012 · Online","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A series combination of n₁ capacitors, each of value C₁, is charged by source of potential difference 4V. When another parallel combination of n₂ capacitors, each of value C₂, is charged by a source of potential difference V, it has the same total energy stored in it as the first combination has. The value of C₂ in terms of C₁ is then","o":["16 {n₂;n₁} C₁","{2C₁;n₁n₂}","2 {n₂;n₁} C₁","{16C₁;n₁n₂}"],"c":3,"s":"Series combination: C_s = C₁/n₁, energy U₁ = ½(C₁/n₁)(4V)² = 8C₁V²/n₁.\nParallel combination: C_p = n₂C₂, energy U₂ = ½n₂C₂V².\nSet U₁ = U₂: ½n₂C₂V² = 8C₁V²/n₁.\nC₂ = 16C₁/(n₁n₂).\nAnswer: (d)"},
{"y":"IIT-JEE 2011","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A 2 μF capacitor is charged as shown in figure. The percentage of its stored energy dissipated after the switch S is turned to position 2 is","fig":{"w":340,"h":170,"alt":"Circuit: battery V on the left, a switch S that can touch contact 1 (battery) or contact 2 (the 8 microfarad capacitor on the right), and a 2 microfarad capacitor connected to the switch pole.","d":[["l",40,30,115,30],["l",40,30,40,140],["l",40,30,40,82],["l",30,82,50,82],["l",35,88,45,88],["l",40,88,40,140],["l",40,140,260,140],["c",115,30,2.5,"F"],["c",150,30,2.5,"F"],["l",150,30,260,30],["l",260,30,260,140],["l",132,52,117,33],["l",132,52,132,70],["l",132,70,132,92],["l",124,92,140,92],["l",124,98,140,98],["l",132,98,132,140],["l",260,30,260,82],["l",252,82,268,82],["l",252,88,268,88],["l",260,88,260,140],["t",112,22,"1","m"],["t",152,22,"2","m"],["t",140,52,"S"],["t",28,89,"V","e"],["t",120,100,"2 μF","e"],["t",248,92,"8 μF","e"]]},"o":["0%","20%","75%","80%"],"c":3,"s":"In position 1 the 2 μF is charged to V: U₁ = ½(2)V² = V² (in μJ).\nIn position 2 the battery is out and the 2 μF shares its charge with the uncharged 8 μF. Common voltage = 2V/(2+8) = V/5.\nFinal energy = ½(10)(V/5)² = V²/5.\nEnergy lost = V² − V²/5 = 4V²/5, which is 80% of the initial energy.\nAnswer: (d)"},
{"y":"AIEEE 2008","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor with air between the plates has a capacitance of 9 pF. The separation between its plates is d. The space between the plates is now filled with two dielectrics. One of the dielectrics has dielectric constant k₁ = 3 and thickness {d;3} while the other one has dielectric constant k₂ = 6 and thickness {2d;3}. Capacitance of the capacitor is now","o":["20.25 pF","1.8 pF","45 pF","40.5 pF"],"c":3,"s":"The two layers are in series. Let C₀ = ε₀A/d = 9 pF.\nLayer 1: C₁ = k₁ε₀A/(d/3) = 9C₀ = 81 pF.\nLayer 2: C₂ = k₂ε₀A/(2d/3) = 9C₀ = 81 pF.\nSeries: C = 81/2 = 40.5 pF.\nAnswer: (d)"},
{"y":"AIEEE 2007","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate condenser with a dielectric of dielectric constant K between the plates has a capacity C and is charged to a potential V volt. The dielectric slab is slowly removed from between the plates and then reinserted. The net work done by the system in this process is","o":["zero","½(K − 1)CV²","{CV²(K−1);K}","(K − 1)CV²"],"c":0,"s":"The electric force on the slab is conservative and the process is slow.\nRemoving the slab and putting it back returns the system to exactly its starting state (same capacitance, same charge, same energy).\nSo the work done by the system on the way out is cancelled by the work on the way in.\nNet work = 0.\nAnswer: (a)"},
{"y":"AIEEE 2007","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A battery is used to charge a parallel plate capacitor till the potential difference between the plates becomes equal to the electromotive force of the battery. The ratio of the energy stored in the capacitor and the work done by the battery will be","o":["1/2","1","2","1/4"],"c":0,"s":"Energy stored in the capacitor U = ½CV².\nThe battery moves charge Q = CV through potential V, so its work W = QV = CV².\nU/W = 1/2 (the other half is lost as heat in the wires).\nAnswer: (a)"},
{"y":"AIEEE 2006","tp":"ecn","st":"Charge sharing and earthing","q":"Two spherical conductors A and B of radii 1 mm and 2 mm are separated by a distance of 5 cm and are uniformly charged. If the spheres are connected by a conducting wire then in equilibrium condition, the ratio of the magnitude of the electric fields at the surface of spheres A and B is","o":["1 : 4","4 : 1","1 : 2","2 : 1"],"c":3,"s":"Joined by a wire, both spheres reach the same potential V.\nAt the surface of a sphere V = kq/r and E = kq/r² = V/r, so E ∝ 1/r.\nE_A/E_B = r_B/r_A = 2 mm/1 mm = 2.\nRatio = 2 : 1.\nAnswer: (d)"},
{"y":"AIEEE 2005","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A fully charged capacitor has a capacitance C. It is discharged through a small coil of resistance wire embedded in a thermally insulated block of specific heat capacity s and mass m. If the temperature of the block is raised by ΔT, the potential difference V across the capacitor is","o":["{msΔT;C}","√{2msΔT;C}","√{2mCΔT;s}","{mCΔT;s}"],"c":1,"s":"The energy stored in the capacitor, ½CV², is turned into heat in the block.\nHeat gained = msΔT.\n½CV² = msΔT, so V = √(2msΔT/C).\nAnswer: (b)"},
{"y":"AIEEE 2005","tp":"ecp","st":"Capacitance and combinations","q":"A parallel plate capacitor is made by stacking n equally spaced plates connected alternately. If the capacitance between any two adjacent plates is C then the resultant capacitance is","o":["C","nC","(n − 1)C","(n + 1)C"],"c":2,"s":"Plates 1, 3, 5, … are joined to one terminal and plates 2, 4, 6, … to the other.\nn plates make n − 1 gaps, so there are n − 1 capacitors, each of capacitance C, all in parallel.\nTotal = (n − 1)C.\nAnswer: (c)"},
{"y":"AIEEE 2003","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"The work done in placing a charge of 8 × 10⁻¹⁸ coulomb on a condenser of capacity 100 micro-farad is","o":["16 × 10⁻³² joule","3.1 × 10⁻²⁶ joule","4 × 10⁻¹⁰ joule","32 × 10⁻³² joule"],"c":3,"s":"Work done = energy stored = q²/2C.\nW = (8×10⁻¹⁸)² / (2 × 100×10⁻⁶) = 64×10⁻³⁶ / (2×10⁻⁴).\nW = 32×10⁻³² J.\nAnswer: (d)"},
{"y":"AIEEE 2003","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A sheet of aluminium foil of negligible thickness is introduced between the plates of a capacitor. The capacitance of the capacitor","o":["decreases","remains unchanged","becomes infinite","increases"],"c":1,"s":"The foil, parallel to the plates, splits the gap into two gaps d₁ and d₂ and makes two capacitors in series.\nBecause the foil is very thin, d₁ + d₂ = d.\n1/C = d₁/ε₀A + d₂/ε₀A = d/ε₀A, the same as before.\nThe capacitance remains unchanged.\nAnswer: (b)"},
{"y":"AIEEE 2002","tp":"ecp","st":"Capacitance and combinations","q":"Capacitance (in F) of a spherical conductor with radius 1 m is","o":["1.1 × 10⁻¹⁰","10⁻⁶","9 × 10⁻⁹","10⁻³"],"c":0,"s":"Capacitance of an isolated sphere C = 4πε₀R = R/(9×10⁹).\nFor R = 1 m, C = 1/(9×10⁹) = 1.1×10⁻¹⁰ F.\nAnswer: (a)"},
{"y":"AIEEE 2002","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"If there are n capacitors in parallel connected to V volt source, then the energy stored is equal to","o":["CV","½nCV²","CV²","{1;2n}CV²"],"c":1,"s":"In parallel each capacitor has the full voltage V.\nEach stores ½CV², and there are n of them.\nTotal energy = n × ½CV² = ½nCV².\nAnswer: (b)"},
{"y":"IIT-JEE 2002","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two identical capacitors have the same capacitance C. One of them is charged to potential V₁ and the other V₂. The negative ends of the capacitors are connected together. When the positive ends are also connected, the decrease in energy of the combined system is","o":["¼C(V₁² − V₂²)","¼C(V₁² + V₂²)","¼C(V₁ − V₂)²","¼C(V₁ + V₂)²"],"c":2,"s":"Charges of the same sign add: total charge C(V₁ + V₂) on total capacitance 2C, so V = (V₁ + V₂)/2.\nInitial energy = ½C(V₁² + V₂²). Final energy = ½(2C)[(V₁+V₂)/2]² = ¼C(V₁+V₂)².\nDecrease = ¼C[2V₁² + 2V₂² − (V₁² + 2V₁V₂ + V₂²)] = ¼C(V₁ − V₂)².\nAnswer: (c)"},
{"y":"IIT-JEE 2001","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Consider the situation shown in the figure. The capacitor A has a charge q on it whereas B is uncharged. The charge appearing on the capacitor B long time after the switch is closed is","fig":{"w":340,"h":160,"alt":"Capacitor A with plates carrying +q (left plate) and -q (right plate); its right plate is joined by a switch S to the left plate of capacitor B; the right plate of B is connected to nothing.","d":[["l",50,25,50,125,"B"],["l",90,25,90,125,"B"],["l",170,25,170,125,"B"],["l",210,25,210,125,"B"],["t",58,36,"+","ms"],["t",58,56,"+","ms"],["t",58,76,"+","ms"],["t",58,96,"+","ms"],["t",58,116,"+","ms"],["t",82,36,"−","ms"],["t",82,56,"−","ms"],["t",82,76,"−","ms"],["t",82,96,"−","ms"],["t",82,116,"−","ms"],["l",90,75,120,75],["l",120,75,138,63],["c",142,75,2.2,"F"],["l",142,75,170,75],["t",130,100,"S","m"],["t",70,144,"A","m"],["t",190,144,"B","m"],["t",50,14,"q","m"]]},"o":["zero","q/2","q","2q"],"c":0,"s":"Closing S joins the right (negative) plate of A to the left plate of B.\nThe right plate of B is connected to nothing, so no charge can flow to it or away from it. It stays neutral.\nWith no charge available on the far plate, B cannot hold equal and opposite charges on its plates.\nAll the charge stays on A; B has zero charge.\nAnswer: (a)"},
{"y":"IIT-JEE 2000","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor of area A, plate separation d and capacitance C is filled with three different dielectric materials having dielectric constant K₁, K₂ and K₃ as shown in the figure. If a single dielectric material is to be used to have the same capacitance C in this capacitor, then its dielectric constant K is given by","fig":{"w":340,"h":175,"alt":"Parallel plates of area A, separation d. The upper half has K1 on the left and K2 on the right, each of area A/2; the lower half is K3 across the full area.","d":[["l",60,30,260,30,"B"],["l",60,130,260,130,"B"],["r",60,30,100,50,"f"],["r",160,30,100,50,"f"],["r",60,80,200,50,"f"],["t",110,60,"K₁","m"],["t",210,60,"K₂","m"],["t",160,110,"K₃","m"],["t",110,22,"A/2","m"],["t",210,22,"A/2","m"],["t",160,150,"A","m"],["l",40,30,40,130,"b"],["t",32,84,"d","e"]]},"o":["{1;K} = {1;K₁} + {1;K₂} + {1;2K₃}","{1;K} = {1;K₁+K₂} + {1;2K₃}","K = {K₁K₂;K₁+K₂} + 2K₃","K = K₁ + K₂ + 2K₃"],"c":1,"s":"Top layer (thickness d/2): K₁ and K₂ side by side, each of area A/2, so they are in parallel: C_top = ε₀(A/2)(K₁+K₂)/(d/2) = ε₀A(K₁+K₂)/d.\nBottom layer (thickness d/2): K₃ over area A: C_bot = ε₀AK₃/(d/2) = 2ε₀AK₃/d.\nThe two layers are in series: 1/C = d/[ε₀A(K₁+K₂)] + d/(2ε₀AK₃).\nFor one material C = Kε₀A/d, so 1/K = 1/(K₁+K₂) + 1/(2K₃).\nAnswer: (b)"},
{"y":"IIT-JEE 1999","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"For the circuit shown in figure, which of the following statements is true?","fig":{"w":340,"h":150,"alt":"Earth, switch S1, capacitor C1 (2 pF, charged to 30 V), switch S3, capacitor C2 (3 pF, charged to 20 V), switch S2 and earth in series along one line.","d":[["l",25,50,25,115],["l",25,109,25,115],["l",13,115,37,115],["l",17,120,33,120],["l",21,125,29,125],["l",25,50,45,50],["l",45,50,63,38],["c",67,50,2.2,"F"],["l",67,50,85,50],["l",85,50,115,50],["l",115,42,115,58],["l",121,42,121,58],["l",121,50,160,50],["l",160,50,177.5,50],["l",177.5,50,195.5,38],["c",199.5,50,2.2,"F"],["l",199.5,50,215,50],["l",215,50,240,50],["l",240,42,240,58],["l",246,42,246,58],["l",246,50,272,50],["l",272,50,282,50],["l",282,50,300,38],["c",304,50,2.2,"F"],["l",304,50,312,50],["l",312,50,312,115],["l",312,109,312,115],["l",300,115,324,115],["l",304,120,320,120],["l",308,125,316,125],["t",112,40,"+","ms"],["t",126,40,"−","ms"],["t",237,40,"+","ms"],["t",251,40,"−","ms"],["t",55,30,"S₁","m"],["t",188,30,"S₃","m"],["t",292,30,"S₂","m"],["t",118,74,"C₁ = 2 pF","ms"],["t",118,90,"V₁ = 30 V","ms"],["t",243,74,"C₂ = 3 pF","ms"],["t",243,90,"V₂ = 20 V","ms"]]},"o":["With S₁ closed, V₁ = 15 V, V₂ = 20 V","With S₃ closed, V₁ = V₂ = 25 V","With S₁ and S₂ closed, V₁ = V₂ = 0","With S₁ and S₃ closed, V₁ = 30 V, V₂ = 20 V"],"c":3,"s":"Charge can change on a capacitor only if there is a complete closed conducting loop through it.\n(a) Only S₁ closed: one end earthed, the other floating, no loop. V₁ stays 30 V, V₂ stays 20 V.\n(b) Only S₃ closed: no connection to earth, no loop. Nothing changes, so not 25 V each.\n(c) S₁ and S₂ closed, S₃ open: C₁ and C₂ are each connected to earth on one side only, no loop. Nothing changes.\n(d) S₁ and S₃ closed, S₂ open: C₁ and C₂ in series from earth to a floating end, no loop. V₁ = 30 V, V₂ = 20 V stay. True.\nAnswer: (d)"},
{"y":"IIT-JEE 1999","tp":"ecp","st":"Capacitance and combinations","q":"Two identical metal plates are given positive charges Q₁ and Q₂ (< Q₁) respectively. If they are now brought close together to form a parallel plate capacitor with capacitance C, the potential difference between them is","o":["(Q₁ + Q₂)/(2C)","(Q₁ + Q₂)/C","(Q₁ − Q₂)/C","(Q₁ − Q₂)/(2C)"],"c":3,"s":"When two plates are brought close, the outer faces carry equal charge (Q₁ + Q₂)/2 each.\nThe inner (facing) faces then carry +(Q₁ − Q₂)/2 and −(Q₁ − Q₂)/2.\nThe charge of the capacitor is q = (Q₁ − Q₂)/2.\nV = q/C = (Q₁ − Q₂)/(2C).\nAnswer: (d)"},
{"y":"IIT-JEE 1995","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor of capacitance C is connected to a battery and is charged to a potential difference V. Another capacitor of capacitance 2C is similarly charged to a potential difference 2V. The charging battery is now disconnected and the capacitors are connected in parallel to each other in such a way that the positive terminal of one is connected to the negative terminal of the other. The final energy of the configuration is","o":["zero","{3;2}CV²","{25;6}CV²","{9;2}CV²"],"c":1,"s":"Charges: Q₁ = CV and Q₂ = (2C)(2V) = 4CV. Opposite terminals joined, so net charge = 4CV − CV = 3CV.\nTotal capacitance = 3C, so the common voltage = 3CV/3C = V.\nFinal energy = ½(3C)V² = (3/2)CV².\nAnswer: (b)"},
{"y":"JEE Advanced 2022","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A medium having dielectric constant K > 1 fills the space between the plates of a parallel plate capacitor. The plates have large area, and the distance between them is d. The capacitor is connected to a battery of voltage V, as shown in figure (a). Now, both the plates are moved by a distance of d/2 from their original positions, as shown in figure (b).\nIn the process of going from the configuration depicted in figure (a) to that in figure (b), which of the following statement(s) is (are) correct?","fig":{"w":340,"h":175,"alt":"Figure (a): a capacitor with a dielectric slab of thickness d filling the gap, connected to a battery V. Figure (b): the plates have been moved apart by d/2 on each side, leaving air gaps d/2 either side of the slab.","d":[["l",55,20,55,85,"B"],["l",105,20,105,85,"B"],["r",56,20,48,65,"f"],["l",55,85,55,135],["l",105,85,105,135],["l",55,135,74,135],["l",74,125,74,145],["l",80,130,80,140],["l",80,135,105,135],["l",55,12,105,12,"b"],["t",80,8,"d","ms"],["t",80,158,"Figure (a)","ms"],["t",46,150,"V","s"],["l",215,20,215,85,"B"],["l",315,20,315,85,"B"],["r",240,20,50,65,"f"],["l",215,85,215,135],["l",315,85,315,135],["l",215,135,262,135],["l",262,125,262,145],["l",268,130,268,140],["l",268,135,315,135],["l",215,98,240,98,"b"],["l",240,98,290,98,"b"],["l",290,98,315,98,"b"],["t",227,112,"d/2","ms"],["t",265,112,"d","ms"],["t",302,112,"d/2","ms"],["t",265,158,"Figure (b)","ms"],["t",236,150,"V","s"]]},"o":["The electric field inside the dielectric material is reduced by a factor of 2K.","The capacitance is decreased by a factor of {1;K+1}.","The voltage between the capacitor plates is increased by a factor of (K + 1).","The work done in the process DOES NOT depend on the presence of the dielectric material."],"c":1,"s":"The battery stays connected, so the plate voltage is V throughout. This rules out (c).\n(a): C = Kε₀A/d. (b): the gap is 2d, with the slab (d) in the middle and air of total thickness d: C′ = ε₀A/(d + d/K) = Kε₀A/[d(K+1)].\nC′/C = 1/(K+1): so (b) is correct.\nField in the slab E = σ/(Kε₀) = C′V/(Kε₀A) = V/[d(K+1)], compared with V/d before: reduced by a factor (K+1), not 2K. So (a) is wrong.\nThe force on a plate depends on the charge density, which depends on K, so the work depends on the dielectric: (d) is wrong.\nAnswer: (b) only"},
{"y":"JEE Advanced 2015","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor having plates of area S and plate separation d, has capacitance C₁ in air. When two dielectrics of different relative permittivities (ε₁ = 2 and ε₂ = 4) are introduced between the two plates as shown in the figure, the capacitance becomes C₂. The ratio {C₂;C₁} is","fig":{"w":340,"h":185,"alt":"Side view of a capacitor: left plate positive, right plate negative, gap d. The lower half of the area is filled with epsilon 1 over the whole gap; in the upper half epsilon 1 fills the left half of the gap and epsilon 2 the right half.","d":[["l",70,20,70,140,"B"],["l",250,20,250,140,"B"],["r",70,20,180,120,"f"],["l",70,80,250,80,"d"],["l",160,20,160,80,"d"],["t",115,55,"ε₁","m"],["t",205,55,"ε₂","m"],["t",160,115,"ε₁","m"],["t",258,54,"S/2"],["t",258,114,"S/2"],["l",70,160,250,160,"b"],["t",160,176,"d","m"],["l",160,12,250,12,"b"],["t",205,8,"d/2","ms"],["l",30,80,70,80],["t",24,76,"+","e"],["l",250,80,290,80],["t",296,84,"−"]]},"o":["6/5","5/3","7/5","7/3"],"c":3,"s":"Split the plate area into two halves of S/2 that are in parallel.\nLower half: ε₁ over the full gap d: C = 2ε₀(S/2)/d = ε₀S/d.\nUpper half: ε₁ (thickness d/2) in series with ε₂ (thickness d/2): 1/C = (d/2)/(2ε₀S/2) + (d/2)/(4ε₀S/2) = d/(2ε₀S) + d/(4ε₀S) = 3d/(4ε₀S), so C = 4ε₀S/(3d).\nC₂ = ε₀S/d + 4ε₀S/(3d) = 7ε₀S/(3d), and C₁ = ε₀S/d.\nC₂/C₁ = 7/3.\nAnswer: (d)"},
{"y":"JEE Advanced 2014","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor has a dielectric slab of dielectric constant K between its plates that covers 1/3 of the area of its plates, as shown in the figure. The total capacitance of the capacitor is C while that of the portion with dielectric in between is C₁. When the capacitor is charged, the plate area covered by the dielectric gets charge Q₁ and the rest of the area gets charge Q₂. The electric field in the dielectric is E₁ and that in the other portion is E₂. Choose the correct option/options, ignoring edge effects.","fig":{"w":340,"h":205,"alt":"Two vertical plates; the top third of the gap is filled with dielectric K, with charge Q1 on that part of the plate and field E1; the lower two thirds are air with charge Q2 and field E2.","d":[["l",100,20,100,190,"B"],["l",240,20,240,190,"B"],["r",101,20,138,57,"f"],["t",92,52,"Q₁","e"],["t",92,130,"Q₂","e"],["t",130,52,"K","m"],["t",200,52,"E₁","m"],["t",170,130,"E₂","m"]]},"o":["E₁/E₂ = 1","E₁/E₂ = 1/K","Q₁/Q₂ = 3/K","C/C₁ = {2+K;K}"],"c":[0,3],"s":"The plates are conductors, so the potential difference V across both portions is the same, and the gap d is the same. So E = V/d in both: E₁ = E₂. (a) is correct, (b) is wrong.\nCharge on a portion = (its capacitance) × V. Dielectric part has area A/3: Q₁ = Kε₀(A/3)V/d. The rest has area 2A/3: Q₂ = ε₀(2A/3)V/d.\nQ₁/Q₂ = K/2, not 3/K, so (c) is wrong.\nC₁ = Kε₀A/(3d) and C = ε₀A(K+2)/(3d), so C/C₁ = (K+2)/K. (d) is correct.\nAnswer: (a) and (d)"},
{"y":"JEE Advanced 2013","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"In the circuit shown in the figure, there are two parallel plate capacitors each of capacitance C. The switch S₁ is pressed first to fully charge the capacitor C₁ and then released. The switch S₂ is then pressed to charge the capacitor C₂. After some time, S₂ is released and then S₃ is pressed. After some time,","fig":{"w":340,"h":175,"alt":"Circuit: a 2V0 battery on the left (top terminal positive) with switch S1, capacitor C1, switch S2, capacitor C2, switch S3 and a V0 battery on the right (top terminal negative), all joined by a common bottom wire.","d":[["l",40,30,40,80],["l",40,87,40,140],["l",30,80,50,80],["l",35,87,45,87],["l",40,30,65,30],["l",65,30,83,18],["c",87,30,2.2,"F"],["l",87,30,110,30],["l",110,30,140,30],["l",140,30,158,18],["c",162,30,2.2,"F"],["l",162,30,190,30],["l",190,30,215,30],["l",215,30,233,18],["c",237,30,2.2,"F"],["l",237,30,260,30],["l",260,30,260,80],["l",260,87,260,140],["l",252,80,268,80],["l",247,87,273,87],["l",110,30,110,82],["l",102,82,118,82],["l",102,88,118,88],["l",110,88,110,140],["l",190,30,190,82],["l",182,82,198,82],["l",182,88,198,88],["l",190,88,190,140],["l",40,140,260,140],["c",110,30,2.4,"F"],["c",190,30,2.4,"F"],["c",110,140,2.4,"F"],["c",190,140,2.4,"F"],["t",28,92,"2V₀","e"],["t",278,92,"V₀"],["t",122,90,"C₁"],["t",202,90,"C₂"],["t",75,14,"S₁","m"],["t",150,14,"S₂","m"],["t",225,14,"S₃","m"]]},"o":["the charge on the upper plate of C₁ is 2CV₀.","the charge on the upper plate of C₁ is CV₀.","the charge on the upper plate of C₂ is 0.","the charge on the upper plate of C₂ is −CV₀."],"c":[1,3],"s":"S₁: C₁ is charged by the 2V₀ battery, whose top terminal is positive. Upper plate of C₁ = +2CV₀.\nS₂ (S₁ released): C₁ shares its charge with the uncharged C₂ (parallel): total 2CV₀ over 2C, so each is at V₀ and each upper plate is +CV₀.\nS₂ released, S₃ pressed: C₂ is connected across the V₀ battery whose top terminal is negative, so C₂ charges to V₀ with its upper plate at −CV₀. C₁ is isolated and keeps +CV₀.\nSo (b) and (d) are correct."},
{"y":"IIT-JEE 1998","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A dielectric slab of thickness d is inserted in a parallel plate capacitor whose negative plate is at x = 0 and positive plate is at x = 3d. The slab is equidistant from the plates. The capacitor is given some charge. As one goes from 0 to 3d,","o":["the magnitude of the electric field remains the same","the direction of the electric field remains the same","the electric potential increases continuously","the electric potential increases at first, then decreases and again increases"],"c":[1,2],"s":"The slab occupies d < x < 2d. The plate charge is fixed, so σ is the same everywhere.\nField in air = σ/ε₀; field in the slab = σ/(Kε₀). The magnitude changes, so (a) is false.\nThe field always points from the positive plate (x = 3d) to the negative plate (x = 0): the direction never changes, so (b) is true.\nSince V = −∫E dx and E points towards −x, potential rises all the way from x = 0 to x = 3d, with a smaller slope in the slab. (c) is true, (d) is false.\nAnswer: (b) and (c)"},
{"y":"IIT-JEE 1996","tp":"egs","st":"Gauss's law and symmetric bodies","q":"The magnitude of electric field E⃗ in the annular region of a charged cylindrical capacitor","o":["is same throughout","is higher near the outer cylinder than near the inner cylinder","varies as 1/r, where r is the distance from axis","varies as 1/r², where r is the distance from axis."],"c":2,"s":"Take a coaxial cylindrical Gaussian surface of radius r and length l between the cylinders.\nFlux = E × 2πrl = λl/ε₀, where λ is the charge per unit length on the inner cylinder.\nSo E = λ/(2πε₀r), that is E ∝ 1/r.\nThe field is largest near the inner cylinder and falls with distance from the axis.\nAnswer: (c)."},
{"y":"IIT-JEE 1991","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor of plate area A and plate separation d is charged to potential difference V and then the battery is disconnected. A slab of dielectric constant K is then inserted between the plates of the capacitor so as to fill the space between the plates. If Q, E and W denote respectively, the magnitude of charge on each plate, the electric field between the plates (after the slab is inserted), and the workdone on the system, in question, in the process of inserting the slab, then","o":["Q = {ε₀AV;d}","Q = {ε₀KAV;d}","E = {V;Kd}","W = {ε₀AV²;2d}[1 − {1;K}]"],"c":[0,2,3],"s":"The battery is disconnected, so the charge stays Q = CV = ε₀AV/d. So (a) is true and (b) is false.\nThe slab reduces the field by K: E = E₀/K = V/(Kd). So (c) is true.\nEnergy before = ε₀AV²/(2d). After = (energy before)/K, because Q is constant and C becomes KC.\nEnergy change = {ε₀AV²;2d}(1 − 1/K); its magnitude is the W given in (d), so (d) is accepted.\nAnswer: (a), (c), (d)."},
{"y":"IIT-JEE 1990","tp":"ecp","st":"Capacitance and combinations","q":"Seven capacitors each of capacitance 2 µF are to be connected in a configuration to obtain an effective capacitance of ({10;11}) µF. Which of the combinations shown in figure will achieve the desired result?","fig":{"w":340,"h":250,"alt":"Four circuit options, each a diamond-shaped bank of 2 µF capacitors followed by a chain of capacitors in series","d":[["t",4,12,"(a)","s"],["l",8,62,30,62],["l",30,34,30,90],["l",70,34,70,90],["l",30,34,47,34],["l",47,29,47,39],["l",53,29,53,39],["l",53,34,70,34],["l",30,48,47,48],["l",47,43,47,53],["l",53,43,53,53],["l",53,48,70,48],["l",30,62,47,62],["l",47,57,47,67],["l",53,57,53,67],["l",53,62,70,62],["l",30,76,47,76],["l",47,71,47,81],["l",53,71,53,81],["l",53,76,70,76],["l",30,90,47,90],["l",47,85,47,95],["l",53,85,53,95],["l",53,90,70,90],["l",70,62,83,62],["l",84,56,84,68],["l",88,56,88,68],["l",88,62,99,62],["l",100,56,100,68],["l",104,56,104,68],["l",104,62,110,62],["t",174,12,"(b)","s"],["l",178,62,200,62],["l",200,41,200,83],["l",240,41,240,83],["l",200,41,217,41],["l",217,36,217,46],["l",223,36,223,46],["l",223,41,240,41],["l",200,55,217,55],["l",217,50,217,60],["l",223,50,223,60],["l",223,55,240,55],["l",200,69,217,69],["l",217,64,217,74],["l",223,64,223,74],["l",223,69,240,69],["l",200,83,217,83],["l",217,78,217,88],["l",223,78,223,88],["l",223,83,240,83],["l",240,62,253,62],["l",254,56,254,68],["l",258,56,258,68],["l",258,62,269,62],["l",270,56,270,68],["l",274,56,274,68],["l",274,62,285,62],["l",286,56,286,68],["l",290,56,290,68],["l",290,62,296,62],["t",4,137,"(c)","s"],["l",8,187,30,187],["l",30,173,30,201],["l",70,173,70,201],["l",30,173,47,173],["l",47,168,47,178],["l",53,168,53,178],["l",53,173,70,173],["l",30,187,47,187],["l",47,182,47,192],["l",53,182,53,192],["l",53,187,70,187],["l",30,201,47,201],["l",47,196,47,206],["l",53,196,53,206],["l",53,201,70,201],["l",70,187,83,187],["l",84,181,84,193],["l",88,181,88,193],["l",88,187,99,187],["l",100,181,100,193],["l",104,181,104,193],["l",104,187,115,187],["l",116,181,116,193],["l",120,181,120,193],["l",120,187,131,187],["l",132,181,132,193],["l",136,181,136,193],["l",136,187,142,187],["t",174,137,"(d)","s"],["l",178,187,200,187],["l",200,180,200,194],["l",240,180,240,194],["l",200,180,217,180],["l",217,175,217,185],["l",223,175,223,185],["l",223,180,240,180],["l",200,194,217,194],["l",217,189,217,199],["l",223,189,223,199],["l",223,194,240,194],["l",240,187,253,187],["l",254,181,254,193],["l",258,181,258,193],["l",258,187,269,187],["l",270,181,270,193],["l",274,181,274,193],["l",274,187,285,187],["l",286,181,286,193],["l",290,181,290,193],["l",290,187,301,187],["l",302,181,302,193],["l",306,181,306,193],["l",306,187,317,187],["l",318,181,318,193],["l",322,181,322,193],["l",322,187,328,187]]},"o":["Circuit (a)","Circuit (b)","Circuit (c)","Circuit (d)"],"c":0,"s":"Each circuit has a diamond bank of capacitors joined to the same two end points (so they are in parallel), followed by a chain of capacitors in series.\nCircuit (a): 5 in parallel = 10 µF; 2 in series = 1 µF. These two parts are in series: (10 × 1)/(10 + 1) = 10/11 µF.\nCircuit (b): 8 µF with 2/3 µF gives 8/13 µF. Circuit (c): 6 µF with 0.5 µF gives 6/13 µF. Circuit (d): 4 µF with 0.4 µF gives 4/11 µF.\nOnly (a) gives 10/11 µF. Answer: (a)."},
{"y":"IIT-JEE 1987","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor is charged and the charging battery is then disconnected. If the plates of the capacitor are moved farther apart by means of insulating handles","o":["the charge on the capacitor increases","the voltage across the plates increases","the capacitance increases","the electrostatic energy stored in the capacitor increases."],"c":[1,3],"s":"The battery is disconnected, so the charge Q stays constant. (a) is false.\nC = ε₀A/d falls when d increases. (c) is false.\nV = Q/C increases. (b) is true.\nU = Q²/(2C) increases, because work is done against the attraction of the plates. (d) is true.\nAnswer: (b), (d)."},
{"y":"IIT-JEE 1985","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate air capacitor is connected to a battery. The quantities charge, voltage, electric field and energy associated with this capacitor are given by Q₀, V₀, E₀ and U₀ respectively. A dielectric slab is now introduced to fill the space between the plates with battery still in connection. The corresponding quantities now given by Q, V, E and U are related to the previous one as","o":["Q > Q₀","V > V₀","E > E₀","U > U₀."],"c":[0,3],"s":"The battery stays connected, so the voltage is fixed: V = V₀. (b) is false.\nE = V/d is unchanged. (c) is false.\nThe slab makes C = KC₀ with K > 1, so Q = CV = KQ₀ > Q₀. (a) is true.\nU = ½CV² = KU₀ > U₀. (d) is true.\nAnswer: (a), (d)."},
{"y":"JEE Main 2025 · 4 Apr · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"Four capacitors each of capacitance 16 µF are connected as shown in the figure. The capacitance between points A and B is ____ (in µF).","fig":{"w":340,"h":150,"alt":"Four capacitors C in a row with wires joining some nodes; terminals A and B","d":[["l",20,70,57,70],["l",57,62,57,78],["l",63,62,63,78],["l",63,70,92,70],["l",92,70,127,70],["l",127,62,127,78],["l",133,62,133,78],["l",133,70,165,70],["l",165,70,197,70],["l",197,62,197,78],["l",203,62,203,78],["l",203,70,240,70],["l",240,70,272,70],["l",272,62,272,78],["l",278,62,278,78],["l",278,70,310,70],["l",20,70,20,25],["l",20,25,310,25],["l",165,25,165,70],["l",310,25,310,70],["l",310,70,310,125],["l",95,70,95,100],["l",95,100,240,100],["l",240,100,240,70],["l",167,100,167,125],["c",95,70,2,"F"],["c",240,70,2,"F"],["c",165,70,2,"F"],["c",167,100,2,"F"],["c",167,125,3,"F"],["c",310,125,3,"F"],["t",60,58,"C","ms"],["t",130,58,"C","ms"],["t",200,58,"C","ms"],["t",275,58,"C","ms"],["t",167,140,"A","m"],["t",310,140,"B","m"]]},"n":64,"s":"Follow the wires. The top wire joins the left end of the chain, the junction between the 2nd and 3rd capacitors, and the point B.\nThe wire from A joins the node between the 1st and 2nd capacitors and the node between the 3rd and 4th capacitors.\nSo every capacitor has one plate on the A group and the other on the B group: all four are in parallel.\nC = 4 × 16 = 64 µF."},
{"y":"JEE Main 2025 · 7 Apr · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor has charge 5 × 10⁻⁶ C. A dielectric slab is inserted between the plates and almost fills the space between the plates. If the induced charge on one face of the slab is 4 × 10⁻⁶ C then the dielectric constant of the slab is ____.","n":5,"s":"Induced charge on a dielectric face is q' = Q(1 − 1/K).\n4 × 10⁻⁶ = 5 × 10⁻⁶ (1 − 1/K).\n1 − 1/K = 0.8, so 1/K = 0.2.\nK = 5."},
{"y":"JEE Main 2025 · 8 Apr · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"Space between the plates of a parallel plate capacitor of plate area 4 cm² and separation of (d) 1.77 mm, is filled with uniform dielectric materials with dielectric constants (3 and 5) as shown in figure. Another capacitor of capacitance 7.5 pF is connected in parallel with it. The effective capacitance of this combination is ____ pF. (Given ε₀ = 8.85 × 10⁻¹² F/m)","fig":{"w":340,"h":160,"alt":"Parallel plate capacitor with two stacked dielectric layers of constants 5 (top) and 3 (bottom), each of thickness d/2","d":[["l",70,40,270,40,"B"],["l",70,120,270,120,"B"],["r",70,40,200,40,"f"],["r",70,80,200,40],["l",170,10,170,40],["l",170,120,170,150],["t",170,64,"k = 5","ms"],["t",170,104,"k = 3","ms"],["l",290,40,290,80,"b"],["l",290,80,290,120,"b"],["t",296,64,"d/2","s"],["t",296,104,"d/2","s"]]},"n":15,"s":"Without dielectric: C₀ = ε₀A/d = 8.85×10⁻¹² × 4×10⁻⁴ / 1.77×10⁻³ = 2 pF.\nEach layer has thickness d/2, so its capacitance is K × ε₀A/(d/2) = 2KC₀: 12 pF (K = 3) and 20 pF (K = 5).\nThe layers are in series: (12 × 20)/(12 + 20) = 7.5 pF.\nIn parallel with 7.5 pF: 7.5 + 7.5 = 15 pF."},
{"y":"JEE Main 2025 · 29 Jan · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor consisting of two circular plates of radius 10 cm is being charged by a constant current of 0.15 A. If the rate of change of potential difference between the plates is 7 × 10⁸ V/s, then the integer value of the distance between the parallel plates is (Take ε₀ = 9×10⁻¹² F/m, π = {22;7}) ____ µm.","n":1320,"s":"I = dQ/dt = C dV/dt, so C = I/(dV/dt) = 0.15/(7×10⁸) = 2.143×10⁻¹⁰ F.\nAlso C = ε₀πR²/d, so d = ε₀πR²/C.\nd = 9×10⁻¹² × (22/7) × (0.1)² / 2.143×10⁻¹⁰ = 1.32×10⁻³ m.\nd = 1320 µm."},
{"y":"JEE Main 2024 · 4 Apr · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor of capacitance 12.5 pF is charged by a battery connected between its plates to potential difference of 12.0 V. The battery is now disconnected and a dielectric slab (εᵣ = 6) is inserted between the plates. The change in its potential energy after inserting the dielectric slab is ____ × 10⁻¹² J.","n":750,"s":"Initial energy U₀ = ½CV² = ½ × 12.5×10⁻¹² × 144 = 900×10⁻¹² J.\nThe battery is disconnected, so Q is constant and C becomes 6C: U = U₀/6 = 150×10⁻¹² J.\nThe energy falls by 900 − 150 = 750 (×10⁻¹² J).\nThe size of the change is 750."},
{"y":"JEE Main 2024 · 5 Apr · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Three capacitors of capacitances 25 µF, 30 µF and 45 µF are connected in parallel to a supply of 100 V. Energy stored in the above combination is E. When these capacitors are connected in series to the same supply, the stored energy is {9;x}E. The value of x is ____.","n":86,"s":"Parallel: C = 25 + 30 + 45 = 100 µF, so E = ½ × 100 µF × V².\nSeries: 1/C' = 1/25 + 1/30 + 1/45 = (18 + 15 + 10)/450 = 43/450, so C' = 450/43 µF.\nSame V, so energy is proportional to C: E'/E = C'/C = (450/43)/100 = 4.5/43.\nSet 9/x = 4.5/43, so x = 9 × 43/4.5 = 86."},
{"y":"JEE Main 2024 · 6 Apr · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor of 10 µF capacitance whose plates are separated by 10 mm through air and each plate has area 4 cm² is now filled equally with two dielectric media of K₁ = 2, K₂ = 3 respectively as shown in figure. If new force between the plates is 8 N. The supply voltage is ____ V.","fig":{"w":320,"h":130,"alt":"Capacitor plates with the gap filled side by side by dielectrics K1 = 2 (left half) and K2 = 3 (right half)","d":[["l",60,40,280,40,"B"],["l",60,100,280,100,"B"],["r",170,40,110,60,"f"],["l",170,40,170,100],["l",45,40,45,100,"b"],["t",34,74,"d","e"],["t",115,74,"K₁ = 2","ms"],["t",225,74,"K₂ = 3","ms"]]},"n":80,"s":"With the two halves filled, the capacitance becomes C' = C(K₁ + K₂)/2 = 10 × 5/2 = 25 µF (taking the 10 µF as the air value, as the problem intends).\nThe battery stays connected. U = ½C'V², and C' ∝ 1/d, so the force is F = U/d = C'V²/(2d).\nV² = 2Fd/C' = 2 × 8 × 0.01 / (25×10⁻⁶) = 6400.\nV = 80 V."},
{"y":"JEE Main 2024 · 30 Jan · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor of capacitance C has energy E. It is connected to another capacitor of capacitance 2C and potential 2V. Then the loss of energy is {x;3}E, where x is ____.","n":2,"s":"Here C has potential V, so E = ½CV². The 2C capacitor has energy ½(2C)(2V)² = 4CV² = 8E.\nTotal initial energy = 9E.\nCharges CV and 4CV (same sign) add: 5CV on 3C, so the common potential is 5V/3.\nFinal energy = ½(3C)(5V/3)² = 25CV²/6 = (25/3)E.\nLoss = 9E − 25E/3 = (2/3)E, so x = 2."},
{"y":"JEE Main 2024 · 31 Jan · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor with plate separation 5 mm is charged up by a battery. It is found that on introducing a dielectric sheet of thickness 2 mm, while keeping the battery connections intact, the capacitor draws 25% more charge from the battery than before. The dielectric constant of the sheet is ____.","n":2,"s":"The battery stays connected, so Q ∝ C.\nC' / C = 1.25, and C = ε₀A/(d − t + t/K).\n1.25 = 5/(5 − 2 + 2/K) = 5/(3 + 2/K).\n3 + 2/K = 4, so 2/K = 1 and K = 2."},
{"y":"JEE Main 2023 · 6 Apr · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor with plate area A and plate separation d is filled with a dielectric material of dielectric constant K = 4. The thickness of the dielectric material is x, where x < d.\nLet C₁ and C₂ be the capacitance of the system for x = {1;3}d and x = {2d;3}, respectively. If C₁ = 2 µF, the value of C₂ is ____ µF.","fig":{"w":340,"h":150,"alt":"Parallel plate capacitor of gap d with a dielectric slab of thickness x resting on plate 2","d":[["l",55,25,255,25,"B"],["l",55,125,255,125,"B"],["r",55,95,200,30,"f"],["l",24,25,24,125,"b"],["t",14,79,"d","e"],["l",42,95,42,125,"b"],["t",36,114,"x","e"],["t",268,29,"Plate - 1",""],["t",268,103,"Dielectric",""],["t",268,134,"Plate - 2",""]]},"n":3,"s":"Use C = ε₀A/(d − x + x/K) with K = 4 and C₀ = ε₀A/d.\nx = d/3: C₁ = C₀/(1 − 1/3 + 1/12) = C₀/(3/4) = 4C₀/3 = 2 µF, so C₀ = 1.5 µF.\nx = 2d/3: C₂ = C₀/(1 − 2/3 + 1/6) = C₀/(1/2) = 2C₀.\nC₂ = 2 × 1.5 = 3 µF."},
{"y":"JEE Main 2023 · 6 Apr · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"As shown in the figure, two parallel plate capacitors having equal plate area of 200 cm² are joined in such a way that a ≠ b. The equivalent capacitance of the combination is xε₀ F. The value of x is ____.","fig":{"w":340,"h":170,"alt":"Two plates a distance d = 5 mm apart with a conducting slab of thickness c = 1 mm between them, leaving gaps a above and b below","d":[["l",80,35,225,35,"B"],["l",80,135,225,135,"B"],["r",90,65,125,20,"f"],["l",152,10,152,35],["l",152,135,152,160],["l",237,35,237,65,"b"],["t",244,54,"a",""],["l",237,85,237,135,"b"],["t",244,114,"b",""],["l",268,35,268,135,"b"],["t",274,89,"d = 5 mm",""],["l",70,65,70,85,"b"],["t",64,79,"c = 1 mm","e"]]},"n":5,"s":"The conducting slab has no field inside it, so only the two air gaps a and b act, and they are in series.\n1/C = a/(ε₀A) + b/(ε₀A) = (a + b)/(ε₀A).\na + b = d − c = 5 − 1 = 4 mm, so it does not depend on a or b separately.\nC = ε₀ × 200×10⁻⁴ / 4×10⁻³ = 5ε₀.\nx = 5."},
{"y":"JEE Main 2023 · 8 Apr · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A 600 pF capacitor is charged by 200 V supply. It is then disconnected from the supply and is connected to another uncharged 600 pF capacitor. Electrostatic energy lost in the process is ____ µJ.","n":6,"s":"Initial energy = ½ × 600×10⁻¹² × 200² = 12×10⁻⁶ J.\nThe charge is shared equally, so the common voltage is 100 V.\nFinal energy = ½ × 1200×10⁻¹² × 100² = 6×10⁻⁶ J.\nLoss = 12 − 6 = 6 µJ."},
{"y":"JEE Main 2023 · 11 Apr · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"In the given circuit, C₁ = 2 µF, C₂ = 0.2 µF, C₃ = 2 µF, C₄ = 4 µF, C₅ = 2 µF, C₆ = 2 µF. The charge stored on capacitor C₄ is ____ µC.","fig":{"w":340,"h":175,"alt":"Circuit with a 10 V battery and capacitors C1 to C6 arranged as a ladder","d":[["l",60,40,107,40],["l",107,32,107,48],["l",113,32,113,48],["l",113,40,227,40],["l",227,32,227,48],["l",233,32,233,48],["l",233,40,290,40],["l",60,140,107,140],["l",107,132,107,148],["l",113,132,113,148],["l",113,140,227,140],["l",227,132,227,148],["l",233,132,233,148],["l",233,140,290,140],["l",170,40,170,87],["l",162,87,178,87],["l",162,93,178,93],["l",170,93,170,140],["l",290,40,290,87],["l",282,87,298,87],["l",282,93,298,93],["l",290,93,290,140],["l",60,40,60,84],["l",50,84,70,84],["l",54,91,66,91,"B"],["l",60,91,60,140],["c",170,40,2,"F"],["c",170,140,2,"F"],["t",46,92,"10 V","e"],["t",110,28,"C₁","m"],["t",230,28,"C₃","m"],["t",110,162,"C₆","m"],["t",230,162,"C₅","m"],["t",180,94,"C₂",""],["t",300,94,"C₄",""]]},"n":4,"s":"C₃, C₄, C₅ are in series: 1/C = 1/2 + 1/4 + 1/2 = 5/4, so C = 0.8 µF. This is in parallel with C₂ = 0.2 µF: 1.0 µF.\nC₁ and C₆ (2 µF each) in series give 1 µF. Total circuit: 1 µF in series with 1 µF = 0.5 µF.\nCharge from the battery = 0.5 × 10 = 5 µC. Voltage across the 1.0 µF block = 5 V.\nCharge on the C₃–C₄–C₅ branch = 0.8 × 5 = 4 µC (same charge on C₄).\nQ(C₄) = 4 µC."},
{"y":"JEE Main 2023 · 15 Apr · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"In the given figure, the total charge stored in the combination of capacitors is 100 µC. The value of 'x' is ____.","fig":{"w":240,"h":170,"alt":"Three capacitors 2 µF, x µF and 3 µF in parallel across 10 V","d":[["l",40,30,40,140],["l",200,30,200,140],["l",40,30,117,30],["l",117,22,117,38],["l",123,22,123,38],["l",123,30,200,30],["t",120,20,"C₁ = 2 µF","ms"],["l",40,70,117,70],["l",117,62,117,78],["l",123,62,123,78],["l",123,70,200,70],["t",120,60,"C₂ = x µF","ms"],["l",40,110,117,110],["l",117,102,117,118],["l",123,102,123,118],["l",123,110,200,110],["t",120,100,"C₃ = 3 µF","ms"],["l",40,140,200,140,"b"],["t",120,158,"V = 10 V","m"]]},"n":5,"s":"The three capacitors are in parallel across 10 V: C = 2 + x + 3 = (5 + x) µF.\nQ = CV, so 100 = (5 + x) × 10.\n5 + x = 10, so x = 5."},
{"y":"JEE Main 2023 · 24 Jan · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor with air between the plate has a capacitance of 15 pF. The separation between the plate becomes twice and the space between them is filled with a medium of dielectric constant 3.5. Then the capacitance becomes {x;4} pF. The value of x is ____.","n":105,"s":"C = Kε₀A/d. Here d becomes 2d and K = 3.5.\nC' = 3.5 × 15 / 2 = 26.25 pF = 105/4 pF.\nSo x = 105."},
{"y":"JEE Main 2023 · 25 Jan · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A capacitor has capacitance 5 µF when it's parallel plates are separated by air medium of separation d. A slab of material of dielectric constant 1.5 having area equal to that of plates but thickness {d;2} is inserted between the plates. Capacitance of the capacitor in the presence of slab will be ____ µF.","n":6,"s":"C = ε₀A/(d − t + t/K) with t = d/2 and K = 1.5.\nDenominator = d/2 + (d/2)/1.5 = d/2 + d/3 = 5d/6.\nC = (6/5) × ε₀A/d = 1.2 × 5 = 6 µF."},
{"y":"JEE Main 2023 · 30 Jan · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor of capacitance 900 µF is charged by a 100 V battery. The capacitor is disconnected from the battery and connected to another uncharged identical capacitor such that one plate of uncharged capacitor connected to positive plate and another plate of uncharged capacitor connected to negative plate of the charged capacitor. The loss of energy in this process is measured as x × 10⁻² J. The value of x is ____.","n":225,"s":"Initial energy = ½ × 900×10⁻⁶ × 100² = 4.5 J.\nThe two identical capacitors are joined in parallel, so the charge splits equally and the voltage halves to 50 V.\nFinal energy = ½ × 1800×10⁻⁶ × 50² = 2.25 J.\nLoss = 4.5 − 2.25 = 2.25 J = 225 × 10⁻² J, so x = 225."},
{"y":"JEE Main 2023 · 31 Jan · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two parallel plate capacitors C₁ and C₂ each having capacitance of 10 µF are individually charged by a 100 V D.C. source. Capacitor C₁ is kept connected to the source and a dielectric slab is inserted between the plates. Capacitor C₂ is disconnected from the source and then a dielectric slab is inserted in it. Afterwards the capacitor C₁ is also disconnected from the source and the two capacitors are finally connected in parallel combination. The common potential of the combination will be ____ V. (Assuming dielectric constant = 10)","n":55,"s":"C₁ stays at 100 V and its capacitance becomes 100 µF: Q₁ = 100 × 100 = 10000 µC.\nC₂ is isolated with Q₂ = 10 × 100 = 1000 µC; the slab raises its capacitance to 100 µF but not its charge.\nJoined in parallel (like plates together): V = (Q₁ + Q₂)/(C₁ + C₂) = 11000/200.\nV = 55 V."},
{"y":"JEE Main 2022 · 25 Jul · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two parallel plate capacitors of capacity C and 3C are connected in parallel combination and charged to a potential difference 18 V. The battery is then disconnected and the space between the plates of the capacitor of capacity C is completely filled with a material of dielectric constant 9. The final potential difference across the combination of the capacitors will be ____ V.","n":6,"s":"Total charge = (C + 3C) × 18 = 72C. The battery is disconnected, so this charge stays.\nFilling the capacitor C with K = 9 makes it 9C. New total capacitance = 9C + 3C = 12C.\nV = 72C/12C = 6 V."},
{"y":"JEE Main 2022 · 26 Jul · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A composite parallel plate capacitor is made up of two different dielectric materials with different thickness (t₁ and t₂) as shown in figure. The two different dielectric material are separated by a conducting foil F. The voltage of conducting foil is ____ V.","fig":{"w":340,"h":140,"alt":"Two dielectric layers (3, 0.5 mm) and (4, 1 mm) separated by a conducting foil F between two plates joined to a 100 V battery","d":[["l",70,40,210,40,"B"],["l",70,115,210,115,"B"],["l",70,65,210,65],["t",140,56,"ε₁ = 3, t₁ = 0.5 mm","ms"],["t",140,94,"ε₂ = 4, t₂ = 1 mm","ms"],["t",216,69,"F","s"],["l",210,40,280,40],["l",280,40,280,72],["l",270,72,290,72],["l",274,79,286,79,"B"],["l",280,79,280,115],["l",280,115,210,115],["t",296,80,"100 V","s"]]},"n":60,"s":"The layers act as two capacitors in series (the foil is the joining node). For equal area, C ∝ K/t.\nC₁ ∝ 3/0.5 = 6 and C₂ ∝ 4/1 = 4.\nSame charge on both, so V₁ : V₂ = 1/C₁ : 1/C₂ = 1/6 : 1/4 = 2 : 3. With V₁ + V₂ = 100 V: V₁ = 40 V, V₂ = 60 V.\nTaking the plate next to the 1 mm layer as 0 V, the foil is at V₂ = 60 V."},
{"y":"JEE Main 2022 · 27 Jul · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor with width 4 cm, length 8 cm and separation between the plates of 4 mm is connected to a battery of 20 V. A dielectric slab of dielectric constant 5 having length 1 cm, width 4 cm and thickness 4 mm is inserted between the plates of parallel plate capacitor. The electrostatic energy of this system will be ____ ε₀ J. (Where ε₀ is the permittivity of free space)","n":240,"s":"The slab fills the full gap over 1 cm × 4 cm = 4 cm². The remaining area is 32 − 4 = 28 cm² (air). These parts are in parallel.\nC = ε₀[28×10⁻⁴ + 5 × 4×10⁻⁴]/(4×10⁻³) = ε₀ × 48×10⁻⁴/4×10⁻³ = 1.2ε₀.\nThe battery stays connected: U = ½CV² = ½ × 1.2ε₀ × 400.\nU = 240ε₀ J."},
{"y":"JEE Main 2022 · 25 Jun · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"The equivalent capacitance between points A and B in below shown figure will be ____ µF.","fig":{"w":340,"h":125,"alt":"Six 8 µF capacitors in a line from A to B with wires shorting some nodes","d":[["c",10,70,3,"F"],["l",10,70,42,70],["l",42,62,42,78],["l",48,62,48,78],["t",45,90,"8 µF","ms"],["l",48,70,92,70],["l",92,62,92,78],["l",98,62,98,78],["t",95,90,"8 µF","ms"],["l",98,70,142,70],["l",142,62,142,78],["l",148,62,148,78],["t",145,90,"8 µF","ms"],["l",148,70,192,70],["l",192,62,192,78],["l",198,62,198,78],["t",195,90,"8 µF","ms"],["l",198,70,242,70],["l",242,62,242,78],["l",248,62,248,78],["t",245,90,"8 µF","ms"],["l",248,70,292,70],["l",292,62,292,78],["l",298,62,298,78],["t",295,90,"8 µF","ms"],["l",298,70,325,70],["c",325,70,3,"F"],["t",10,86,"A","m"],["t",325,86,"B","m"],["l",28,70,28,35],["l",28,35,120,35],["l",120,35,120,70],["l",70,70,70,108],["l",70,108,170,108],["l",170,108,170,70],["l",170,70,170,35],["l",170,35,270,35],["l",270,35,270,70],["c",28,70,2,"F"],["c",70,70,2,"F"],["c",120,70,2,"F"],["c",170,70,2,"F"],["c",270,70,2,"F"]]},"n":6,"s":"Call the nodes after the 1st, 2nd, 3rd, 4th, 5th capacitors N₁ to N₅. The left top wire joins A with N₂; the bottom wire joins N₁ with N₃; the right top wire joins N₃ with N₅.\nSo C₁ (A–N₁), C₂ (N₁–A) and C₃ (A–N₃, since N₂ = A and N₃ = N₁) are all between A and N₁: 8 + 8 + 8 = 24 µF.\nC₄ and C₅ lie between N₃ and N₅, which are the same node, and their middle node connects nowhere else, so they carry no charge.\nC₆ joins N₅ (= N₁) to B: 8 µF, in series with 24 µF.\nC = (24 × 8)/(24 + 8) = 6 µF."},
{"y":"JEE Main 2022 · 27 Jun · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor of capacitance 50 pF is charged by 100 V source. It is then connected to another uncharged identical capacitor. Electrostatic energy loss in the process is ____ nJ.","n":125,"s":"Initial energy = ½ × 50×10⁻¹² × 100² = 250 nJ.\nThe charge is shared equally, so the voltage is 50 V.\nFinal energy = ½ × 100×10⁻¹² × 50² = 125 nJ.\nLoss = 250 − 125 = 125 nJ."},
{"y":"JEE Main 2022 · 27 Jun · Shift 2","tp":"ecp","st":"Capacitance and combinations","q":"A parallel plate capacitor is made up of stair like structure with a plate area A of each stair and that is connected with a wire of length b, as shown in the figure. The capacitance of the arrangement is {x ε₀ A;15 b}. The value of x is ____.","fig":{"w":340,"h":195,"alt":"Two staircase-shaped plates facing each other, each step of area A and each step height b","d":[["p","M40 20 H120 V50 H200 V80 H290","B"],["p","M40 170 H120 V140 H200 V110 H290","B"],["l",108,20,108,50,"b"],["t",100,39,"b","e"],["l",188,50,188,80,"b"],["t",180,69,"b","e"],["l",275,80,275,110,"b"],["t",281,99,"b",""],["l",212,110,212,140,"b"],["t",218,129,"b",""],["l",108,140,108,170,"b"],["t",100,159,"b","e"],["t",80,13,"A","m"],["t",245,96,"A","ms"],["t",160,134,"A","ms"],["t",80,186,"A","m"]]},"n":23,"s":"The two stair-shaped plates face each other across three steps. The facing steps are separated by b, 3b and 5b (each step adds b above and b below).\nEach pair has area A and is a capacitor; they are all connected between the same two plates, so they are in parallel.\nC = ε₀A/b + ε₀A/(3b) + ε₀A/(5b) = (15 + 5 + 3)/15 × ε₀A/b = {23 ε₀A;15 b}.\nx = 23."},
{"y":"JEE Main 2022 · 28 Jun · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A capacitor C₁ of capacitance 5 µF is charged to a potential of 30 V using a battery. The battery is then removed and the charged capacitor is connected to an uncharged capacitor C₂ of capacitance 10 µF as shown in figure. When the switch is closed charge flows between the capacitors. At equilibrium, the charge on the capacitor C₂ is ____ µC.","fig":{"w":340,"h":145,"alt":"Capacitor C1 (5 µF) and capacitor C2 (10 µF) joined through a switch","d":[["l",60,30,120,30],["l",120,30,150,12],["l",160,30,250,30],["l",60,30,60,77],["l",52,77,68,77],["l",52,83,68,83],["l",60,83,60,130],["l",250,30,250,77],["l",242,77,258,77],["l",242,83,258,83],["l",250,83,250,130],["l",60,130,250,130],["t",72,86,"5 µF","s"],["t",58,66,"C₁","e"],["t",262,86,"10 µF","s"],["t",248,66,"C₂","e"]]},"n":100,"s":"Initial charge on C₁ = 5 × 30 = 150 µC.\nAt equilibrium both have the same voltage: V = 150/(5 + 10) = 10 V.\nCharge on C₂ = 10 × 10 = 100 µC."},
{"y":"JEE Advanced 2022","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"In the following circuit, C₁ = 12 µF, C₂ = C₃ = 4 µF and C₄ = C₅ = 2 µF. The charge stored in C₃ is ____ µC.","fig":{"w":340,"h":160,"alt":"Circuit with C1 on the top wire, C2 and C4 on slanted wires, C3 and C5 vertical, a 6 V battery on the left and a 2 V battery on the right","d":[["l",60,30,102,30],["l",102,22,102,38],["l",108,22,108,38],["l",108,30,300,30],["l",60,140,300,140],["l",60,30,60,82],["l",50,82,70,82],["l",54,89,66,89,"B"],["l",60,89,60,140],["l",300,30,300,82],["l",290,82,310,82],["l",294,89,306,89,"B"],["l",300,89,300,140],["l",150,30,150,82],["l",142,82,158,82],["l",142,88,158,88],["l",150,88,150,140],["l",230,30,230,82],["l",222,82,238,82],["l",222,88,238,88],["l",230,88,230,140],["l",60,140,103.1,87.3],["l",96.9,82.2,109.3,92.4],["l",100.7,77.6,113.1,87.8],["l",106.9,82.7,150,30],["l",150,30,188.2,82.6],["l",181.7,87.3,194.7,77.9],["l",185.3,92.1,198.3,82.7],["l",191.8,87.4,230,140],["c",150,30,2,"F"],["t",105,20,"C₁","m"],["t",82,76,"C₂","e"],["t",157,106,"C₃",""],["t",204,108,"C₄",""],["t",238,80,"C₅",""],["t",46,90,"6 V","e"],["t",312,92,"2 V",""]]},"n":8,"s":"The bottom wire and both bottom corners are one node (G). The top wire to the right of C₁ joins the apex of the triangle, the top of C₅ and the 2 V battery: one node (T).\nThe 2 V battery fixes the voltage between T and G as 2 V.\nC₂, C₃, C₄ and C₅ each connect T to G, so each has 2 V across it. (C₁ and the 6 V battery only fix how much charge C₁ holds.)\nQ₃ = C₃V = 4 µF × 2 V = 8 µC."},
{"y":"JEE Main 2021 · 31 Aug · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor of capacitance 200 µF is connected to a battery of 200 V. A dielectric slab of dielectric constant 2 is now inserted into the space between plates of capacitor while the battery remain connected. The change in the electrostatic energy in the capacitor will be ____ J.","n":4,"s":"The battery stays connected, so V = 200 V. The slab doubles the capacitance: C' = 400 µF.\nU₀ = ½ × 200×10⁻⁶ × 200² = 4 J.\nU = ½ × 400×10⁻⁶ × 200² = 8 J.\nChange = 8 − 4 = 4 J."},
{"y":"JEE Main 2021 · 16 Mar · Shift 2","tp":"ecp","st":"Dielectrics and conducting slabs","q":"In a parallel plate capacitor set up, the plate area of capacitor is 2 m² and the plates are separated by 1 m. If the space between the plates are filled with a dielectric material of thickness 0.5 m and area 2 m² (see fig) the capacitance of the set-up will be ____ ε₀. (Dielectric constant of the material = 3.2) (Round off to the nearest integer)","fig":{"w":300,"h":155,"alt":"Plates a distance d apart; a dielectric of thickness d/2 sits against the left plate","d":[["l",50,30,50,120,"B"],["l",250,30,250,120,"B"],["r",50,30,100,90,"f"],["t",100,78,"k","ms"],["l",50,18,250,18,"b"],["t",150,12,"d","m"],["l",50,132,150,132,"b"],["t",100,148,"d/2","ms"]]},"n":3,"s":"C = ε₀A/(d − t + t/K) = ε₀ × 2/(1 − 0.5 + 0.5/3.2).\n0.5/3.2 = 0.15625, so the denominator = 0.65625.\nC = 2/0.65625 ε₀ = 3.05 ε₀.\nRounded: 3."},
{"y":"JEE Main 2021 · 17 Mar · Shift 1","tp":"ecp","st":"Capacitance and combinations","q":"Four identical rectangular plates with length l = 2 cm and breadth b = {3;2} cm are arranged as shown in figure. The equivalent capacitance between A and C is {xε₀;d}. The value of x is ____. (Round off to the nearest integer)","fig":{"w":300,"h":200,"alt":"Four parallel plates A, B, C, D a distance d apart; plates B and D are joined by a wire","d":[["l",60,60,60,150],["l",120,30,120,150],["l",180,60,180,150],["l",240,30,240,150],["l",120,30,120,15],["l",120,15,240,15],["l",240,15,240,30],["t",60,52,"A","m"],["t",114,50,"B","e"],["t",180,52,"C","m"],["t",234,50,"D","e"],["l",60,172,120,172,"b"],["l",120,172,180,172,"b"],["l",180,172,240,172,"b"],["t",90,190,"d","m"],["t",150,190,"d","m"],["t",210,190,"d","m"]]},"n":2,"s":"Plate area S = l × b = 2 × 1.5 = 3 cm². Each gap is a capacitor C₀ = ε₀S/d.\nB and D are joined, so call that node X. A–X is one gap: C₀. C–X is two gaps (C–B and C–D) in parallel: 2C₀.\nBetween A and C, these are in series: C₀ × 2C₀/(3C₀) = 2C₀/3 = (2/3) ε₀S/d.\nWith S = 3 cm²: C = 2 ε₀ (cm²)/d, so x = 2 when the area is counted in cm² (in SI units the number would be 2×10⁻⁴). The official answer is 2."},
{"y":"JEE Main 2021 · 17 Mar · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A parallel plate capacitor whose capacitance C is 14 pF is charged by a battery to a potential difference V = 12 V between its plates. The charging battery is now disconnected and a porcelain plate with K = 7 is inserted between the plates, then the plate would oscillate back and forth between the plates with a constant mechanical energy of ____ pJ. (Assume no friction)","n":864,"s":"Initial energy U₀ = ½CV² = ½ × 14 × 144 = 1008 pJ.\nThe battery is off, so Q is constant. With the plate fully inside, U = U₀/K = 1008/7 = 144 pJ.\nThe plate is pulled in and gains the lost energy as kinetic energy; with no friction it oscillates with this constant mechanical energy.\nE = 1008 − 144 = 864 pJ."},
{"y":"JEE Main 2021 · 17 Mar · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A 2 µF capacitor C₁ is first charged to a potential difference of 10 V using a battery. Then the battery is removed and the capacitor is connected to an uncharged capacitor C₂ of 8 µF. The charge in C₂ on equilibrium condition is ____ µC. (Round off to the nearest integer)","n":16,"s":"Charge on C₁ = 2 × 10 = 20 µC.\nAt equilibrium the voltage is common: V = 20/(2 + 8) = 2 V.\nCharge on C₂ = 8 × 2 = 16 µC."},
{"y":"JEE Main 2021 · 18 Mar · Shift 1","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor has plate area 100 m² and plate separation of 10 m. The space between the plates is filled up to a thickness 5 m with a material of dielectric constant of 10. The resultant capacitance of the system is 'x' pF. The value of 'x' to the nearest integer is ____. The value of ε₀ = 8.85 × 10⁻¹² F m⁻¹","n":161,"s":"C = ε₀A/(d − t + t/K) = 8.85×10⁻¹² × 100/(10 − 5 + 0.5).\nDenominator = 5.5 m.\nC = 8.85×10⁻¹⁰/5.5 = 1.609×10⁻¹⁰ F ≈ 161 pF.\nx = 161."},
{"y":"JEE Main 2020 · 2 Sep · Shift 1","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A 5 µF capacitor is charged fully by a 220 V supply. It is then disconnected from the supply and is connected in series to another uncharged 2.5 µF capacitor. If the energy change during the charge redistribution is {X;100} J then value of X to the nearest integer is ____.","n":4,"s":"Charge Q = 5 × 220 = 1100 µC. Initial energy = ½ × 5×10⁻⁶ × 220² = 0.121 J.\nThe capacitors are joined into a loop, so the charge redistributes until both have the same voltage: V = 1100/(5 + 2.5) = 146.7 V.\nFinal energy = ½ × 7.5×10⁻⁶ × 146.7² = 0.0807 J.\nEnergy change = 0.121 − 0.0807 = 0.0403 J = 4/100 J, so X = 4."},
{"y":"JEE Main 2020 · 7 Jan · Shift 2","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"A 60 pF capacitor is fully charged by a 20 V supply. It is then disconnected from the supply and is connected to another uncharged 60 pF capacitor in parallel. The electrostatic energy that is lost in this process by the time the charge is redistributed between them is (in nJ) ____.","n":6,"s":"Initial energy = ½ × 60×10⁻¹² × 20² = 12 nJ.\nThe charge is shared equally, so the voltage is 10 V.\nFinal energy = ½ × 120×10⁻¹² × 10² = 6 nJ.\nEnergy lost = 12 − 6 = 6 nJ."},
{"y":"JEE Advanced 2020","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Two capacitors with capacitance values C₁ = 2000 ± 10 pF and C₂ = 3000 ± 15 pF are connected in series. The voltage applied across this combination is V = 5.00 ± 0.02 V. The percentage error in the calculation of the energy stored in this combination of capacitors is ____.","n":1.3,"s":"Series capacitance: C = C₁C₂/(C₁ + C₂) = 1200 pF.\nΔC = (C₂/(C₁+C₂))² ΔC₁ + (C₁/(C₁+C₂))² ΔC₂ = 0.36 × 10 + 0.16 × 15 = 6 pF, so ΔC/C = 0.5%.\nEnergy U = ½CV², so ΔU/U = ΔC/C + 2ΔV/V = 0.5% + 2 × 0.02/5 = 0.5% + 0.8%.\nPercentage error = 1.30%."},
{"y":"JEE Advanced 2019","tp":"ecp","st":"Dielectrics and conducting slabs","q":"A parallel plate capacitor of capacitance C has spacing d between two plates having area A. The region between the plates is filled with N dielectric layers, parallel to its plates, each with thickness δ = {d;N}. The dielectric constant of the mᵗʰ layer is Kₘ = K(1 + {m;N}). For a very large N (> 10³), the capacitance C is α({Kε₀A;d ln 2}). The value of α will be ____. [ε₀ is the permittivity of free space]","n":1,"s":"The layers are capacitors in series: 1/C = Σ δ/(Kₘε₀A) = {d;Nε₀AK} Σ 1/(1 + m/N).\nFor very large N the sum becomes an integral: Σ 1/(1 + m/N) ≈ N ∫₀¹ dx/(1 + x) = N ln 2.\nSo 1/C = d ln 2/(Kε₀A), that is C = Kε₀A/(d ln 2).\nComparing with C = α(Kε₀A/(d ln 2)): α = 1."},
{"y":"JEE Advanced 2024","tp":"ecp","st":"Statements, matching and subjective","q":"Four identical thin, square metal sheets, S₁, S₂, S₃ and S₄, each of side a are kept parallel to each other with equal distance d (<< a) between them, as shown in the figure. Let C₀ = ε₀a²/d, where ε₀ is the permittivity of free space.\nMatch the quantities mentioned in List-I with their values in List-II and choose the correct option.\nList-I\n(P) The capacitance between S₁ and S₄, with S₂ and S₃ not connected, is\n(Q) The capacitance between S₁ and S₄, with S₂ shorted to S₃, is\n(R) The capacitance between S₁ and S₃, with S₂ shorted to S₄, is\n(S) The capacitance between S₁ and S₂, with S₃ shorted to S₁ and S₂ shorted to S₄, is\nList-II\n1. 3C₀\n2. C₀/2\n3. C₀/3\n4. 2C₀/3\n5. 2C₀","fig":{"w":280,"h":185,"alt":"Four identical square metal sheets S1 to S4 placed parallel with equal gaps d; side of each sheet is a","d":[["p","M40 55 L80 30 L80 120 L40 145 Z","f"],["t",60,22,"S₁","ms"],["p","M70 55 L110 30 L110 120 L70 145 Z","f"],["t",90,22,"S₂","ms"],["p","M100 55 L140 30 L140 120 L100 145 Z","f"],["t",120,22,"S₃","ms"],["p","M130 55 L170 30 L170 120 L130 145 Z","f"],["t",150,22,"S₄","ms"],["l",40,160,70,160,"b"],["l",70,160,100,160,"b"],["l",100,160,130,160,"b"],["t",55,174,"d","ms"],["t",85,174,"d","ms"],["t",115,174,"d","ms"],["l",200,30,200,120,"b"],["t",208,78,"a",""]]},"o":["P → 3; Q → 2; R → 4; S → 5","P → 2; Q → 3; R → 2; S → 1","P → 3; Q → 2; R → 4; S → 1","P → 3; Q → 2; R → 2; S → 5"],"c":2,"s":"Each gap between neighbouring sheets is a capacitor C₀.\nP: three gaps in series: C₀/3, so P → 3.\nQ: S₂ and S₃ shorted, so the middle gap vanishes; two gaps in series: C₀/2, so Q → 2.\nR: let S₂ = S₄ = M. Gap S₁–S₂ is between S₁ and M (C₀). Gaps S₂–S₃ and S₃–S₄ are both between S₃ and M (2C₀). Series: C₀ × 2C₀/3C₀ = 2C₀/3, so R → 4.\nS: let S₁ = S₃ = A and S₂ = S₄ = M. All three gaps lie between A and M: parallel, 3C₀, so S → 1.\nP → 3; Q → 2; R → 4; S → 1: option (c)."},
{"y":"JEE Advanced 2017","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Consider a simple RC circuit as shown in figure 1.\nProcess 1: In the circuit the switch S is closed at t = 0 and the capacitor is fully charged to voltage V₀ (i.e., charging continues for time T >> RC). In the process some dissipation (E_D) occurs across the resistance R. The amount of energy finally stored in the fully charged capacitor is E_C.\nProcess 2: In a different process the voltage is first set to {V₀;3} and maintained for a charging time T >> RC. Then the voltage is raised to {2V₀;3} without discharging the capacitor and again maintained for a time T >> RC. The process is repeated one more time by raising the voltage to V₀ and the capacitor is charged to the same final voltage V₀ as in Process 1.\nThese two processes are depicted in figure 2.\nIn Process 2, total energy dissipated across the resistance E_D is","fig":{"w":340,"h":175,"alt":"Left: RC circuit with a source V, switch S, resistor R and capacitor C. Right: voltage against time for Process 1 (jump to V0) and Process 2 (steps V0/3, 2V0/3, V0)","d":[["l",30,40,48,40],["l",48,40,64,28],["l",66,40,72,40],["p","M72 40 L77 32 L84 48 L91 32 L98 48 L105 32 L110 40 L120 40"],["l",120,40,120,77],["l",112,77,128,77],["l",112,83,128,83],["l",120,83,120,140],["l",30,140,120,140],["l",30,40,30,86],["l",20,86,40,86],["l",24,93,36,93,"B"],["l",30,93,30,140],["t",52,24,"S","s"],["t",92,28,"R","ms"],["t",130,86,"C",""],["t",14,92,"V","e"],["t",75,165,"figure 1","ms"],["l",200,140,330,140,"a"],["l",200,140,200,15,"a"],["t",206,18,"V","s"],["t",326,156,"t","es"],["l",197,40,203,40],["l",197,73,203,73],["l",197,107,203,107],["t",194,43,"V₀","es"],["t",194,76,"2V₀/3","es"],["t",194,110,"V₀/3","es"],["p","M200 140 V40 H325","a"],["p","M200 140 V107 H250 V73 H300 V40 H325","a"],["l",250,140,250,145],["l",300,140,300,145],["t",250,157,"T","ms"],["t",300,157,"2T","ms"],["t",250,32,"Process 1","ms"],["t",222,100,"Process 2","ms"]]},"o":["E_D = 3({1;2}CV₀²)","E_D = {1;3}({1;2}CV₀²)","E_D = 3CV₀²","E_D = {1;2}CV₀²"],"c":1,"s":"In each charging step the voltage source rises by ΔV and the capacitor charges through R; the energy lost in R is ½C(ΔV)².\nProcess 2 has three equal steps of ΔV = V₀/3 (0 → V₀/3 → 2V₀/3 → V₀).\nE_D = 3 × ½C(V₀/3)² = 3 × CV₀²/18 = CV₀²/6.\nThis is (1/3)(½CV₀²). Answer: (b)."},
{"y":"JEE Advanced 2017","tp":"ecp","st":"Energy, force and circuits (including RC)","q":"Consider a simple RC circuit as shown in figure 1.\nProcess 1: In the circuit the switch S is closed at t = 0 and the capacitor is fully charged to voltage V₀ (i.e., charging continues for time T >> RC). In the process some dissipation (E_D) occurs across the resistance R. The amount of energy finally stored in the fully charged capacitor is E_C.\nProcess 2: In a different process the voltage is first set to {V₀;3} and maintained for a charging time T >> RC. Then the voltage is raised to {2V₀;3} without discharging the capacitor and again maintained for a time T >> RC. The process is repeated one more time by raising the voltage to V₀ and the capacitor is charged to the same final voltage V₀ as in Process 1.\nThese two processes are depicted in figure 2.\nIn process 1, the energy stored in the capacitor E_C and heat dissipated across resistance E_D are related by","fig":{"w":340,"h":175,"alt":"Left: RC circuit with a source V, switch S, resistor R and capacitor C. Right: voltage against time for Process 1 (jump to V0) and Process 2 (steps V0/3, 2V0/3, V0)","d":[["l",30,40,48,40],["l",48,40,64,28],["l",66,40,72,40],["p","M72 40 L77 32 L84 48 L91 32 L98 48 L105 32 L110 40 L120 40"],["l",120,40,120,77],["l",112,77,128,77],["l",112,83,128,83],["l",120,83,120,140],["l",30,140,120,140],["l",30,40,30,86],["l",20,86,40,86],["l",24,93,36,93,"B"],["l",30,93,30,140],["t",52,24,"S","s"],["t",92,28,"R","ms"],["t",130,86,"C",""],["t",14,92,"V","e"],["t",75,165,"figure 1","ms"],["l",200,140,330,140,"a"],["l",200,140,200,15,"a"],["t",206,18,"V","s"],["t",326,156,"t","es"],["l",197,40,203,40],["l",197,73,203,73],["l",197,107,203,107],["t",194,43,"V₀","es"],["t",194,76,"2V₀/3","es"],["t",194,110,"V₀/3","es"],["p","M200 140 V40 H325","a"],["p","M200 140 V107 H250 V73 H300 V40 H325","a"],["l",250,140,250,145],["l",300,140,300,145],["t",250,157,"T","ms"],["t",300,157,"2T","ms"],["t",250,32,"Process 1","ms"],["t",222,100,"Process 2","ms"]]},"o":["E_C = E_D","E_C = E_D ln 2","E_C = 2E_D","E_C = {1;2}E_D"],"c":0,"s":"Process 1 is a single jump to V₀. The capacitor ends with E_C = ½CV₀².\nThe source supplies QV₀ = CV₀². Energy lost in R = CV₀² − ½CV₀² = ½CV₀² = E_D.\nSo E_C = E_D. Answer: (a)."},
{"y":"JEE Main 2023 · 1 Feb · Shift 2","tp":"ecn","st":"Statements, matching and subjective","q":"Given below are two statements : One is labelled as Assertion (A) and the other is labelled as Reason (R).\nAssertion (A) : Two metallic spheres are charged to the same potential. One of them is hollow and another is solid, and both have the same radii. Solid sphere will have lower charge than the hollow one.\nReason (R) : Capacitance of metallic spheres depend on the radii of spheres.\nIn the light of above statements, choose the most appropriate answer from the options given below.","o":["Both (A) and (R) are true and (R) is the correct explanation of (A).","Both (A) and (R) are true but (R) is not the correct explanation of (A).","(A) is true but (R) is false.","(A) is false but (R) is true."],"c":3,"s":"The charge on a conducting sphere is on its outer surface only, so a hollow and a solid sphere of the same radius have the same capacitance C = 4πε₀R.\nAt the same potential, Q = CV is the same for both. So (A) is false.\n(R) is true: the capacitance of a metallic sphere depends on its radius.\nAnswer: (d)."},
{"y":"IIT-JEE 1999","tp":"ecp","st":"Statements, matching and subjective","q":"Two parallel plate capacitors A and B have the same separation d = 8.85 × 10⁻⁴ m between the plates. The plate areas of A and B are 0.04 m² and 0.02 m² respectively. A slab of dielectric constant (relative permittivity) K = 9 has dimensions such that it can exactly fill the space between the plates of capacitor B.\n(i) The dielectric slab is placed inside A as shown in figure (a). A is then charged to a potential difference of 110 V. Calculate the capacitance of A and the energy stored in it.\n(ii) The battery is disconnected and then the dielectric slab is moved from A. Find the work done by the external agent in removing the slab from A.\n(iii) The same dielectric slab is now placed inside B, filling it completely. The two capacitors A and B are then connected as shown in figure (c). Calculate the energy stored in the system.","fig":{"w":340,"h":175,"alt":"(a) Capacitor A with a slab filling half of it, connected to 110 V; (b) capacitor B; (c) capacitors A and B connected in parallel, with the slab inside B","d":[["l",40,60,100,60,"B"],["l",40,100,100,100,"B"],["r",70,60,30,40,"f"],["l",15,60,40,60],["l",15,60,15,125],["l",15,125,29,125],["l",29,118,29,132],["l",34,122,34,128,"B"],["l",34,125,55,125],["l",55,125,55,100],["t",104,57,"A","s"],["t",30,148,"110 V","ms"],["t",60,166,"(a)","ms"],["l",130,60,170,60,"B"],["l",130,100,170,100,"B"],["l",150,40,150,60],["l",150,100,150,120],["t",176,56,"B","s"],["t",150,166,"(b)","ms"],["l",200,60,240,60,"B"],["l",200,100,240,100,"B"],["l",270,60,310,60,"B"],["l",270,100,310,100,"B"],["r",270,60,40,40,"f"],["l",220,60,220,40],["l",220,40,290,40],["l",290,40,290,60],["l",220,100,220,125],["l",220,125,290,125],["l",290,125,290,100],["t",196,56,"A","es"],["t",316,56,"B","s"],["t",255,166,"(c)","ms"]]},"a":"(i) 2×10⁻⁹ F, 1.21×10⁻⁵ J   (ii) 4.84×10⁻⁵ J   (iii) 1.1×10⁻⁵ J","s":"(i) The slab covers half of A (area 0.02 m²). ε₀ × 0.02/d = 2×10⁻¹⁰ F, so C_A = 2×10⁻¹⁰ (9 + 1) = 2×10⁻⁹ F. U = ½CV² = ½ × 2×10⁻⁹ × 110² = 1.21×10⁻⁵ J.\n(ii) Q = CV = 2.2×10⁻⁷ C stays constant. Without the slab C = ε₀ × 0.04/d = 4×10⁻¹⁰ F, so U' = Q²/2C = (2.2×10⁻⁷)²/(8×10⁻¹⁰) = 6.05×10⁻⁵ J.\nWork by the agent = 6.05×10⁻⁵ − 1.21×10⁻⁵ = 4.84×10⁻⁵ J.\n(iii) B with the slab: C_B = 9 × 2×10⁻¹⁰ = 1.8×10⁻⁹ F. A (no slab) still has Q = 2.2×10⁻⁷ C and C_A = 4×10⁻¹⁰ F. Joined in parallel: C = 2.2×10⁻⁹ F, V = Q/C = 100 V.\nU = ½ × 2.2×10⁻⁹ × 100² = 1.1×10⁻⁵ J."},
{"y":"IIT-JEE 1997","tp":"ecp","st":"Statements, matching and subjective","q":"Two capacitors A and B with capacities 3 µF and 2 µF are charged to a potential difference of 100 V and 180 V respectively. The plates of the capacitors are connected as shown in the figure with one wire from each capacitor free. The upper plate of A is positive and that of B is negative. An uncharged 2 µF capacitor with lead wires falls on the free ends to complete the circuit. Calculate\n(i) the final charge on the three capacitors and\n(ii) the amount of electrostatic energy stored in the system before and after the completion of the circuit.","fig":{"w":340,"h":140,"alt":"Charged capacitors A (3 µF, 100 V) and B (2 µF, 180 V) with bottom plates joined and top wires free; an uncharged 2 µF capacitor C is shown above the free ends","d":[["l",70,40,270,40],["l",167,32,167,48],["l",173,32,173,48],["t",170,26,"2 µF","ms"],["t",170,12,"C","ms"],["l",70,40,70,40],["c",70,40,2,"F"],["c",70,58,2,"F"],["c",270,40,2,"F"],["c",270,58,2,"F"],["l",70,58,70,72],["l",62,72,78,72],["l",62,78,78,78],["l",70,78,70,125],["l",270,58,270,72],["l",262,72,278,72],["l",262,78,278,78],["l",270,78,270,125],["l",70,125,270,125],["t",80,72,"+","s"],["t",80,96,"3 µF, 100 V","s"],["t",80,112,"A","s"],["t",260,72,"−","es"],["t",260,96,"2 µF, 180 V","es"],["t",260,112,"B","es"]]},"a":"(i) q₁ = 90×10⁻⁶ C (on A), q₂ = 210×10⁻⁶ C (on the new 2 µF capacitor), q₃ = 150×10⁻⁶ C (on B)   (ii) after: 1.8×10⁻² J (before: 4.74×10⁻² J)","s":"Initial charges: A has +300 µC on its top plate; B has −360 µC on its top plate.\nLet the final charges be q₁ (A), q₂ (new capacitor), q₃ (B), in µC. Charge conservation on the two isolated nodes: q₁ + q₂ = 300 and q₂ + q₃ = 360.\nVoltage loop: q₁/3 + q₃/2 = q₂/2.\nSubstitute q₁ = 300 − q₂ and q₃ = 360 − q₂: 2(300 − q₂) + 3(360 − q₂) = 3q₂, so 8q₂ = 1680 and q₂ = 210. Then q₁ = 90, q₃ = 150 (µC).\nEnergy before = ½(3)(100²) + ½(2)(180²) = 15000 + 32400 µJ = 4.74×10⁻² J.\nEnergy after = 90²/(2×3) + 210²/(2×2) + 150²/(2×2) = 1350 + 11025 + 5625 µJ = 1.8×10⁻² J."},
{"y":"IIT-JEE 1996","tp":"ecp","st":"Statements, matching and subjective","q":"The capacitance of a parallel plate capacitor with plate area A and separation d is C. The space between the plates is filled with two wedges of dielectric constants K₁ and K₂, respectively. Find the capacitance of the resulting capacitor.","fig":{"w":320,"h":150,"alt":"Capacitor plates of area A and gap d; the gap is filled by two wedges of dielectric K1 (lower left) and K2 (upper right) split along a diagonal","d":[["l",70,40,250,40,"B"],["l",70,130,250,130,"B"],["r",80,40,160,90],["l",80,40,240,130],["t",205,72,"K₂","ms"],["t",120,112,"K₁","ms"],["t",160,30,"A","ms"],["l",272,40,272,130,"b"],["t",280,89,"d",""]]},"a":"ε₀AK₁K₂ ln(K₁/K₂) / [d(K₁ − K₂)]","s":"Let the plate have side L (A = L²). At distance x along the plate, K₁ has thickness (x/L)d and K₂ has thickness (1 − x/L)d.\nA thin strip of width dx is two capacitors in series: dC = ε₀L dx / [d(u/K₁ + (1 − u)/K₂)], with u = x/L.\nThe strips are in parallel: C = (ε₀A/d) ∫₀¹ du / [1/K₂ + u(1/K₁ − 1/K₂)].\nThe integral equals K₁K₂ ln(K₁/K₂)/(K₁ − K₂).\nC = ε₀AK₁K₂ ln(K₁/K₂) / [d(K₁ − K₂)]."},
{"y":"IIT-JEE 1983","tp":"ecp","st":"Statements, matching and subjective","q":"The figure shows two identical parallel plate capacitors connected to a battery with the switch S closed. The switch is now opened and the free space between the plates of the capacitors is filled with a dielectric of dielectric constant (or relative permittivity) 3. Find the ratio of the total electrostatic energy stored in both capacitors before and after the introduction of the dielectric.","fig":{"w":320,"h":150,"alt":"A battery V across capacitor A; a switch S joins capacitor B to the same wires","d":[["l",50,40,175,40],["l",175,40,205,26],["l",212,40,260,40],["l",50,40,50,76],["l",40,76,60,76],["l",44,83,56,83,"B"],["l",50,83,50,130],["l",130,40,130,82],["l",122,82,138,82],["l",122,88,138,88],["l",130,88,130,130],["l",260,40,260,82],["l",252,82,268,82],["l",252,88,268,88],["l",260,88,260,130],["l",50,130,260,130],["c",130,40,2,"F"],["c",130,130,2,"F"],["t",195,22,"S","ms"],["t",38,84,"V","e"],["t",140,90,"A  C","s"],["t",270,90,"B  C","s"]]},"a":"3/5","s":"Before: both capacitors are at V, so U₁ = 2 × ½CV² = CV².\nAfter S is opened, capacitor A is still connected to the battery: V is fixed and C becomes 3C, so U_A = ½(3C)V² = 3CV²/2.\nCapacitor B is isolated with charge Q = CV; its capacitance becomes 3C, so U_B = Q²/(2 × 3C) = CV²/6.\nU₂ = 3CV²/2 + CV²/6 = 5CV²/3.\nRatio U₁ : U₂ = 1 : (5/3) = 3/5."},
{"y":"IIT-JEE 1986","tp":"efl","st":"Statements, matching and subjective","q":"Two protons A and B are placed in between the two plates of a parallel plate capacitor charged to a potential difference V as shown in the figure. The forces on the two protons are identical.","fig":{"w":240,"h":180,"alt":"Plates with + on the left, − on the right; proton A near the left plate and proton B higher up near the right plate","d":[["l",70,15,70,155],["l",170,15,170,155],["c",88,110,2.5,"F"],["t",80,114,"A","e"],["c",150,60,2.5,"F"],["t",142,64,"B","e"],["l",70,168,170,168,"b"],["t",120,162,"V","ms"],["t",62,32,"+","es"],["t",178,32,"−","s"],["t",62,49,"+","es"],["t",178,49,"−","s"],["t",62,66,"+","es"],["t",178,66,"−","s"],["t",62,83,"+","es"],["t",178,83,"−","s"],["t",62,100,"+","es"],["t",178,100,"−","s"],["t",62,117,"+","es"],["t",178,117,"−","s"],["t",62,134,"+","es"],["t",178,134,"−","s"],["t",62,151,"+","es"],["t",178,151,"−","s"]]},"o":["True","False"],"c":0,"s":"Between the plates (away from the edges) the field of a parallel plate capacitor is uniform: E = V/d, same in size and direction everywhere.\nThe force on a proton is F = eE, so it is the same at A and at B, whatever their positions.\nSo the statement is True."},
{"y":"IIT-JEE 1989","tp":"ecp","st":"Statements, matching and subjective","q":"Two parallel plate capacitors of capacitances C and 2C are connected in parallel and charged to a potential difference V. The battery is then disconnected and the region between the plates of the capacitor C is completely filled with a material of dielectric constant K. The potential difference across the capacitors now becomes ____.","a":"3V/(K + 2)","s":"Total charge = (C + 2C)V = 3CV, and it stays constant after the battery is disconnected.\nThe capacitor C becomes KC, so the total capacitance is KC + 2C = (K + 2)C.\nV' = Q/C' = 3CV/[(K + 2)C].\nV' = 3V/(K + 2)."},
{"y":"IIT-JEE 1984","tp":"ecp","st":"Statements, matching and subjective","q":"Five identical parallel plates, each of area A, are arranged such that adjacent plates are at a distance d apart. The plates are connected to a source of emf V as shown in the figure. The charge on plate 1 is ____ and on plate 4 is ____.","fig":{"w":300,"h":180,"alt":"Five parallel plates numbered 1 to 5; plates 2 and 4 are joined to the negative terminal and plates 1, 3 and 5 to the positive terminal of a source V","d":[["l",60,50,60,140,"B"],["t",54,100,"1","es"],["l",100,50,100,140,"B"],["t",94,100,"2","es"],["l",140,50,140,140,"B"],["t",134,100,"3","es"],["l",180,50,180,140,"B"],["t",174,100,"4","es"],["l",220,50,220,140,"B"],["t",214,100,"5","es"],["l",100,50,100,30],["l",180,50,180,30],["l",100,30,260,30],["l",260,30,260,70],["l",254,70,266,70,"B"],["l",246,77,274,77],["l",260,77,260,160],["l",60,140,60,160],["l",140,140,140,160],["l",220,140,220,160],["l",60,160,260,160],["c",100,30,2,"F"],["c",180,30,2,"F"],["c",140,160,2,"F"],["t",240,66,"−","es"],["t",240,92,"+","es"],["t",272,76,"V","s"]]},"a":"ε₀AV/d; −2ε₀AV/d","s":"Plates 1, 3, 5 are joined to the positive terminal and plates 2, 4 to the negative terminal, so every gap has voltage V and capacitance C = ε₀A/d.\nPlate 1 faces only plate 2: charge = +CV = ε₀AV/d.\nPlate 4 faces plate 3 and plate 5, both positive, with V across each gap: it carries −CV from each side.\nCharge on plate 4 = −2CV = −2ε₀AV/d."}
];
